        Console.WriteLine();
        for (int v = 1; v <= 2; v++)
        {
            Console.WriteLine($"    {BtVName(v)}");
            Console.WriteLine($"      餌由来の出力/戦 ＝ 追撃 {gFireA[v] / gN:F2} 回 ＋ 毒 {gFireP[v] / gN:F2} 層 ＋ 深追い {gFireO[v] / gN:F2} 回");
            Console.WriteLine($"      餌の代金/戦     ＝ {gHits[v] / gN:F2} 回 × 平均打点 {(gHits[v] > 0 ? gAtk[v] / gHits[v] : 0):F1}"
                              + $" ＝ **{gAtk[v] / gN:F1} 点/戦**");
