reKubi:
    Console.WriteLine("### C. 萎縮（クビ）との同居 —— 開戦時1回・1体につき 9（予測4）");
    Console.WriteLine();
    Console.WriteLine("採用行のノノをクビに差し替える。萎縮は**開戦時1回・味方1体につき 9**なので、");
    Console.WriteLine("中央（隣接次数4）のワタは1ターン目に 4体ぶん = 36 を横取りし、代金は 72。");
    Console.WriteLine("**HP84 に対して 86%。** 角（次数2）なら 18 / 代金 36。");
    Console.WriteLine();
    Console.WriteLine("| 版 | 平均勝率 | 第1波 | 第2波 | 第3波 | 第4波 | 第5波 | 横取り/戦 | 代金/戦 | 自弁率 | 渡し/戦 | 攻ゼロ/戦 | 早逝(T/率) |");
    Console.WriteLine("|---|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|");
    var kubiMid = Formation.Build(front1: UnitCatalog.Kubi, front3: UnitCatalog.Gald,
                                  center: UnitCatalog.Wata, back1: UnitCatalog.Doha, back3: UnitCatalog.Dolga);
    var kubiCorner = Formation.Build(front1: UnitCatalog.Wata, front3: UnitCatalog.Gald,
                                     center: UnitCatalog.Kubi, back1: UnitCatalog.Doha, back3: UnitCatalog.Dolga);
    foreach (var (vn, vf) in new[] { ("クビ同居（ワタ中央・次数4）", kubiMid), ("クビ同居（ワタ前1・次数2）", kubiCorner) })
    {
        double tk = 0, cs = 0, sp = 0, sn = 0, zr = 0, de = 0, dd = 0;
        var per = new double[reStages.Count];
        for (int w = 0; w < reStages.Count; w++)
        {
            var z = MeasureRelay(vf, reStages[w].Enemy, RelayRule.Default);
            per[w] = z.Win; tk += z.Taken; cs += z.Cost; sp += z.SelfPaid;
            sn += z.Sent; zr += z.Zeroed; de += z.Death; dd += z.Died;
        }
        int n = reStages.Count;
        Console.WriteLine($"| {vn} | {per.Average():0.0}% | " + string.Join(" | ", per.Select(v => $"{v:0.0}%"))
            + $" | {tk / n:0.00} | {cs / n:0.00} "
            + $"| {(cs > 0 ? $"{sp * 100 / cs:0.0}%" : "—")} | {sn / n:0.00} | {zr / n:0.00} "
            + $"| {de / n:0.0} / {dd * 100 / n:0.0}% |");
        Console.Out.Flush();
    }
    Console.WriteLine();
    return;
}

// 誹り（第44期）を測る。**敵から味方へ弱体を撒く初めての経路**で、窓口は第42期の
// BattleContext.Dull。撒いた量そのものではなく、**そのうち何割が読み手（ウケ＝アーマー化 /
// ワタ＝敵へ転嫁）に届いたか**で読む——第42期が「生成したアーマー」ではなく「実際に吸った量」で、
// 第43期が「流した量」ではなく「効き」で判断したのと同じ理由。**撒いた量は成果ではない。**
//
// **「早逝」が必須。** 保持者は前列（第二波・前3）なので早く落ちる。供給の総量は
// 保持者の生存ターン数で決まるので、これを見ないと「弱すぎる」と「早く死んでいる」が切り分かない。
//
// **陽性対照は SlanderRule(0)。** 誹りが 0.00 になること自体が計数の検算で、
// 同時にその行の「差し替え前の値」（＝Phase 0 の基準）になる。
if (focusId == "slander")
{
    var slBuilds = CompareBuilds();
    const int SlSeeds = 200;   // compare / spread / shove / dull / relay と同じ。balance.md と突き合わせる
    const int SlWave = 1;      // 第二波（0 起算）。誹りの保持者はここにしかいない

    string slFilter = args.Length > 2 ? args[2] : "";
    var slTargets = slBuilds
        .Where(b => slFilter.Length == 0 || slFilter.Split(',').Any(k => b.Name.Contains(k.Trim())))
        .ToArray();

    // **波は診断のローカルに組む**（gradient / aim / guard と同じ扱い）。
    // 誹りは測って採用しなかったので `Stages` には載っていない——載せ替えずに測れるようにしてある。
    //
    // 差し替え版（前3 = Slanderer）と、差し替え前（前3 = KnightG）。
    // **2体は数値・型・速さが1つも違わない**ので、差分は誹り1つに閉じる。
    Formation SlSlanderWave2() => Formation.Build(
        front1: EnemyCatalog.KnightG, front3: EnemyCatalog.Slanderer, center: EnemyCatalog.Husher,
        back1: EnemyCatalog.Almoner, back3: EnemyCatalog.ArcherG);

    Formation SlPlainWave2() => Formation.Build(
        front1: EnemyCatalog.KnightG, front3: EnemyCatalog.KnightG, center: EnemyCatalog.Husher,
        back1: EnemyCatalog.Almoner, back3: EnemyCatalog.ArcherG);

    Formation slWave2 = SlSlanderWave2();

    // 弱体の読み手（ウツ＝逆しま / ウケ＝集約 / ワタ＝渡し）を1枚でも含む行か。
    static bool SlHasReader(Formation f) => f.Occupied().Any(o =>
        o.Def.Traits.Contains(TraitId.Perverse) || o.Def.Traits.Contains(TraitId.Bear)
        || o.Def.Traits.Contains(TraitId.Relay));

    int slRouteIdx = (int)DullRoute.Slander;

    (double Win, double Fired, double Total, double Taken, double Passed, double Zeroed,
     double Death, double Died, double Turns, double Foe, double Swings,
     Dictionary<string, double> To, Dictionary<string, double> Zero, Dictionary<string, double> RelayTo)
    MeasureSlander(Formation f, Formation enemy, SlanderRule rule, int seed0 = 0, int seedN = SlSeeds)
    {
        var to = new Dictionary<string, double>();
        var zero = new Dictionary<string, double>();
        var rto = new Dictionary<string, double>();
        double win = 0, fired = 0, total = 0, taken = 0, passed = 0, zeroed = 0;
        double death = 0, died = 0, turns = 0, foe = 0, swings = 0;

        for (int seed = seed0; seed < seed0 + seedN; seed++)
        {
            var r = BattleEngine.Run(f, enemy, seed, verbose: false,
                                    null, null, null, null, null, null, null, null, rule);
            if (r.PlayerWon) win++;
            fired += r.SlanderFired; total += r.SlanderTotal;
            taken += r.DullTakenByRoute[slRouteIdx];
            passed += r.DullByRoute[slRouteIdx] - r.DullTakenByRoute[slRouteIdx];
            zeroed += r.DullZeroed; turns += r.Turns;

            foreach (var kv in r.SlanderTo)
                to[kv.Key] = to.TryGetValue(kv.Key, out double c) ? c + kv.Value : kv.Value;
            foreach (var kv in r.DullZeroedWho)
                zero[kv.Key] = zero.TryGetValue(kv.Key, out double c) ? c + kv.Value : kv.Value;
            foreach (var kv in r.RelayTo)
                rto[kv.Key] = rto.TryGetValue(kv.Key, out double c) ? c + kv.Value : kv.Value;

            // 敵が味方に与えたダメージと、敵が振った回数（第二波の攻撃回数＝誹りの発火の母数）
            foreach ((int _, UnitDef d) in enemy.Occupied())
                if (r.TallyByUnit.TryGetValue(d.Id, out UnitTally? t))
                { foe += t.DamageToEnemy; swings += t.Attacks; }

            // 早逝: 誹りの保持者が倒れた試行の、倒れたターン（UnitTally.LastActiveTurn は
            // 死亡時にその手番のターンで上書きされる）。倒れなかった試行は分母に入れない。
            if (r.TallyByUnit.TryGetValue(EnemyCatalog.Slanderer.Id, out UnitTally? st) && st.Deaths > 0)
            { died++; death += st.LastActiveTurn; }
        }

        double n = seedN, md = Math.Max(1, died);
        foreach (string k in to.Keys.ToList()) to[k] /= n;
        foreach (string k in zero.Keys.ToList()) zero[k] /= n;
        foreach (string k in rto.Keys.ToList()) rto[k] /= n;
        return (win * 100 / n, fired / n, total / n, taken / n, passed / n, zeroed / n,
                death / md, died / n, turns / n, foe / n, swings / n, to, zero, rto);
    }

    // 逆しま持ちの CurrentAttack（StatSnapshot。ターン頭の値）。**verbose が要るので別立て**。
    (double Open, double Max, double Last, double Seen) MeasureUtsu(Formation f, Formation enemy, SlanderRule rule)
    {
        int readerId = -1;
        for (int i = 0, k = 0; i < FormationRules.PlayableSlotCount; i++)
            if (f[i] is { } d) { if (d.Traits.Contains(TraitId.Perverse)) readerId = k; k++; }
        if (readerId < 0) return (0, 0, 0, 0);

        double open = 0, max = 0, last = 0, seen = 0;
        for (int seed = 0; seed < SlSeeds; seed++)
        {
            var r = BattleEngine.Run(f, enemy, seed, verbose: true,
                                    null, null, null, null, null, null, null, null, rule);
            var snaps = r.Events
                .Where(e => e.Kind == BattleEventKind.StatSnapshot && e.TargetId == readerId)
                .Select(e => e.Amount).ToList();
            if (snaps.Count > 0) { open += snaps[0]; max += snaps.Max(); last += snaps[^1]; seen++; }
        }
        double m = Math.Max(1, seen);
        return (open / m, max / m, last / m, seen);
    }

    Console.WriteLine("# 誹り（slander）");
    Console.WriteLine();
    Console.WriteLine("`dotnet run --project BattleSim -c Release 0 slander [絞り込み]` の出力。");
    Console.WriteLine($"**docs/ には置かない**（標準出力で読むだけ）。seed 0..{SlSeeds - 1}。数字は**1戦あたりの平均**。");
    Console.WriteLine();
    Console.WriteLine("`CompareBuilds()` / `Stages` / `Columns` は触っていない。");
    Console.WriteLine("**測るのは第二波だけ**——誹りの保持者（誹りの巡礼騎士・前3）はそこにしかいない。");
    Console.WriteLine();
    Console.WriteLine("| 列 | 中身 |");
    Console.WriteLine("|---|---|");
    Console.WriteLine("| 誹り | 発火回数/戦（`SlanderFired`）と撒いた総量/戦（`SlanderTotal`） |");
    Console.WriteLine("| 横取り | ウケ／ワタが横取りした量/戦（`DullTakenByRoute[Slander]`）＝**敵の供給が資産に変わった量** |");
    Console.WriteLine("| 素通り | 読み手に届かずただの損になった量/戦（`DullByRoute[Slander]` − 横取り） |");
    Console.WriteLine("| 攻ゼロ | 味方の `CurrentAttack` が 0 になった回数/戦（**崖の検算**・全経路） |");
    Console.WriteLine("| 早逝 | 誹りの保持者が倒れたターン（倒れた試行の平均）と、倒れた試行の割合 |");
    Console.WriteLine("| 敵振り | 敵5体が攻撃を振った回数/戦（`UnitTally.Attacks` の和）＝**誹りの発火の母数** |");
    Console.WriteLine();
    Console.WriteLine("**撒いた量は成果ではない。** 採否は「横取り ÷（横取り + 素通り）」で読む。");
    Console.WriteLine();

    // --- 0. 検算（受け入れ基準1・2）--------------------------------------------------------
    Console.WriteLine("## 0. 検算 —— 差分は規則だけに閉じているか");
    Console.WriteLine();
    {
        Formation plain = SlPlainWave2();
        int cells = 0, diffA = 0, diffB = 0;
        foreach (var b in slBuilds)
        {
            int a = 0, c = 0, d = 0;
            for (int seed = 0; seed < SlSeeds; seed++)
            {
                // A: 誹りの保持者を置いた波 × SlanderRule(0)
                if (BattleEngine.Run(b.F, slWave2, seed, false,
                        null, null, null, null, null, null, null, null, new SlanderRule(0)).PlayerWon) a++;
                // B: 前3 を KnightG に戻した波 ×
                //    SlanderRule(0)（＝出荷している Stages[1] そのもの）
                if (BattleEngine.Run(b.F, EnemyCatalog.Stages[SlWave].Enemy, seed, false,
                        null, null, null, null, null, null, null, null, new SlanderRule(0)).PlayerWon) c++;
                // C: 前3 を KnightG に戻した波 × SlanderRule(3)（規則を有効にしても保持者がいない）
                if (BattleEngine.Run(b.F, plain, seed, false,
                        null, null, null, null, null, null, null, null, new SlanderRule(3)).PlayerWon) d++;
            }
            cells++;
            if (a != c) diffA++;
            if (c != d) diffB++;
        }
        Console.WriteLine($"- **基準1**（保持者を置いた波 × `SlanderRule(0)` ⇔ 出荷している `Stages[1]`）: "
            + $"**{cells} セル中 {diffA} 件の食い違い**（{cells} 行 × 第二波）");
        Console.WriteLine($"- **基準2**（`KnightG` に戻すと規則を有効にしても元へ戻る）: **{cells} セル中 {diffB} 件の食い違い**");
        Console.WriteLine();
        Console.Out.Flush();
    }

    int[] slPens = { 0, 1, 2, 3 };
    const int SlMain = 2;   // 主表に使う Penalty

    // --- 1. 陽性対照と主表 ------------------------------------------------------------------
    Console.WriteLine($"## 1. 全 {slBuilds.Length} 行 × 第二波（陽性対照 `SlanderRule(0)` と 主表 `Penalty = {SlMain}`）");
    Console.WriteLine();
    Console.WriteLine("`読` = 弱体の読み手（ウツ／ウケ／ワタ）を持つ行。");
    Console.WriteLine();
    Console.WriteLine($"| 行 | 読 | 勝率(P0) | 勝率(P{SlMain}) | 差 | 誹り | 総量 | 横取り | 素通り | 攻ゼロ(P0→P{SlMain}) | 早逝(T/率) | 敵振り | 決着T(P0→P{SlMain}) |");
    Console.WriteLine("|---|:-:|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|");

    var slAggTo = new Dictionary<string, double>();
    var slAggZero = new Dictionary<string, double>();
    var slAggZero0 = new Dictionary<string, double>();
    double slPassReader = 0, slPassPlain = 0; int slNReader = 0, slNPlain = 0;
    double slDeltaReader = 0, slDeltaPlain = 0;

    foreach (var b in slBuilds)
    {
        var z0 = MeasureSlander(b.F, slWave2, new SlanderRule(0));
        var z = MeasureSlander(b.F, slWave2, new SlanderRule(SlMain));
        bool reader = SlHasReader(b.F);

        foreach (var kv in z.To)
            slAggTo[kv.Key] = slAggTo.TryGetValue(kv.Key, out double c) ? c + kv.Value : kv.Value;
        foreach (var kv in z.Zero)
            slAggZero[kv.Key] = slAggZero.TryGetValue(kv.Key, out double c) ? c + kv.Value : kv.Value;

        foreach (var kv in z0.Zero)
            slAggZero0[kv.Key] = slAggZero0.TryGetValue(kv.Key, out double c) ? c + kv.Value : kv.Value;

        if (reader) { slPassReader += z.Passed; slNReader++; slDeltaReader += z.Win - z0.Win; }
        else { slPassPlain += z.Passed; slNPlain++; slDeltaPlain += z.Win - z0.Win; }

        Console.WriteLine($"| {b.Name} | {(reader ? "○" : "")} | {z0.Win:0.0}% | {z.Win:0.0}% "
            + $"| {z.Win - z0.Win:+0.0;-0.0;±0.0} | {z.Fired:0.00} | {z.Total:0.0} | {z.Taken:0.00} "
            + $"| {z.Passed:0.00} | {z0.Zeroed:0.00} → {z.Zeroed:0.00} | {z.Death:0.0} / {z.Died * 100:0.0}% "
            + $"| {z0.Swings:0.0} | {z0.Turns:0.0} → {z.Turns:0.0} |");
        Console.Out.Flush();
    }
    Console.WriteLine();
    Console.WriteLine($"読み手あり **{slNReader} 行**: 平均 {slDeltaReader / Math.Max(1, slNReader):+0.00;-0.00;±0.00} pt"
        + $" / 素通り {slPassReader / Math.Max(1, slNReader):0.00} per 戦");
    Console.WriteLine($"読み手なし **{slNPlain} 行**: 平均 {slDeltaPlain / Math.Max(1, slNPlain):+0.00;-0.00;±0.00} pt"
        + $" / **目減り（素通り）{slPassPlain / Math.Max(1, slNPlain):0.00} per 戦**");
    Console.WriteLine();

    // --- 2. 誰が誹られたか ------------------------------------------------------------------
    Console.WriteLine($"## 2. 誰が誹られたか（`Penalty = {SlMain}` ・全 {slBuilds.Length} 行の合計 / 戦）");
    Console.WriteLine();
    Console.WriteLine("| 駒 | 量/戦（全行合計） |");
    Console.WriteLine("|---|--:|");
    foreach (var kv in slAggTo.OrderByDescending(k => k.Value).Take(12))
        Console.WriteLine($"| {kv.Key} | {kv.Value:0.00} |");
    Console.WriteLine();

    Console.WriteLine("### 攻ゼロの内訳（崖の検算・受け入れ基準4）");
    Console.WriteLine();
    Console.WriteLine("**帰属は P0 との差で取る**——`攻ゼロ` は窓口を通る全経路を数えるので、");
    Console.WriteLine("呪詛・萎縮・なまりのぶんが P0 の側に既に載っている。");
    Console.WriteLine();
    Console.WriteLine("| 駒 | 素の攻 | P0 | P" + SlMain + " | 差（＝誹りに帰属） |");
    Console.WriteLine("|---|--:|--:|--:|--:|");
    if (slAggZero.Count == 0) Console.WriteLine("| （0 件） | — | 0.00 | 0.00 | ±0.00 |");
    foreach (var kv in slAggZero.OrderByDescending(k => k.Value - (slAggZero0.TryGetValue(k.Key, out double q) ? q : 0)).Take(15))
    {
        var def = UnitCatalog.All.FirstOrDefault(u => u.Name == kv.Key);
        double b0 = slAggZero0.TryGetValue(kv.Key, out double p) ? p : 0;
        Console.WriteLine($"| {kv.Key} | {(def is null ? "—" : def.Attack.ToString())} "
            + $"| {b0:0.00} | {kv.Value:0.00} | {kv.Value - b0:+0.00;-0.00;±0.00} |");
    }
    Console.WriteLine();

    // --- 3. 読み手を持つ行の詳細（ウツ攻 / ワタの流し先）-------------------------------------
    Console.WriteLine("## 3. 弱体の読み手を持つ行の詳細");
    Console.WriteLine();
    Console.WriteLine("`ウツ攻` は逆しま持ちの `CurrentAttack`（開戦時 / 最大 / 最終T）。`StatSnapshot` から。");
    Console.WriteLine("**開戦時 < 最大 が「敵の供給が読み手に届いた」の直接の証拠。**");
    Console.WriteLine();
    Console.WriteLine($"| 行 | 勝率(P0→P{SlMain}) | 誹り | 横取り | 素通り | 横取り率 | ウツ攻(P0) | ウツ攻(P{SlMain}) |");
    Console.WriteLine("|---|--:|--:|--:|--:|--:|--:|--:|");
    var slRelayNotes = new List<string>();
    foreach (var b in slBuilds.Where(x => SlHasReader(x.F)))
    {
        var z0 = MeasureSlander(b.F, slWave2, new SlanderRule(0));
        var z = MeasureSlander(b.F, slWave2, new SlanderRule(SlMain));
        var u0 = MeasureUtsu(b.F, slWave2, new SlanderRule(0));
        var u1 = MeasureUtsu(b.F, slWave2, new SlanderRule(SlMain));
        double got = z.Taken + z.Passed;
        Console.WriteLine($"| {b.Name} | {z0.Win:0.0}% → {z.Win:0.0}% | {z.Fired:0.00} | {z.Taken:0.00} "
            + $"| {z.Passed:0.00} | {(got > 0 ? $"{z.Taken * 100 / got:0.0}%" : "—")} "
            + $"| {(u0.Seen > 0 ? $"{u0.Open:0.0} / {u0.Max:0.0} / {u0.Last:0.0}" : "—")} "
            + $"| {(u1.Seen > 0 ? $"{u1.Open:0.0} / {u1.Max:0.0} / {u1.Last:0.0}" : "—")} |");
        Console.Out.Flush();

        if (z.RelayTo.Count > 0 || z0.RelayTo.Count > 0)
        {
            slRelayNotes.Add($"- **{b.Name}** P0 の流し先: "
                + (z0.RelayTo.Count == 0 ? "（なし）" : string.Join(" / ", z0.RelayTo.OrderByDescending(k => k.Value)
                    .Select(k => $"{k.Key} {k.Value:0.00}"))));
            slRelayNotes.Add($"- **{b.Name}** P{SlMain} の流し先: "
                + (z.RelayTo.Count == 0 ? "（なし）" : string.Join(" / ", z.RelayTo.OrderByDescending(k => k.Value)
                    .Select(k => $"{k.Key} {k.Value:0.00}"))));
        }
    }
    Console.WriteLine();
    if (slRelayNotes.Count > 0)
    {
        Console.WriteLine("### ワタの流し先（**撒いた呪いが本人に返るか**）");
        Console.WriteLine();
        Console.WriteLine("第二波の最高攻撃力は `KnightG` / `Slanderer` の 24 なので、");
        Console.WriteLine("**誹りの保持者自身に返る可能性がある**（設計としては望ましい）。");
        Console.WriteLine();
        foreach (string note in slRelayNotes) Console.WriteLine(note);
        Console.WriteLine();
    }

    // --- 4. 掃引 ----------------------------------------------------------------------------
    Console.WriteLine("## 4. 掃引（`Penalty` 0 / 1 / 2 / 3）");
    Console.WriteLine();
    Console.WriteLine("**見るのは勝率ではなく「横取り／素通り」の比と、第二波の情報セル。**");
    Console.WriteLine("第41期の掃引は「比が全点で 2.30 で動かない＝ノブは強度しか変えず性質を変えない」を示した。");
    Console.WriteLine("同じことが起きるかを先に疑う。");
    Console.WriteLine();
    Console.WriteLine("| Penalty | 平均(全行) | 主判定17行 | 情報セル | 100%行 | 0%行 | 誹り | 総量 | 横取り | 素通り | 横取り率 | 攻ゼロ |");
    Console.WriteLine("|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|");

    // 主判定17行（design/HANDOFF_NEXT_SESSION.md §4-4）。行集合を固定した歯止めの分母。
    string[] slMainKeys =
    {
        "隊列崩し (バサ×ヨミ×セロ)", "燃焼 (ボルグ×ホタ)", "縛め収入型 (クグ×バン×ガン)",
        "仇討ち×砕け (ヒビ×ザン)", "刻み×抉り (ノミ×エグ)", "裂き (キリ×エグ)",
        "耐久 (ガルド×ノノ)", "溜め改 (クグ×バン×ガン)", "逆しま (ネル×ウツ)",
        "追撃×据え (ハギ×バン)", "置き去り×分散回復", "毒+耐久 (ベニ×トウ)",
        "速攻 (ボルグ×ムド)", "反撃改2 (ガン×カド)", "惨禍×死の連鎖",
        "後衛特化+後備え", "突き出し (セロ×ヨミ)"
    };

    var slSweep = new Dictionary<int, Dictionary<string, double>>();
    foreach (int pen in slPens)
    {
        var wins = new Dictionary<string, double>();
        double fired = 0, total = 0, taken = 0, passed = 0, zeroed = 0;
        foreach (var b in slBuilds)
        {
            var z = MeasureSlander(b.F, slWave2, new SlanderRule(pen));
            wins[b.Name] = z.Win;
            fired += z.Fired; total += z.Total; taken += z.Taken; passed += z.Passed; zeroed += z.Zeroed;
        }
        slSweep[pen] = wins;
        double n = slBuilds.Length;
        var col = wins.Values.ToList();
        double got = taken + passed;
        Console.WriteLine($"| {pen} | {col.Average():0.00} "
            + $"| {slMainKeys.Average(k => wins[k]):0.00} "
            + $"| {col.Count(x => x > 0 && x < 100)} | {col.Count(x => x >= 100)} | {col.Count(x => x <= 0)} "
            + $"| {fired / n:0.00} | {total / n:0.0} | {taken / n:0.00} | {passed / n:0.00} "
            + $"| {(got > 0 ? $"{taken * 100 / got:0.0}%" : "—")} | {zeroed / n:0.00} |");
        Console.Out.Flush();
    }
    Console.WriteLine();
    Console.WriteLine("**歯止め**: 主判定17行の第二波は `Penalty = 0` の値から 10pt 以上落ちてはいけない。");
    Console.WriteLine();

    // --- 5. 符号反転（受け入れ基準6）--------------------------------------------------------
    Console.WriteLine("## 5. 符号反転（受け入れ基準6・**この期の主眼**）");
    Console.WriteLine();
    Console.WriteLine($"`Penalty = {SlMain}` で第二波の勝率が動いた行。**上がる行と下がる行が両方あること**が条件。");
    Console.WriteLine();
    Console.WriteLine($"| 行 | 読 | P0 | P{SlMain} | 差 |");
    Console.WriteLine("|---|:-:|--:|--:|--:|");
    var slMoved = slBuilds
        .Select(b => (b.Name, Reader: SlHasReader(b.F), A: slSweep[0][b.Name], B: slSweep[SlMain][b.Name]))
        .Where(x => Math.Abs(x.B - x.A) > 0.001)
        .OrderByDescending(x => x.B - x.A).ToList();
    foreach (var x in slMoved)
        Console.WriteLine($"| {x.Name} | {(x.Reader ? "○" : "")} | {x.A:0.0}% | {x.B:0.0}% | {x.B - x.A:+0.0;-0.0;±0.0} |");
    Console.WriteLine();
    Console.WriteLine($"上がった行 **{slMoved.Count(x => x.B > x.A)}** / 下がった行 **{slMoved.Count(x => x.B < x.A)}**"
        + $" / 動かなかった行 **{slBuilds.Length - slMoved.Count}**。");
    Console.WriteLine();


    // --- 6. 別 seed での追試（confirm）------------------------------------------------------
    // **選定に使っていない seed に当てて採否を決める**（CLAUDE.md の reseat → confirm と同じ作法）。
    // 対象は「読み手を持つ7行」と「主表で 1.0pt 以上動いた行」。+1.0pt が 200 試行のうち2件でしかない
    // 以上、seed 帯を変えても符号が保つかを見ないと符号反転を主張できない。
    Console.WriteLine("## 6. 別 seed での追試（seed 200..599 の 400 試行）");
    Console.WriteLine();
    Console.WriteLine("**選定に使っていない seed 帯**。主表（seed 0..199）で1セルでも動いた行と、");
    Console.WriteLine("読み手を持つ7行が対象。**符号が保つかどうかだけを見る。**");
    Console.WriteLine();
    Console.WriteLine($"| 行 | 読 | 主表 P0→P{SlMain} | 主表 差 | 追試 P0→P{SlMain} | 追試 差 | 符号 |");
    Console.WriteLine("|---|:-:|--:|--:|--:|--:|:-:|");
    foreach (var b in slBuilds)
    {
        bool reader = SlHasReader(b.F);
        double a = slSweep[0][b.Name], c = slSweep[SlMain][b.Name];
        if (!reader && Math.Abs(c - a) < 0.001) continue;
        var q0 = MeasureSlander(b.F, slWave2, new SlanderRule(0), 200, 400);
        var q1 = MeasureSlander(b.F, slWave2, new SlanderRule(SlMain), 200, 400);
        double d1 = c - a, d2 = q1.Win - q0.Win;
        string sign = Math.Abs(d1) < 0.001 && Math.Abs(d2) < 0.001 ? "—"
            : (d1 > 0) == (d2 > 0) && Math.Abs(d2) > 0.001 ? "保つ" : "**割れる**";
        Console.WriteLine($"| {b.Name} | {(reader ? "○" : "")} | {a:0.0}% → {c:0.0}% | {d1:+0.0;-0.0;±0.0} "
            + $"| {q0.Win:0.0}% → {q1.Win:0.0}% | {d2:+0.0;-0.0;±0.0} | {sign} |");
        Console.Out.Flush();
    }
    Console.WriteLine();

    if (slTargets.Length > 0 && slFilter.Length > 0)
    {
        Console.WriteLine($"## 7. 絞り込み `{slFilter}` の掃引（第二波）");
        Console.WriteLine();
        Console.WriteLine("| 行 | " + string.Join(" | ", slPens.Select(p => $"P{p}")) + " |");
        Console.WriteLine("|---|" + string.Join("|", slPens.Select(_ => "--:")) + "|");
        foreach (var b in slTargets)
            Console.WriteLine($"| {b.Name} | " + string.Join(" | ", slPens.Select(p => $"{slSweep[p][b.Name]:0.0}%")) + " |");
        Console.WriteLine();
    }
    return;
}

// overbear モード: 驕り（第46期）。**隣接を「量」ではなく「誰がいるか」で読む駒**を測る。
//
// 第45期の結論は「隣接を単調な量（隣に何人いるか）で読む駒は席が定数になる」で、
// 反例はロスターに1枚しかない非単調な読み手（囃し立てのヒサ）だけだった（n=1）。
// オゴは条件を隣接する味方**全員**への AND にするので、
//
//     隣接数が増えるほど条件が厳しくなる（中央は削る量が多い代わりに成立が遅い）
//     さらに「隣が誰か」で成立時刻が変わる（ドルガ38 の隣なら13ターン、ムグ6 の隣なら即座）
//
// **この期の核心は「成立時刻」**で、席（隣接数）と相方（隣の攻撃力）の両方で変わるはず。
// 変わらなければ非単調にした意味が無い。
//
// **陽性対照を2本置く**: OverbearRule(0)（削らない＝条件が永遠に成立しない＝プラス側だけを切る）と、
// オゴを外した4体版（＝第21期の飽和検査も兼ねる）。
// **発火しなかったことは盤面の値に痕跡を残さない**ので、計数は BattleResult の
// Overbear*（verbose に依存しない）から取る。
//
//     dotnet run --project BattleSim -c Release 0 overbear [絞り込み]
if (focusId == "overbear")
{
    var obBuilds = CompareBuilds();
    IReadOnlyList<EnemyCatalog.Stage> obStages = EnemyCatalog.Stages;
    const int ObSeeds = 200;   // compare / spread / shove / dull / relay / slander と揃える
    const int ObMain = 2;      // 主表に使う Drain（採用値）
    int[] obDrains = { 0, 1, 2, 3 };
    int obRouteIdx = (int)DullRoute.Overbear;

    string obFilter = args.Length > 2 ? args[2] : "";

    static bool ObHasOgo(Formation f) => f.Occupied().Any(o => ReferenceEquals(o.Def, UnitCatalog.Ogo));

    // **測定した2編成は診断のローカルに持つ**（gradient / aim / guard / slander と同じ扱い）。
    // 第46期は驕りを**採用しなかった**ので `CompareBuilds()` には残していない
    // ——測ったときは 50 行に足して回し、棄却と同時に外した。ここに残しておけば、
    // `CompareBuilds()` を1行も動かさずに全部を測り直せる。
    //
    // 2行は「条件が早く成立する台」と「遅く成立する台」の対。律速は隣でいちばん攻撃力の高い1枚。
    //
    //   早い台 = 死の連鎖行の ゴルム(10)→ウケ・ヴェル(6)→オゴ。開幕の隣の最高は 6 で**どの席でも成立する**
    //   遅い台 = 分かち×逆しま行の ノノ(3) → オゴ。**ドルガ 38 と ウツ（削るほど育つ）が隣にいると成立しない**
    //
    // **早い台は「攻撃力の低い駒だけ」では組めなかった**（測った5通りが全部 20.0〜23.2% ＝
    // CLAUDE.md の「台が死んでいる」）——ロスターでは弱体・毒・支援の駒が軒並み攻2〜9 で、
    // 攻撃力と出力が強く相関している。抜け道は**攻撃力を経由しない出力**で、
    // 死の連鎖（破裂・胞子・墓守）がそれに当たる。
    static (string Name, Formation F)[] ObRows() => new (string, Formation)[]
    {
        ("驕り (オゴ×ウケ)", Formation.Build(front1: UnitCatalog.Zoto, front3: UnitCatalog.Mug,
                                        center: UnitCatalog.Uke, back1: UnitCatalog.Rica,
                                        back3: UnitCatalog.Ogo)),
        ("驕り改 (オゴ×ウツ)", Formation.Build(front1: UnitCatalog.Utsu, front3: UnitCatalog.Gald,
                                          center: UnitCatalog.Ogo, back1: UnitCatalog.Doha,
                                          back3: UnitCatalog.Dolga)),
    };

    var obTargets = ObRows();
    if (obFilter.Length > 0)
        obTargets = obTargets.Where(b => obFilter.Split(',').Any(k => b.Name.Contains(k.Trim()))).ToArray();

    // オゴを外した同じ編成（4体版）。**第21期の飽和検査を兼ねる**
    // ——4体版と5体版が同じ値なら、その台では中央の駒が何であっても結果が変わらない。
    static Formation ObWithoutOgo(Formation f)
    {
        var g = new Formation();
        foreach ((int slot, UnitDef d) in f.Occupied())
            if (!ReferenceEquals(d, UnitCatalog.Ogo)) g[slot] = d;
        return g;
    }

    // オゴの席だけを振った5変種。**他の4枚は元の相対順のまま**空いた席へ詰める
    // （reseat の120通りと違い、動かすのはオゴ1枚だけ＝席の効果を1変数に閉じる）。
    static Formation ObSeat(Formation f, int seat)
    {
        var others = f.Occupied().Where(o => !ReferenceEquals(o.Def, UnitCatalog.Ogo))
                      .Select(o => o.Def).ToList();
        var g = new Formation();
        g[seat] = UnitCatalog.Ogo;
        int k = 0;
        for (int i = 0; i < FormationRules.PlayableSlotCount && k < others.Count; i++)
            if (i != seat) g[i] = others[k++];
        return g;
    }

    (double Win, double Fired, double Total, double Taken, double Passed, double Zeroed,
     double MetRate, double First, double Never, double Doubled, double Swings,
     double Back, double BackHits, double Turns,
     Dictionary<string, double> To, Dictionary<string, double> Zero)
    MeasureOverbear(Formation f, Formation enemy, OverbearRule rule, int seed0 = 0, int seedN = ObSeeds)
    {
        var to = new Dictionary<string, double>();
        var zero = new Dictionary<string, double>();
        double win = 0, fired = 0, total = 0, taken = 0, passed = 0, zeroed = 0;
        double met = 0, obTurns = 0, first = 0, firstN = 0, never = 0;
        double doubled = 0, swings = 0, back = 0, backHits = 0, turns = 0;

        for (int seed = seed0; seed < seed0 + seedN; seed++)
        {
            var r = BattleEngine.Run(f, enemy, seed, verbose: false,
                                    null, null, null, null, null, null, null, null, null, rule);
            if (r.PlayerWon) win++;
            fired += r.OverbearFired; total += r.OverbearTotal;
            taken += r.DullTakenByRoute[obRouteIdx];
            passed += r.DullByRoute[obRouteIdx] - r.DullTakenByRoute[obRouteIdx];
            zeroed += r.DullZeroed;
            met += r.OverbearMetTurns; obTurns += r.OverbearTurns;
            if (r.OverbearFirstTurn > 0) { first += r.OverbearFirstTurn; firstN++; } else never++;
            doubled += r.OverbearDoubled; swings += r.OverbearSwings;
            back += r.OverbearBackfire; backHits += r.OverbearBackfireHits;
            turns += r.Turns;

            foreach (var kv in r.OverbearTo)
                to[kv.Key] = to.TryGetValue(kv.Key, out double c) ? c + kv.Value : kv.Value;
            foreach (var kv in r.DullZeroedWho)
                zero[kv.Key] = zero.TryGetValue(kv.Key, out double c) ? c + kv.Value : kv.Value;
        }

        double n = seedN;
        foreach (string k in to.Keys.ToList()) to[k] /= n;
        foreach (string k in zero.Keys.ToList()) zero[k] /= n;
        return (win * 100 / n, fired / n, total / n, taken / n, passed / n, zeroed / n,
                obTurns > 0 ? met * 100 / obTurns : 0, firstN > 0 ? first / firstN : 0, never * 100 / n,
                doubled / n, swings / n, back / n, backHits / n, turns / n, to, zero);
    }

    // 全波を通した集計（機構の量は波で平均する。勝率だけは波ごとに出す）
    (double[] Wins, double Fired, double Total, double Taken, double Passed, double Zeroed,
     double MetRate, double First, double Never, double Doubled, double Swings,
     double Back, double BackHits, Dictionary<string, double> To, Dictionary<string, double> Zero)
    MeasureAll(Formation f, OverbearRule rule)
    {
        var wins = new double[obStages.Count];
        var to = new Dictionary<string, double>();
        var zero = new Dictionary<string, double>();
        double fired = 0, total = 0, taken = 0, passed = 0, zeroed = 0, met = 0, first = 0, firstN = 0;
        double never = 0, doubled = 0, swings = 0, back = 0, backHits = 0;
        for (int w = 0; w < obStages.Count; w++)
        {
            var z = MeasureOverbear(f, obStages[w].Enemy, rule);
            wins[w] = z.Win;
            fired += z.Fired; total += z.Total; taken += z.Taken; passed += z.Passed; zeroed += z.Zeroed;
            met += z.MetRate; never += z.Never; doubled += z.Doubled; swings += z.Swings;
            back += z.Back; backHits += z.BackHits;
            if (z.First > 0) { first += z.First; firstN++; }
            foreach (var kv in z.To) to[kv.Key] = to.TryGetValue(kv.Key, out double c) ? c + kv.Value : kv.Value;
            foreach (var kv in z.Zero) zero[kv.Key] = zero.TryGetValue(kv.Key, out double c) ? c + kv.Value : kv.Value;
        }
        double m = obStages.Count;
        foreach (string k in to.Keys.ToList()) to[k] /= m;
        foreach (string k in zero.Keys.ToList()) zero[k] /= m;
        return (wins, fired / m, total / m, taken / m, passed / m, zeroed / m, met / m,
                firstN > 0 ? first / firstN : 0, never / m, doubled / m, swings / m,
                back / m, backHits / m, to, zero);
    }

    static string ObCells(double[] w) => string.Concat(w.Select(x => $" {x:0.0}% |"));

    Console.WriteLine("# 驕り（overbear）");
    Console.WriteLine();
    Console.WriteLine("`dotnet run --project BattleSim -c Release 0 overbear [絞り込み]` の出力。");
    Console.WriteLine($"**docs/ には置かない**（標準出力で読むだけ）。seed 0..{ObSeeds - 1}。数字は特記なければ**1戦あたりの平均**。");
    Console.WriteLine();
    Console.WriteLine("`Stages` / `Columns` は触っていない。`CompareBuilds()` には**2行足した**（第45期の残件 C）。");
    Console.WriteLine();
    Console.WriteLine("| 列 | 中身 |");
    Console.WriteLine("|---|---|");
    Console.WriteLine("| 削り | 撒いた総量/戦（`OverbearTotal`）と延べ体数（`OverbearFired`） |");
    Console.WriteLine("| 成立率 | 条件を満たしていたターン数 ÷ 保持者がターン頭を迎えた回数（`MetTurns/Turns`） |");
    Console.WriteLine("| 成立T | **条件が初めて成立したターン**（成立した試行だけの平均）。`未成立` が成立しなかった試行の割合 |");
    Console.WriteLine("| 2倍 | 2倍が乗った攻撃回数/戦（`OverbearDoubled`）と振った回数（`OverbearSwings`） |");
    Console.WriteLine("| 横取り | ウケ／ワタが横取りした量/戦（`DullTakenByRoute[Overbear]`）＝**削りが資産に変わった量** |");
    Console.WriteLine("| 素通り | 読み手に届かずただの損になった量/戦 |");
    Console.WriteLine("| 逆行 | **削ったのに相手の `CurrentAttack` が上がった量**/戦（逆しまの自己矛盾） |");
    Console.WriteLine("| 攻ゼロ | 味方の `CurrentAttack` が 0 になった回数/戦（**崖の検算**・全経路） |");
    Console.WriteLine();

    // --- 0. 検算（受け入れ基準1・2）--------------------------------------------------------
    Console.WriteLine("## 0. 検算 —— 差分は驕りだけに閉じているか（受け入れ基準1・2）");
    Console.WriteLine();
    {
        var plain = obBuilds.Where(b => !ObHasOgo(b.F)).ToArray();   // 現状は 48 行すべて
        int cells = 0, diff = 0;
        foreach (var b in plain)
            for (int w = 0; w < obStages.Count; w++)
            {
                int a = 0, c = 0;
                for (int seed = 0; seed < ObSeeds; seed++)
                {
                    if (BattleEngine.Run(b.F, obStages[w].Enemy, seed, false,
                            null, null, null, null, null, null, null, null, null, new OverbearRule(0)).PlayerWon) a++;
                    if (BattleEngine.Run(b.F, obStages[w].Enemy, seed, false,
                            null, null, null, null, null, null, null, null, null, new OverbearRule(9)).PlayerWon) c++;
                }
                cells++;
                if (a != c) diff++;
            }
        Console.WriteLine($"- **基準2**（オゴを含まない {plain.Length} 行が `OverbearRule` の値に対して不変）: "
            + $"**{cells} セル中 {diff} 件の食い違い**（{plain.Length} 行 × {obStages.Count} 波・`Drain` 0 対 9）");
        Console.WriteLine("- **基準1**（新駒を編成に入れない状態で `compare` が `docs/balance.md` と完全一致）は");
        Console.WriteLine("  行を足す前に `compare` の全文 diff で確認する（**240 セル中 0 件**）。");
        Console.WriteLine();
        Console.Out.Flush();
    }

    // --- 1. 主表 ----------------------------------------------------------------------------
    Console.WriteLine($"## 1. 主表（`Drain = {ObMain}` と 陽性対照2本）");
    Console.WriteLine();
    Console.WriteLine("`D0` = `OverbearRule(0)`（削らない＝条件が永遠に成立しない＝**プラス側だけを切る**）。");
    Console.WriteLine("`4体` = オゴを外した同じ編成（**第21期の飽和検査**も兼ねる。4体版と5体版が同値なら台が測定になっていない）。");
    Console.WriteLine();
    Console.WriteLine("| 行 | 版 | 第1波 | 第2波 | 第3波 | 第4波 | 第5波 | 平均 |");
    Console.WriteLine("|---|---|--:|--:|--:|--:|--:|--:|");
    var obMain = new Dictionary<string, (double[] Wins, double Fired, double Total, double Taken,
        double Passed, double Zeroed, double MetRate, double First, double Never, double Doubled,
        double Swings, double Back, double BackHits, Dictionary<string, double> To,
        Dictionary<string, double> Zero)>();
    var obZero = new Dictionary<string, (double[] Wins, double Fired, double Total, double Taken,
        double Passed, double Zeroed, double MetRate, double First, double Never, double Doubled,
        double Swings, double Back, double BackHits, Dictionary<string, double> To,
        Dictionary<string, double> Zero)>();

    foreach (var b in obTargets)
    {
        var z = MeasureAll(b.F, new OverbearRule(ObMain));
        var z0 = MeasureAll(b.F, new OverbearRule(0));
        obMain[b.Name] = z;
        obZero[b.Name] = z0;
        var four = new double[obStages.Count];
        for (int w = 0; w < obStages.Count; w++)
        {
            int wins = 0;
            for (int seed = 0; seed < ObSeeds; seed++)
                if (BattleEngine.Run(ObWithoutOgo(b.F), obStages[w].Enemy, seed, false).PlayerWon) wins++;
            four[w] = wins * 100.0 / ObSeeds;
        }
        Console.WriteLine($"| {b.Name} | **D{ObMain}** |{ObCells(z.Wins)} {z.Wins.Average():0.0}% |");
        Console.WriteLine($"| | D0 |{ObCells(z0.Wins)} {z0.Wins.Average():0.0}% |");
        Console.WriteLine($"| | 4体 |{ObCells(four)} {four.Average():0.0}% |");
        Console.Out.Flush();
    }
    Console.WriteLine();

    Console.WriteLine($"### 機構の計数（`Drain` = {ObMain}・5波の平均）");
    Console.WriteLine();
    Console.WriteLine("| 行 | 削り(量/体) | 成立率 | 成立T | 未成立 | 2倍/振り | 横取り | 素通り | 横取り率 | 逆行(量/回) | 攻ゼロ |");
    Console.WriteLine("|---|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|");
    foreach (var b in obTargets)
    {
        var z = obMain[b.Name];
        double got = z.Taken + z.Passed;
        Console.WriteLine($"| {b.Name} | {z.Total:0.0} / {z.Fired:0.0} | {z.MetRate:0.0}% "
            + $"| {(z.First > 0 ? $"{z.First:0.00}" : "—")} | {z.Never:0.0}% "
            + $"| {z.Doubled:0.00} / {z.Swings:0.00} | {z.Taken:0.00} | {z.Passed:0.00} "
            + $"| {(got > 0 ? $"{z.Taken * 100 / got:0.0}%" : "—")} "
            + $"| {z.Back:0.0} / {z.BackHits:0.00} | {z.Zeroed:0.00} |");
    }
    Console.WriteLine();

    // --- 2. 削った相手と攻ゼロの内訳 --------------------------------------------------------
    Console.WriteLine($"## 2. 誰を削ったか / 誰が攻ゼロになったか（`Drain = {ObMain}`）");
    Console.WriteLine();
    foreach (var b in obTargets)
    {
        var z = obMain[b.Name];
        var z0 = obZero[b.Name];
        Console.WriteLine($"### {b.Name}");
        Console.WriteLine();
        Console.WriteLine("| 駒 | 素の攻 | 削られた量/戦 |");
        Console.WriteLine("|---|--:|--:|");
        foreach (var kv in z.To.OrderByDescending(k => k.Value))
        {
            var def = UnitCatalog.All.FirstOrDefault(u => u.Name == kv.Key);
            Console.WriteLine($"| {kv.Key} | {(def is null ? "—" : def.Attack.ToString())} | {kv.Value:0.00} |");
        }
        Console.WriteLine();
        Console.WriteLine("**攻ゼロの内訳（崖の検算・受け入れ基準4）。** 帰属は D0 との差で取る");
        Console.WriteLine("——`攻ゼロ` は窓口を通る全経路を数えるので、なまり・呪詛・萎縮のぶんが D0 側に載っている。");
        Console.WriteLine();
        Console.WriteLine($"| 駒 | 素の攻 | D0 | D{ObMain} | 差（＝驕りに帰属） |");
        Console.WriteLine("|---|--:|--:|--:|--:|");
        if (z.Zero.Count == 0 && z0.Zero.Count == 0) Console.WriteLine("| （0 件） | — | 0.00 | 0.00 | ±0.00 |");
        foreach (var kv in z.Zero.OrderByDescending(k => k.Value))
        {
            var def = UnitCatalog.All.FirstOrDefault(u => u.Name == kv.Key);
            double b0 = z0.Zero.TryGetValue(kv.Key, out double q) ? q : 0;
            Console.WriteLine($"| {kv.Key} | {(def is null ? "—" : def.Attack.ToString())} | {b0:0.00} "
                + $"| {kv.Value:0.00} | {kv.Value - b0:+0.00;-0.00;±0.00} |");
        }
        Console.WriteLine();
        Console.Out.Flush();
    }

    // --- 3. 成立時刻 × 席（**この期の核心**）------------------------------------------------
    Console.WriteLine("## 3. 成立時刻 × 席（**この期の核心**）");
    Console.WriteLine();
    Console.WriteLine("**オゴ1枚だけを動かす。** 他の4枚は元の相対順のまま空いた席へ詰める");
    Console.WriteLine("（`reseat` の120通りと違い、動かすのは1枚だけ＝席の効果を1変数に閉じる）。");
    Console.WriteLine();
    Console.WriteLine("**席と相方の両方で成立時刻が動かなければ、非単調にした意味が無い。**");
    Console.WriteLine();
    Console.WriteLine("`勝率(D0)` は同じ席配置で `OverbearRule(0)`（削らない＝条件が成立しない）を回した対照。");
    Console.WriteLine("**オゴを動かすと他の4枚の席も動く**ので、対照を置かないと席の差が機構の差かどうか決まらない。");
    Console.WriteLine();
    foreach (var b in obTargets)
    {
        Console.WriteLine($"### {b.Name}");
        Console.WriteLine();
        Console.WriteLine("| オゴの席 | 次数 | 隣接する駒（開幕） | 成立率 | 成立T | 未成立 | 2倍/振り | 削り | 横取り | 逆行 | 勝率(D0) | 勝率(D2) | 差 |");
        Console.WriteLine("|---|--:|---|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|");
        for (int seat = 0; seat < FormationRules.PlayableSlotCount; seat++)
        {
            Formation g = ObSeat(b.F, seat);
            int deg = 0;
            var names = new List<string>();
            foreach ((int slot, UnitDef d) in g.Occupied())
                if (slot != seat && FormationRules.AreAdjacent(seat, slot)) { deg++; names.Add($"{d.Name}({d.Attack})"); }
            var z = MeasureAll(g, new OverbearRule(ObMain));
            var zc = MeasureAll(g, new OverbearRule(0));   // 席の効果から機構の効果を割る対照
            Console.WriteLine($"| {FormationRules.SeatNames[seat]} | {deg} | {string.Join("・", names)} "
                + $"| {z.MetRate:0.0}% | {(z.First > 0 ? $"{z.First:0.00}" : "—")} | {z.Never:0.0}% "
                + $"| {z.Doubled:0.00} / {z.Swings:0.00} | {z.Total:0.0} | {z.Taken:0.00} | {z.Back:0.0} "
                + $"| {zc.Wins.Average():0.0}% | {z.Wins.Average():0.0}% "
                + $"| {z.Wins.Average() - zc.Wins.Average():+0.0;-0.0;±0.0} |");
            Console.Out.Flush();
        }
        Console.WriteLine();
    }

    // --- 4. 掃引 ----------------------------------------------------------------------------
    Console.WriteLine("## 4. 掃引（`Drain` 0 / 1 / 2 / 3）");
    Console.WriteLine();
    Console.WriteLine("**見るのは勝率ではなく「成立時刻」と「席」。** `Drain` は成立時刻を直接動かすノブなので、");
    Console.WriteLine("席の選び方も動くはず。動かなければ非単調化が効いていない証拠になる。");
    Console.WriteLine();
    Console.WriteLine("`最適席` は §3 の5変種のうち平均勝率が最大の席（**1位の値ではなく次数を読むこと**・第45期の残件 D）。");
    Console.WriteLine();
    Console.WriteLine("| 行 | Drain | 平均勝率 | 成立率 | 成立T | 未成立 | 2倍/振り | 削り | 横取り | 素通り | 逆行 | 攻ゼロ | 最適席(次数) |");
    Console.WriteLine("|---|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|---|");
    foreach (var b in obTargets)
    {
        foreach (int d in obDrains)
        {
            var z = MeasureAll(b.F, new OverbearRule(d));
            int best = -1; double bestAvg = double.MinValue;
            for (int seat = 0; seat < FormationRules.PlayableSlotCount; seat++)
            {
                var q = MeasureAll(ObSeat(b.F, seat), new OverbearRule(d));
                double avg = q.Wins.Average();
                if (avg > bestAvg) { bestAvg = avg; best = seat; }
            }
            int deg = 0;
            for (int i = 0; i < FormationRules.PlayableSlotCount; i++)
                if (FormationRules.AreAdjacent(best, i)) deg++;
            Console.WriteLine($"| {b.Name} | {d} | {z.Wins.Average():0.0}% | {z.MetRate:0.0}% "
                + $"| {(z.First > 0 ? $"{z.First:0.00}" : "—")} | {z.Never:0.0}% | {z.Doubled:0.00} / {z.Swings:0.00} "
                + $"| {z.Total:0.0} | {z.Taken:0.00} | {z.Passed:0.00} | {z.Back:0.0} | {z.Zeroed:0.00} "
                + $"| {FormationRules.SeatNames[best]}({deg}) {bestAvg:0.0}% |");
            Console.Out.Flush();
        }
    }
    Console.WriteLine();

    // --- 5. 席の分散（seats2 の写し・**受け入れ基準6**）--------------------------------------
    // `seats2` は `CompareBuilds()` の行しか見ないので、2行を外した後は同じ数字を出せない。
    // **探索と検証の作り方は `seats2` の写し**（粗探索 seed 0..49 の全120通り →
    // 上位20 + 現行 を seed 0..199 で測り直し）で、ここでローカルの2編成に対して回す。
    Console.WriteLine("## 5. 席の分散（`seats2` の写し・**受け入れ基準6・この期の主眼**）");
    Console.WriteLine();
    Console.WriteLine("粗探索 seed 0..49 の全 120 通り → 上位20 + 現行 を seed 0..199 で測り直し。");
    Console.WriteLine("**採否に使うのは1位の配置ではなく次数**（第45期の残件 D。1位は別 seed 帯で 48行中28行で");
    Console.WriteLine("入れ替わるが、次数の追試一致率は 98%）。");
    Console.WriteLine();
    Console.WriteLine("| 行 | 駒 | 最適席 | 次数 | 上位5の席（中央/角） | 幅 |");
    Console.WriteLine("|---|---|---|--:|---|--:|");
    foreach (var b in obTargets)
    {
        var members = b.F.Occupied().Select(x => x.Def).ToList();
        var perms = new List<Formation>();
        foreach (int[] assign in SlotAssignments(members.Count))
        {
            var g = new Formation();
            for (int m = 0; m < members.Count; m++) g[assign[m]] = members[m];
            perms.Add(g);
        }

        var scan = new int[perms.Count];
        for (int i = 0; i < perms.Count; i++)
        {
            int wins = 0;
            foreach (EnemyCatalog.Stage st in obStages)
                for (int seed = 0; seed < 50; seed++)
                    if (BattleEngine.Run(perms[i], st.Enemy, seed, verbose: false).PlayerWon) wins++;
            scan[i] = wins;
        }
        var order = Enumerable.Range(0, perms.Count).OrderByDescending(i => scan[i]).ThenBy(i => i).ToList();
        int curIdx = order.First(i => SameFormation(perms[i], b.F));
        var pool = order.Take(20).Append(curIdx).Append(order[^1]).Distinct().ToList();

        double Avg(Formation f)
        {
            double avg = 0;
            foreach (EnemyCatalog.Stage st in obStages)
            {
                int wins = 0;
                for (int seed = 0; seed < ObSeeds; seed++)
                    if (BattleEngine.Run(f, st.Enemy, seed, verbose: false).PlayerWon) wins++;
                avg += wins * 100.0 / ObSeeds;
            }
            return avg / obStages.Count;
        }

        var verified = pool.Select(i => (Idx: i, Avg: Avg(perms[i]))).OrderByDescending(x => x.Avg).ToList();
        double width = verified[0].Avg - verified[^1].Avg;
        var top5 = verified.Take(5).ToList();

        foreach (UnitDef d in members)
        {
            int bestSlot = -1;
            foreach ((int slot, UnitDef dd) in perms[verified[0].Idx].Occupied())
                if (ReferenceEquals(dd, d)) bestSlot = slot;
            int mid = 0, corner = 0;
            foreach (var v in top5)
                foreach ((int slot, UnitDef dd) in perms[v.Idx].Occupied())
                    if (ReferenceEquals(dd, d))
                    {
                        int deg2 = 0;
                        for (int i = 0; i < FormationRules.PlayableSlotCount; i++)
                            if (FormationRules.AreAdjacent(slot, i)) deg2++;
                        if (deg2 == 4) mid++; else corner++;
                    }
            int bdeg = 0;
            for (int i = 0; i < FormationRules.PlayableSlotCount; i++)
                if (FormationRules.AreAdjacent(bestSlot, i)) bdeg++;
            Console.WriteLine($"| {b.Name} | {d.Name} | {FormationRules.SeatNames[bestSlot]} | {bdeg} "
                + $"| 中央{mid} / 角{corner} | {width:0.0}pt |");
        }
        Console.Out.Flush();
    }
    Console.WriteLine();
    return;
}

// scale モード: アーマー（`StatusKeys.Armor`）に初めての読み手を作る（第47期）。
//
// **出力は docs/ に置かない**（標準出力で読むだけ）。
// `CompareBuilds()` / `Stages` / `Columns` は触らない。
//
//     dotnet run --project BattleSim -c Release 0 scale [絞り込み]
//     dotnet run --project BattleSim -c Release 0 scale phase0   # 実装前の地図（§2 Phase 0）
if (focusId == "scale")
{
    var scBuilds = CompareBuilds();
    IReadOnlyList<EnemyCatalog.Stage> scStages = EnemyCatalog.Stages;
    const int ScSeeds = 200;   // compare / spread / shove / dull / relay / slander / overbear と揃える
    const int ScMain = 1;      // 主表に使う CostPerAttack（探索段階の初期値）
    int[] scCosts = { 0, 1, 2 };

    string scMode = args.Length > 2 ? args[2] : "";

    // --- Phase 0（§2）: 実装の前に走らせる地図 ------------------------------------------------
    // **盤面を1つも動かさない純粋な記録。** 鱗の実装とは独立で、`ScaleRule` にも触れない。
    if (scMode == "phase0")
    {
        Console.WriteLine("# 鱗 Phase 0 —— 供給の地図（第47期 §2）");
        Console.WriteLine();
        Console.WriteLine($"`dotnet run --project BattleSim -c Release 0 scale phase0` の出力。seed 0..{ScSeeds - 1}。");
        Console.WriteLine("**盤面は1つも動かない。** 実装の前に走らせる測定で、`docs/` には置かない。");
        Console.WriteLine();

        // 0-3. 敵の範囲攻撃を波ごとに数える。
        // **砕け（ShatterTrait）は `source.CurrentPattern != Single` で発火する**ので、
        // 薙ぎ・全体だけでなく**貫きも破片を生む**。ここを単体/範囲の2値で数えると
        // ヒビの供給源を1波ぶん数え落とす。
        Console.WriteLine("## 0-3. 敵の範囲攻撃（＝砕けの供給源）を波ごとに数える");
        Console.WriteLine();
        Console.WriteLine("`ShatterTrait.OnDamaged` は `source.CurrentPattern == AttackPattern.Single` で早期 return するので、");
        Console.WriteLine("**薙ぎ・全体・貫きの3つすべてが破片を生む**（毒・燃焼は `source` が null なので外れる）。");
        Console.WriteLine();
        Console.WriteLine("| 波 | 範囲持ちの敵（席・型・溜め） | 範囲枚数 / 5 |");
        Console.WriteLine("|---|---|--:|");
        for (int w = 0; w < scStages.Count; w++)
        {
            var names = new List<string>();
            int cnt = 0;
            foreach ((int slot, UnitDef d) in scStages[w].Enemy.Occupied())
            {
                if (d.Pattern == AttackPattern.Single) continue;
                cnt++;
                string label = d.Pattern switch
                {
                    AttackPattern.Sweep => "薙ぎ",
                    AttackPattern.Pierce => "貫き",
                    AttackPattern.All => "全体",
                    _ => "単体"
                };
                bool charge = d.Actions is not null
                    && d.Actions.Any(a => a.Kind == ActionKind.Charge);
                names.Add($"{FormationRules.SeatNames[slot]}:{d.Name}({label}{(charge ? "・溜め" : "")})");
            }
            Console.WriteLine($"| {scStages[w].Name} | {(names.Count == 0 ? "—" : string.Join(" / ", names))} | {cnt} |");
        }
        Console.WriteLine();

        // 0-6. 味方の攻撃型の分布。**ロスターに常時の貫きは1枚も無い**ことの確認。
        Console.WriteLine("## 0-6. 味方の攻撃型の分布（`Def.Pattern`）と `ModifyPattern` の既存実装");
        Console.WriteLine();
        var pat = new Dictionary<AttackPattern, List<string>>();
        foreach (UnitDef d in UnitCatalog.All)
        {
            if (!pat.TryGetValue(d.Pattern, out var l)) pat[d.Pattern] = l = new List<string>();
            l.Add(d.Name);
        }
        Console.WriteLine("| 型 | 枚数 | 駒 |");
        Console.WriteLine("|---|--:|---|");
        foreach (AttackPattern p in new[] { AttackPattern.Single, AttackPattern.Sweep,
                                            AttackPattern.Pierce, AttackPattern.All })
        {
            var l = pat.TryGetValue(p, out var x) ? x : new List<string>();
            Console.WriteLine($"| {p} | {l.Count} | {(l.Count == 0 ? "—" : (l.Count > 6 ? "（略）" : string.Join("・", l)))} |");
        }
        Console.WriteLine();
        Console.WriteLine($"ロスターは {UnitCatalog.All.Count} 枚。**常時の貫きは 0 枚**で、");
        Console.WriteLine("貫きは `ModifyPattern` を通してしか立たない。");
        Console.WriteLine();

        // 0-4. 味方の1戦あたりの死亡数を波ごとに出す。**ウロの供給条件そのもの。**
        //
        // 蘇生（ヴェル）で戻ってから再度倒れると `Deaths` は2回数えるが、
        // **鱗の供給も `OnAllyDeath` が2回走る**ので、数え方は供給と揃っている。
        // 胞子（ムグ）の子は `Ephemeral` で、これも `OnAllyDeath` を通る（本文で扱う）。
        Console.WriteLine("## 0-4. 味方の死亡数（1戦あたり）を波ごとに出す");
        Console.WriteLine();
        Console.WriteLine("`UnitTally.Deaths` の味方側の合計 ÷ 試行数。**蘇生されて再度倒れると 2 と数える**");
        Console.WriteLine("（鱗の供給も `OnAllyDeath` が2回走るので、数え方は供給と揃っている）。");
        Console.WriteLine("`死軸` は リィカ・ムグ・ゾト・ヴェル・ラウ・ハギ のいずれかを含む行。");
        Console.WriteLine();
        Console.WriteLine("| 編成 | 死軸 | 第1波 | 第2波 | 第3波 | 第4波 | 第5波 | 平均 |");
        Console.WriteLine("|---|---|--:|--:|--:|--:|--:|--:|");
        string[] deathAxis = { "rica", "mug", "zoto", "vel", "rau", "hagi" };
        var deathRows = new List<(string Name, bool Axis, double[] D)>();
        foreach (var b in scBuilds)
        {
            var ids = b.F.Occupied().Select(o => o.Def.Id).ToHashSet();
            bool axis = deathAxis.Any(ids.Contains);
            var d = new double[scStages.Count];
            for (int w = 0; w < scStages.Count; w++)
            {
                int deaths = 0;
                for (int seed = 0; seed < ScSeeds; seed++)
                {
                    var r = BattleEngine.Run(b.F, scStages[w].Enemy, seed, verbose: false);
                    foreach ((string id, UnitTally t) in r.TallyByUnit)
                        if (UnitCatalog.All.Any(u => u.Id == id)
                            || id == "spore")   // 胞子は味方側の増援
                            deaths += t.Deaths;
                }
                d[w] = (double)deaths / ScSeeds;
            }
            deathRows.Add((b.Name, axis, d));
            Console.WriteLine($"| {b.Name} | {(axis ? "**●**" : "")} "
                + string.Concat(d.Select(x => $"| {x:0.00} ")) + $"| {d.Average():0.00} |");
            Console.Out.Flush();
        }
        Console.WriteLine();
        Console.WriteLine("| 群 | 行数 | 第1波 | 第2波 | 第3波 | 第4波 | 第5波 | 平均 |");
        Console.WriteLine("|---|--:|--:|--:|--:|--:|--:|--:|");
        foreach (var (label, sel) in new (string, Func<(string, bool, double[]), bool>)[]
                 { ("全 48 行", _ => true), ("死軸", x => x.Item2), ("死軸でない", x => !x.Item2) })
        {
            var g = deathRows.Select(x => (x.Name, x.Axis, x.D)).Where(sel).ToList();
            var avg = new double[scStages.Count];
            for (int w = 0; w < scStages.Count; w++) avg[w] = g.Average(x => x.Item3[w]);
            Console.WriteLine($"| {label} | {g.Count} "
                + string.Concat(avg.Select(x => $"| {x:0.00} ")) + $"| {avg.Average():0.00} |");
        }
        Console.WriteLine();
        return;
    }

    static bool ScHasUro(Formation f) => f.Occupied().Any(o => ReferenceEquals(o.Def, UnitCatalog.Uro));

    var scTargets = scBuilds.Where(b => ScHasUro(b.F)).ToArray();
    if (scMode.Length > 0 && scMode != "sweep" && scMode != "seats")
        scTargets = scTargets.Where(b => scMode.Split(',').Any(k => b.Name.Contains(k.Trim()))).ToArray();

    // ウロを外した同じ編成（4体版）。**第21期の飽和検査を兼ねる**
    // ——4体版と5体版が同じ値なら、その台では第5の駒が何であっても結果が変わらない。
    static Formation ScWithoutUro(Formation f)
    {
        var g = new Formation();
        foreach ((int slot, UnitDef d) in f.Occupied())
            if (!ReferenceEquals(d, UnitCatalog.Uro)) g[slot] = d;
        return g;
    }

    // **素体の対照。** ウロと数値・型・速さが1つも違わず、特性だけを持たない駒。
    // **`ScaleRule(0)` は消費を止めるだけで供給も発揮も止めない**ので、
    // あれだけでは「鱗が効いたのか、ただ 70/9/7 の体が入ったのか」が割れない
    // ——第41期の「符号を測りたい効果は、その効果だけを 0 にできるノブと対にして作ること」の
    // 実装漏れをここで塞ぐ（規則ではなく駒の側で塞ぐ。`ScaleRule` にノブを増やさない）。
    // カタログには載せない（`gradient` / `aim` / `guard` と同じ、診断のローカルの def）。
    UnitDef ScPlainDef = new()
    {
        Id = "uro_plain", Name = "素体のウロ", MaxHp = UnitCatalog.Uro.MaxHp,
        Attack = UnitCatalog.Uro.Attack, Speed = UnitCatalog.Uro.Speed,
        Traits = Array.Empty<TraitId>(), Pattern = UnitCatalog.Uro.Pattern
    };
    Formation ScPlain(Formation f)
    {
        var g = new Formation();
        foreach ((int slot, UnitDef d) in f.Occupied())
            g[slot] = ReferenceEquals(d, UnitCatalog.Uro) ? ScPlainDef : d;
        return g;
    }

    // ウロの席だけを振った5変種。他の4枚は元の相対順のまま空いた席へ詰める。
    static Formation ScSeat(Formation f, int seat)
    {
        var others = f.Occupied().Where(o => !ReferenceEquals(o.Def, UnitCatalog.Uro))
                      .Select(o => o.Def).ToList();
        var g = new Formation();
        g[seat] = UnitCatalog.Uro;
        int k = 0;
        for (int i = 0; i < FormationRules.PlayableSlotCount && k < others.Count; i++)
            if (i != seat) g[i] = others[k++];
        return g;
    }

    // 1つの（編成 × 波 × 規則）についての計測。**盤面は触らない**——`BattleResult` の計数を読むだけ。
    (double Win, double GainDeath, double GainShard, double GainEph, double Worn, double First,
     double Never, double Swings, double Pierce, double Back, double BackDmg,
     double SpentAtk, double SpentHit, double Depleted, double Leftover, double FullSoak, double Turns)
    MeasureScale(Formation f, Formation enemy, ScaleRule rule)
    {
        double win = 0, gd = 0, gs = 0, ge = 0, worn = 0, alive = 0, first = 0, firstN = 0, never = 0;
        double sw = 0, pi = 0, bk = 0, bd = 0, sa = 0, sh = 0, dep = 0, left = 0, soak = 0, turns = 0;
        for (int seed = 0; seed < ScSeeds; seed++)
        {
            var r = BattleEngine.Run(f, enemy, seed, verbose: false,
                                    null, null, null, null, null, null, null, null, null, null, rule);
            if (r.PlayerWon) win++;
            gd += r.ScaleGainDeath; gs += r.ScaleGainShatter; ge += r.ScaleGainEphemeral;
            worn += r.ScaleWornTurns; alive += r.ScaleAliveTurns;
            if (r.ScaleFirstTurn > 0) { first += r.ScaleFirstTurn; firstN++; } else never++;
            sw += r.ScaleSwings; pi += r.ScalePierceSwings;
            bk += r.ScaleBackHits; bd += r.ScaleBackDamage;
            sa += r.ScaleSpentAttack; sh += r.ScaleSpentHit;
            dep += r.ScaleDepleted; left += r.ScaleLeftover; soak += r.ScaleFullSoaks;
            turns += r.Turns;
        }
        double n = ScSeeds;
        return (win * 100 / n, gd / n, gs / n, ge / n, alive > 0 ? worn * 100 / alive : 0,
                firstN > 0 ? first / firstN : 0, never * 100 / n, sw / n, pi / n, bk / n, bd / n,
                sa / n, sh / n, dep / n, left / n, soak / n, turns / n);
    }

    // 全波を通した集計（機構の量は波で平均する。勝率だけは波ごとに残す）
    (double[] Wins, double GainDeath, double GainShard, double GainEph, double Worn, double First,
     double Never, double Swings, double Pierce, double Back, double BackDmg,
     double SpentAtk, double SpentHit, double Depleted, double Leftover, double FullSoak)
    ScAll(Formation f, ScaleRule rule)
    {
        var wins = new double[scStages.Count];
        double gd = 0, gs = 0, ge = 0, worn = 0, first = 0, firstN = 0, never = 0;
        double sw = 0, pi = 0, bk = 0, bd = 0, sa = 0, sh = 0, dep = 0, left = 0, soak = 0;
        for (int w = 0; w < scStages.Count; w++)
        {
            var z = MeasureScale(f, scStages[w].Enemy, rule);
            wins[w] = z.Win;
            gd += z.GainDeath; gs += z.GainShard; ge += z.GainEph; worn += z.Worn; never += z.Never;
            sw += z.Swings; pi += z.Pierce; bk += z.Back; bd += z.BackDmg;
            sa += z.SpentAtk; sh += z.SpentHit; dep += z.Depleted; left += z.Leftover; soak += z.FullSoak;
            if (z.First > 0) { first += z.First; firstN++; }
        }
        double m = scStages.Count;
        return (wins, gd / m, gs / m, ge / m, worn / m, firstN > 0 ? first / firstN : 0, never / m,
                sw / m, pi / m, bk / m, bd / m, sa / m, sh / m, dep / m, left / m, soak / m);
    }

    static string ScCells(double[] w) => string.Concat(w.Select(x => $" {x:0.0}% |"));

    Console.WriteLine("# 鱗（scale）");
    Console.WriteLine();
    Console.WriteLine("`dotnet run --project BattleSim -c Release 0 scale [絞り込み]` の出力。");
    Console.WriteLine($"**docs/ には置かない**（標準出力で読むだけ）。seed 0..{ScSeeds - 1}。数字は特記なければ**1戦あたりの平均**。");
    Console.WriteLine();
    Console.WriteLine("`Stages` / `Columns` は触っていない。`CompareBuilds()` には**2行足した**（供給源を変えた対）。");
    Console.WriteLine();
    Console.WriteLine("| 列 | 中身 |");
    Console.WriteLine("|---|---|");
    Console.WriteLine("| 獲得 | 破片の獲得量/戦。**内訳は 味方の死 / 砕けの破片**（`(儚)` は死のうち胞子ぶんの内数） |");
    Console.WriteLine("| 纏い率 | `Armor > 0` だったターン数 ÷ **ウロが生きてターン頭を迎えた回数** |");
    Console.WriteLine("| 初纏い | 初めて破片を得たターン（得た試行だけの平均）。`未纏` が一度も纏わなかった試行の割合 |");
    Console.WriteLine("| 貫き | 貫きで振った回数/戦（`振り` が総振り回数） |");
    Console.WriteLine("| **後列到達** | **貫きが後列の敵に当たった回数**/戦と、そのとき振り下ろした量（減衰後） |");
    Console.WriteLine("| 支出・攻 / 支出・被 | 攻撃で消費した量/戦 ／ 被弾で吸われた量/戦（**二重支出**） |");
    Console.WriteLine("| 枯渇 / 死蔵 | `Armor` が 0 に戻った回数/戦 ／ 決着時に残っていた量/戦 |");
    Console.WriteLine("| 受切 | 破片が被弾を**受け切った**回数/戦（受け切ると `OnDamaged` が呼ばれない＝§7-1 の干渉） |");
    Console.WriteLine();
    Console.WriteLine("> **「貫き」と「後列到達」は別の列。** 貫いた回数は成果ではない");
    Console.WriteLine("> ——後列に敵がいなければ単体攻撃と同じである。");
    Console.WriteLine();

    // --- 0. 検算（受け入れ基準1・2）--------------------------------------------------------
    if (scMode != "sweep" && scMode != "seats")
    {
        Console.WriteLine("## 0. 検算 —— 差分は鱗だけに閉じているか（受け入れ基準2）");
        Console.WriteLine();
        var plain = scBuilds.Where(b => !ScHasUro(b.F)).ToArray();   // 現状は既存 48 行
        int cells = 0, diff = 0;
        foreach (var b in plain)
            for (int w = 0; w < scStages.Count; w++)
            {
                int a = 0, c = 0;
                for (int seed = 0; seed < ScSeeds; seed++)
                {
                    if (BattleEngine.Run(b.F, scStages[w].Enemy, seed, false,
                            null, null, null, null, null, null, null, null, null, null,
                            new ScaleRule(0)).PlayerWon) a++;
                    if (BattleEngine.Run(b.F, scStages[w].Enemy, seed, false,
                            null, null, null, null, null, null, null, null, null, null,
                            new ScaleRule(9)).PlayerWon) c++;
                }
                cells++;
                if (a != c) diff++;
            }
        Console.WriteLine($"- **基準2**（ウロを含まない {plain.Length} 行が `ScaleRule` の値に対して不変）: "
            + $"**{cells} セル中 {diff} 件の食い違い**（{plain.Length} 行 × {scStages.Count} 波・`CostPerAttack` 0 対 9）");
        Console.WriteLine("- **基準1**（新駒を編成に入れない状態で `compare` が `docs/balance.md` と完全一致）は");
        Console.WriteLine("  行を足す前に `compare` の全文で確認済み（**240 セル中 0 件**）。");
        Console.WriteLine();
        Console.Out.Flush();
    }

    // --- 1. 主表 ----------------------------------------------------------------------------
    if (scMode != "sweep" && scMode != "seats")
    {
        Console.WriteLine($"## 1. 主表（`CostPerAttack = {ScMain}` と 陽性対照2本）");
        Console.WriteLine();
        Console.WriteLine("`C0` = `ScaleRule(0)`（**消費しない＝維持型**）。**強度ではなく性質を切るノブ**なので、");
        Console.WriteLine("これは「弱くした版」ではなく「別の駒」。");
        Console.WriteLine("`素体` = ウロと**数値・型・速さが1つも違わず特性だけを持たない駒**に差し替えた版。");
        Console.WriteLine("**これが機構の帰属を取る唯一の窓口**——`C0` は消費を止めるだけで供給も発揮も止めない。");
        Console.WriteLine("`4体` = ウロを外した同じ編成（**第21期の飽和検査**も兼ねる）。");
        Console.WriteLine("`土台` = ウロの席に元の駒（死軸＝ヴェル / ヒビ台＝リィカ）が入っている既存行。");
        Console.WriteLine();
        Console.WriteLine("| 行 | 版 | 第1波 | 第2波 | 第3波 | 第4波 | 第5波 | 平均 |");
        Console.WriteLine("|---|---|--:|--:|--:|--:|--:|--:|");
        foreach (var b in scTargets)
        {
            var z = ScAll(b.F, new ScaleRule(ScMain));
            var z0 = ScAll(b.F, new ScaleRule(0));
            var four = new double[scStages.Count];
            for (int w = 0; w < scStages.Count; w++)
            {
                int wins = 0;
                for (int seed = 0; seed < ScSeeds; seed++)
                    if (BattleEngine.Run(ScWithoutUro(b.F), scStages[w].Enemy, seed, false).PlayerWon) wins++;
                four[w] = wins * 100.0 / ScSeeds;
            }
            var plainW = new double[scStages.Count];
            for (int w = 0; w < scStages.Count; w++)
            {
                int wins = 0;
                for (int seed = 0; seed < ScSeeds; seed++)
                    if (BattleEngine.Run(ScPlain(b.F), scStages[w].Enemy, seed, false).PlayerWon) wins++;
                plainW[w] = wins * 100.0 / ScSeeds;
            }
            Console.WriteLine($"| {b.Name} | **C{ScMain}** |{ScCells(z.Wins)} {z.Wins.Average():0.0}% |");
            Console.WriteLine($"| | C0（維持型） |{ScCells(z0.Wins)} {z0.Wins.Average():0.0}% |");
            Console.WriteLine($"| | 素体（特性なし・同数値） |{ScCells(plainW)} {plainW.Average():0.0}% |");
            Console.WriteLine($"| | 4体 |{ScCells(four)} {four.Average():0.0}% |");
            Console.Out.Flush();
        }
        // 土台（既存行）を同じ物差しで並べる
        foreach (string baseName in new[] { "死の連鎖 (リィカ軸)", "範囲耐性 (ヒビ×ボルグ)" })
        {
            var bb = scBuilds.FirstOrDefault(x => x.Name == baseName);
            if (bb.F is null) continue;
            var wv = new double[scStages.Count];
            for (int w = 0; w < scStages.Count; w++)
            {
                int wins = 0;
                for (int seed = 0; seed < ScSeeds; seed++)
                    if (BattleEngine.Run(bb.F, scStages[w].Enemy, seed, false).PlayerWon) wins++;
                wv[w] = wins * 100.0 / ScSeeds;
            }
            Console.WriteLine($"| 土台: {baseName} | — |{ScCells(wv)} {wv.Average():0.0}% |");
            Console.Out.Flush();
        }
        Console.WriteLine();

        Console.WriteLine($"### 機構の計数（`CostPerAttack` = {ScMain}・5波の平均）");
        Console.WriteLine();
        Console.WriteLine("| 行 | 獲得(死/破片) | (儚) | 纏い率 | 初纏い | 未纏 | 貫き/振り | **後列到達(回/量)** | 支出・攻 | 支出・被 | 枯渇 | 死蔵 | 受切 |");
        Console.WriteLine("|---|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|");
        foreach (var b in scTargets)
        {
            var z = ScAll(b.F, new ScaleRule(ScMain));
            Console.WriteLine($"| {b.Name} | {z.GainDeath:0.0} / {z.GainShard:0.0} | {z.GainEph:0.0} "
                + $"| {z.Worn:0.0}% | {(z.First > 0 ? $"{z.First:0.00}" : "—")} | {z.Never:0.0}% "
                + $"| {z.Pierce:0.00} / {z.Swings:0.00} | {z.Back:0.00} / {z.BackDmg:0.0} "
                + $"| {z.SpentAtk:0.0} | {z.SpentHit:0.0} | {z.Depleted:0.00} | {z.Leftover:0.0} | {z.FullSoak:0.00} |");
            Console.Out.Flush();
        }
        Console.WriteLine();

        // --- 2. 波ごとの内訳（供給の時間分布がこの期の設計）------------------------------------
        Console.WriteLine($"## 2. 波ごとの内訳（`CostPerAttack = {ScMain}`）—— 供給の時間分布");
        Console.WriteLine();
        Console.WriteLine("**「初纏い」と「後列到達」を波ごとに読む。** 第一波は敵が3体（前1・前3・中央）で");
        Console.WriteLine("**後列が存在しない**ので、貫いても到達は構造的に 0 になる。");
        Console.WriteLine();
        foreach (var b in scTargets)
        {
            Console.WriteLine($"### {b.Name}");
            Console.WriteLine();
            Console.WriteLine("| 波 | 勝率 | 獲得(死/破片) | 纏い率 | 初纏い | 未纏 | 貫き/振り | 後列到達(回/量) | 到達率 | 支出・攻 | 支出・被 | 決着T |");
            Console.WriteLine("|---|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|");
            for (int w = 0; w < scStages.Count; w++)
            {
                var z = MeasureScale(b.F, scStages[w].Enemy, new ScaleRule(ScMain));
                Console.WriteLine($"| {scStages[w].Name} | {z.Win:0.0}% | {z.GainDeath:0.0} / {z.GainShard:0.0} "
                    + $"| {z.Worn:0.0}% | {(z.First > 0 ? $"{z.First:0.00}" : "—")} | {z.Never:0.0}% "
                    + $"| {z.Pierce:0.00} / {z.Swings:0.00} | {z.Back:0.00} / {z.BackDmg:0.0} "
                    + $"| {(z.Pierce > 0 ? $"{z.Back * 100 / z.Pierce:0.0}%" : "—")} "
                    + $"| {z.SpentAtk:0.0} | {z.SpentHit:0.0} | {z.Turns:0.0} |");
                Console.Out.Flush();
            }
            Console.WriteLine();
        }
    }

    // --- 3. 掃引（受け入れ基準9）------------------------------------------------------------
    if (scMode.Length == 0 || scMode == "sweep")
    {
        Console.WriteLine("## 3. 掃引（`CostPerAttack` 0 / 1 / 2）");
        Console.WriteLine();
        Console.WriteLine("**`0` は維持型・`1` 以上は消費型**なので、このノブは強度ではなく**性質**を切っている（はず）。");
        Console.WriteLine("**`0` が明確に強いだけなら、切っているのは性質ではなく強度**（第41期と同じ結末）。");
        Console.WriteLine();
        Console.WriteLine("| 行 | Cost | 平均勝率 | 第1波 | 第2波 | 第3波 | 第4波 | 第5波 | 纏い率 | 貫き/振り | 後列到達 | 支出・攻 | 支出・被 | 枯渇 | 死蔵 |");
        Console.WriteLine("|---|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|");
        foreach (var b in scTargets)
            foreach (int c in scCosts)
            {
                var z = ScAll(b.F, new ScaleRule(c));
                Console.WriteLine($"| {b.Name} | {c} | **{z.Wins.Average():0.0}%** |{ScCells(z.Wins)} "
                    + $"{z.Worn:0.0}% | {z.Pierce:0.00} / {z.Swings:0.00} | {z.Back:0.00} "
                    + $"| {z.SpentAtk:0.0} | {z.SpentHit:0.0} | {z.Depleted:0.00} | {z.Leftover:0.0} |");
                Console.Out.Flush();
            }
        Console.WriteLine();
    }

    // --- 4. 席の分散（seats2 の写し・受け入れ基準10）-----------------------------------------
    if (scMode.Length == 0 || scMode == "seats")
    {
        Console.WriteLine("## 4. 席の分散（`seats2` の写し・受け入れ基準10）");
        Console.WriteLine();
        Console.WriteLine("粗探索 seed 0..49 の全 120 通り → 上位20 + 現行 + 最下位 を seed 0..199 で測り直し。");
        Console.WriteLine("**採否に使うのは1位の配置ではなく次数**（第45期の残件 D）。");
        Console.WriteLine("**鱗は隣接を1つも読まない**ので、第45期の対照（隣接も列も読まない駒＝最頻率 65%）が比較先。");
        Console.WriteLine();
        Console.WriteLine("| 行 | 駒 | 最適席 | 次数 | 上位5の席（3値） | 最頻率 | 幅 |");
        Console.WriteLine("|---|---|---|--:|---|--:|--:|");
        foreach (var b in scTargets)
        {
            var members = b.F.Occupied().Select(x => x.Def).ToList();
            var perms = new List<Formation>();
            foreach (int[] assign in SlotAssignments(members.Count))
            {
                var g = new Formation();
                for (int m = 0; m < members.Count; m++) g[assign[m]] = members[m];
                perms.Add(g);
            }
            var scan = new int[perms.Count];
            for (int i = 0; i < perms.Count; i++)
            {
                int wins = 0;
                foreach (EnemyCatalog.Stage st in scStages)
                    for (int seed = 0; seed < 50; seed++)
                        if (BattleEngine.Run(perms[i], st.Enemy, seed, verbose: false).PlayerWon) wins++;
                scan[i] = wins;
            }
            var order = Enumerable.Range(0, perms.Count).OrderByDescending(i => scan[i]).ThenBy(i => i).ToList();
            int curIdx = order.First(i => SameFormation(perms[i], b.F));
            var pool = order.Take(20).Append(curIdx).Append(order[^1]).Distinct().ToList();

            double Avg(Formation f)
            {
                double avg = 0;
                foreach (EnemyCatalog.Stage st in scStages)
                {
                    int wins = 0;
                    for (int seed = 0; seed < ScSeeds; seed++)
                        if (BattleEngine.Run(f, st.Enemy, seed, verbose: false).PlayerWon) wins++;
                    avg += wins * 100.0 / ScSeeds;
                }
                return avg / scStages.Count;
            }

            var verified = pool.Select(i => (Idx: i, Avg: Avg(perms[i]))).OrderByDescending(x => x.Avg).ToList();
            double width = verified[0].Avg - verified[^1].Avg;
            var top5 = verified.Take(5).ToList();

            foreach (UnitDef d in members)
            {
                int bestSlot = -1;
                foreach ((int slot, UnitDef dd) in perms[verified[0].Idx].Occupied())
                    if (ReferenceEquals(dd, d)) bestSlot = slot;
                // 第45期の3値（前角 / 中央 / 後角）。**2値（中央/角）だと行と列が混ざる**
                // ——鱗は隣接を読まないが貫きはレーンを走るので、効くとしたら列の側。
                int mid = 0, fcorner = 0, bcorner = 0;
                foreach (var v in top5)
                    foreach ((int slot, UnitDef dd) in perms[v.Idx].Occupied())
                        if (ReferenceEquals(dd, d))
                        {
                            int deg2 = 0;
                            for (int i = 0; i < FormationRules.PlayableSlotCount; i++)
                                if (FormationRules.AreAdjacent(slot, i)) deg2++;
                            if (deg2 == 4) mid++;
                            else if (FormationRules.RowOf(slot) == Row.Front) fcorner++;
                            else bcorner++;
                        }
                int bdeg = 0;
                for (int i = 0; i < FormationRules.PlayableSlotCount; i++)
                    if (FormationRules.AreAdjacent(bestSlot, i)) bdeg++;
                int top = Math.Max(mid, Math.Max(fcorner, bcorner));
                Console.WriteLine($"| {b.Name} | {d.Name} | {FormationRules.SeatNames[bestSlot]} | {bdeg} "
                    + $"| 前角{fcorner} / 中央{mid} / 後角{bcorner} | {top * 100 / 5}% | {width:0.0}pt |");
            }
            Console.Out.Flush();
        }
        Console.WriteLine();

        Console.WriteLine("### ウロ1枚だけを振った5変種（他の4枚は元の相対順のまま詰める）");
        Console.WriteLine();
        Console.WriteLine("| 行 | ウロの席 | 次数 | 纏い率 | 初纏い | 貫き/振り | 後列到達 | 支出・攻 | 支出・被 | 平均勝率 |");
        Console.WriteLine("|---|---|--:|--:|--:|--:|--:|--:|--:|--:|");
        foreach (var b in scTargets)
            for (int seat = 0; seat < FormationRules.PlayableSlotCount; seat++)
            {
                Formation g = ScSeat(b.F, seat);
                int deg = 0;
                for (int i = 0; i < FormationRules.PlayableSlotCount; i++)
                    if (FormationRules.AreAdjacent(seat, i)) deg++;
                var z = ScAll(g, new ScaleRule(ScMain));
                Console.WriteLine($"| {b.Name} | {FormationRules.SeatNames[seat]} | {deg} | {z.Worn:0.0}% "
                    + $"| {(z.First > 0 ? $"{z.First:0.00}" : "—")} | {z.Pierce:0.00} / {z.Swings:0.00} "
                    + $"| {z.Back:0.00} | {z.SpentAtk:0.0} | {z.SpentHit:0.0} | {z.Wins.Average():0.0}% |");
                Console.Out.Flush();
            }
        Console.WriteLine();
    }

    return;
}

if (focusId == "scapegoat" && (args.Length > 2 ? args[2] : "") == "phase0") { ScapegoatDiag.Phase0(args, stageIndex); return; }

if (focusId == "scapegoat") { ScapegoatDiag.Run(args, stageIndex); return; }

if (focusId == "divert" && (args.Length > 2 ? args[2] : "") == "phase0") { DivertDiag.Phase0(args, stageIndex); return; }

if (focusId == "divert" && (args.Length > 2 ? args[2] : "") == "probe") { DivertDiag.Probe(args, stageIndex); return; }

if (focusId == "divert") { DivertDiag.Run(args, stageIndex); return; }

// census モード: 棚卸し（第48期）。**駒と通貨の対応表を作るための素材だけを機械的に出す。**
//
// ロスターの上限を52体と決めたので、新規追加の合否テストに「どの通貨の空白を埋めるか」を
// 足す必要が出た。その判断に要る員数（分母）と、`CompareBuilds()` の走査結果を出す。
//
// **盤面は1つも動かさない。** 戦闘を1回も回さないので所要は1秒未満。
// `Traits.cs` / `UnitCatalog.cs` / `Stages` / `CompareBuilds()` には1行も触れていない。
//
// **通貨の書き手/読み手の判定はここでは行わない**（grep と目視で報告書に手で書く。§3）。
// ここが出すのは員数・compare の出現数・特性の保持者一覧＝**判定の分母**だけ。
// Trait に属性を足して自動判定させる案は採らない——判定の根拠が
// 「誰かが属性を正しく付けたか」に化けて、grep で検算できなくなる。
//
// **出力は docs/ に置かない**（標準出力で読むだけ）。
//
//     dotnet run --project BattleSim -c Release 0 census
if (focusId == "census")
{
    const int RosterCap = 52;   // トランプ1組（ジョーカーを除く）

    // 反射で拾うのは「定義された `UnitDef`」——`All` に載っていない残置駒
    // （第44期の誹り・第46期の驕り）を数えるには、リストではなくフィールドを見るしかない。
    static (string Field, UnitDef Def)[] CsDefs(Type t) =>
        t.GetFields(System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Static)
         .Where(f => f.FieldType == typeof(UnitDef))
         .Select(f => (f.Name, (UnitDef)f.GetValue(null)!))
         .ToArray();

    static string CsTraits(UnitDef d)
        => d.Traits is { Count: > 0 } tr ? string.Join(", ", tr.Select(t => t.ToString())) : "—";

    var csAllyDefs = CsDefs(typeof(UnitCatalog));
    var csEnemyDefs = CsDefs(typeof(EnemyCatalog));
    var csRoster = UnitCatalog.All;
    var csRosterIds = csRoster.Select(u => u.Id).ToHashSet();
    var csOrphans = csAllyDefs.Where(d => !csRosterIds.Contains(d.Def.Id)).ToArray();

    var csBuilds = CompareBuilds();
    var csStages = EnemyCatalog.Stages;

    Console.WriteLine("# 棚卸し —— 駒と通貨の対応表の素材（第48期 census）");
    Console.WriteLine();
    Console.WriteLine("`dotnet run --project BattleSim -c Release 0 census` の出力。**docs/ には置かない。**");
    Console.WriteLine("戦闘を1回も回していない（盤面は1つも動かない）。");
    Console.WriteLine();

    // --- Phase 0-1: 員数 ---------------------------------------------------------------------
    Console.WriteLine("## Phase 0-1: `UnitDef` の員数");
    Console.WriteLine();
    Console.WriteLine("| 区分 | 数 |");
    Console.WriteLine("|---|--:|");
    Console.WriteLine($"| 味方 `UnitDef` の定義 | {csAllyDefs.Length} |");
    Console.WriteLine($"| うち `UnitCatalog.All` に登録 | {csRoster.Count} |");
    Console.WriteLine($"| うち `All` に載っていない | {csOrphans.Length} |");
    Console.WriteLine($"| 敵 `UnitDef` の定義 | {csEnemyDefs.Length} |");
    Console.WriteLine();
    Console.WriteLine("**`All` に載っていない味方の駒**（52 の分母に数えるかどうかの論点）:");
    Console.WriteLine();
    Console.WriteLine("| フィールド | Id | 名前 | 特性 |");
    Console.WriteLine("|---|---|---|---|");
    foreach (var (field, d) in csOrphans)
        Console.WriteLine($"| `{field}` | `{d.Id}` | {d.Name} | {CsTraits(d)} |");
    Console.WriteLine();
    Console.WriteLine($"残り枠 = {RosterCap} − {csRoster.Count}（`All` のみ）= **{RosterCap - csRoster.Count}** ／ "
        + $"{RosterCap} − {csAllyDefs.Length}（定義すべて）= **{RosterCap - csAllyDefs.Length}**");
    Console.WriteLine();

    // --- Phase 0-2: StatusKeys ---------------------------------------------------------------
    Console.WriteLine("## Phase 0-2: `StatusKeys.All`");
    Console.WriteLine();
    Console.WriteLine($"要素数 **{StatusKeys.All.Length}**。主表の 1〜{StatusKeys.All.Length} はこれで確定する。");
    Console.WriteLine();
    Console.WriteLine("| # | 値 |");
    Console.WriteLine("|--:|---|");
    for (int i = 0; i < StatusKeys.All.Length; i++)
        Console.WriteLine($"| {i + 1} | `{StatusKeys.All[i]}` |");
    Console.WriteLine();

    // --- Phase 0-3: CompareBuilds の走査 ------------------------------------------------------
    var csRows = new Dictionary<string, List<string>>();
    foreach (var b in csBuilds)
        foreach (var (_, d) in b.F.Occupied())
        {
            if (!csRows.TryGetValue(d.Id, out var lst)) csRows[d.Id] = lst = new List<string>();
            if (!lst.Contains(b.Name)) lst.Add(b.Name);
        }

    int CsCount(string id) => csRows.TryGetValue(id, out var l) ? l.Count : 0;

    Console.WriteLine("## Phase 0-3: `CompareBuilds()` の走査");
    Console.WriteLine();
    Console.WriteLine($"行数 **{csBuilds.Length}**。同じ編成に同じ駒は2枚入らないので、出現数＝行数。");
    Console.WriteLine();
    Console.WriteLine("| 駒 | Id | 行数 | 出ている編成 |");
    Console.WriteLine("|---|---|--:|---|");
    foreach (var u in csRoster.OrderByDescending(u => CsCount(u.Id)).ThenBy(u => u.Id))
        Console.WriteLine($"| {u.Name} | `{u.Id}` | {CsCount(u.Id)} | "
            + (CsCount(u.Id) == 0 ? "**—（一度も出ていない）**" : string.Join(" / ", csRows[u.Id])) + " |");
    Console.WriteLine();

    var csUnused = csRoster.Where(u => CsCount(u.Id) == 0).ToArray();
    Console.WriteLine($"**一度も compare に載っていない駒: {csUnused.Length} 体**（表D の母集団）");
    Console.WriteLine();
    Console.WriteLine("| 駒 | Id | 特性 |");
    Console.WriteLine("|---|---|---|");
    foreach (var u in csUnused)
        Console.WriteLine($"| {u.Name} | `{u.Id}` | {CsTraits(u)} |");
    Console.WriteLine();
    Console.WriteLine("`All` に載っていない駒（Phase 0-1）は定義上ここに含まれない——");
    Console.WriteLine("**「ロスターに載っていない」と「ロスターに載っているのに使われていない」は別の話**なので分けて数える。");
    Console.WriteLine();

    // --- Phase 0-4: 回帰チェックの分母 --------------------------------------------------------
    Console.WriteLine("## Phase 0-4: `docs/balance.md` の分母");
    Console.WriteLine();
    Console.WriteLine($"編成 **{csBuilds.Length}** 行 × 波 **{csStages.Count}** = **{csBuilds.Length * csStages.Count} セル**。");
    Console.WriteLine("§4-1 の回帰チェック（`compare` の食い違い0件）はこの分母で数える。");
    Console.WriteLine();

    // --- 付表1: 駒 × 特性（表B の素材） -------------------------------------------------------
    Console.WriteLine("## 付表1: 駒 × 特性（表B の索引）");
    Console.WriteLine();
    Console.WriteLine("**特性は通貨ではない。** この表は「どの Trait クラスを grep すればよいか」の索引にすぎず、");
    Console.WriteLine("通貨の書き手/読み手はここからは決まらない（1つの特性が複数の通貨を書く場合がある）。");
    Console.WriteLine();
    Console.WriteLine("| 駒 | Id | 陣営 | `All` | 特性 | compare 行数 |");
    Console.WriteLine("|---|---|---|---|---|--:|");
    foreach (var (_, d) in csAllyDefs.OrderBy(x => x.Def.Id))
        Console.WriteLine($"| {d.Name} | `{d.Id}` | 味方 | {(csRosterIds.Contains(d.Id) ? "○" : "**×**")} "
            + $"| {CsTraits(d)} | {CsCount(d.Id)} |");
    foreach (var (_, d) in csEnemyDefs.OrderBy(x => x.Def.Id))
        Console.WriteLine($"| {d.Name} | `{d.Id}` | 敵 | — | {CsTraits(d)} | — |");
    Console.WriteLine();

    // --- 付表2: 特性 → 保持者（表C の素材） -------------------------------------------------
    Console.WriteLine("## 付表2: 特性 → 保持者（表C の素材）");
    Console.WriteLine();
    Console.WriteLine("**唯一性の判定そのものではない**（唯一性は通貨について問うもので、特性についてではない）。");
    Console.WriteLine("保持者が1体の特性は、その駒を切ると**その特性の実装が誰にも使われなくなる**という別の意味を持つ。");
    Console.WriteLine();
    Console.WriteLine("| 特性 | 味方の保持者 | 敵の保持者 | 味方数 | 敵数 |");
    Console.WriteLine("|---|---|---|--:|--:|");
    foreach (TraitId t in Enum.GetValues<TraitId>())
    {
        var a = csAllyDefs.Where(x => x.Def.Traits is { } tr && tr.Contains(t)).Select(x => x.Def.Name).ToArray();
        var e = csEnemyDefs.Where(x => x.Def.Traits is { } tr && tr.Contains(t)).Select(x => x.Def.Name).ToArray();
        Console.WriteLine($"| {t} | {(a.Length == 0 ? "—" : string.Join(" / ", a))} "
            + $"| {(e.Length == 0 ? "—" : string.Join(" / ", e))} | {a.Length} | {e.Length} |");
    }
    Console.WriteLine();

    // --- 付表3: 敵の駒 × Stages ---------------------------------------------------------------
    var csInStage = new Dictionary<string, List<string>>();
    foreach (var st in csStages)
        foreach (var (_, d) in st.Enemy.Occupied())
        {
            if (!csInStage.TryGetValue(d.Id, out var lst)) csInStage[d.Id] = lst = new List<string>();
            if (!lst.Contains(st.Name)) lst.Add(st.Name);
        }

    Console.WriteLine("## 付表3: 敵の駒 × `Stages`");
    Console.WriteLine();
    Console.WriteLine("敵側の「事実上すでにリストラされている駒」。味方の表D と対になる。");
    Console.WriteLine("`Columns` は `Stages` の並べ替えなので、ここに出ない駒はどの部隊列にも出ない。");
    Console.WriteLine();
    Console.WriteLine("| 駒 | Id | 波数 | 出ている波 |");
    Console.WriteLine("|---|---|--:|---|");
    foreach (var (_, d) in csEnemyDefs
        .OrderByDescending(x => csInStage.TryGetValue(x.Def.Id, out var l) ? l.Count : 0)
        .ThenBy(x => x.Def.Id))
    {
        var l = csInStage.TryGetValue(d.Id, out var v) ? v : new List<string>();
        Console.WriteLine($"| {d.Name} | `{d.Id}` | {l.Count} | {(l.Count == 0 ? "**—**" : string.Join(" / ", l))} |");
    }
    Console.WriteLine();

    return;
}

if (focusId == "guard")
{
    string guardMode = args.Length > 2 ? args[2] : "";
    var gBuilds = CompareBuilds();
    const int GuardSeeds = 200;   // compare / spread と同じ。セルを突き合わせるので変えない
    const int GuardLogSeeds = 50; // 機構の指標だけ verbose で回す本数
    int[] gHps = { 52, 71, 90, 145 };
    int gnb = gBuilds.Length, gnh = gHps.Length;

    // 殉教者の HP だけを差し替えた複製。Id・名前・攻・速・型・特性はカタログのまま。
    UnitDef MartyrWithHp(int hp) => new UnitDef
    {
        Id = EnemyCatalog.Martyr.Id, Name = EnemyCatalog.Martyr.Name,
        MaxHp = hp, Attack = EnemyCatalog.Martyr.Attack, Speed = EnemyCatalog.Martyr.Speed,
        Traits = EnemyCatalog.Martyr.Traits, Pattern = EnemyCatalog.Martyr.Pattern,
        PlusText = EnemyCatalog.Martyr.PlusText, MinusText = EnemyCatalog.Martyr.MinusText,
        Flavor = EnemyCatalog.Martyr.Flavor,
    };

    // **対照: 庇うを外して HP だけ同じにした版。** HP を上げると介入の窓が伸びるが、
    // 同時に**波の総HPも増える**（前列が厚くなる）。この2つを分けないと、
    // 用量反応が「介入が効いた」なのか「ただ硬くなった」なのかが決まらない
    // ——渇き・軛・粛が「規則を無効にした同数値の版」を必ず対照に置いたのと同じ理由。
    UnitDef PlainWithHp(int hp) => new UnitDef
    {
        Id = EnemyCatalog.Axeman2.Id, Name = EnemyCatalog.Axeman2.Name,
        MaxHp = hp, Attack = EnemyCatalog.Axeman2.Attack, Speed = EnemyCatalog.Axeman2.Speed,
        Traits = EnemyCatalog.Axeman2.Traits, Pattern = EnemyCatalog.Axeman2.Pattern,
    };

    // 第五波の残り4枠はカタログのまま。**動く変数は前1の HP と庇うの有無だけ。**
    Formation Wave5WithHp(int hp) => Formation.Build(
        front1: MartyrWithHp(hp), front3: EnemyCatalog.Hero2, center: EnemyCatalog.Knight2,
        back1: EnemyCatalog.Seer, back3: EnemyCatalog.Lancer);

    Formation Wave5PlainHp(int hp) => Formation.Build(
        front1: PlainWithHp(hp), front3: EnemyCatalog.Hero2, center: EnemyCatalog.Knight2,
        back1: EnemyCatalog.Seer, back3: EnemyCatalog.Lancer);

    // ログ行から殉教者の（発火・最終攻・生存T）を取る。gullet log / yoke log / hush と同じ理由
    // ——**発火しなかったことは盤面の値に痕跡を残さない**（庇いは標的を差し替えるだけ）。
    static int TurnOf(string t, int cur)
    {
        if (!t.StartsWith("--- ターン ")) return cur;
        int from = "--- ターン ".Length, to = t.IndexOf(' ', from);
        return to > from && int.TryParse(t.Substring(from, to - from), out int n) ? n : cur;
    }

    static (int Fire, int Atk, int Life) MartyrStats(BattleResult r)
    {
        int turn = 0, death = -1, fire = 0, atk = EnemyCatalog.Martyr.Attack;
        foreach (LogLine line in r.Log)
        {
            string t = line.Text;
            turn = TurnOf(t, turn);
            if (!t.Contains("殉教者")) continue;
            if (t.Contains("を庇った")) fire++;
            else if (t.Contains("殉教者 は倒れた") && death < 0) death = turn;
            else if (t.Contains("誓いを思い出させる"))
            {
                int arrow = t.LastIndexOf('→');
                if (arrow >= 0 && int.TryParse(new string(t.Substring(arrow + 1)
                        .Where(char.IsDigit).ToArray()), out int m)) atk = m;
            }
        }
        return (fire, atk, death < 0 ? r.Turns : death);
    }

    // 勇者候補が落ちたターン（落ちなければ決着ターン）。**庇いの窓を閉じる律速**。
    static int HeroDeathTurn(BattleResult r)
    {
        int turn = 0;
        foreach (LogLine line in r.Log)
        {
            turn = TurnOf(line.Text, turn);
            if (line.Text.Contains("勇者候補 は倒れた")) return turn;
        }
        return r.Turns;
    }

    // ---- 第2〜4波（殉教者がいないので HP を振っても不変）--------------------------------
    var gOther = new double[gnb][];   // gOther[編成][波] 波は 0..4（第1波と第5波は使わない）
    for (int b = 0; b < gnb; b++)
    {
        gOther[b] = new double[EnemyCatalog.Stages.Count];
        for (int w = 1; w <= 3; w++)
        {
            int wins = 0;
            for (int seed = 0; seed < GuardSeeds; seed++)
                if (BattleEngine.Run(gBuilds[b].F, EnemyCatalog.Stages[w].Enemy, seed, verbose: false).PlayerWon)
                    wins++;
            gOther[b][w] = wins * 100.0 / GuardSeeds;
        }
    }
    Console.Error.WriteLine("  第2〜4波 完了");

    // ---- percent: 介入の密度（RedirectPercent）の掃引（第35期）---------------------------
    //
    // 第34期で「窓の長さ（体）では立たない」が確定した。律速は**勇者候補の生存ターン数**で、
    // 殉教者の体はそこに効かない（生存T 2.1倍に対して発火 1.5倍で頭打ち）。
    // 残る交絡の無いノブは**窓の密度**だけ——**HP を動かさないので波の総HPは1も動かず、
    // 対照は第34期の「庇うなし・HP52」1本で足りる。**
    //
    // 割合は MartyrRule で外から差す（static のノブは置かない。Colossus/Yoke/Hush と同じ）。
    // **p=50 は検算点**で、ここが docs/balance.md の第五波と一致しなければ掃引の台が違う。
    if (guardMode == "percent")
    {
        int[] gPs = { 50, 75, 100 };
        int gnp = gPs.Length;
        Formation gFoe = EnemyCatalog.Stages[4].Enemy;                  // 現行の第五波（殉教者 HP52）
        Formation gCtl = Wave5PlainHp(EnemyCatalog.Martyr.MaxHp);       // 対照: 庇うなし・同HP

        Console.WriteLine("# 介入の密度の掃引（guard percent）");
        Console.WriteLine();
        Console.WriteLine($"代表編成 {gnb} × 第五波 × p {gnp} 点、seed 0..{GuardSeeds - 1}。診断用なので docs/ には置かない。");
        Console.WriteLine();
        Console.WriteLine("動かすのは **割合（`MartyrRule.RedirectPercent`）の1変数のみ**。");
        Console.WriteLine("HP52・攻11・速5・薙ぎ・`DamagePerGain` 2・前1 の席・ガルド側はすべて据え置き。");
        Console.WriteLine("**HP を動かさないので波の総HPは1も動かない**——対照は「庇うなし・HP52」1本で足りる。");
        Console.WriteLine();

        var pRate = new double[gnp][];
        var pFire = new double[gnp][];
        var pAtk = new double[gnp][];
        var pLife = new double[gnp][];
        var pHero = new double[gnp][];   // 勇者候補の生存T（律速の直接観測）
        var ctlRate = new double[gnb];
        var ctlHero = new double[gnb];

        for (int b = 0; b < gnb; b++)
        {
            int w = 0;
            for (int seed = 0; seed < GuardSeeds; seed++)
                if (BattleEngine.Run(gBuilds[b].F, gCtl, seed, verbose: false).PlayerWon) w++;
            ctlRate[b] = w * 100.0 / GuardSeeds;

            long hero = 0;
            for (int seed = 0; seed < GuardLogSeeds; seed++)
            {
                BattleResult r = BattleEngine.Run(gBuilds[b].F, gCtl, seed, verbose: true);
                hero += HeroDeathTurn(r);
            }
            ctlHero[b] = hero / (double)GuardLogSeeds;
        }
        Console.Error.WriteLine("  対照（庇うなし・HP52）完了");

        for (int h = 0; h < gnp; h++)
        {
            var rule = new MartyrRule(gPs[h]);
            pRate[h] = new double[gnb]; pFire[h] = new double[gnb]; pAtk[h] = new double[gnb];
            pLife[h] = new double[gnb]; pHero[h] = new double[gnb];

            for (int b = 0; b < gnb; b++)
            {
                int w = 0;
                for (int seed = 0; seed < GuardSeeds; seed++)
                    if (BattleEngine.Run(gBuilds[b].F, gFoe, seed, verbose: false, null, null, null, rule).PlayerWon) w++;
                pRate[h][b] = w * 100.0 / GuardSeeds;

                long fire = 0, atk = 0, life = 0, hero = 0;
                for (int seed = 0; seed < GuardLogSeeds; seed++)
                {
                    BattleResult r = BattleEngine.Run(gBuilds[b].F, gFoe, seed, verbose: true, null, null, null, rule);
                    (int f, int a, int l) = MartyrStats(r);
                    fire += f; atk += a; life += l;
                    hero += HeroDeathTurn(r);
                }
                pFire[h][b] = fire / (double)GuardLogSeeds;
                pAtk[h][b] = atk / (double)GuardLogSeeds;
                pLife[h][b] = life / (double)GuardLogSeeds;
                pHero[h][b] = hero / (double)GuardLogSeeds;
            }
            Console.Error.WriteLine($"  p {gPs[h]} 完了");
        }

        Console.WriteLine("## 1. 第五波の分布");
        Console.WriteLine();
        Console.WriteLine("| 割合 p | 平均 | 100%の編成 | 0%の編成 | 中間帯(5〜95%) | 標準偏差 |");
        Console.WriteLine("|--:|--:|--:|--:|--:|--:|");
        {
            double m0 = ctlRate.Average();
            double s0 = Math.Sqrt(ctlRate.Select(x => (x - m0) * (x - m0)).Average());
            Console.WriteLine($"| **対照（庇うなし）** | {m0:F1} | {ctlRate.Count(x => x == 100.0)} / {gnb} "
                              + $"| {ctlRate.Count(x => x == 0.0)} | {ctlRate.Count(x => x > 5.0 && x < 95.0)} | {s0:F1} |");
        }
        for (int h = 0; h < gnp; h++)
        {
            double[] v = pRate[h];
            double m = v.Average();
            double sd = Math.Sqrt(v.Select(x => (x - m) * (x - m)).Average());
            Console.WriteLine($"| {gPs[h]} | {m:F1} | {v.Count(x => x == 100.0)} / {gnb} | {v.Count(x => x == 0.0)} "
                              + $"| {v.Count(x => x > 5.0 && x < 95.0)} | {sd:F1} |");
        }

        Console.WriteLine();
        Console.WriteLine("## 2. 固有の敗者の帰属（対照で敗者でない行だけを数える）");
        Console.WriteLine();
        Console.WriteLine("**庇うが作った敗者** = 庇うありで `≤10` かつ**対照では `>10`** かつ 第2〜4波がすべて `>10`。");
        Console.WriteLine("第34期の帰属条件をそのまま使う（見かけの新規と区別する）。");
        Console.WriteLine();
        var ctlLosers = new List<string>();
        for (int b = 0; b < gnb; b++)
            if (ctlRate[b] <= 10.0 && Enumerable.Range(1, 3).All(w => gOther[b][w] > 10.0))
                ctlLosers.Add(gBuilds[b].Name);
        Console.WriteLine($"- **対照（庇うなし）の敗者 {ctlLosers.Count}**: {(ctlLosers.Count == 0 ? "なし" : string.Join(" / ", ctlLosers))}");
        for (int h = 0; h < gnp; h++)
        {
            var all = new List<string>();
            var owned = new List<string>();
            for (int b = 0; b < gnb; b++)
            {
                if (!Enumerable.Range(1, 3).All(w => gOther[b][w] > 10.0)) continue;
                if (pRate[h][b] > 10.0) continue;
                all.Add(gBuilds[b].Name);
                if (ctlRate[b] > 10.0) owned.Add(gBuilds[b].Name);
            }
            Console.WriteLine($"- **p{gPs[h]}**: 敗者 {all.Count} / うち**庇うが作った敗者 {owned.Count}**");
            Console.WriteLine($"    - 敗者: {(all.Count == 0 ? "なし" : string.Join(" / ", all))}");
            Console.WriteLine($"    - **庇うが作った: {(owned.Count == 0 ? "**なし**" : string.Join(" / ", owned))}**");
        }

        Console.WriteLine();
        Console.WriteLine("## 3. 編成 × p の勝率（第五波）");
        Console.WriteLine();
        Console.WriteLine("`介入分` = その p の勝率 − 対照（庇うなし）。**これが庇うの正味の税額。**");
        Console.WriteLine();
        Console.Write("| 編成 | 他波最小 | 対照 |");
        foreach (int p in gPs) Console.Write($" p{p} |");
        foreach (int p in gPs) Console.Write($" 介入分(p{p}) |");
        Console.WriteLine();
        Console.Write("|---|--:|--:|");
        for (int i = 0; i < gnp * 2; i++) Console.Write("--:|");
        Console.WriteLine();
        for (int b = 0; b < gnb; b++)
        {
            string name = gBuilds[b].Name;
            bool canary = name.Contains("毒+ベニ+ラウ") || name.Contains("毒+耐久");
            double omin = Enumerable.Range(1, 3).Min(w => gOther[b][w]);
            Console.Write($"| {(canary ? "**" + name + "**（カナリア）" : name)} | {omin:F1} | {ctlRate[b]:F1} |");
            foreach (var t in pRate) Console.Write($" {t[b]:F1} |");
            foreach (var t in pRate) Console.Write($" {t[b] - ctlRate[b]:+0.0;-0.0;0.0} |");
            Console.WriteLine();
        }

        Console.WriteLine();
        Console.WriteLine($"## 4. 機構の指標（seed 0..{GuardLogSeeds - 1} の平均・全42編成）");
        Console.WriteLine();
        Console.WriteLine("`勇者候補の生存T` が第34期に確定した律速。**ここが伸びない限り発火は頭打ちになる。**");
        Console.WriteLine();
        Console.WriteLine("| 割合 p | 発火/戦 | 殉教者の最終攻 | 殉教者の生存T | 勇者候補の生存T |");
        Console.WriteLine("|--:|--:|--:|--:|--:|");
        Console.WriteLine($"| **対照（庇うなし）** | 0.00 | — | — | {ctlHero.Average():F2} |");
        for (int h = 0; h < gnp; h++)
            Console.WriteLine($"| {gPs[h]} | {pFire[h].Average():F2} | {pAtk[h].Average():F1} "
                              + $"| {pLife[h].Average():F2} | {pHero[h].Average():F2} |");

        Console.WriteLine();
        Console.WriteLine("## 5. 発火が多い順（上位12行）");
        Console.WriteLine();
        Console.Write("| 編成 |");
        foreach (int p in gPs) Console.Write($" 発火(p{p}) |");
        foreach (int p in gPs) Console.Write($" 最終攻(p{p}) |");
        foreach (int p in gPs) Console.Write($" 殉教者生存T(p{p}) |");
        Console.WriteLine();
        Console.Write("|---|");
        for (int i = 0; i < gnp * 3; i++) Console.Write("--:|");
        Console.WriteLine();
        foreach (int b in Enumerable.Range(0, gnb).OrderByDescending(i => pFire[gnp - 1][i]).Take(12))
        {
            Console.Write($"| {gBuilds[b].Name} |");
            foreach (var t in pFire) Console.Write($" {t[b]:F1} |");
            foreach (var t in pAtk) Console.Write($" {t[b]:F1} |");
            foreach (var t in pLife) Console.Write($" {t[b]:F1} |");
            Console.WriteLine();
        }
        return;
    }


    Console.WriteLine("# 殉教者の体の用量反応（guard）");
    Console.WriteLine();
    Console.WriteLine($"代表編成 {gnb} × 第五波 × HP {gnh} 点、seed 0..{GuardSeeds - 1}。診断用なので docs/ には置かない。");
    Console.WriteLine();
    Console.WriteLine("動かすのは **HP の1変数のみ**（攻11・速5・薙ぎ・Guardian・前1 の席は据え置き）。");
    Console.WriteLine("掃引点は既存の敵の体から借りている: 52=現行 / 71=この波の中央 / 90=この波の前3 / 145=ロスター最重。");
    Console.WriteLine();


    // ---- 各 HP 点で第五波を測る ------------------------------------------------------------
    var gRate = new double[gnh][];        // 勝率(%)・庇うあり
    var gPlain = new double[gnh][];       // 勝率(%)・庇うなし（同HPの対照）
    var gFire = new double[gnh][];        // 肩代わりの発火 /戦
    var gAtk = new double[gnh][];         // 殉教者の最終攻撃力（平均）
    var gLife = new double[gnh][];        // 殉教者の生存ターン（平均。生存し続けたら決着T）

    for (int h = 0; h < gnh; h++)
    {
        Formation foe = Wave5WithHp(gHps[h]);
        Formation plain = Wave5PlainHp(gHps[h]);
        gRate[h] = new double[gnb];
        gPlain[h] = new double[gnb];
        gFire[h] = new double[gnb];
        gAtk[h] = new double[gnb];
        gLife[h] = new double[gnb];

        for (int b = 0; b < gnb; b++)
        {
            int wins = 0;
            for (int seed = 0; seed < GuardSeeds; seed++)
                if (BattleEngine.Run(gBuilds[b].F, foe, seed, verbose: false).PlayerWon) wins++;
            gRate[h][b] = wins * 100.0 / GuardSeeds;

            int pwins = 0;
            for (int seed = 0; seed < GuardSeeds; seed++)
                if (BattleEngine.Run(gBuilds[b].F, plain, seed, verbose: false).PlayerWon) pwins++;
            gPlain[h][b] = pwins * 100.0 / GuardSeeds;

            // 機構の指標は verbose のログ行から。**盤面は1つも動かさない。**
            long fire = 0, atk = 0, life = 0;
            for (int seed = 0; seed < GuardLogSeeds; seed++)
            {
                BattleResult r = BattleEngine.Run(gBuilds[b].F, foe, seed, verbose: true);
                int turn = 0, deathTurn = -1, lastAtk = EnemyCatalog.Martyr.Attack;

                foreach (LogLine line in r.Log)
                {
                    string t = line.Text;
                    if (t.StartsWith("--- ターン "))
                    {
                        int from = "--- ターン ".Length, to = t.IndexOf(' ', from);
                        if (to > from && int.TryParse(t.Substring(from, to - from), out int n)) turn = n;
                        continue;
                    }
                    if (!t.Contains("殉教者")) continue;

                    if (t.Contains("を庇った")) fire++;
                    else if (t.Contains("殉教者 は倒れた") && deathTurn < 0) deathTurn = turn;
                    else if (t.Contains("誓いを思い出させる"))
                    {
                        // 「（攻撃 +N → M）」の M を取る。最後に出た値が最終攻撃力。
                        int arrow = t.LastIndexOf('→');
                        if (arrow >= 0)
                        {
                            string tail = new string(t.Substring(arrow + 1).Where(char.IsDigit).ToArray());
                            if (int.TryParse(tail, out int m)) lastAtk = m;
                        }
                    }
                }
                fire += 0;
                atk += lastAtk;
                life += deathTurn < 0 ? r.Turns : deathTurn;   // 落ちなければ決着まで生存
            }
            gFire[h][b] = fire / (double)GuardLogSeeds;
            gAtk[h][b] = atk / (double)GuardLogSeeds;
            gLife[h][b] = life / (double)GuardLogSeeds;
        }
        Console.Error.WriteLine($"  HP {gHps[h]} 完了");
    }

    // ---- 1. 分布 -------------------------------------------------------------------------
    Console.WriteLine("## 1. 第五波の分布");
    Console.WriteLine();
    Console.WriteLine("| 殉教者HP | 平均 | 100%の編成 | 0%の編成 | 中間帯(5〜95%) | 標準偏差 |");
    Console.WriteLine("|--:|--:|--:|--:|--:|--:|");
    for (int h = 0; h < gnh; h++)
    {
        double[] v = gRate[h];
        double m = v.Average();
        double sd = Math.Sqrt(v.Select(x => (x - m) * (x - m)).Average());
        Console.WriteLine($"| {gHps[h]} | {m:F1} | {v.Count(x => x == 100.0)} / {gnb} | {v.Count(x => x == 0.0)} "
                          + $"| {v.Count(x => x > 5.0 && x < 95.0)} | {sd:F1} |");
    }

    Console.WriteLine();
    Console.WriteLine("## 1b. 交絡の切り分け —— 庇うを外した同HPの対照");
    Console.WriteLine();
    Console.WriteLine("HP を上げると**介入の窓が伸びる**と同時に**波の総HPが増える**。");
    Console.WriteLine("同じ HP で庇うだけを外した版と比べれば、差がそのまま**介入の効果**になる");
    Console.WriteLine("（渇き・軛・粛が「規則を無効にした同数値の版」を対照に置いたのと同じ形）。");
    Console.WriteLine();
    Console.WriteLine("**HP52 の対照は差し替え前の第五波そのもの**（前1 戦斧兵 52/11/5・薙ぎ）なので、");
    Console.WriteLine("その行が第32期差し戻し後の値と一致することが診断そのものの検算になる。");
    Console.WriteLine();
    Console.WriteLine("| 殉教者HP | 庇うあり 平均 | 庇うなし 平均 | 介入の効果 | 波の総HP | HP による増分 |");
    Console.WriteLine("|--:|--:|--:|--:|--:|--:|");
    double baseAll = gPlain[0].Average();
    for (int h = 0; h < gnh; h++)
    {
        double a = gRate[h].Average(), p = gPlain[h].Average();
        int total = gHps[h] + EnemyCatalog.Hero2.MaxHp + EnemyCatalog.Knight2.MaxHp
                    + EnemyCatalog.Seer.MaxHp + EnemyCatalog.Lancer.MaxHp;
        Console.WriteLine($"| {gHps[h]} | {a:F1} | {p:F1} | **{a - p:+0.0;-0.0;0.0}** | {total} | {p - baseAll:+0.0;-0.0;0.0} |");
    }

    // ---- 2. 固有の敗者 --------------------------------------------------------------------
    // 「第五波だけで 10 以下、他のどの波（第一波を除く）でも 10 超」。
    // 第一波は全編成 100% のチュートリアル波なので比較から外す（spread と同じ作法）。
    Console.WriteLine();
    Console.WriteLine("## 2. 第五波の固有の敗者（閾値 90/10・第一波は比較対象外）");
    Console.WriteLine();
    Console.WriteLine("**新規** = HP52（第33期の採用値）では固有の敗者でなかった行。");
    Console.WriteLine();
    var baseLosers = new HashSet<string>();
    for (int h = 0; h < gnh; h++)
    {
        var losers = new List<string>();
        var winners = new List<string>();
        for (int b = 0; b < gnb; b++)
        {
            bool otherAbove = Enumerable.Range(1, 3).All(w => gOther[b][w] > 10.0);
            if (gRate[h][b] <= 10.0 && otherAbove) losers.Add(gBuilds[b].Name);
            bool otherBelow = Enumerable.Range(1, 3).All(w => gOther[b][w] < 90.0);
            if (gRate[h][b] >= 90.0 && otherBelow) winners.Add(gBuilds[b].Name);
        }
        if (h == 0) foreach (string n in losers) baseLosers.Add(n);
        var fresh = losers.Where(n => !baseLosers.Contains(n)).ToList();
        Console.WriteLine($"- **HP {gHps[h]}**: 敗者 {losers.Count} / 勝者 {winners.Count}");
        Console.WriteLine($"    - 敗者: {(losers.Count == 0 ? "なし" : string.Join(" / ", losers))}");
        Console.WriteLine($"    - **新規の敗者: {(fresh.Count == 0 ? "なし" : string.Join(" / ", fresh))}**");
        Console.WriteLine($"    - 勝者: {(winners.Count == 0 ? "なし" : string.Join(" / ", winners))}");
    }

    // ---- 3. カナリア + 全行の勝率 ----------------------------------------------------------
    Console.WriteLine();
    Console.WriteLine("## 3. 編成 × HP の勝率（第五波）");
    Console.WriteLine();
    Console.WriteLine("`カナリア` = 指示書が指定した課税過剰の検出行（毒+ベニ+ラウ / 毒+耐久）。");
    Console.WriteLine("`他波最小` = 第2〜4波の最小値（10 以下なら固有の敗者になれない）。");
    Console.WriteLine();
    Console.Write("| 編成 | 他波最小 |");
    foreach (int hp in gHps) Console.Write($" HP{hp} |");
    Console.Write(" 52→145 |");
    foreach (int hp in gHps) Console.Write($" 介入分(HP{hp}) |");
    Console.WriteLine();
    Console.Write("|---|--:|");
    for (int i = 0; i < gnh * 2 + 1; i++) Console.Write("--:|");
    Console.WriteLine();
    for (int b = 0; b < gnb; b++)
    {
        string name = gBuilds[b].Name;
        bool canary = name.Contains("毒+ベニ+ラウ") || name.Contains("毒+耐久");
        double omin = Enumerable.Range(1, 3).Min(w => gOther[b][w]);
        Console.Write($"| {(canary ? "**" + name + "**（カナリア）" : name)} | {omin:F1} |");
        foreach (var t in gRate) Console.Write($" {t[b]:F1} |");
        Console.Write($" {gRate[gnh - 1][b] - gRate[0][b]:+0.0;-0.0;0.0} |");
        for (int h = 0; h < gnh; h++) Console.Write($" {gRate[h][b] - gPlain[h][b]:+0.0;-0.0;0.0} |");
        Console.WriteLine();
    }

    // ---- 4. 機構の指標 ---------------------------------------------------------------------
    Console.WriteLine();
    Console.WriteLine($"## 4. 殉教者の側の指標（seed 0..{GuardLogSeeds - 1} の平均）");
    Console.WriteLine();
    Console.WriteLine("`発火` = 肩代わりが成立した回数/戦。`最終攻` = 戦闘終了時の攻撃力（素は 11）。");
    Console.WriteLine("`生存T` = 殉教者が落ちたターン（落ちなければ決着ターン）。");
    Console.WriteLine();
    Console.Write("| 編成 |");
    foreach (int hp in gHps) Console.Write($" 発火(HP{hp}) |");
    foreach (int hp in gHps) Console.Write($" 最終攻(HP{hp}) |");
    foreach (int hp in gHps) Console.Write($" 生存T(HP{hp}) |");
    Console.WriteLine();
    Console.Write("|---|");
    for (int i = 0; i < gnh * 3; i++) Console.Write("--:|");
    Console.WriteLine();
    foreach (int b in Enumerable.Range(0, gnb).OrderByDescending(i => gFire[gnh - 1][i]))
    {
        Console.Write($"| {gBuilds[b].Name} |");
        foreach (var t in gFire) Console.Write($" {t[b]:F1} |");
        foreach (var t in gAtk) Console.Write($" {t[b]:F1} |");
        foreach (var t in gLife) Console.Write($" {t[b]:F1} |");
        Console.WriteLine();
    }

    // ---- 5. 平均の要約 ----------------------------------------------------------------------
    Console.WriteLine();
    Console.WriteLine("## 5. 全編成の平均（機構の指標）");
    Console.WriteLine();
    Console.WriteLine("| 殉教者HP | 発火/戦 | 最終攻 | 生存T |");
    Console.WriteLine("|--:|--:|--:|--:|");
    for (int h = 0; h < gnh; h++)
        Console.WriteLine($"| {gHps[h]} | {gFire[h].Average():F2} | {gAtk[h].Average():F1} | {gLife[h].Average():F2} |");

    return;
}

// pace モード: **勝率以外の物差しで、波から情報を取り出せるか**（第54期・調査）。
//
// `compare` の5波のうち第一波は 56 行すべてが 100.0% で、情報セルが 0 のまま遊んでいる
// （第51期の実測では、3体のうちどれを空席にしても 56 行すべて 100.0% のまま）。
// しかし決着ターンは 2.0〜6.1 と3倍の幅で散っている——**勝敗という物差しでは何も
// 測れていないが、盤面では明確な差が出ている。**
//
// ここでやるのは物差しの比較だけで、**波は1体も触らない**（`Stages` 差分ゼロ）。
// 既存の `chain` / `pulse` も決着T・残存・被ダメを出しているが、どちらも
// **全ステージ通算**（か駒ごと）なので、第一波の値が通算の中に埋もれて取り出せない。
// この診断の要は「**波ごとに**、複数の物差しを、同じ実行の中で並べる」ことにある。
//
// 群の数の定義は第54期の指示書で測る前に固定した（design/PHASE54_PACE.md §1-1）:
//   A 帯（seed 0..199・compare と同じ）の値で昇順に並べ、位置 k に切れ目を入れるのは
//   **B 帯（seed 200..399・選定に使っていない）でも前半と後半が完全に分離する**ときだけ。
//   群 = 切れ目 + 1。隣接ペアだけの比較にすると1組の逆転で群が増減して不安定になる
//   （第45期の「1位は 28/48 行で入れ替わる」と同じ罠）。
//
// 強化の分布（第56期）。**窓口 `BattleContext.Whet` を通った量だけ**を経路別・受け手別に数える。
//
// 第42期に弱体は `ctx.Dull` へ統一されたが、強化側は15箇所が `AtkBonus` を直に叩いていた
// （第52期 Phase 0-1 の持ち越し）。窓口ができたので、**強化の総量と経路別の内訳が初めて測れる。**
// 窓口そのものは挙動不変（`compare` が 280 セル 0 件で一致）なので、**この診断がこの期の成果。**
//
// **通っているのは他者強化の6本だけ。** 自己強化の9本（怒り・庇う／殉教・墓守2本・処刑・棘・
// 澱み喰い・軋み・分かち）は直叩きのまま残してあるので、ここの「総量」は
// **`AtkBonus` の総流量ではなく「他者から受け取った量」**である。収支も同じ意味。
//
// **渡した量は成果ではない**（第42期以降の作法）。`死蔵`（受け取ったのに一度も振らなかった駒への
// 付与量）を必ず分けて出す。`逆しま` は**受け取ったことがそのまま害になった量**。
//
// **陽性対照**（§7）: 既存のノブで経路を1本ずつ殺し、`whet` がその欠落を検出することを確かめる
// ——**合否は「狙った経路が 0 になったか」の1本だけ。** ノブは計数ではなく盤面を切るので、
// 他の経路がわずかに動くのは故障ではない（決着の長さと生死が変わる）
// ——`ColossusRule(Regurgitate: false)` が吐き戻しを、`GoadRule(0)` が駆り立てを 0 にする。
// 「0 件でした」が検出器の故障と区別できないので、**新しいノブは足さず既存のノブでやる。**
//
//     dotnet run --project BattleSim -c Release 0 whet [絞り込み]
if (focusId == "whet")
{
    var whBuilds = CompareBuilds();
    IReadOnlyList<EnemyCatalog.Stage> whStages = EnemyCatalog.Stages;
    const int WhSeeds = 200;   // compare / spread / dull と同じ帯

    string whFilter = args.Length > 2 ? args[2] : "";
    var whTargets = whBuilds
        .Where(b => whFilter.Length == 0 || whFilter.Split(',').Any(k => b.Name.Contains(k.Trim())))
        .ToArray();

    // 駒名の引き当て。TallyByUnit は両陣営を Def.Id で混ぜて持つので、敵側の名前も要る
    // （弱体は呪詛・転嫁で敵にも載る）。召喚（胞子）は Occupied に出ないので、
    // 見つからなければ Id をそのまま出す（**握り潰さない**）。
    var whName = new Dictionary<string, string>();
    foreach (UnitDef d in UnitCatalog.All) whName[d.Id] = d.Name;
    var whEnemyIds = new HashSet<string>();
    foreach (EnemyCatalog.Stage st in whStages)
        foreach ((int _, UnitDef d) in st.Enemy.Occupied()) { whName[d.Id] = d.Name; whEnemyIds.Add(d.Id); }
    string WhLabel(string id) => whName.TryGetValue(id, out string? n) ? n : id;

    // 1戦ぶんを足し込む器。**すべて「延べ量 ÷ 戦数」で割って出す**（量/戦の作法）。
    var whRoute = new double[WhetRoutes.Count];
    double whTotal = 0, whDull = 0, whPerv = 0, whFlip = 0;
    double whHoard = 0;                                    // 死蔵(旧): 受け取ったが Attacks == 0 の駒への付与量
    double whHoardInt = 0;                                 // 参考: Interventions == 0 の駒への付与量
    double whHoardNew = 0;                                 // **死蔵(新)**: AttackReads == 0 の駒への付与量
    var whHoardNewWho = new Dictionary<string, double>();  // 新定義の内訳
    var whGot = new Dictionary<string, double>();          // 受け手ごとの Whetted
    var whLost = new Dictionary<string, double>();         // 受け手ごとの Dulled
    var whHoardWho = new Dictionary<string, double>();     // 死蔵の内訳
    var whRowRoute = new Dictionary<string, double[]>();   // 行ごとの経路別（供給源の地図）
    int whBattles = 0;

    var whSw = System.Diagnostics.Stopwatch.StartNew();
    foreach ((string whRowName, Formation whF) in whTargets)
    {
        var rowRoute = new double[WhetRoutes.Count];
        foreach (EnemyCatalog.Stage st in whStages)
        {
            for (int seed = 0; seed < WhSeeds; seed++)
            {
                BattleResult r = BattleEngine.Run(whF, st.Enemy, seed, verbose: false);
                whBattles++;

                whTotal += r.WhetTotal;
                whDull += r.DullTotal;
                whPerv += r.WhetToPerverse;
                whFlip += r.WhetPerverseFlips;
                for (int i = 0; i < WhetRoutes.Count; i++)
                {
                    whRoute[i] += r.WhetByRoute[i];
                    rowRoute[i] += r.WhetByRoute[i];
                }

                foreach ((string id, UnitTally t) in r.TallyByUnit)
                {
                    if (t.Whetted > 0)
                    {
                        whGot[id] = whGot.TryGetValue(id, out double g) ? g + t.Whetted : t.Whetted;
                        // 死蔵。**振った回数が 0 の駒**への付与量。反撃（棘）は Attacks を通らないので
                        // 「反応型」も死蔵に数えてしまう——内訳を出して読む側で切り分ける。
                        if (t.Attacks == 0)
                        {
                            whHoard += t.Whetted;
                            whHoardWho[id] = whHoardWho.TryGetValue(id, out double h) ? h + t.Whetted : t.Whetted;
                        }
                        // **死蔵の新定義（第64期）。** `Attacks` は `PerformAttack` を通った回数なので、
                        // 棘（カド）のように **`PerformAttack` を通らずに自分の `CurrentAttack` を
                        // 打点に変える駒**を「死蔵」に数えてしまう（第63期 §11-2 で符号を逆に読んだ）。
                        // `AttackReads` は攻撃力を出力に変換した回数そのものなので、そこが塞がる。
                        if (t.Interventions == 0) whHoardInt += t.Whetted;
                        if (t.AttackReads == 0)
                        {
                            whHoardNew += t.Whetted;
                            whHoardNewWho[id] = whHoardNewWho.TryGetValue(id, out double h2)
                                ? h2 + t.Whetted : t.Whetted;
                        }
                    }
                    if (t.Dulled > 0)
                        whLost[id] = whLost.TryGetValue(id, out double d) ? d + t.Dulled : t.Dulled;
                }
            }
        }
        whRowRoute[whRowName] = rowRoute;
    }
    whSw.Stop();

    double whN = Math.Max(1, whBattles);

    Console.WriteLine("# 強化の分布 —— 窓口 `Whet`（第56期）");
    Console.WriteLine();
    Console.WriteLine($"対象 **{whTargets.Length} 編成** × 全 {whStages.Count} 波 × seed 0..{WhSeeds - 1} = **{whBattles} 戦**"
                      + $"（{whSw.Elapsed.TotalSeconds:F1} 秒）。");
    Console.WriteLine();
    Console.WriteLine("**通っているのは他者強化の6経路だけ。** 自己強化の9本（怒り・庇う／殉教・墓守2本・処刑・");
    Console.WriteLine("棘・澱み喰い・軋み・分かち）は `AtkBonus` を直に叩いたまま残してあるので、");
    Console.WriteLine("下の「総量」は `AtkBonus` の総流量ではなく **「他者から受け取った量」** である。");
    Console.WriteLine();

    // ---- 1. 経路別 -------------------------------------------------------
    Console.WriteLine("## 1. 経路別の強化総量");
    Console.WriteLine();
    Console.WriteLine("| 経路 | 量/戦 | 占有率 | 出た編成 |");
    Console.WriteLine("|---|--:|--:|--:|");
    for (int i = 0; i < WhetRoutes.Count; i++)
    {
        int rows = whRowRoute.Count(kv => kv.Value[i] > 0);
        Console.WriteLine($"| {WhetRoutes.Names[i]} | {whRoute[i] / whN:F2} | "
                          + $"{(whTotal > 0 ? whRoute[i] * 100.0 / whTotal : 0):F1}% | {rows} |");
    }
    Console.WriteLine($"| **合計** | **{whTotal / whN:F2}** | 100.0% | {whRowRoute.Count(kv => kv.Value.Sum() > 0)} |");
    Console.WriteLine();
    Console.WriteLine($"参考: 弱体総量（`Dull`）は **{whDull / whN:F2}** /戦。"
                      + $"強化 ÷ 弱体 = **{(whDull > 0 ? whTotal / whDull : 0):F2} 倍**。");
    Console.WriteLine();
    Console.WriteLine("> `その他` が 0 でないなら、札を付け忘れた `Whet` の呼び出しがある（受け入れ基準・指示書 §6-5）。");
    Console.WriteLine();

    // ---- 2. 受け手 -------------------------------------------------------
    Console.WriteLine("## 2. 受け手（強化を受け取った駒・上位10）");
    Console.WriteLine();
    Console.WriteLine("| 駒 | 受けた強化/戦 | 占有率 | 陣営 |");
    Console.WriteLine("|---|--:|--:|:-:|");
    foreach ((string id, double v) in whGot.OrderByDescending(kv => kv.Value).Take(10))
        Console.WriteLine($"| {WhLabel(id)} | {v / whN:F2} | {(whTotal > 0 ? v * 100.0 / whTotal : 0):F1}% | "
                          + (whEnemyIds.Contains(id) ? "敵" : "味方") + " |");
    Console.WriteLine();
    Console.WriteLine($"受け手の延べ種類数 **{whGot.Count}**。");
    Console.WriteLine();

    // ---- 3. 収支 ---------------------------------------------------------
    Console.WriteLine("## 3. 収支（`Whet - Dull` の正味）");
    Console.WriteLine();
    Console.WriteLine("**他者から受け取った正味**であって `AtkBonus` の総収支ではない（自己強化9本は窓口を通らない）。");
    Console.WriteLine();
    Console.WriteLine("| 駒 | 強化/戦 | 弱体/戦 | 正味 | 陣営 |");
    Console.WriteLine("|---|--:|--:|--:|:-:|");
    var whAll = new HashSet<string>(whGot.Keys);
    whAll.UnionWith(whLost.Keys);
    foreach (string id in whAll
                 .OrderByDescending(x => Math.Abs((whGot.TryGetValue(x, out double a) ? a : 0)
                                                  - (whLost.TryGetValue(x, out double b) ? b : 0)))
                 .Take(15))
    {
        double g = whGot.TryGetValue(id, out double gv) ? gv : 0;
        double d = whLost.TryGetValue(id, out double dv) ? dv : 0;
        Console.WriteLine($"| {WhLabel(id)} | {g / whN:F2} | {d / whN:F2} | **{(g - d) / whN:+0.00;-0.00;0.00}** | "
                          + (whEnemyIds.Contains(id) ? "敵" : "味方") + " |");
    }
    Console.WriteLine();

    // ---- 4. 死蔵 ---------------------------------------------------------
    Console.WriteLine("## 4. 死蔵（配った強化が出力にならなかった量）");
    Console.WriteLine();
    Console.WriteLine("**第64期に定義を直した**（第63期 §11-2）。3つの数え方を併記する。");
    Console.WriteLine();
    Console.WriteLine("| 定義 | 数え方 | 死蔵量/戦 | 強化総量に占める割合 |");
    Console.WriteLine("|---|---|--:|--:|");
    Console.WriteLine($"| 旧（第56期） | `Attacks == 0`（`PerformAttack` を通らなかった） | {whHoard / whN:F2} | "
                      + $"**{(whTotal > 0 ? whHoard * 100.0 / whTotal : 0):F1}%** |");
    Console.WriteLine($"| 参考 | `Interventions == 0`（ダメージの出どころにならなかった） | {whHoardInt / whN:F2} | "
                      + $"{(whTotal > 0 ? whHoardInt * 100.0 / whTotal : 0):F1}% |");
    Console.WriteLine($"| **新（第64期）** | **`AttackReads == 0`（攻撃力を出力に1度も変換しなかった）** | "
                      + $"**{whHoardNew / whN:F2}** | **{(whTotal > 0 ? whHoardNew * 100.0 / whTotal : 0):F1}%** |");
    Console.WriteLine();
    Console.WriteLine("> **旧定義は広すぎ、`Interventions` は狭すぎる。** 棘（カド）は `PerformAttack` を1度も");
    Console.WriteLine("> 通らないが反撃量を自分の `CurrentAttack` で決めるので**強化は満額効く**（旧定義は死蔵に数える）。");
    Console.WriteLine("> 逆に破裂・生贄・吸いは**固定量**で攻撃力を1ビットも読まないのに `Interventions` は立つ。");
    Console.WriteLine("> **`AttackReads` は攻撃力を出力量に変換した回数そのもの**で、加算箇所は4つだけ");
    Console.WriteLine("> （`PerformAttack` / 棘 / 仇討ち / 責め苦の追撃）。");
    Console.WriteLine();
    Console.WriteLine("| 駒 | 死蔵(旧)/戦 | 死蔵(新)/戦 | その駒が受けた総量 | 新定義の割合 |");
    Console.WriteLine("|---|--:|--:|--:|--:|");
    var whHoardAll = new HashSet<string>(whHoardWho.Keys);
    whHoardAll.UnionWith(whHoardNewWho.Keys);
    foreach (string id in whHoardAll
                 .OrderByDescending(x => Math.Max(whHoardWho.TryGetValue(x, out double a) ? a : 0,
                                                  whHoardNewWho.TryGetValue(x, out double b) ? b : 0))
                 .Take(12))
    {
        double o = whHoardWho.TryGetValue(id, out double ov) ? ov : 0;
        double nv = whHoardNewWho.TryGetValue(id, out double nvv) ? nvv : 0;
        double got = whGot.TryGetValue(id, out double g) ? g : 0;
        Console.WriteLine($"| {WhLabel(id)} | {o / whN:F2} | **{nv / whN:F2}** | {got / whN:F2} | "
                          + $"{(got > 0 ? nv * 100.0 / got : 0):F1}% |");
    }
    Console.WriteLine();

    // ---- 5. 逆しま -------------------------------------------------------
    Console.WriteLine("## 5. 逆しま（強化が害になった量）");
    Console.WriteLine();
    Console.WriteLine($"ウツが受けた強化 **{whPerv / whN:F2}** /戦 ＝ 強化総量の **{(whTotal > 0 ? whPerv * 100.0 / whTotal : 0):F1}%**。");
    Console.WriteLine($"そのうち **符号が正へ渡った（半減側へ落ちた）回数 {whFlip / whN:F3} 回/戦**。");
    Console.WriteLine();
    Console.WriteLine("> `AtkBonus` が正だと攻撃力が半減し、負だと下げ幅の3倍になる（`PerverseTrait`）。");
    Console.WriteLine("> **量ではなく符号が読まれる**ので、「落ちた回数」のほうが本体。");
    Console.WriteLine();

    // ---- 6. 行ごとの供給源 -----------------------------------------------
    Console.WriteLine("## 6. 行ごとの供給源（強化を持つ編成だけ）");
    Console.WriteLine();
    Console.WriteLine("| 編成 | " + string.Join(" | ", WhetRoutes.Names.Skip(1)) + " | 合計/戦 |");
    Console.WriteLine("|---" + string.Concat(Enumerable.Repeat("|--:", WhetRoutes.Count)) + "|");
    double whPerRow = whStages.Count * WhSeeds;
    foreach ((string rn, double[] rr) in whRowRoute.Where(kv => kv.Value.Sum() > 0)
                                                   .OrderByDescending(kv => kv.Value.Sum()))
        Console.WriteLine($"| {rn} | "
                          + string.Join(" | ", rr.Skip(1).Select(v => $"{v / whPerRow:F1}"))
                          + $" | **{rr.Sum() / whPerRow:F1}** |");
    Console.WriteLine();
    Console.WriteLine($"強化を1点でも通す行は **{whRowRoute.Count(kv => kv.Value.Sum() > 0)} / {whTargets.Length}**。");
    Console.WriteLine();

    // ---- 7. 陽性対照 -----------------------------------------------------
    // **「0 件でした」は検出器の故障と区別が付かない**（第37期の作法）。
    // 既存のノブで経路を1本ずつ殺し、その経路だけが 0 になり他が動かないことを確かめる。
    // **新しいノブは足さない。**
    Console.WriteLine("## 7. 陽性対照（経路を1本ずつ窓口から外す）");
    Console.WriteLine();
    Console.WriteLine("既存のノブで経路を殺し、**狙った経路が 0 になる**ことを確かめる（合否はこの1本）。");
    Console.WriteLine("`ColossusRule(Regurgitate: false)` が吐き戻しを、`GoadRule(0)` が駆り立てを 0 にする。");
    Console.WriteLine();

    double[] WhMeasure((string Name, Formation F)[] rows, ColossusRule? col, GoadRule? goad)
    {
        var acc = new double[WhetRoutes.Count];
        int n = 0;
        foreach ((string _, Formation f) in rows)
            foreach (EnemyCatalog.Stage st in whStages)
                for (int seed = 0; seed < WhSeeds; seed++)
                {
                    BattleResult r = BattleEngine.Run(f, st.Enemy, seed, verbose: false,
                                                      colossus: col, goad: goad);
                    n++;
                    for (int i = 0; i < WhetRoutes.Count; i++) acc[i] += r.WhetByRoute[i];
                }
        for (int i = 0; i < WhetRoutes.Count; i++) acc[i] /= Math.Max(1, n);
        return acc;
    }

    var whProbes = new (string Label, int Route, TraitId Need, ColossusRule? Col, GoadRule? Goad)[]
    {
        ("吐き戻しを切る (`Regurgitate: false`)", (int)WhetRoute.Regurgitate, TraitId.Colossus,
         ColossusRule.Default with { Regurgitate = false }, null),
        ("駆り立てを切る (`GoadRule(0)`)", (int)WhetRoute.Goad, TraitId.Goad,
         null, new GoadRule(0)),
    };

    foreach ((string label, int route, TraitId need, ColossusRule? col, GoadRule? goad) in whProbes)
    {
        // 対照の台は「その経路を実際に持っている行」だけに絞る（持たない行を混ぜると分母で薄まる）。
        var rows = whTargets.Where(t => t.F.Occupied().Any(o => o.Item2.Traits.Contains(need))).ToArray();
        Console.WriteLine($"### {label}");
        Console.WriteLine();
        if (rows.Length == 0)
        {
            Console.WriteLine("**対象の行が絞り込みに入っていない**（対照が立たない）。絞り込みを外して回すこと。");
            Console.WriteLine();
            continue;
        }
        double[] before = WhMeasure(rows, null, null);
        double[] after = WhMeasure(rows, col, goad);

        Console.WriteLine($"対象 {rows.Length} 行。");
        Console.WriteLine();
        Console.WriteLine("| 経路 | 切る前 | 切った後 | 差 |");
        Console.WriteLine("|---|--:|--:|--:|");
        for (int i = 0; i < WhetRoutes.Count; i++)
        {
            if (before[i] == 0 && after[i] == 0) continue;
            Console.WriteLine($"| {WhetRoutes.Names[i]}{(i == route ? " ←狙い" : "")} | "
                              + $"{before[i]:F2} | {after[i]:F2} | {after[i] - before[i]:+0.00;-0.00;0.00} |");
        }
        // **合否は「狙った経路が 0 になったか」の1本だけ。**
        // 他の経路のずれは検出器の故障ではない——ノブは計数ではなく**盤面**を切るので
        // （`Regurgitate: false` は攻撃力が返らない盤面・`GoadRule(0)` は押し出しの無い盤面）、
        // 決着ターン数と生死が変わり、ターンあたりで走る他の経路の回数も動く。
        // **「他が動かないこと」を合格条件にすると、盤面を動かさないノブしか対照に使えなくなる。**
        bool killed = before[route] > 0 && after[route] == 0;
        double drift = Enumerable.Range(0, WhetRoutes.Count)
                                 .Where(i => i != route)
                                 .Sum(i => Math.Abs(after[i] - before[i]));
        Console.WriteLine();
        Console.WriteLine($"狙った経路: {before[route]:F2} → **{after[route]:F2}**（切る前が 0 でないこと・切った後が 0 であること）");
        Console.WriteLine($"→ 検出器は **{(killed ? "機能している" : "疑わしい（読む前に原因を潰すこと）")}**");
        Console.WriteLine();
        double rest = before.Sum() - before[route];
        double driftPct = rest > 0 ? drift * 100.0 / rest : 0;
        Console.WriteLine($"参考: 他経路の総ずれ **{drift:F2}**/戦（他経路の合計の {driftPct:F1}%）。"
                          + "**これは故障ではない**——ノブは計数ではなく盤面を切るので、");
        Console.WriteLine("決着の長さと生死が変わり、他の経路が走る回数も動く。合否は狙った経路の1本だけで読む。");
        Console.WriteLine();
    }

    return;
}

// 軋みが響く（第66期 → **第67期に条件の出どころを差し替えた**）。
// **駒は作らない。ロスターの最後の1枠は使わない。**
//
// 第66期は `AtkBonus` を読んで単体 → 薙ぎにしたが、閾値 9 はヨミ自身の上昇（軋み 9 / 突き出し 22）
// だけで満たされ、**条件ではなく起動スイッチ**になっていた（到達時点の内訳 軋み 21.8 対 窓口 8.0）。
// 第67期は条件を **`UnitState.WhetReceived`（`Whet` 窓口を通って届いた累計）** に差し替える。
// **軋み自身の上昇は条件に入らない**ので、これで初めて「強化の2枚目の読み手」になる
// （第65期 積み残し1': 供給 16 対 読み手 1）。
//
// 自由度は構造的に消してある（第64期の教訓・自己検査 (e)）:
//   行は4本に固定（ヨミを含む全3行 ＋ 実演行 `軋み×吐き戻し`。**測定前の宣言**）／
//   席は動かさない（`reseat` は帰属の器具ではない）／攻撃型は薙ぎで固定（第66期と同じ）／
//   閾値は `UnitTally.CreakWhetProbes` の格子から3点、採り方は §2-2 で固定
//   （Q1 を満たす版のうち帰属が最大・同点は高い方）。
//
//     dotnet run --project BattleSim -c Release 0 creak         # 主表（A 帯 seed 0..199）
//     dotnet run --project BattleSim -c Release 0 creak phase0  # Phase 0（V0 の `WhetReceived` の分布）
//     dotnet run --project BattleSim -c Release 0 creak alt     # 再現帯（seed 200..599）
if (focusId == "creak")
{
    string ckArg = args.Length > 2 ? args[2] : "";
    bool ckAlt = ckArg == "alt";
    int ckSeed0 = ckAlt ? 200 : 0;
    int ckSeedN = ckAlt ? 400 : 200;
    IReadOnlyList<EnemyCatalog.Stage> ckStages = EnemyCatalog.Stages;
    var ckAll = CompareBuilds().ToArray();

    bool CkHasYomi((string Name, Formation F) row)
        => row.F.Occupied().Any(o => o.Item2.Id == UnitCatalog.Yomi.Id);

    var ckRows = ckAll.Where(CkHasYomi).ToArray();
    var ckOther = ckAll.Where(b => !CkHasYomi(b)).ToArray();

    // 実演行（第66期 §1-5）。**第67期は「供給がある台」が主題なので採否にも使う**（指示書 §2-3・測定前の宣言）。
    // 配置は手で固定し `reseat` しない。巨躯は `DepthOf(wall) < DepthOf(target)`＝**ゴルムより後ろ**を庇うので、
    // 吐き戻しを受けるにはヨミが後ろでなければならない（第66期の前提の訂正）。
    var ckDemo = ("軋み×吐き戻し (ヨミ×ゴルム)",
        Formation.Build(front1: UnitCatalog.Golm, front3: UnitCatalog.Gald, center: UnitCatalog.Basa,
                        back1: UnitCatalog.Yomi, back3: UnitCatalog.Sero));

    // Q3ダッシュの器具（指示書 §1-4）。**ゴルムだけを同数値・特性なしの素体に落とす。他の4枚と席は動かさない。**
    // 規則にノブを増やさず駒の側で塞ぐ（第47期・`gradient` / `aim` と同じ扱い）。
    var ckPlainGolm = new UnitDef
    {
        Id = "golm_plain", Name = "素体（ゴルム同数値）",
        MaxHp = 150, Attack = 10, Speed = 3, Traits = Array.Empty<TraitId>(),
        PlusText = "", MinusText = "", Flavor = ""
    };
    var ckDemoPlain = ("軋み×吐き戻し（ゴルム素体）",
        Formation.Build(front1: ckPlainGolm, front3: UnitCatalog.Gald, center: UnitCatalog.Basa,
                        back1: UnitCatalog.Yomi, back3: UnitCatalog.Sero));

    // 版と閾値（§2-2・**測る前に固定**）。Phase 0-3 の分布から `CreakWhetProbes` の格子上で3点を採る。
    int[] ckVer = { 0, 2, 6, 12 };
    string[] ckVerName = { "V0", "Va", "Vb", "Vc" };

    // 1行ぶんの器。**勝率と計数を同じ走査で取る。**
    (double[] Win, double Sweeps, double Swings, double WhetMax,
     double SelfGain, double WhetGain, double RegurgGain,
     double[] ProbeT, double[] ProbeN)
    CkRun(Formation f, int threshold)
    {
        int np = UnitTally.CreakWhetProbes.Length;
        var win = new double[ckStages.Count];
        double sweeps = 0, swings = 0, wmax = 0, sg = 0, wg = 0, rg = 0;
        var pt = new double[np]; var pn = new double[np];

        for (int w = 0; w < ckStages.Count; w++)
        {
            int wins = 0;
            for (int seed = ckSeed0; seed < ckSeed0 + ckSeedN; seed++)
            {
                BattleResult r = BattleEngine.Run(f, ckStages[w].Enemy, seed, verbose: false,
                                                  creak: new CreakRule(threshold));
                if (r.PlayerWon) wins++;
                if (!r.TallyByUnit.TryGetValue(UnitCatalog.Yomi.Id, out UnitTally? t)) continue;
                sweeps += t.CreakSweeps; swings += t.CreakSwings; wmax += t.CreakWhetMax;
                sg += t.CreakSelfGain; wg += t.CreakWhetGain; rg += t.CreakRegurgGain;
                if (t.CreakWhetProbeTurn is null) continue;
                for (int i = 0; i < np; i++)
                {
                    if (t.CreakWhetProbeTurn[i] == 0) continue;
                    pn[i]++; pt[i] += t.CreakWhetProbeTurn[i];
                }
            }
            win[w] = wins * 100.0 / ckSeedN;
        }
        int n = ckStages.Count * ckSeedN;
        return (win, sweeps / n, swings / n, wmax / n, sg / n, wg / n, rg / n, pt, pn);
    }

    var ckSw = System.Diagnostics.Stopwatch.StartNew();

    // ---- phase0: V0 の `WhetReceived` の分布と、判定式の実効レンジ ----------------
    if (ckArg == "phase0")
    {
        Console.WriteLine("# 軋みが響く（第67期） —— Phase 0（**規則は無効のまま測る**）");
        Console.WriteLine();
        Console.WriteLine($"seed {ckSeed0}..{ckSeed0 + ckSeedN - 1} × 5 波。**盤面は1つも動かない**"
                          + "（`CreakRule` 無効＝`ModifyPattern` が素通り）。");
        Console.WriteLine();
        Console.WriteLine("## 0-3. ヨミの `WhetReceived` の分布（現行・V0）");
        Console.WriteLine();
        Console.WriteLine("`押され` は1戦あたり窓口経由で届いた累計の平均、`うち吐` はそのうち吐き戻し、");
        Console.WriteLine("`軋み` は自前の上昇（**条件に入らない**）。各列は 5 波 × 試行のうちその点へ届いた割合で、");
        Console.WriteLine("次の行が届いた試行だけの平均ターン。**閾値の候補はこの格子から採る。**");
        Console.WriteLine();
        Console.Write("| 行 | 振/戦 | 押され | うち吐 | 軋み |");
        foreach (int q in UnitTally.CreakWhetProbes) Console.Write($" {q} |");
        Console.WriteLine();
        Console.Write("|---|--:|--:|--:|--:|");
        foreach (int _ in UnitTally.CreakWhetProbes) Console.Write("--:|");
        Console.WriteLine();
        double ckDen = ckStages.Count * ckSeedN;
        foreach ((string rn, Formation f) in ckRows.Append(ckDemo).Append(ckDemoPlain))
        {
            var g = CkRun(f, 0);
            Console.Write($"| {rn} | {g.Swings:F2} | {g.WhetGain:F1} | {g.RegurgGain:F1} | {g.SelfGain:F1} |");
            for (int i = 0; i < UnitTally.CreakWhetProbes.Length; i++)
                Console.Write($" {g.ProbeN[i] * 100.0 / ckDen:F1}% |");
            Console.WriteLine();
            Console.Write("|  |  |  |  | 到達T |");
            for (int i = 0; i < UnitTally.CreakWhetProbes.Length; i++)
                Console.Write(g.ProbeN[i] > 0 ? $" {g.ProbeT[i] / g.ProbeN[i]:F2} |" : " — |");
            Console.WriteLine();
        }
        Console.WriteLine();
        Console.WriteLine("## 0-5. 主判定19行との重なりと、Q6 の実効レンジ（自己検査 (c)）");
        Console.WriteLine();
        var ckPrimary0 = new HashSet<string>(Baseline.PrimaryRows);
        var ckIn0 = ckRows.Where(b => ckPrimary0.Contains(b.Name)).Select(b => b.Name).ToArray();
        Console.WriteLine($"ヨミを含む行は **{ckRows.Length} 行**、うち主判定 {Baseline.PrimaryRows.Length} 行に "
                          + $"**{ckIn0.Length} 行**（{string.Join(" / ", ckIn0)}）。");
        Console.WriteLine();
        double[] ckFifth0 = Baseline.PrimaryRows
            .Select(n => Array.FindIndex(ckAll, b => b.Name == n)).Where(i => i >= 0)
            .Select(i => CkRun(ckAll[i].Item2, 0).Win[4]).ToArray();
        double ckAvg0 = ckFifth0.Average();
        double ckSwing0 = ckIn0.Select(n => CkRun(ckAll[Array.FindIndex(ckAll, b => b.Name == n)].Item2, 0).Win[4]).Sum()
                          / ckFifth0.Length;
        Console.WriteLine($"主判定の第五波平均（現行）= **{ckAvg0:F1}%**、歯止め {Baseline.PrimaryFifthFloor:F1}% との余裕 "
                          + $"**{ckAvg0 - Baseline.PrimaryFifthFloor:F1}pt**。");
        Console.WriteLine($"重なる {ckIn0.Length} 行が第五波で 0.0% まで落ちても平均の低下は最大 **{ckSwing0:F2}pt**"
                          + "——**実効レンジがこの幅**。");
        Console.WriteLine();
        Console.WriteLine("## 0-6. 陰性対照の分母");
        Console.WriteLine();
        Console.WriteLine($"ヨミを含まない **{ckOther.Length} 行**（{ckOther.Length} × 5 波 = **{ckOther.Length * 5} セル**）。");
        Console.WriteLine();
        Console.WriteLine($"所要 {ckSw.Elapsed.TotalSeconds:F1} 秒。");
        return;
    }

    // ---- 主表 -------------------------------------------------------------------
    Console.WriteLine($"# 軋みが響く（第67期） —— 主表{(ckAlt ? "・再現帯" : "")}");
    Console.WriteLine();
    Console.WriteLine($"seed {ckSeed0}..{ckSeed0 + ckSeedN - 1} × 5 波。帰属 = V_n − V0。");
    Console.WriteLine("**席は現行のまま（`reseat` しない）／行は4本に固定（測定前の宣言）。**");
    Console.WriteLine($"閾値は `WhetReceived`（窓口経由の累計）で **{ckVer[1]} / {ckVer[2]} / {ckVer[3]}**。");
    Console.WriteLine();

    var ckMain = ckRows.Append(ckDemo).ToArray();
    var ckBase = new Dictionary<string, double[]>();
    foreach ((string rn, Formation f) in ckMain.Append(ckDemoPlain)) ckBase[rn] = CkRun(f, 0).Win;

    Console.WriteLine("## 1. 行 × 版（波ごとの勝率・平均・帰属・薙ぎ化率）");
    Console.WriteLine();
    Console.WriteLine("| 行 | 版 | 第1波 | 第2波 | 第3波 | 第4波 | 第5波 | 平均 | 帰属 | 薙ぎ化率 | 振/戦 | 押され | 初到達T |");
    Console.WriteLine("|---|---|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|");
    var ckAttr = new Dictionary<string, double[]>();
    var ckRate = new Dictionary<string, double[]>();
    foreach ((string rn, Formation f) in ckMain)
    {
        var attr = new double[ckVer.Length];
        var rate = new double[ckVer.Length];
        for (int v = 0; v < ckVer.Length; v++)
        {
            var g = CkRun(f, ckVer[v]);
            double avg = g.Win.Average();
            attr[v] = avg - ckBase[rn].Average();
            rate[v] = g.Swings > 0 ? g.Sweeps * 100.0 / g.Swings : 0;
            int pi = Array.IndexOf(UnitTally.CreakWhetProbes, ckVer[v]);
            string ft = pi >= 0 && g.ProbeN[pi] > 0 ? (g.ProbeT[pi] / g.ProbeN[pi]).ToString("F2") : "—";
            Console.WriteLine($"| {(v == 0 ? rn : "")} | {ckVerName[v]} | "
                              + string.Join(" | ", g.Win.Select(x => $"{x:F1}%"))
                              + $" | {avg:F1}% | {(v == 0 ? "—" : $"{attr[v]:+0.0;-0.0}")} "
                              + $"| {rate[v]:F1}% | {g.Swings:F2} | {g.WhetGain:F1} | {ft} |");
        }
        ckAttr[rn] = attr; ckRate[rn] = rate;
    }
    Console.WriteLine();

    // ---- Q1 → 閾値の採用 ---------------------------------------------------------
    Console.WriteLine("## 2. Q1（条件は条件か）と閾値の採用");
    Console.WriteLine();
    Console.WriteLine("**採る版は「Q1 を満たす版のうち帰属が最大のもの。同点は高い閾値」**（§2-2・測る前に固定）。");
    Console.WriteLine("Q1 = 採る版で、**4行中3行**の薙ぎ化率が **10% 以上 90% 以下**。**90% 超が1行でもあれば×。**");
    Console.WriteLine();
    Console.WriteLine("| 版 | 閾値 | 薙ぎ化率（4行） | 帯内 | 90%超 | Q1 | 帰属（4行平均） |");
    Console.WriteLine("|---|--:|---|--:|--:|---|--:|");
    int ckPick = -1; double ckPickAttr = double.NegativeInfinity;
    for (int v = 1; v < ckVer.Length; v++)
    {
        var rr = ckMain.Select(b => ckRate[b.Item1][v]).ToArray();
        int inBand = rr.Count(x => x >= 10.0 && x <= 90.0);
        int over = rr.Count(x => x > 90.0);
        bool q1 = inBand >= 3 && over == 0;
        double aa = ckMain.Select(b => ckAttr[b.Item1][v]).Average();
        Console.WriteLine($"| {ckVerName[v]} | {ckVer[v]} | {string.Join(" / ", rr.Select(x => $"{x:F1}%"))} "
                          + $"| {inBand} | {over} | {(q1 ? "○" : "×")} | {aa:+0.0;-0.0} |");
        if (q1 && aa >= ckPickAttr) { ckPickAttr = aa; ckPick = v; }
    }
    Console.WriteLine();
    if (ckPick < 0) Console.WriteLine("**Q1 を満たす版が1つも無い → 採らない（残置）。**");
    else Console.WriteLine($"→ 採る版は **{ckVerName[ckPick]}（Threshold = {ckVer[ckPick]}）**。");
    Console.WriteLine();

    // ---- Q3ダッシュ（主判定・読み手か） ---------------------------------------------
    Console.WriteLine("## 3. Q3'（**主判定**: 外の供給を読んでいるか）");
    Console.WriteLine();
    Console.WriteLine("`軋み×吐き戻し` のゴルムだけを同数値・特性なしの素体に落とす（他の4枚と席は動かさない）。");
    Console.WriteLine("**薙ぎ化率が 1/5 以下に落ちること。**落ちなければ条件は外の供給を読んでいない。");
    Console.WriteLine();
    Console.WriteLine("| 版 | 閾値 | 現行の薙ぎ化率 | 素体の薙ぎ化率 | 比 | 押され（現行→素体） | 1/5 以下 |");
    Console.WriteLine("|---|--:|--:|--:|--:|---|---|");
    for (int v = 1; v < ckVer.Length; v++)
    {
        var gn = CkRun(ckDemo.Item2, ckVer[v]);
        var gp = CkRun(ckDemoPlain.Item2, ckVer[v]);
        double rn2 = gn.Swings > 0 ? gn.Sweeps * 100.0 / gn.Swings : 0;
        double rp = gp.Swings > 0 ? gp.Sweeps * 100.0 / gp.Swings : 0;
        double ratio = rn2 > 0 ? rp / rn2 : 0;
        Console.WriteLine($"| {ckVerName[v]} | {ckVer[v]} | {rn2:F1}% | {rp:F1}% | {ratio:F2} "
                          + $"| {gn.WhetGain:F1} → {gp.WhetGain:F1} | {(rn2 > 0 && ratio <= 0.2 ? "○" : "×")} |");
    }
    Console.WriteLine();

    // ---- Q2 ------------------------------------------------------------------------
    if (ckPick >= 0)
    {
        Console.WriteLine("## 4. Q2（帰属）");
        Console.WriteLine();
        Console.WriteLine("| 行 | 帰属 | ≥ +1.5pt | ≥ −3.0pt |");
        Console.WriteLine("|---|--:|---|---|");
        foreach ((string rn, Formation _) in ckMain)
        {
            double a = ckAttr[rn][ckPick];
            Console.WriteLine($"| {rn} | {a:+0.0;-0.0} | {(a >= 1.5 ? "○" : "×")} | {(a >= -3.0 ? "○" : "**×**")} |");
        }
        int okN = ckMain.Count(b => ckAttr[b.Item1][ckPick] >= 1.5);
        bool floorOk = ckMain.All(b => ckAttr[b.Item1][ckPick] >= -3.0);
        Console.WriteLine();
        Console.WriteLine($"**Q2 = {(okN >= 2 && floorOk ? "○" : "×")}**（+1.5pt 以上が {okN} / 4 行"
                          + $"・下限を割った行 {ckMain.Count(b => ckAttr[b.Item1][ckPick] < -3.0)}）。");
        Console.WriteLine();
    }

    // ---- Q4 / Q5 / Q6 / Q7 ---------------------------------------------------------
    Console.WriteLine("## 5. Q4（情報セル）・Q5（陰性対照）・Q6（歯止め）・Q7（絵）");
    Console.WriteLine();
    int InfoCells(double[] w) => w.Skip(1).Count(x => x > 0.0 && x < 100.0);
    Console.WriteLine("| 行 | 情報セル V0 | " + string.Join(" | ", ckVerName.Skip(1).Select(n => $"情報セル {n}")) + " |");
    Console.WriteLine("|---|--:|--:|--:|--:|");
    foreach ((string rn, Formation f) in ckMain)
        Console.WriteLine($"| {rn} | {InfoCells(ckBase[rn])} | "
                          + string.Join(" | ", ckVer.Skip(1).Select(t => InfoCells(CkRun(f, t).Win).ToString())) + " |");
    Console.WriteLine();

    int ckDiff = 0;
    foreach ((string rn, Formation f) in ckOther)
    {
        double[] b0 = CkRun(f, 0).Win;
        foreach (int t in ckVer.Skip(1))
        {
            double[] bt = CkRun(f, t).Win;
            for (int w = 0; w < b0.Length; w++) if (Math.Abs(b0[w] - bt[w]) > 1e-9) ckDiff++;
        }
    }
    Console.WriteLine($"**Q5**: ヨミを含まない {ckOther.Length} 行 × 5 波 = {ckOther.Length * 5} セルを"
                      + $"3つの閾値で照合 → **ずれ {ckDiff} 件**。");
    Console.WriteLine();

    var ckPrimIdx = Baseline.PrimaryRows.Select(n => Array.FindIndex(ckAll, b => b.Name == n))
                                        .Where(i => i >= 0).ToArray();
    foreach (int v in (ckPick < 0 ? new[] { 0 } : new[] { 0, ckPick }))
    {
        double avg = ckPrimIdx.Select(i => CkRun(ckAll[i].Item2, ckVer[v]).Win[4]).Average();
        Console.WriteLine($"**Q6**: 主判定 {ckPrimIdx.Length} 行の第五波平均（{ckVerName[v]}）= **{avg:F1}%**"
                          + $"、歯止め {Baseline.PrimaryFifthFloor:F1}% との余裕 **{avg - Baseline.PrimaryFifthFloor:F1}pt**。");
    }
    Console.WriteLine();
    Console.WriteLine("**Q7**（絵）: 初到達Tは §1 の最右列。第66期の 1.55〜2.55 より遅いことが条件。");
    Console.WriteLine();
    Console.WriteLine($"所要 {ckSw.Elapsed.TotalSeconds:F1} 秒。");
    return;
}


// 棚卸し: 条件付き変質を載せられる駒はどれか（第68期・調査）。
// **この期は新しい機構を1つも作らない。駒を作らない。最後の1枠を使わない。`docs/` の差分はゼロ。**
//
// 第66・67期はヨミ1枚で2回落ちた。落ちた理由は駒の性質ではなく**供給の時間分布**だった
// （第67期 7-2: 開戦時一括の供給は閾値を上げても 100% → 0% の2値にしか割れない）。
// ここでやるのは、第67期の格子（閾値ごとの到達%と到達T）を
// **ヨミ専用から全51体・全キーへ一般化する**こと。**既存モードは1行も書き換えていない。**
//
// 足したのは **誰も読んで分岐しない計数**（`UnitTally.Carry*`。窓口 `Whet` / `Dull` /
// `ApplyDamage` / `SwapSlots` と `UnitState.SetCounter` の5箇所で積む）だけで、
// **特性の側には1行も足していない**。`compare` は 305 セル 0 件で一致する（Q5）。
//
//     dotnet run --project BattleSim -c Release 0 carry        # 表A・表B と Q1〜Q3（両 seed 帯）
//     dotnet run --project BattleSim -c Release 0 carry keys   # 表C（供給の形の一覧。同じ走査を A 帯だけで）
//     dotnet run --project BattleSim -c Release 0 carry solo   # 表D（単独成立度）と Q4
//     dotnet run --project BattleSim -c Release 0 carry leak   # 表E（`AcceptsSupport` の漏れの地図）
//     dotnet run --project BattleSim -c Release 0 carry check  # Q5（陰性対照）
if (focusId == "carry")
{
    string cyArg = args.Length > 2 ? args[2] : "";
    IReadOnlyList<EnemyCatalog.Stage> cyStages = EnemyCatalog.Stages;
    var cyRows = CompareBuilds();
    int cyNK = UnitTally.CarryKeys.Length;
    int cyNP = UnitTally.CarryProbes.Length;
    var cySw = System.Diagnostics.Stopwatch.StartNew();

    // ---- 形の判定（**測る前に固定**。指示書 §1-3 の判定式をコードにしたもの） ----------
    //
    // 不発: 格子1 への到達% < 20
    // 2値 : 到達% が 80 以上の最大格子と 20 未満の最小格子が**隣り合う**、
    //       または到達T の 最大−最小 < 0.5 ターン（**到達した格子点が2つ以上あるときだけ**
    //       ——1点しか無い「幅」は幅ではない。指示書が書いていない側を埋めた1点）
    // 連続: 到達% が 20〜80 に入る格子が 2 つ以上、かつ**その帯の格子点の上で**到達T が単調増加
    //       （帯の外＝裾の到達T は「そこまで届いた試行」の偏りで前後する。
    //        指示書の1文が同じ格子点について2つの条件を並べていると読んだ）
    // 他  : どれにも当たらない
    //
    // 優先順位は 不発 → 2値 → 連続 → 他。**重なりうるので順序を測る前に決めてある。**
    const string CyMute = "不発", CyBin = "2値", CyCont = "連続", CyElse = "他";
    string CyForm(int trials, int[] n, double[] tsum)
    {
        if (trials == 0) return CyMute;
        var p = new double[cyNP];
        for (int i = 0; i < cyNP; i++) p[i] = n[i] * 100.0 / trials;
        if (p[0] < 20.0) return CyMute;

        for (int i = 0; i + 1 < cyNP; i++)
            if (p[i] >= 80.0 && p[i + 1] < 20.0) return CyBin;

        var hit = Enumerable.Range(0, cyNP).Where(i => n[i] > 0).ToArray();
        if (hit.Length >= 2)
        {
            var tt = hit.Select(i => tsum[i] / n[i]).ToArray();
            if (tt.Max() - tt.Min() < 0.5) return CyBin;
        }

        var band = Enumerable.Range(0, cyNP).Where(i => p[i] >= 20.0 && p[i] <= 80.0).ToArray();
        if (band.Length >= 2)
        {
            bool mono = true;
            for (int j = 1; j < band.Length; j++)
            {
                double a = tsum[band[j - 1]] / n[band[j - 1]];
                double b = tsum[band[j]] / n[band[j]];
                if (b < a - 1e-9) { mono = false; break; }
            }
            if (mono) return CyCont;
        }
        return CyElse;
    }

    // ---- 1帯ぶんの走査。行 × 駒 のセルに積む -------------------------------------------
    Dictionary<(string Row, string Unit), CyCell> CyScan(int seed0, int seedN)
    {
        var data = new Dictionary<(string Row, string Unit), CyCell>();
        foreach ((string rn, Formation f) in cyRows)
        {
            var members = f.Occupied().Select(o => o.Def).ToArray();
            foreach (UnitDef d in members) data[(rn, d.Id)] = new CyCell(cyNK, cyNP);
            for (int w = 0; w < cyStages.Count; w++)
                for (int seed = seed0; seed < seed0 + seedN; seed++)
                {
                    BattleResult r = BattleEngine.Run(f, cyStages[w].Enemy, seed, verbose: false);
                    foreach (UnitDef d in members)
                    {
                        CyCell c = data[(rn, d.Id)];
                        c.Trials++;
                        if (!r.TallyByUnit.TryGetValue(d.Id, out UnitTally? t)) continue;
                        c.Attacks += t.Attacks;
                        c.AtkGain += t.CarryAtkGain;
                        c.Taken += t.DamageTaken;
                        c.Deaths += t.Deaths;
                        if (t.CarryAmount is int[] am)
                            for (int k = 0; k < cyNK; k++) { c.Amount[k] += am[k]; c.Count[k] += t.CarryCount![k]; }
                        if (t.CarryProbeTurn is int[][] pt)
                            for (int k = 0; k < cyNK; k++)
                            {
                                if (pt[k] is not int[] pk) continue;
                                for (int i = 0; i < cyNP; i++)
                                {
                                    if (pk[i] == 0) continue;
                                    c.ProbeN[k * cyNP + i]++;
                                    c.ProbeT[k * cyNP + i] += pk[i];
                                }
                            }
                    }
                }
            Console.Error.Write(".");
        }
        Console.Error.WriteLine();
        return data;
    }

    // 駒 → その駒を含む行（compare の並び順）
    var cyUnitRows = new Dictionary<string, List<string>>();
    foreach ((string rn, Formation f) in cyRows)
        foreach ((_, UnitDef d) in f.Occupied())
        {
            if (!cyUnitRows.TryGetValue(d.Id, out var l)) cyUnitRows[d.Id] = l = new List<string>();
            if (!l.Contains(rn)) l.Add(rn);
        }
    var cyRoster = UnitCatalog.All.Where(u => cyUnitRows.ContainsKey(u.Id)).ToArray();

    string CyFormOf(CyCell c, int k)
    {
        var n = new int[cyNP];
        var t = new double[cyNP];
        for (int i = 0; i < cyNP; i++) { n[i] = c.ProbeN[k * cyNP + i]; t[i] = c.ProbeT[k * cyNP + i]; }
        return CyForm(c.Trials, n, t);
    }

    // ---- 表E: `AcceptsSupport` の漏れの地図 ---------------------------------------------
    if (cyArg == "leak")
    {
        // ガルドから `Stoic` **だけ**を外した版。数値も庇うも1つも動かさない
        // （規則にノブを増やさず駒の側で塞ぐ。第47期・`gradient` / `aim` と同じ扱い）。
        var cyGaldOpen = new UnitDef
        {
            Id = UnitCatalog.Gald.Id,
            Name = "ガルド（Stoic なし）",
            MaxHp = UnitCatalog.Gald.MaxHp,
            Attack = UnitCatalog.Gald.Attack,
            Speed = UnitCatalog.Gald.Speed,
            Traits = new[] { TraitId.Guardian },
            PlusText = "", MinusText = "", Flavor = ""
        };

        var galdRows = cyRows.Where(b => b.F.Occupied().Any(o => o.Def.Id == UnitCatalog.Gald.Id)).ToArray();

        Console.WriteLine("# 表E —— `AcceptsSupport` の漏れの地図（第68期）");
        Console.WriteLine();
        Console.WriteLine($"seed 0..199 × {cyStages.Count} 波。ガルド（`Stoic`）を含む **{galdRows.Length} 行**。");
        Console.WriteLine("`SupportTargets` は受け取らない駒のぶんを**隣接する味方へそのまま流す**ので、");
        Console.WriteLine("ガルドの隣は**直接ぶんと拡散ぶんで二重に受ける**（第67期 7-4 の一般化）。");
        Console.WriteLine();
        Console.WriteLine("漏れ量は対照との差で測る——**ガルドから `Stoic` だけを外した版**（数値も庇うも同一）を");
        Console.WriteLine("同じ席で回し、隣接する味方の受取の差を取る。**この対照は盤面を動かす**");
        Console.WriteLine("（`Stoic` は受取そのものを止める性質なので、切れば拡散が消えると同時に本人が受け取り始める）");
        Console.WriteLine("——第56期の作法どおり、読みは「狙った経路の計数が動いたか」の1本で取る。");
        Console.WriteLine();
        Console.WriteLine("| 行 | ガルドの席 | 次数 | 隣接する味方 | 強化・隣（現行） | 強化・隣（Stoic なし） | 漏れ（強化） "
                          + "| 弱体・隣（現行） | 弱体・隣（Stoic なし） | 漏れ（弱体） | ガルド本人（現行→Stoic なし） |");
        Console.WriteLine("|---|---|--:|---|--:|--:|--:|--:|--:|--:|---|");

        double totWhet = 0, totDull = 0;
        foreach ((string rn, Formation f) in galdRows)
        {
            int gslot = f.Occupied().First(o => o.Def.Id == UnitCatalog.Gald.Id).Slot;
            var neigh = f.Occupied().Where(o => o.Slot != gslot && FormationRules.AreAdjacent(gslot, o.Slot))
                                    .Select(o => o.Def).ToArray();
            var open = new Formation();
            foreach ((int sl, UnitDef d) in f.Occupied())
                open[sl] = d.Id == UnitCatalog.Gald.Id ? cyGaldOpen : d;

            (double W, double D, double GW, double GD) Measure(Formation g)
            {
                double w = 0, d2 = 0, gw = 0, gd = 0;
                int n = 0;
                for (int wv = 0; wv < cyStages.Count; wv++)
                    for (int seed = 0; seed < 200; seed++)
                    {
                        BattleResult r = BattleEngine.Run(g, cyStages[wv].Enemy, seed, verbose: false);
                        n++;
                        foreach (UnitDef nd in neigh)
                            if (r.TallyByUnit.TryGetValue(nd.Id, out UnitTally? t) && t.CarryAmount is int[] a)
                            {
                                w += a[UnitTally.CarryWhet];
                                d2 += a[UnitTally.CarryDull];
                            }
                        if (r.TallyByUnit.TryGetValue(UnitCatalog.Gald.Id, out UnitTally? gt) && gt.CarryAmount is int[] ga)
                        {
                            gw += ga[UnitTally.CarryWhet];
                            gd += ga[UnitTally.CarryDull];
                        }
                    }
                return (w / n, d2 / n, gw / n, gd / n);
            }

            var cur = Measure(f);
            var alt = Measure(open);
            double lkW = cur.W - alt.W, lkD = cur.D - alt.D;
            // 表示上 0 に丸まる負の微小値を潰す（書式の負セクションに落ちて `-+0.00` になる）
            if (Math.Abs(lkW) < 0.005) lkW = 0;
            if (Math.Abs(lkD) < 0.005) lkD = 0;
            int deg = 0;
            for (int i = 0; i < FormationRules.PlayableSlotCount; i++)
                if (FormationRules.AreAdjacent(gslot, i)) deg++;
            totWhet += lkW;
            totDull += lkD;
            Console.WriteLine($"| {rn} | {FormationRules.SeatNames[gslot]} | {deg} | {string.Join(" / ", neigh.Select(x => x.Name))} "
                              + $"| {cur.W:F2} | {alt.W:F2} | **{lkW:+0.00;-0.00}** "
                              + $"| {cur.D:F2} | {alt.D:F2} | **{lkD:+0.00;-0.00}** "
                              + $"| 強化 {cur.GW:F2}→{alt.GW:F2} / 弱体 {cur.GD:F2}→{alt.GD:F2} |");
            Console.Out.Flush();
        }
        Console.WriteLine();
        Console.WriteLine($"**漏れの合計（{galdRows.Length} 行平均）: 強化 {totWhet / galdRows.Length:+0.00;-0.00} 量/戦 / "
                          + $"弱体 {totDull / galdRows.Length:+0.00;-0.00} 量/戦。**");
        Console.WriteLine();
        Console.WriteLine($"所要 {cySw.Elapsed.TotalSeconds:F1} 秒。");
        return;
    }

    // ---- Q5: 陰性対照 --------------------------------------------------------------------
    if (cyArg == "check")
    {
        Console.WriteLine("# Q5 —— 陰性対照（第68期）");
        Console.WriteLine();
        Console.WriteLine($"`compare` と同じ走査（{cyRows.Length} 行 × {cyStages.Count} 波 × seed 0..199）を");
        Console.WriteLine("**`verbose` の有無**で2回回し、1セルも違わないことを確かめる。");
        Console.WriteLine("計数は `UnitTally` の私有カウンタで誰も読んで分岐しないので原理的には一致するが、");
        Console.WriteLine("第68期は `UnitState.SetCounter` と `AtkBonus` の setter に通知を足したので、");
        Console.WriteLine("**乱数列が動いていないこと**をここで直に見る（`docs/balance.md` との照合は `compare` の diff で別に取る）。");
        Console.WriteLine();
        int diff = 0;
        Console.WriteLine("| 行 | 第1波 | 第2波 | 第3波 | 第4波 | 第5波 |");
        Console.WriteLine("|---|--:|--:|--:|--:|--:|");
        foreach ((string rn, Formation f) in cyRows)
        {
            var win = new double[cyStages.Count];
            for (int w = 0; w < cyStages.Count; w++)
            {
                int a = 0, b = 0;
                for (int seed = 0; seed < 200; seed++)
                {
                    if (BattleEngine.Run(f, cyStages[w].Enemy, seed, verbose: false).PlayerWon) a++;
                    if (BattleEngine.Run(f, cyStages[w].Enemy, seed, verbose: true).PlayerWon) b++;
                }
                if (a != b) diff++;
                win[w] = a / 2.0;
            }
            Console.WriteLine($"| {rn} | " + string.Join(" | ", win.Select(x => $"{x:F1}%")) + " |");
            Console.Out.Flush();
        }
        Console.WriteLine();
        Console.WriteLine($"**`verbose` の有無で食い違ったセル {diff} 件 / {cyRows.Length * cyStages.Count}。**");
        Console.WriteLine();
        Console.WriteLine($"所要 {cySw.Elapsed.TotalSeconds:F1} 秒。");
        return;
    }

    // ---- 表D: 単独成立度（指示書 §1-4） --------------------------------------------------
    if (cyArg == "solo")
    {
        // 相方の定義（**機械的**）: その行で、その駒と**同じキーの書き手または読み手**である他の駒。
        // 判定は grep で作った 特性 → キー の対応表（下）を機械的に当てる。
        // **`Trait` に属性を足さない**——判定の根拠が「誰かが属性を正しく付けたか」に化けて
        // grep で検算できなくなる（第48期 census の作法）。
        //
        // 出典は `BattleCore/Traits.cs` の grep:
        //   `StatusKeys.*` の `SetCounter` / `Counter` ／ `ctx.Whet` ／ `ctx.Dull` ／ `ctx.Ignite` ／
        //   `ctx.SwapSlots` ／ `OnMoved` / `OnAllyMoved` / `OnDamaged` の override。
        // **engine 側の窓口は駒に属さないのでここには入らない**（第50期の窓口一覧の裏返し）。
        // 対応表は `TraitKeyMap`（Program.cs の末尾）に1箇所だけ置いてある。
        int[] CyKeysOf(UnitDef d) => TraitKeyMap.KeysOf(d);

        Console.WriteLine("# 表D —— 単独成立度（第68期）");
        Console.WriteLine();
        Console.WriteLine($"seed 0..199 × {cyStages.Count} 波 × {cyRows.Length} 行。**寄与 = フル編成 − その1枚を抜いた版**");
        Console.WriteLine("（正なら「その駒がいると強い」。`ablate` の `差` とは符号が逆）。");
        Console.WriteLine();
        Console.WriteLine("**相方の定義（機械的・測る前に固定）**: その行で、その駒と**同じキーの書き手または読み手**である他の駒。");
        Console.WriteLine("キーの割り当ては 特性 → キー の対応表（`Traits.cs` の grep から作り、診断のローカルに置いた）。");
        Console.WriteLine("**キーを1つも持たない駒**（数値だけの駒）は相方の判定ができないので別に並べる。");
        Console.WriteLine();

        double CyWin(Formation f)
        {
            int wins = 0, n = 0;
            foreach (EnemyCatalog.Stage st in cyStages)
                for (int seed = 0; seed < 200; seed++)
                {
                    n++;
                    if (BattleEngine.Run(f, st.Enemy, seed, verbose: false).PlayerWon) wins++;
                }
            return wins * 100.0 / n;
        }

        var soloWith = new Dictionary<string, List<double>>();
        var soloAlone = new Dictionary<string, List<double>>();
        // **第141期: 箱は `Everyone`（`All ∪ Retired`）で作る。** `compare` の行にはエグ（第139期に `All` から外した）が
        // 残っているので、`cyRoster`（＝`All` のうち compare に出る駒）だけで箱を作ると `soloWith["egu"]` で落ちる。
        // **表（D-2 以降）は `cyRoster` を回すので行数は動かない**——箱が増えるだけ。
        foreach (UnitDef u in UnitCatalog.Everyone.Where(x => cyUnitRows.ContainsKey(x.Id))) { soloWith[u.Id] = new List<double>(); soloAlone[u.Id] = new List<double>(); }

        Console.WriteLine("## D-1. 行 × 駒（寄与と相方の有無）");
        Console.WriteLine();
        Console.WriteLine("| 行 | フル | 駒 | 抜いた後 | 寄与 | その駒のキー | 相方 |");
        Console.WriteLine("|---|--:|---|--:|--:|---|---|");
        foreach ((string rn, Formation f) in cyRows)
        {
            double full = CyWin(f);
            var members = f.Occupied().ToArray();
            bool first = true;
            foreach ((int slot, UnitDef d) in members)
            {
                var ab = new Formation();
                foreach ((int ms, UnitDef md) in members) if (ms != slot) ab[ms] = md;
                double contrib = full - CyWin(ab);

                int[] mine = CyKeysOf(d);
                var mates = members.Where(o => o.Def.Id != d.Id && CyKeysOf(o.Def).Intersect(mine).Any())
                                   .Select(o => o.Def.Name).ToArray();
                // **キーを1つも持たない駒も「相方なし」に数える**（指示書 §1-4 の字義どおり
                // ——同じキーの書き手／読み手である他の駒が存在しないので、定義上「なし」）。
                // ただしその「なし」は盤面の性質ではなく**キーの一覧が §1-2 の11本しか無いこと**の
                // 影から出ているので、Q4 は保守読み（キー無しを除く）と併記する。
                if (mates.Length > 0) soloWith[d.Id].Add(contrib);
                else soloAlone[d.Id].Add(contrib);

                Console.WriteLine($"| {(first ? rn : "")} | {(first ? $"{full:F1}%" : "")} | {d.Name} "
                    + $"| {full - contrib:F1}% | {contrib:+0.0;-0.0}pt "
                    + $"| {(mine.Length == 0 ? "**キー無し**" : string.Join("・", mine.Select(k => UnitTally.CarryKeys[k])))} "
                    + $"| {(mates.Length == 0 ? "**なし**" : string.Join(" / ", mates))} |");
                first = false;
            }
            Console.Out.Flush();
        }
        Console.WriteLine();

        Console.WriteLine("## D-2. 駒ごとの単独成立度");
        Console.WriteLine();
        Console.WriteLine("| 駒 | 行数 | キー | 相方あり行 | 平均寄与 | 相方なし行 | 平均寄与 | 差（なし − あり） |");
        Console.WriteLine("|---|--:|---|--:|--:|--:|--:|--:|");
        foreach (UnitDef u in cyRoster.OrderByDescending(x => soloAlone[x.Id].Count).ThenBy(x => x.Id))
        {
            var wl = soloWith[u.Id];
            var al = soloAlone[u.Id];
            int[] mk = CyKeysOf(u);
            string wm = wl.Count > 0 ? $"{wl.Average():+0.0;-0.0}pt" : "—";
            string am = al.Count > 0 ? $"{al.Average():+0.0;-0.0}pt" : "—";
            string dd = wl.Count > 0 && al.Count > 0 ? $"{al.Average() - wl.Average():+0.0;-0.0}pt" : "—";
            Console.WriteLine($"| {u.Name} | {cyUnitRows[u.Id].Count} "
                + $"| {(mk.Length == 0 ? "**無し**" : string.Join("・", mk.Select(k => UnitTally.CarryKeys[k])))} "
                + $"| {wl.Count} | {wm} | {al.Count} | {am} | {dd} |");
        }
        Console.WriteLine();

        var haveAlone = cyRoster.Where(u => soloAlone[u.Id].Count > 0).ToArray();
        var noKey = cyRoster.Where(u => CyKeysOf(u).Length == 0).ToArray();
        var haveAloneKeyed = haveAlone.Where(u => CyKeysOf(u).Length > 0).ToArray();
        var noAlone = cyRoster.Where(u => soloAlone[u.Id].Count == 0).ToArray();
        Console.WriteLine("**Q4 は2通りに読める。指示書の字義（キーを持たない駒には相方が存在しない）と、");
        Console.WriteLine("保守読み（キーが無いのは §1-2 のキー一覧が11本しか無いせいなので判定不能として除く）。**");
        Console.WriteLine();
        Console.WriteLine("| 読み | 相方なし行を持つ駒 | Q4（20 駒以上） |");
        Console.WriteLine("|---|--:|---|");
        Console.WriteLine($"| 字義（キー無しも数える） | {haveAlone.Length} | {(haveAlone.Length >= 20 ? "○" : "×")} |");
        Console.WriteLine($"| 保守（キー無しを除く） | {haveAloneKeyed.Length} | {(haveAloneKeyed.Length >= 20 ? "○" : "×")} |");
        Console.WriteLine();
        Console.WriteLine($"**相方なし行が 0 の駒（＝単独では測っていない・第69期の穴）: {noAlone.Length} 駒**");
        Console.WriteLine();
        foreach (UnitDef u in noAlone)
            Console.WriteLine($"- {u.Name}（{cyUnitRows[u.Id].Count} 行・キー: "
                + string.Join("・", CyKeysOf(u).Select(k => UnitTally.CarryKeys[k])) + "）");
        Console.WriteLine();
        Console.WriteLine($"**キーを1つも持たない駒: {noKey.Length} 駒** —— "
            + (noKey.Length == 0 ? "なし" : string.Join(" / ", noKey.Select(u => u.Name))));
        Console.WriteLine("（§1-2 のキー一覧に**回復と死が無い**ぶんがここへ落ちる。");
        Console.WriteLine("墓守・継ぎ接ぎ・胞子体は死の、継ぎ当て・置き去り・散開は回復の駒である。）");
        Console.WriteLine();
        Console.WriteLine($"所要 {cySw.Elapsed.TotalSeconds:F1} 秒。");
        return;
    }

    // ---- ここから先は 表A / 表B / 表C（走査は共通） --------------------------------------
    var cyA = CyScan(0, 200);
    double cyTa = cySw.Elapsed.TotalSeconds;

    double CyAmt(UnitDef u, int k, Dictionary<(string Row, string Unit), CyCell> data)
    {
        double sum = 0;
        long n = 0;
        foreach (string rn in cyUnitRows[u.Id]) { CyCell c = data[(rn, u.Id)]; sum += c.Amount[k]; n += c.Trials; }
        return n > 0 ? sum / n : 0;
    }
    int CyFormRows(UnitDef u, int k, string form, Dictionary<(string Row, string Unit), CyCell> data)
        => cyUnitRows[u.Id].Count(rn => CyFormOf(data[(rn, u.Id)], k) == form);

    // ---- 表C: 供給の形の一覧（`carry keys`） ---------------------------------------------
    if (cyArg == "keys")
    {
        // 経路は `Traits.cs` の grep（フックの位置）から作った静的な表で、
        // **測っているのは右2列だけ**（その供給元を含む行で、そのキーがどの形になったか）。
        // `Trait` が null の行は engine 側／敵側の供給なので、分母は全行になる。
        var cyRoutes = new (int Key, string Route, TraitId? Trait, string Holder, string Hook, string Kind)[]
        {
            (UnitTally.CarryWhet, "号令の鬨", TraitId.Rally, "鬨の号令ガン", "OnBattleStart", "開戦時一括"),
            (UnitTally.CarryWhet, "号令の溜め", TraitId.Rally, "鬨の号令ガン", "OnTurnStart", "毎ターン"),
            (UnitTally.CarryWhet, "縛め", TraitId.Bind, "縛めのクグ", "OnTurnStart", "毎ターン"),
            (UnitTally.CarryWhet, "駆り立て", TraitId.Goad, "駆り立てのカリ", "OnTurnStart", "毎ターン"),
            (UnitTally.CarryWhet, "火選り", TraitId.Favor, "火選りのヒヨ", "OnAction", "毎ターン"),
            (UnitTally.CarryWhet, "移り木", TraitId.Drifter, "移り木のシオ", "OnAllyMoved", "事象ごと（移動）"),
            (UnitTally.CarryWhet, "吐き戻し", TraitId.Colossus, "大喰らいゴルム", "ApplyDamage（engine）", "事象ごと（被弾）"),
            (UnitTally.CarryDull, "呪詛（味方漏れ）", TraitId.Curse, "呪詛官ネル", "OnBattleStart", "開戦時一括"),
            (UnitTally.CarryDull, "萎縮", TraitId.Cower, "萎縮のクビ", "OnBattleStart", "開戦時一括"),
            (UnitTally.CarryDull, "火選りの鈍り", TraitId.Favor, "火選りのヒヨ", "OnAction", "毎ターン"),
            (UnitTally.CarryDull, "突き返しのよろけ", TraitId.Shove, "突き返しのハネ", "OnMoved / OnAllyMoved", "事象ごと（移動）"),
            (UnitTally.CarryDull, "分かちのなまり", TraitId.Sharer, "分かちのドハ", "ApplyDamage（engine）", "事象ごと（被弾）"),
            (UnitTally.CarryPoison, "瘴気", TraitId.Miasma, "瘴気袋のグザ", "OnAction", "毎ターン"),
            (UnitTally.CarryPoison, "澱み（増幅）", TraitId.Amplifier, "澱みのミオ", "OnAction", "毎ターン"),
            (UnitTally.CarryPoison, "毒撃", TraitId.Venom, "毒吐きのスィド", "OnDamaged", "事象ごと（被弾）"),
            (UnitTally.CarryPoison, "疫み", TraitId.Contagion, "疫みのラウ", "OnAnyDeath", "事象ごと（死）"),
            (UnitTally.CarryBurn, "火の粉", TraitId.Cinder, "焼け残りのボルグ", "OnAfterAttack", "事象ごと（攻撃）"),
            (UnitTally.CarryBurn, "破裂の着火", TraitId.Bomber, "爆ぜるゾト", "OnDeath", "事象ごと（死）"),
            (UnitTally.CarryStun, "縛め（味方）", TraitId.Bind, "縛めのクグ", "OnTurnStart", "毎ターン"),
            (UnitTally.CarryStun, "痺れ粉", TraitId.Paralyze, "痺れ粉のトウ", "OnAfterAttack", "事象ごと（攻撃）"),
            (UnitTally.CarryStun, "責め苦", TraitId.Torment, "責め苦のシガ", "OnAfterAttack", "事象ごと（攻撃）"),
            (UnitTally.CarryStun, "抉りの怯み", TraitId.Gouge, "抉りのエグ", "OnAfterAttack", "事象ごと（攻撃）"),
            (UnitTally.CarryStun, "仇討ちの代金", TraitId.Avenge, "仇討ちのザン", "OnAllyDamaged（自分に）", "事象ごと（味方の被弾）"),
            (UnitTally.CarryStun, "断罪（敵）", null, "勇者候補 / 審問官", "OnDamaged", "事象ごと（被弾）"),
            (UnitTally.CarryMark, "囃し立て", TraitId.Marker, "囃し立てのヒサ", "OnBattleStart", "開戦時一括"),
            (UnitTally.CarryMark, "逸らし", TraitId.Divert, "逸らしのソラ", "OnTurnStart", "毎ターン"),
            (UnitTally.CarryMark, "駆り立ての標", TraitId.Goad, "駆り立てのカリ", "OnTurnStart", "毎ターン"),
            (UnitTally.CarryArmor, "砕け", TraitId.Shatter, "砕け盾のヒビ", "OnDamaged", "事象ごと（被弾）"),
            (UnitTally.CarryArmor, "鱗（自前）", TraitId.Scale, "鱗のウロ", "OnAllyDeath", "事象ごと（死）"),
            (UnitTally.CarryArmor, "引き受け", TraitId.Bear, "引き受けのウケ", "Dull（engine）", "事象ごと（弱体）"),
            (UnitTally.CarryWound, "裂き", TraitId.Rend, "裂きのキリ", "OnAfterAttack", "事象ごと（攻撃）"),
            (UnitTally.CarryWound, "刻み", TraitId.Carve, "刻みのノミ", "OnAfterAttack", "事象ごと（攻撃）"),
            (UnitTally.CarryIdle, "engine の痺れ振替", null, "engine", "行動順ループ", "事象ごと（痺れ）"),
            (UnitTally.CarryHit, "engine の被弾", null, "engine", "ApplyDamage", "事象ごと（被弾）"),
            (UnitTally.CarryMove, "喧噪", TraitId.Shuffler, "喧噪のバサ", "OnTurnStart", "毎ターン"),
            (UnitTally.CarryMove, "逃亡", TraitId.Coward, "逃亡兵セロ", "OnTurnStart", "毎ターン"),
            (UnitTally.CarryMove, "棘守り", TraitId.ThornGuard, "棘鎧のカド", "OnDamaged", "事象ごと（被弾）"),
            (UnitTally.CarryMove, "突き返し", TraitId.Shove, "突き返しのハネ", "OnMoved / OnAllyMoved", "事象ごと（移動）"),
            (UnitTally.CarryMove, "曝き（敵・第五波）", null, "告発人", "OnAfterAttack", "事象ごと（攻撃）"),
        };

        Console.WriteLine("# 表C —— 供給の形の一覧（第68期）");
        Console.WriteLine();
        Console.WriteLine($"A 帯 seed 0..199 × {cyStages.Count} 波 × {cyRows.Length} 行。");
        Console.WriteLine("経路・フック・分類は `BattleCore/Traits.cs` の grep（フックの位置）から。");
        Console.WriteLine("**測っているのは右2列だけ**——その供給元を含む行で、そのキーの形が何になったか");
        Console.WriteLine("（分母はその行の5枚ぶん。`Trait` が engine 側・敵側の経路は全行が分母）。");
        Console.WriteLine();
        Console.WriteLine("| キー | 経路 | 供給元 | フック | 分類 | 含む行 | 受け手の形 連 / 二 / 他 / 不 |");
        Console.WriteLine("|---|---|---|---|---|--:|---|");
        foreach (var rt in cyRoutes)
        {
            var rows = rt.Trait is TraitId tid
                ? cyRows.Where(b => b.F.Occupied().Any(o => o.Def.Traits.Contains(tid))).ToArray()
                : cyRows;
            int co = 0, bi = 0, el = 0, mu = 0;
            foreach ((string rn, Formation f) in rows)
                foreach ((_, UnitDef d) in f.Occupied())
                {
                    if (!cyA.TryGetValue((rn, d.Id), out CyCell? c)) continue;
                    string fm = CyFormOf(c, rt.Key);
                    if (fm == CyCont) co++;
                    else if (fm == CyBin) bi++;
                    else if (fm == CyElse) el++;
                    else mu++;
                }
            Console.WriteLine($"| {UnitTally.CarryKeys[rt.Key]} | {rt.Route} | {rt.Holder} | `{rt.Hook}` | **{rt.Kind}** "
                + $"| {rows.Length} | {co} / {bi} / {el} / {mu} |");
        }
        Console.WriteLine();
        Console.WriteLine("## 分類ごとの集計");
        Console.WriteLine();
        Console.WriteLine("| 分類 | 経路数 | キー |");
        Console.WriteLine("|---|--:|---|");
        foreach (var g in cyRoutes.GroupBy(r => r.Kind).OrderByDescending(g => g.Count()))
            Console.WriteLine($"| {g.Key} | {g.Count()} | "
                + string.Join("・", g.Select(r => UnitTally.CarryKeys[r.Key]).Distinct()) + " |");
        Console.WriteLine();
        Console.WriteLine($"所要 {cySw.Elapsed.TotalSeconds:F1} 秒。");
        return;
    }

    // ---- 表A・表B と Q1〜Q3 ---------------------------------------------------------------
    var cyB = CyScan(200, 400);
    double cyTb = cySw.Elapsed.TotalSeconds - cyTa;

    Console.WriteLine("# 棚卸し —— 条件付き変質を載せられる駒はどれか（第68期 carry）");
    Console.WriteLine();
    Console.WriteLine($"A 帯 seed 0..199 / B 帯 seed 200..599 × {cyStages.Count} 波 × {cyRows.Length} 行。");
    Console.WriteLine($"ロスター {UnitCatalog.All.Count} 体のうち compare に出る **{cyRoster.Length} 体**が対象。");
    Console.WriteLine("**盤面は1ビットも動かない**（計数だけ。`compare` は 305 セル 0 件で一致する）。");
    Console.WriteLine();
    Console.WriteLine("キーの単位: " + string.Join(" / ", Enumerable.Range(0, cyNK)
        .Select(k => $"{UnitTally.CarryKeys[k]} = {UnitTally.CarryUnits[k]}")) + "。");
    Console.WriteLine($"格子は **{string.Join(" / ", UnitTally.CarryProbes)}**（第67期の `CreakWhetProbes` と同じ9点）。");
    Console.WriteLine();

    // ---- 表A-1 --------------------------------------------------------------------------
    Console.WriteLine("## 表A-1. 駒 × キー の在庫（1戦あたりの届いた累計・A 帯）");
    Console.WriteLine();
    Console.WriteLine("`自前` は `AtkBonus` が上がった総量から窓口経由（強化）を引いた残り＝**自己強化9本の合計**。");
    Console.WriteLine("**条件の候補には入れない**（第66期: 自分で作れる値を条件にすると閾値が起動スイッチになる）。");
    Console.WriteLine("`被ダメ` は被弾の**量**（被弾のキー自体は回数）。");
    Console.WriteLine();
    Console.Write("| 駒 | 行数 | 振/戦 | 自前 | 被ダメ |");
    foreach (string k in UnitTally.CarryKeys) Console.Write($" {k} |");
    Console.WriteLine();
    Console.Write("|---|--:|--:|--:|--:|");
    foreach (string _ in UnitTally.CarryKeys) Console.Write("--:|");
    Console.WriteLine();
    foreach (UnitDef u in cyRoster.OrderBy(x => x.Id))
    {
        long tr = 0;
        double sw = 0, self = 0, tk = 0;
        foreach (string rn in cyUnitRows[u.Id])
        {
            CyCell c = cyA[(rn, u.Id)];
            tr += c.Trials; sw += c.Attacks; tk += c.Taken;
            self += c.AtkGain - c.Amount[UnitTally.CarryWhet];
        }
        Console.Write($"| {u.Name} | {cyUnitRows[u.Id].Count} | {sw / tr:F2} | {self / tr:F1} | {tk / tr:F0} |");
        for (int k = 0; k < cyNK; k++)
        {
            double v = CyAmt(u, k, cyA);
            Console.Write(v > 0 ? $" {v:F2} |" : " — |");
        }
        Console.WriteLine();
    }
    Console.WriteLine();

    // ---- 表A-2 --------------------------------------------------------------------------
    Console.WriteLine("## 表A-2. 駒 × キー の形（該当行数。`連` = 連続 / `二` = 2値 / `他` = どちらでもない）");
    Console.WriteLine();
    Console.WriteLine("**不発の行は書かない**（届いていない行がほとんどで、書くと表が読めなくなる）。");
    Console.WriteLine("セルの合計がその駒の行数に満たないぶんが不発。**A 帯の判定。**");
    Console.WriteLine();
    Console.Write("| 駒 | 行数 |");
    foreach (string k in UnitTally.CarryKeys) Console.Write($" {k} |");
    Console.WriteLine();
    Console.Write("|---|--:|");
    foreach (string _ in UnitTally.CarryKeys) Console.Write("---|");
    Console.WriteLine();
    foreach (UnitDef u in cyRoster.OrderBy(x => x.Id))
    {
        Console.Write($"| {u.Name} | {cyUnitRows[u.Id].Count} |");
        for (int k = 0; k < cyNK; k++)
        {
            int co = CyFormRows(u, k, CyCont, cyA);
            int bi = CyFormRows(u, k, CyBin, cyA);
            int el = CyFormRows(u, k, CyElse, cyA);
            var parts = new List<string>();
            if (co > 0) parts.Add($"**連{co}**");
            if (bi > 0) parts.Add($"二{bi}");
            if (el > 0) parts.Add($"他{el}");
            Console.Write(parts.Count == 0 ? " — |" : " " + string.Join(" ", parts) + " |");
        }
        Console.WriteLine();
    }
    Console.WriteLine();

    // ---- 表B ----------------------------------------------------------------------------
    Console.WriteLine("## 表B. 載せられる駒の候補（`連続` の行が 2 行以上ある 駒 × キー）");
    Console.WriteLine();
    Console.WriteLine("並びは `連続` の行数の多い順。`B帯` は同じ判定を再現帯でやり直した行数。");
    Console.WriteLine("`型` は `Def.Pattern`（**戦闘中の型ではない**——熾のホタは燃えている間だけ貫きになる）。");
    Console.WriteLine();
    Console.WriteLine("| 駒 | キー | 連続の行数 A / B | 平均量 | 振/戦 | 型 | 含む行数 | 既存の1文（`PlusText`） |");
    Console.WriteLine("|---|---|--:|--:|--:|---|--:|---|");
    var cyCand = new List<(UnitDef U, int K, int A, int B)>();
    foreach (UnitDef u in cyRoster)
        for (int k = 0; k < cyNK; k++)
        {
            int a = CyFormRows(u, k, CyCont, cyA);
            if (a < 2) continue;
            cyCand.Add((u, k, a, CyFormRows(u, k, CyCont, cyB)));
        }
    foreach (var (u, k, a, b) in cyCand.OrderByDescending(x => x.A).ThenBy(x => x.U.Id))
    {
        long tr = 0;
        double sw = 0;
        foreach (string rn in cyUnitRows[u.Id]) { CyCell c = cyA[(rn, u.Id)]; tr += c.Trials; sw += c.Attacks; }
        Console.WriteLine($"| {u.Name} | {UnitTally.CarryKeys[k]} | **{a}** / {b} | {CyAmt(u, k, cyA):F2} "
            + $"| {sw / tr:F2} | {u.Pattern} | {cyUnitRows[u.Id].Count} | {u.PlusText} |");
    }
    Console.WriteLine();
    var cyCarriers = cyCand.Select(x => x.U.Id).Distinct().ToArray();
    Console.WriteLine($"**候補の 駒 × キー は {cyCand.Count} 組、駒の実数は {cyCarriers.Length} 体。**");
    Console.WriteLine($"**Q1 = {(cyCarriers.Length >= 3 ? "○" : "×")}**（表B の駒 {cyCarriers.Length} / 3）。");
    Console.WriteLine();

    // ---- Q2 -----------------------------------------------------------------------------
    Console.WriteLine("## Q2. 形の判定は両 seed 帯で一致するか");
    Console.WriteLine();
    int same = 0, tot = 0, sameLive = 0, totLive = 0;
    var mis = new List<string>();
    foreach (UnitDef u in cyRoster)
        foreach (string rn in cyUnitRows[u.Id])
            for (int k = 0; k < cyNK; k++)
            {
                string fa = CyFormOf(cyA[(rn, u.Id)], k);
                string fb = CyFormOf(cyB[(rn, u.Id)], k);
                tot++;
                if (fa == fb) same++;
                if (fa == CyMute && fb == CyMute) continue;
                totLive++;
                if (fa == fb) sameLive++;
                else mis.Add($"{u.Name} × {UnitTally.CarryKeys[k]} × {rn}: A={fa} / B={fb}");
            }
    Console.WriteLine("| 分母 | 一致 | 一致率 |");
    Console.WriteLine("|---|--:|--:|");
    Console.WriteLine($"| 全セル（駒 × キー × 行） | {same} / {tot} | **{same * 100.0 / tot:F1}%** |");
    Console.WriteLine($"| どちらかの帯で不発でないセル | {sameLive} / {totLive} | **{sameLive * 100.0 / totLive:F1}%** |");
    Console.WriteLine();
    Console.WriteLine($"**Q2 = {(same * 100.0 / tot >= 95.0 ? "○" : "×")}**（全セル一致率 {same * 100.0 / tot:F1}% / 95.0%）。");
    Console.WriteLine();
    Console.WriteLine($"食い違ったセル {mis.Count} 件のうち先頭 40 件:");
    Console.WriteLine();
    foreach (string m in mis.Take(40)) Console.WriteLine($"- {m}");
    Console.WriteLine();

    // ---- Q3: ヨミの再現（器具の検算） -----------------------------------------------------
    Console.WriteLine("## Q3. ヨミの再現（器具の検算）");
    Console.WriteLine();
    Console.WriteLine("第67期 7-2 の判定を、一般化した格子で引き直す。");
    Console.WriteLine("**隊列崩し = 2値 / 移動改・突き出し = 連続**が出れば器具は同じものを測っている。");
    Console.WriteLine();
    Console.WriteLine("| 行 | 強化の形 A | 強化の形 B | 押され | " + string.Join(" | ", UnitTally.CarryProbes) + " |");
    Console.WriteLine("|---|---|---|--:|" + string.Concat(UnitTally.CarryProbes.Select(_ => "--:|")));
    foreach (string rn in cyUnitRows[UnitCatalog.Yomi.Id])
    {
        CyCell c = cyA[(rn, UnitCatalog.Yomi.Id)];
        Console.Write($"| {rn} | **{CyFormOf(c, UnitTally.CarryWhet)}** "
            + $"| {CyFormOf(cyB[(rn, UnitCatalog.Yomi.Id)], UnitTally.CarryWhet)} "
            + $"| {(double)c.Amount[UnitTally.CarryWhet] / c.Trials:F1} |");
        for (int i = 0; i < cyNP; i++)
            Console.Write($" {c.ProbeN[UnitTally.CarryWhet * cyNP + i] * 100.0 / c.Trials:F1}% |");
        Console.WriteLine();
        Console.Write("|  |  |  | 到達T |");
        for (int i = 0; i < cyNP; i++)
        {
            int n = c.ProbeN[UnitTally.CarryWhet * cyNP + i];
            Console.Write(n > 0 ? $" {c.ProbeT[UnitTally.CarryWhet * cyNP + i] / n:F2} |" : " — |");
        }
        Console.WriteLine();
    }
    Console.WriteLine();
    Console.WriteLine($"所要 A 帯 {cyTa:F1} 秒 / B 帯 {cyTb:F1} 秒。");
    Console.WriteLine();
    return;
}

// ============================================================================
// draft モード: ドラフト台（第69期）
//
// **測定台を1つ作るだけの期。** 新機構ゼロ・駒ゼロ・`docs/` 差分ゼロ。
// `CompareBuilds()` も `Stages` も `UnitCatalog` も1行も書き換えていない
// （素体と標本は診断のローカルに組む。`gradient` / `aim` / `scale` と同じ扱い）。
//
// 現在の 61 行は**すべて理想編成**で、コンボが確実に揃うことを前提にしている。
// 第68期の表D で、**ロスターの過半（27 / 51）が相方のいない盤面で一度も測られていない**
// ことが分かった。ここで答えるのは2つだけ:
//
//   問1: 相方が保証されない盤面で、各駒はどれだけ働くか
//   問2: 配置は何ptの価値があるか（無作為配置と規則配置の差がそのまま答え）
//
// **どちらも数えるだけ。設計判断をしない。採否も無い。**
//
//     dotnet run --project BattleSim -c Release 0 draft phase0  # N と M を決める（パイロット）
//     dotnet run --project BattleSim -c Release 0 draft         # 主表（表A〜F）・A 帯
//     dotnet run --project BattleSim -c Release 0 draft alt     # 同じ標本を B 帯（seed 200..）で
//     dotnet run --project BattleSim -c Release 0 draft check   # 陰性対照（Q6）
if (focusId == "draft")
{
    string dfArg = args.Length > 2 ? args[2] : "";
    IReadOnlyList<EnemyCatalog.Stage> dfStages = EnemyCatalog.Stages;
    int dfW = dfStages.Count;
    var dfSw = System.Diagnostics.Stopwatch.StartNew();
    var dfRoster = UnitCatalog.All.ToArray();
    int dfRN = dfRoster.Length;                     // 51

    // ---- 測る前に固定した定数（§1〜§2。**結果を見てから動かしていない**） ----------------
    //
    // 標本の乱数と測定の乱数を分ける（指示書 §1-1）。標本抽選は `DfSampleSeed + 標本番号` の
    // `Random` だけを使い、**戦闘 seed には一切触れない**。戦闘 seed の帯は 0.. と 200.. の2本で、
    // 標本抽選の系列（1000000..）とは重ならない。**帯を変えても標本は1体も変わらない**
    // （`draft check` の (1) がそれを直に確かめる）。
    const int DfSampleSeed = 1_000_000;
    const int DfBandA = 0, DfBandB = 200;

    // M（1標本あたりの戦闘 seed 数）は **8 に固定**。測る前に決めた値で、パイロットで動かさない
    // ——1標本の勝率が 4波 × 8 seed = 32 戦で決まる（刻み 3.1pt）。
    const int DfM = 8;

    // N（標本数）は phase0 のパイロットが §2-1 の式で出した値。
    //
    //     半幅 = 1.96 × s_u / √K_u ≤ 1.5   （s_u = 駒 u の寄与の標本間標準偏差）
    //     K_u  = N × 5 / 51                （51体から無作為5体なので 1駒あたりの在席標本数）
    //     ⇒ N ≥ (51 / 5) × (1.96 × s_max / 1.5)²      s_max = 対象駒の中の最大の s_u
    //
    // **s_max（最悪の駒）で決める**のは、Q2 が「対象駒すべてで ±1.5pt 未満」を要求するため。
    const int DfN = 11000;
    const int DfPilotN = 800;
    const double DfCiTarget = 1.5, DfZ = 1.96;

    // ---- 対象駒（測る前に固定。§2-1 の規則をそのまま当てた結果） --------------------------
    //
    //   (1) 第68期の表D で「相方なし行が 0」だった 27 駒 —— 単独で一度も測られていない駒。この期の主題
    //   (2) ＋ 移動軸の3枚（ヨミ・バサ・シオ）—— **3枚とも (1) に既に入っている**ので新規は 0
    //   (3) ＋ 対照として理想編成で寄与が最大級の3枚（第68期の表D の「相方あり行の寄与」上位で、
    //       かつ (1) に入っていないもの）= ゾト +68.8 / ウロ +47.8 / ネル +41.5
    //
    // 合計 **30 体**（指示書の「33 前後」の内側。(2) が (1) と完全に重なったぶんだけ少ない）。
    UnitDef[] dfTargets =
    {
        // (1) 相方なし行が 0 だった 27 駒（第68期 §10-1 の並び順）
        UnitCatalog.Mudo, UnitCatalog.Sid,  UnitCatalog.Mio,  UnitCatalog.Rau,  UnitCatalog.Beni,
        UnitCatalog.Vio,  UnitCatalog.Yomi, UnitCatalog.Basa, UnitCatalog.Shio, UnitCatalog.Utsu,
        UnitCatalog.Doha, UnitCatalog.Kubi, UnitCatalog.Sekki, UnitCatalog.Hota, UnitCatalog.Hibi,
        UnitCatalog.Shiga, UnitCatalog.Zan, UnitCatalog.Kiri, UnitCatalog.Egu,  UnitCatalog.Nata,
        UnitCatalog.Hari, UnitCatalog.Hane, UnitCatalog.Uke,  UnitCatalog.Wata, UnitCatalog.Kari,
        UnitCatalog.Tome, UnitCatalog.Hiyo,
        // (3) 対照
        UnitCatalog.Zoto, UnitCatalog.Uro,  UnitCatalog.Nel,
    };
    int dfT = dfTargets.Length;
    var dfTargetIdx = new Dictionary<string, int>();
    for (int i = 0; i < dfT; i++) dfTargetIdx[dfTargets[i].Id] = i;

    // 第68期 表D の published 値（駒ごとの平均寄与）。**器具の検算にしか使わない**
    // ——27 駒は「相方なし行 0」なので相方あり行の平均がそのまま全行の平均で、
    // 対照3枚だけ2列を行数で重み付けした（ゾト (2×68.8+7×30.1)/9 / ウロ (47.8+43.6)/2 /
    // ネル (3×41.5+3×12.8)/6）。表の丸めのぶん ±0.1pt の誤差が乗る。
    Dictionary<string, double> DfPublished68() => new()
    {
        [UnitCatalog.Mudo.Id] = 24.2, [UnitCatalog.Sid.Id] = 33.3, [UnitCatalog.Mio.Id] = 38.1,
        [UnitCatalog.Rau.Id] = 22.2, [UnitCatalog.Beni.Id] = 24.1, [UnitCatalog.Vio.Id] = 51.9,
        [UnitCatalog.Yomi.Id] = 51.0, [UnitCatalog.Basa.Id] = 34.3, [UnitCatalog.Shio.Id] = 29.6,
        [UnitCatalog.Utsu.Id] = 57.5, [UnitCatalog.Doha.Id] = 34.5, [UnitCatalog.Kubi.Id] = 45.0,
        [UnitCatalog.Sekki.Id] = 21.1, [UnitCatalog.Hota.Id] = 36.3, [UnitCatalog.Hibi.Id] = 32.5,
        [UnitCatalog.Shiga.Id] = 27.4, [UnitCatalog.Zan.Id] = 33.4, [UnitCatalog.Kiri.Id] = 13.9,
        [UnitCatalog.Egu.Id] = 26.8, [UnitCatalog.Nata.Id] = 19.5, [UnitCatalog.Hari.Id] = 28.6,
        [UnitCatalog.Hane.Id] = 14.6, [UnitCatalog.Uke.Id] = 23.0, [UnitCatalog.Wata.Id] = 44.6,
        [UnitCatalog.Kari.Id] = 26.4, [UnitCatalog.Tome.Id] = 36.7, [UnitCatalog.Hiyo.Id] = 15.8,
        [UnitCatalog.Zoto.Id] = 38.7, [UnitCatalog.Uro.Id] = 45.7, [UnitCatalog.Nel.Id] = 27.2,
    };

    // 素体 = **数値・型・速さが1つも違わず、特性だけを持たない駒**（第47期からの作法）。
    //
    // **`Actions` は落とす。** ミオ・ヒヨ（対象駒）とカド・ノノ（対象外）は `Actions = [Skill]` を
    // 持つが、あれは「術を手番の行動そのものにする」ための機構側の配管で、
    // カタログのコメントも「挙動の差を『攻撃が出ない』だけに絞るため」と書いている。
    // 残すと**素体が1ターンも何もしない駒**になり、機構の帰属に体の値段が丸ごと混ざる。
    // **測る前に決めてコードに固定した1点。**
    var dfPlainDef = dfTargets.Select(d => new UnitDef
    {
        Id = d.Id + "_plain", Name = "素体の" + d.Name,
        MaxHp = d.MaxHp, Attack = d.Attack, Speed = d.Speed,
        Traits = Array.Empty<TraitId>(), Pattern = d.Pattern
    }).ToArray();

    // ---- 相方の定義（第68期 §1-4 / 表D と**同じ機械的定義**をそのまま写した） --------------
    //
    // その標本の中で、その駒と**同じキーの書き手または読み手**である他の駒。
    // 判定は grep で作った 特性 → キー の対応表を機械的に当てる。
    // **`Trait` に属性を足さない**（第48期 census の作法。判定の根拠が
    // 「誰かが属性を正しく付けたか」に化けて grep で検算できなくなる）。
    // **engine 側の窓口は駒に属さないので入らない。**
    // **第141期: キー表は `Everyone`（`All ∪ Retired`）で引く。** `dfTargets` の 30 体はこの期の対象として固定してあり
    // エグ（第139期）とハリ（第108期）を含む——`dfRoster`（＝`All`）で表を作ると `dfKeyOfUnit["egu"]` で落ちる。
    // **抽選の母集団 `dfRoster` は `All` のまま**（列挙は触らない）。
    var dfKeyOfUnit = UnitCatalog.Everyone.ToDictionary(u => u.Id, TraitKeyMap.KeysOf);

    // ---- 標本の作り方（**測る前に固定**） ------------------------------------------------
    //
    // 1. `UnitCatalog.All`（51体）から無作為に5体（重複なし・部分 Fisher-Yates）
    // 2. R 版 = その5体を無作為に5席へ（**同じ `Random` の続き**。戦闘 seed には触れない）
    // 3. H 版 = §1-3 の4行の規則で決定的に置く
    //
    // §1-3 が書いていない側を1点だけ埋めた（**測る前に**決めてコードに固定）:
    // **前列の2体のうちどちらが席0でどちらが席1か / 後列の2体のうち席3と席4** は
    // 指示書に無いので、**並べ替えに使ったキーの順（HP降順・攻撃力降順、同値は `Def.Id` の辞書順）で
    // 若いほうを 席0 / 席3 に置く**。規則は決定的なままで、強さは1行も足していない。
    (UnitDef[] Units, int[] RSlot, int[] HSlot) DfSampleOf(int i)
    {
        var rng = new Random(DfSampleSeed + i);
        var idx = new int[dfRN];
        for (int k = 0; k < dfRN; k++) idx[k] = k;
        for (int k = 0; k < 5; k++)
        {
            int j = k + rng.Next(dfRN - k);
            (idx[k], idx[j]) = (idx[j], idx[k]);
        }
        var units = new UnitDef[5];
        for (int k = 0; k < 5; k++) units[k] = dfRoster[idx[k]];

        // R: 席の無作為割り当て
        var seats = new[] { 0, 1, 2, 3, 4 };
        for (int k = 0; k < 5; k++)
        {
            int j = k + rng.Next(5 - k);
            (seats[k], seats[j]) = (seats[j], seats[k]);
        }

        // H: 規則配置
        var all5 = new[] { 0, 1, 2, 3, 4 };
        var front = all5.OrderByDescending(k => units[k].MaxHp)
                        .ThenBy(k => units[k].Id, StringComparer.Ordinal).Take(2).ToArray();
        var rest = all5.Where(k => k != front[0] && k != front[1]).ToArray();
        var back = rest.OrderByDescending(k => units[k].Attack)
                       .ThenBy(k => units[k].Id, StringComparer.Ordinal).Take(2).ToArray();
        int center = rest.Single(k => k != back[0] && k != back[1]);
        var rule = new int[5];
        rule[front[0]] = 0; rule[front[1]] = 1; rule[center] = 2; rule[back[0]] = 3; rule[back[1]] = 4;

        return (units, seats, rule);
    }

    // ---- 1帯ぶんの走査 -------------------------------------------------------------------
    //
    // **素体の差し替えは席を動かさない。** H 版の席は「元の5体」から決めた並びをそのまま使う
    // （素体の `Def.Id` は `..._plain` なので、差し替えてから規則を引き直すと同値の辞書順が
    // ずれて席が動きうる。それは配置の差であって機構の差ではない）。
    DfResult DfMeasure(int n, int m, int band, string label)
    {
        var full = new int[n][];
        var plain = new int[n][];
        var present = new int[n][];
        var members = new int[n][];
        int done = 0;
        Console.Error.Write($"{label}: ");
        Parallel.For(0, n, i =>
        {
            var (units, rslot, hslot) = DfSampleOf(i);
            var mem = new int[5];
            for (int k = 0; k < 5; k++) mem[k] = Array.IndexOf(dfRoster, units[k]);
            members[i] = mem;

            var pres = new List<int>();
            var pos = new List<int>();
            for (int k = 0; k < 5; k++)
                if (dfTargetIdx.TryGetValue(units[k].Id, out int ti)) { pres.Add(ti); pos.Add(k); }
            present[i] = pres.ToArray();

            var fw = new int[2 * dfW];
            var pw = new int[2 * pres.Count * dfW];
            for (int ver = 0; ver < 2; ver++)
            {
                int[] slot = ver == 0 ? rslot : hslot;
                var f = new Formation();
                for (int k = 0; k < 5; k++) f[slot[k]] = units[k];
                for (int w = 0; w < dfW; w++)
                    for (int seed = band; seed < band + m; seed++)
                        if (BattleEngine.Run(f, dfStages[w].Enemy, seed, verbose: false).PlayerWon)
                            fw[ver * dfW + w]++;

                for (int t = 0; t < pres.Count; t++)
                {
                    var g = new Formation();
                    for (int k = 0; k < 5; k++)
                        g[slot[k]] = k == pos[t] ? dfPlainDef[pres[t]] : units[k];
                    for (int w = 0; w < dfW; w++)
                        for (int seed = band; seed < band + m; seed++)
                            if (BattleEngine.Run(g, dfStages[w].Enemy, seed, verbose: false).PlayerWon)
                                pw[(ver * pres.Count + t) * dfW + w]++;
                }
            }
            full[i] = fw; plain[i] = pw;
            int d = Interlocked.Increment(ref done);
            if (d % 1000 == 0) Console.Error.Write(".");
        });
        Console.Error.WriteLine();
        return new DfResult
        {
            N = n, M = m, W = dfW, Band = band,
            Full = full, Plain = plain, Present = present, Members = members
        };
    }

    // 標本の勝率（**第一波は集計から除外**。波は全部回している）
    double DfRate(DfResult r, int i, int ver)
    {
        int s2 = 0;
        for (int w = 1; w < r.W; w++) s2 += r.Full[i][ver * r.W + w];
        return s2 * 100.0 / ((r.W - 1) * r.M);
    }
    double DfPlainRate(DfResult r, int i, int ver, int t)
    {
        int p = r.Present[i].Length;
        int s2 = 0;
        for (int w = 1; w < r.W; w++) s2 += r.Plain[i][(ver * p + t) * r.W + w];
        return s2 * 100.0 / ((r.W - 1) * r.M);
    }

    // **符号付きの表示は自前でやる。** `:+0.0;-0.0` の負セクションは、値が -0.0 に丸まると
    // `-+0.0` を吐く（第68期の `carry leak` が同じ穴を踏んで、微小値を 0 に潰して回避していた）。
    // ここは符号付きの列が多いので書式の側で直す。
    string DfP1(double x) => (x < -0.05 ? "-" : "+") + Math.Abs(x).ToString("F1");
    string DfP2(double x) => (x < -0.005 ? "-" : "+") + Math.Abs(x).ToString("F2");

    (double Mean, double Sd, int N) DfStats(IReadOnlyList<double> xs)
    {
        int n = xs.Count;
        if (n == 0) return (0, 0, 0);
        double m = xs.Average();
        if (n < 2) return (m, 0, n);
        double v = xs.Sum(x => (x - m) * (x - m)) / (n - 1);
        return (m, Math.Sqrt(v), n);
    }
    double DfCorr(IReadOnlyList<double> a, IReadOnlyList<double> b)
    {
        int n = a.Count;
        if (n < 2) return double.NaN;
        double ma = a.Average(), mb = b.Average();
        double sa = 0, sb = 0, sab = 0;
        for (int i = 0; i < n; i++) { double x = a[i] - ma, y = b[i] - mb; sa += x * x; sb += y * y; sab += x * y; }
        return (sa <= 0 || sb <= 0) ? double.NaN : sab / Math.Sqrt(sa * sb);
    }

    // 駒ごとの寄与（版別）を取り出す
    List<double>[] DfContrib(DfResult r, int ver)
    {
        var acc = new List<double>[dfT];
        for (int t = 0; t < dfT; t++) acc[t] = new List<double>();
        for (int i = 0; i < r.N; i++)
        {
            double full = DfRate(r, i, ver);
            for (int t = 0; t < r.Present[i].Length; t++)
                acc[r.Present[i][t]].Add(full - DfPlainRate(r, i, ver, t));
        }
        return acc;
    }

    string DfHistRow(string ver, string label, double[] xs)
    {
        int n = xs.Length;
        int b0 = xs.Count(x => x == 0);
        int b1 = xs.Count(x => x > 0 && x < 5);
        int b2 = xs.Count(x => x >= 5 && x < 25);
        int b3 = xs.Count(x => x >= 25 && x < 50);
        int b4 = xs.Count(x => x >= 50 && x < 75);
        int b5 = xs.Count(x => x >= 75 && x <= 95);
        int b6 = xs.Count(x => x > 95 && x < 100);
        int b7 = xs.Count(x => x == 100);
        var st = DfStats(xs);
        return $"| {ver} | {label} | {st.Mean:F2}% | {st.Sd:F1} "
               + $"| {b0 * 100.0 / n:F1} | {b1 * 100.0 / n:F1} | {b2 * 100.0 / n:F1} | {b3 * 100.0 / n:F1} "
               + $"| {b4 * 100.0 / n:F1} | {b5 * 100.0 / n:F1} | {b6 * 100.0 / n:F1} | {b7 * 100.0 / n:F1} "
               + $"| **{(b2 + b3 + b4 + b5) * 100.0 / n:F1}%** |";
    }

