            }
        Console.WriteLine();
        Console.WriteLine("| B | 読み手の発火 Δ(V1−V0)/戦 | 与ダメ(B) Δ/戦 | 回復 Δ/戦 |");
        Console.WriteLine("|---|--:|--:|--:|");
        for (int i = 0; i < thWound.Length; i++)
        {
            var s0 = new ThStat(); var s1 = new ThStat();
            for (int w = 1; w < thW; w++) { s0.AddFrom(cst[i, 0, w]); s1.AddFrom(cst[i, 1, w]); }
            if (s0.N == 0 || s1.N == 0) continue;
            double f0 = (s0.Gouge + s0.Trace + s0.Sever + s0.Suture) / s0.N, f1 = (s1.Gouge + s1.Trace + s1.Sever + s1.Suture) / s1.N;
            Console.WriteLine($"| {thName[thWound[i]]} | {ThP2(f1 - f0)} | {ThP2(s1.DmgB / s1.N - s0.DmgB / s0.N)} | {ThP2(s1.Healed / s1.N - s0.Healed / s0.N)} |");
        }
        Console.WriteLine();

        // ---- 表E: 自己検査 --------------------------------------------------------------------
        Console.WriteLine("## 表E —— 自己検査（(a)(c)(e)(f)(g)(h)。(b)(d) と拒否権は `thorn check`）");
        Console.WriteLine();
        double maxA = 0; int cellsA = 0;
        foreach (int b in thOthers)
        {
            if (!Y0.ContainsKey(b) || !Y1.ContainsKey(b)) continue;
            int nT = Math.Min(Y0[b].Length, Y1[b].Length);
            for (int t = 0; t < nT; t++) foreach (int k in new[] { 1, 3 })
                {
                    cellsA++;
                    maxA = Math.Max(maxA, Math.Abs(Y0[b][t][k] - Y1[b][t][k]));
                    if (Y2 is not null && Y2.ContainsKey(b) && t < Y2[b].Length) { cellsA++; maxA = Math.Max(maxA, Math.Abs(Y0[b][t][k] - Y2[b][t][k])); }
                }
        }
        double maxC = 0; int cellsC = 0;
        if (Y2 is not null)
            foreach (int b in thOthers)
            {
                if (!Y1.ContainsKey(b) || !Y2.ContainsKey(b)) continue;
                int nT = Math.Min(Y1[b].Length, Y2[b].Length);
                for (int t = 0; t < nT; t++) for (int k = 0; k < 4; k++) { cellsC++; maxC = Math.Max(maxC, Math.Abs(Y1[b][t][k] - Y2[b][t][k])); }
            }
        var e2 = new ThStat(); var e4 = new ThStat(); var all1 = new ThStat(); var all2 = new ThStat();
        for (int i = 0; i < thWound.Length; i++) { e2.AddFrom(cst[i, 1, 1]); e4.AddFrom(cst[i, 1, 3]); for (int w = 1; w < thW; w++) { all1.AddFrom(cst[i, 1, w]); if (nV > 2) all2.AddFrom(cst[i, 2, w]); } }
        Console.WriteLine("| 検査 | 内容 | 値 | 判定 |");
        Console.WriteLine("|---|---|--:|:-:|");
        Console.WriteLine($"| (a) | y01・y00（カド素体）が V0・V1{(Y2 is null ? "" : "・V2")} で完全一致 | {cellsA} セル・最大差 {maxA:F10}pt | {(maxA == 0 ? "○" : "**×**")} |");
        if (Y2 is null) Console.WriteLine("| (c) | V2 は V1 と全セル ±0.0 ＋ 味方に傷が載った回数 > 0 | V2 の TSV が無い | — |");
        else Console.WriteLine($"| (c) | V2 は V1 と全セル ±0.0 ＋ 味方に傷が載った回数 > 0 | {cellsC} セル・最大差 {maxC:F10}pt ／ 味方傷 {(all2.N > 0 ? (all2.WoundsAlly / all2.N).ToString("F2") : "—")} 回/戦（V1 では {all1.WoundsAlly / all1.N:F2}） | {(maxC == 0 && all2.WoundsAlly > 0 ? "○" : "**×**")} |");
        Console.WriteLine($"| (e) | 第二波の供給が 0 に近い（粛） | {e2.Wounds / e2.N:F3} 回/戦（第四波 {e4.Wounds / e4.N:F2}・粛の下の発火 {e2.FiresUnderHush / e2.N:F3}） | {(e2.FiresUnderHush == 0 ? "○" : "**×**")} |");
        Console.WriteLine($"| (f) | 1反撃 = 1傷（書き込み ÷ 生存していた反撃 = 1.00） | {all1.Wounds} / {all1.FiresAlive} = {(all1.FiresAlive > 0 ? all1.Wounds / all1.FiresAlive : double.NaN):F4}（発火 {all1.Fires}・Events の発火 {all1.FiresEv}） | {(all1.Wounds == all1.FiresAlive ? "○" : "**×**")} |");
        Console.WriteLine($"| (g) | Q1 が2系列で同符号 | 系列1 {ThP2(q1Ser[0])} / 系列2 {ThP2(q1Ser[1])} | {(Math.Sign(q1Ser[0]) == Math.Sign(q1Ser[1]) ? "○" : "**×**")} |");
        Console.WriteLine($"| (h) | Δ相乗 の分母は5枚固定（個数を主判定に混ぜない） | 表A の平均 {ThP2(q1)}（有意な相手の数 {nPos} は表B の参考値） | ○ |");
        Console.WriteLine();
        Console.WriteLine("**(b) の読み方**: 計数は `if (!ctx.WoundIgnite.Enabled) continue;` の**手前**にあるので、"
                          + "**同じ盤面なら Y0 と Y1 で必ず同じ数だけ通る**（コードの形から従う。理想台の (a') と `compare` の (c) がその実証）。"
                          + "上の残差は**盤面が版で分岐したぶん**——Y1 では毒が敵を削るので、決着ターン数も生き残る敵の数も変わる。"
                          + "**「版に依らない計数」は経路の性質であって、観測される値の性質ではない。**");
        Console.WriteLine();
        Console.WriteLine("## 判定表");
        Console.WriteLine();
        Console.WriteLine("| | 判定 | 値 | 線 | 結果 |");
        Console.WriteLine("|---|---|--:|--:|:-:|");
        Console.WriteLine($"| **Q1** | **傷の5枚の Δ相乗 の平均** | **{ThP2(q1)}** | ≥ +{ThQ1Line:F1} | **{(q1 >= ThQ1Line ? "○" : "×")}** |");
        Console.WriteLine($"| Q2 | 供給/戦: 第四波 > 第二波 | {SupplyWave(1, 3):F2} 対 {SupplyWave(1, 1):F2} | — | {(SupplyWave(1, 3) > SupplyWave(1, 1) ? "○" : "×")} |");
        Console.WriteLine($"| Q3 | 在庫/T の V1 − V0（ハリ同席で 1 を超えるか） | {ThP2(hariStockV1 - hariStockV0)}（V1 {hariStockV1:F2}） | 記録 | {(hariStockV1 > 1.0 ? "超えた" : "超えない")} |");
        {
            var s0 = new ThStat(); var s1 = new ThStat();
            for (int i = 0; i < thWound.Length; i++) for (int w = 1; w < thW; w++) { s0.AddFrom(cst[i, 0, w]); s1.AddFrom(cst[i, 1, w]); }
            Console.WriteLine($"| Q4 | 読み手の発火 Δ/戦（5組合算）・断ちが閾値に届いた回数 | {ThP2((s1.Gouge + s1.Trace + s1.Sever + s1.Suture) / s1.N - (s0.Gouge + s0.Trace + s0.Sever + s0.Suture) / s0.N)}・断ち {s0.SeverReached / s0.N * thWound.Length:F2} → {s1.SeverReached / s1.N * thWound.Length:F2}（ナタ行） | 記録 | — |");
        }
        Console.WriteLine();
        Console.WriteLine($"所要 {thSw.Elapsed.TotalSeconds:F1} 秒。");
        return;
    }

    // =====================================================================================
    // check: (b)(d) `compare` 61 行の V0 対 V1、(c) V1 対 V2、拒否権1・2、`docs/balance.md` との突き合わせ
    // =====================================================================================
    if (thArg == "check")
    {
        Console.WriteLine("# 第84期 —— 受け入れ基準: `compare` 61 行の V0 / V1 / V2 の突き合わせと拒否権");
        Console.WriteLine();
        var c0 = new double[thAllRows.Length][]; var c1 = new double[thAllRows.Length][]; var c2 = new double[thAllRows.Length][];
        Parallel.For(0, thAllRows.Length * 3, k =>
        {
            int i = k / 3, v = k % 3;
            var r = ThCompare(thAllRows[i].F, ThRuleOf(v));
            if (v == 0) c0[i] = r; else if (v == 1) c1[i] = r; else c2[i] = r;
        });
        int mismDoc = 0, cellsDoc = 0, missingDoc = 0, mism01 = 0, mism12 = 0, mismWound = 0;
        var lines = new List<string>();
        for (int i = 0; i < thAllRows.Length; i++)
        {
            bool isWound = thWoundRows.Any(rw => rw.Name == thAllRows[i].Name);
            if (thBalance.TryGetValue(thAllRows[i].Name, out double[]? doc))
                for (int w = 0; w < thW; w++) { cellsDoc++; if (Math.Abs(doc[w] - c0[i][w]) > 0.05) { mismDoc++; lines.Add($"| {thAllRows[i].Name} | 第{w + 1}波 | docs {doc[w]:F1} | V0 {c0[i][w]:F1} |"); } }
            else missingDoc++;
            for (int w = 0; w < thW; w++)
            {
                if (Math.Abs(c0[i][w] - c1[i][w]) > 0.001) { mism01++; if (isWound) mismWound++; lines.Add($"| {thAllRows[i].Name} | 第{w + 1}波 | V0 {c0[i][w]:F1} | V1 {c1[i][w]:F1} |"); }
                if (Math.Abs(c1[i][w] - c2[i][w]) > 0.001) { mism12++; lines.Add($"| {thAllRows[i].Name} | 第{w + 1}波 | V1 {c1[i][w]:F1} | V2 {c2[i][w]:F1} |"); }
            }
        }
        Console.WriteLine($"`CompareBuilds()` {thAllRows.Length} 行 × {thW} 波 × seed 0..199 を V0 / V1 / V2 で回した（{thAllRows.Length * thW * 200 * 3:N0} 戦）。");
        Console.WriteLine();
        Console.WriteLine("| 検査 | 内容 | 値 | 判定 |");
        Console.WriteLine("|---|---|--:|:-:|");
        Console.WriteLine($"| 受け入れ | V0 と `docs/balance.md` の突き合わせ | {cellsDoc} セル・ずれ {mismDoc} 件（`docs` に無い行 {missingDoc}） | {(mismDoc == 0 ? "○" : "**×**")} |");
        Console.WriteLine($"| (b) | `compare` {thAllRows.Length} 行が V0 と V1 で全セル ±0.0 | ずれ {mism01} 件 / {thAllRows.Length * thW} | {(mism01 == 0 ? "○" : "**×**")} |");
        Console.WriteLine($"| (c) | V2 は V1 と全セル ±0.0（味方傷の計数は `tables` (c)） | ずれ {mism12} 件 / {thAllRows.Length * thW} | {(mism12 == 0 ? "○" : "**×**")} |");
        Console.WriteLine($"| (d) | 傷を含む {thWoundRows.Length} 行が V1 で ±0.0 | ずれ {mismWound} 件 | {(mismWound == 0 ? "○" : "**×**")} |");
        // 拒否権
        double Fifth(double[][] c, IEnumerable<string> names)
        {
            var xs = new List<double>();
            foreach (string n in names) { int i = Array.FindIndex(thAllRows, rw => rw.Name == n); if (i >= 0) xs.Add(c[i][thW - 1]); }
            return xs.Count == 0 ? double.NaN : xs.Average();
        }
        double f0 = Fifth(c0, Baseline.PrimaryRows), f1 = Fifth(c1, Baseline.PrimaryRows);
        int over0 = thKadoRows.Count(rw => c0[Array.FindIndex(thAllRows, x => x.Name == rw.Name)][thW - 1] > 95.0);
        int over1 = thKadoRows.Count(rw => c1[Array.FindIndex(thAllRows, x => x.Name == rw.Name)][thW - 1] > 95.0);
        Console.WriteLine($"| 拒否権1 | 主判定 {Baseline.PrimaryRows.Length} 行の第五波平均 ≥ {Baseline.PrimaryFifthFloor:F1}% | V0 {f0:F2}% → V1 {f1:F2}% | {(f1 >= Baseline.PrimaryFifthFloor ? "立たない" : "**立つ**")} |");
        Console.WriteLine($"| 拒否権2 | カドを含む {thKadoRows.Length} 行で第五波 > 95% が新たに 2 行以上 | V0 {over0} → V1 {over1} 行 | {(over1 - over0 >= 2 ? "**立つ**" : "立たない")} |");
        Console.WriteLine();
        Console.WriteLine($"カドと傷の駒が同居する行は {thBothRows.Length} 行なので、V1 で `compare` が動かないのは論理的な帰結（**立たないこと自体が「傷を書くだけ」の実装であることの自己検査**）。");
        if (lines.Count > 0)
        {
            Console.WriteLine(); Console.WriteLine("| 行 | 波 | 左 | 右 |"); Console.WriteLine("|---|---|--:|--:|");
            foreach (string l in lines) Console.WriteLine(l);
        }
        Console.WriteLine();
        Console.WriteLine($"| 行（カドを含む {thKadoRows.Length} 行・V1） | 第1波 | 第2波 | 第3波 | 第4波 | 第5波 |");
        Console.WriteLine("|---|--:|--:|--:|--:|--:|");
        foreach (var rw in thKadoRows)
        {
            int i = Array.FindIndex(thAllRows, x => x.Name == rw.Name);
            Console.WriteLine($"| {rw.Name} (V1) | " + string.Join(" | ", c1[i].Select(x => $"{x:F1}%")) + " |");
        }
        Console.WriteLine();
        Console.WriteLine($"所要 {thSw.Elapsed.TotalSeconds:F1} 秒。");
        return;
    }

    Console.WriteLine("thorn: 引数は phase0 / run <v> [skip] [take] / tables <v0> <v1> [<v2>] / check。");
    return;
}


if (focusId == "suture2") { Suture2Diag.Run(args, stageIndex); return; }

if (focusId == "mender") { MenderDiag.Run(args, stageIndex); return; }

if (focusId == "blaze2") { Blaze2Diag.Run(args, stageIndex); return; }

if (focusId == "gauge") { GaugeDiag.Run(args, stageIndex); return; }


if (focusId == "gather") { GatherDiag.Run(args, stageIndex); return; }
if (focusId == "deep") { DeepDiag.Run(args, stageIndex); return; }
if (focusId == "soak") { SoakDiag.Run(args, stageIndex); return; }
if (focusId == "lastslot") { LastslotDiag.Run(args, stageIndex); return; }

if (focusId == "creak3")
{
    string c3Arg = args.Length > 2 ? args[2] : "";
    bool c3Alt = c3Arg == "alt";
    var c3Sw = System.Diagnostics.Stopwatch.StartNew();

    IReadOnlyList<EnemyCatalog.Stage> c3Stages = EnemyCatalog.Stages;
    int c3W = c3Stages.Count;
    var c3Roster = UnitCatalog.All.ToArray();
    int c3RN = c3Roster.Length;
    string c3YomiId = UnitCatalog.Yomi.Id;

    var c3All = CompareBuilds().ToArray();
    bool C3HasYomi((string Name, Formation F) row) => row.F.Occupied().Any(o => o.Def.Id == c3YomiId);
    var c3Rows = c3All.Where(C3HasYomi).ToArray();
    var c3Other = c3All.Where(b => !C3HasYomi(b)).ToArray();

    // 味方側で**ヨミを動かせる**駒は3枚だけ（`SwapSlots` の呼び出し全数から。Phase 0-1）。
    // 逃亡（セロ）／棘守り（カド）／喧噪（バサ）。突き返し（ハネ）と曝き（告発人）は
    // `HaulOutPair(Opponent)` なので**敵陣**を動かす——味方のヨミは動かない。
    var c3Movers = new[] { UnitCatalog.Sero.Id, UnitCatalog.Kado.Id, UnitCatalog.Basa.Id };
    // `Whet` 窓口の供給者6枚（`WhetRoute` の7経路の持ち主。号令は開戦と毎Tの2経路で1枚）。
    var c3Feeders = new[] { UnitCatalog.Kari.Id, UnitCatalog.Gan.Id, UnitCatalog.Kugu.Id,
                            UnitCatalog.Shio.Id, UnitCatalog.Golm.Id, UnitCatalog.Hiyo.Id };

    // ---- 版（**測る前に固定**・指示書 §2-2）------------------------------------------------
    const int C3V = 10;
    var c3Rule = new CreakRule[C3V]
    {
        new(0, CreakSource.Whet),
        new(9, CreakSource.Bonus), new(18, CreakSource.Bonus), new(30, CreakSource.Bonus),
        new(2, CreakSource.Whet),  new(6, CreakSource.Whet),   new(12, CreakSource.Whet),
        new(9, CreakSource.Both),  new(18, CreakSource.Both),  new(30, CreakSource.Both),
    };
    string[] c3Name =
    {
        "V0（無効）",
        "B9 自己 9", "B18 自己 18", "B30 自己 30",
        "W2 外部 2", "W6 外部 6", "W12 外部 12",
        "T9 合計 9", "T18 合計 18", "T30 合計 30",
    };
    // 族: 1 = Bonus（自己供給）/ 2 = Whet（外部供給）/ 3 = Both（合計）
    int C3Fam(int v) => v == 0 ? 0 : v <= 3 ? 1 : v <= 6 ? 2 : 3;
    string[] c3FamName = { "—", "**自己**", "**外部**", "合計" };

    int C3ProbeIdx(int v) => C3Fam(v) switch
    {
        1 or 3 => Array.IndexOf(UnitTally.CreakProbes, c3Rule[v].Threshold),
        2 => Array.IndexOf(UnitTally.CreakWhetProbes, c3Rule[v].Threshold),
        _ => -1,
    };
    int[]? C3ProbeArr(int v, UnitTally t) => C3Fam(v) switch
    {
        1 => t.CreakProbeTurn,
        2 => t.CreakWhetProbeTurn,
        3 => t.CreakBothProbeTurn,
        _ => null,
    };

    // ---- 1版ぶんの計数（**どれも誰も読んで分岐しない**）---------------------------------------
    // 0 戦数 / 1 振（分母）/ 2 薙ぎ（分子）/ 3 軋みの上昇Σ / 4 外から届いたΣ / 5 うち吐き戻し /
    // 6 AtkBonus の最大Σ / 7 WhetReceived の最大Σ / 8 閾値到達の戦数 / 9 その初到達TΣ /
    // 10 一度でも動かされた戦数 / 11 一度でも押された戦数
    const int C3C = 12;
    void C3Acc(BattleResult r, int v, double[] a, int off)
    {
        if (!r.TallyByUnit.TryGetValue(c3YomiId, out UnitTally? t)) return;
        a[off + 0]++;
        a[off + 1] += t.CreakSwings; a[off + 2] += t.CreakSweeps;
        a[off + 3] += t.CreakSelfGain; a[off + 4] += t.CreakWhetGain; a[off + 5] += t.CreakRegurgGain;
        a[off + 6] += t.CreakMaxBonus; a[off + 7] += t.CreakWhetMax;
        if (t.CreakSelfGain > 0) a[off + 10]++;
        if (t.CreakWhetGain > 0) a[off + 11]++;
        int pi = C3ProbeIdx(v);
        int[]? pa = C3ProbeArr(v, t);
        if (pi >= 0 && pa is not null && pa[pi] != 0) { a[off + 8]++; a[off + 9] += pa[pi]; }
    }
    double C3Rate(double[] a, int off) => a[off + 1] > 0 ? a[off + 2] * 100.0 / a[off + 1] : 0;

    string C3P1(double x) => double.IsNaN(x) ? "—" : (x < -0.05 ? "-" : "+") + Math.Abs(x).ToString("F1");
    string C3P2(double x) => double.IsNaN(x) ? "—" : (x < -0.005 ? "-" : "+") + Math.Abs(x).ToString("F2");

    // ---- 理想台（`compare` と同じ seed 帯）---------------------------------------------------
    const int C3Seeds = 200;
    int c3Seed0 = c3Alt ? 200 : 0;
    (double[] Win, double[] Cnt) C3Ideal(Formation f, int v)
    {
        var win = new double[c3W];
        var cnt = new double[C3C];
        for (int w = 0; w < c3W; w++)
        {
            int wins = 0;
            for (int seed = c3Seed0; seed < c3Seed0 + C3Seeds; seed++)
            {
                BattleResult r = BattleEngine.Run(f, c3Stages[w].Enemy, seed, verbose: false, creak: c3Rule[v]);
                if (r.PlayerWon) wins++;
                C3Acc(r, v, cnt, 0);
            }
            win[w] = wins * 100.0 / C3Seeds;
        }
        return (win, cnt);
    }
    int C3Info(double[] w) => w.Skip(1).Count(x => x > 0.0 && x < 100.0);

    // ---- ドラフト台 Pw（第69〜76期の写し。**1文字も変えていない**）-----------------------------
    const int C3OfferSeed = 2_000_000;
    const int C3N = 11000, C3M = 8;
    const int C3Strong = 7;
    const int C3WeakPct = 60;
    int c3Band = c3Alt ? 200 : 0;

    var c3WeakCache = new Dictionary<string, UnitDef>();
    UnitDef C3WeakOf(UnitDef d)
    {
        if (c3WeakCache.TryGetValue(d.Id, out UnitDef? w)) return w;
        w = new UnitDef
        {
            Id = d.Id, Name = d.Name, MaxHp = d.MaxHp * C3WeakPct / 100,
            Attack = d.Attack, Speed = d.Speed, Traits = d.Traits,
            Pattern = d.Pattern, Actions = d.Actions
        };
        c3WeakCache[d.Id] = w;
        return w;
    }
    var c3Weak = c3Stages.Select(st =>
    {
        var f = new Formation();
        foreach ((int sl, UnitDef d) in st.Enemy.Occupied()) f[sl] = C3WeakOf(d);
        return new EnemyCatalog.Stage(st.Name, f);
    }).ToArray();

    UnitDef[] C3Team(int i)
    {
        var rng = new Random(C3OfferSeed + i);
        var idx = new int[c3RN];
        for (int k = 0; k < c3RN; k++) idx[k] = k;
        int remain = c3RN, strong = 0;
        var picked = new UnitDef[5];
        for (int r = 0; r < 5; r++)
        {
            var offer = new UnitDef[3];
            for (int t = 0; t < 3; t++)
            {
                int j = t + rng.Next(remain - t);
                (idx[t], idx[j]) = (idx[j], idx[t]);
                offer[t] = c3Roster[idx[t]];
            }
            UnitDef sel = strong < 2
                ? offer.OrderByDescending(x => x.Attack).ThenBy(x => x.Id, StringComparer.Ordinal).First()
                : offer.OrderByDescending(x => x.MaxHp).ThenBy(x => x.Id, StringComparer.Ordinal).First();
            picked[r] = sel;
            if (sel.Attack >= C3Strong) strong++;
            int pi = 0;
            for (int t = 0; t < 3; t++) if (ReferenceEquals(c3Roster[idx[t]], sel)) { pi = t; break; }
            (idx[pi], idx[remain - 1]) = (idx[remain - 1], idx[pi]);
            remain--;
        }
        return picked;
    }
    int[] C3Seats(UnitDef[] u)
    {
        var all5 = new[] { 0, 1, 2, 3, 4 };
        var front = all5.OrderByDescending(k => u[k].MaxHp)
                        .ThenBy(k => u[k].Id, StringComparer.Ordinal).Take(2).ToArray();
        var rest = all5.Where(k => k != front[0] && k != front[1]).ToArray();
        var back = rest.OrderByDescending(k => u[k].Attack)
                       .ThenBy(k => u[k].Id, StringComparer.Ordinal).Take(2).ToArray();
        int center = rest.Single(k => k != back[0] && k != back[1]);
        var r = new int[5];
        r[front[0]] = 0; r[front[1]] = 1; r[center] = 2; r[back[0]] = 3; r[back[1]] = 4;
        return r;
    }
    Formation C3Form(UnitDef[] u, int[] seats)
    {
        var f = new Formation();
        for (int k = 0; k < 5; k++) f[seats[k]] = u[k];
        return f;
    }
    var c3KeyOf = c3Roster.ToDictionary(u => u.Id, TraitKeyMap.KeysOf);
    int C3MoveKeys(UnitDef[] team)
        => team.Count(x => c3KeyOf.TryGetValue(x.Id, out int[]? k) && k.Contains(UnitTally.CarryMove));

    double C3Slope(IReadOnlyList<double> rate, IReadOnlyList<int> box)
    {
        var bk = new List<double>[4];
        for (int j = 0; j < 4; j++) bk[j] = new List<double>();
        for (int i = 0; i < rate.Count; i++) bk[Math.Min(3, box[i])].Add(rate[i]);
        double d10 = (bk[0].Count > 0 && bk[1].Count > 0) ? bk[1].Average() - bk[0].Average() : double.NaN;
        double d21 = (bk[1].Count > 0 && bk[2].Count > 0) ? bk[2].Average() - bk[1].Average() : double.NaN;
        return double.IsNaN(d10) ? d21 : double.IsNaN(d21) ? d10 : (d10 + d21) / 2;
    }
    double[] C3BoxMeans(IReadOnlyList<double> rate, IReadOnlyList<int> box)
    {
        var r = new double[4];
        for (int j = 0; j < 4; j++)
        {
            var xs = new List<double>();
            for (int i = 0; i < rate.Count; i++) if (Math.Min(3, box[i]) == j) xs.Add(rate[i]);
            r[j] = xs.Count > 0 ? xs.Average() : double.NaN;
        }
        return r;
    }

    // 1行ぶんの分布（Phase 0-3 用）。**規則は無効のまま回す。**
    int[] c3Grid = { 1, 2, 4, 6, 8, 9, 12, 16, 18, 24, 30, 32 };
    void C3DistRow(string label, Func<int, Formation> form, int rows, bool ideal)
    {
        var bonusMax = new List<int>(); var whetMax = new List<int>();
        var selfSum = new List<int>(); var whetSum = new List<int>(); var swings = new List<int>();
        var tSelf = new double[UnitTally.CreakProbes.Length];
        var nSelf = new double[UnitTally.CreakProbes.Length];
        var tWhet = new double[UnitTally.CreakWhetProbes.Length];
        var nWhet = new double[UnitTally.CreakWhetProbes.Length];
        int lo = ideal ? c3Seed0 : c3Band, hi = ideal ? c3Seed0 + C3Seeds : c3Band + C3M;
        for (int r0 = 0; r0 < rows; r0++)
        {
            Formation f = form(r0);
            for (int w = 0; w < c3W; w++)
                for (int seed = lo; seed < hi; seed++)
                {
                    BattleResult r = BattleEngine.Run(f, ideal ? c3Stages[w].Enemy : c3Weak[w].Enemy,
                                                      seed, verbose: false);
                    if (!r.TallyByUnit.TryGetValue(c3YomiId, out UnitTally? t)) continue;
                    bonusMax.Add(t.CreakMaxBonus); whetMax.Add(t.CreakWhetMax);
                    selfSum.Add(t.CreakSelfGain); whetSum.Add(t.CreakWhetGain); swings.Add(t.CreakSwings);
                    if (t.CreakProbeTurn is not null)
                        for (int k = 0; k < UnitTally.CreakProbes.Length; k++)
                            if (t.CreakProbeTurn[k] != 0) { nSelf[k]++; tSelf[k] += t.CreakProbeTurn[k]; }
                    if (t.CreakWhetProbeTurn is not null)
                        for (int k = 0; k < UnitTally.CreakWhetProbes.Length; k++)
                            if (t.CreakWhetProbeTurn[k] != 0) { nWhet[k]++; tWhet[k] += t.CreakWhetProbeTurn[k]; }
                }
        }
        int n = Math.Max(1, bonusMax.Count);
        Console.Write($"| {label} | `AtkBonus` | {swings.Average():F2} | {selfSum.Average():F1} | {whetSum.Average():F1} | {bonusMax.Average():F1} |");
        foreach (int q in c3Grid) Console.Write($" {100.0 * bonusMax.Count(x => x >= q) / n:F1}% |");
        Console.WriteLine();
        Console.Write("|  | 到達T |  |  |  |  |");
        foreach (int q in c3Grid)
        {
            int i = Array.IndexOf(UnitTally.CreakProbes, q);
            Console.Write(i >= 0 && nSelf[i] > 0 ? $" {tSelf[i] / nSelf[i]:F2} |" : " — |");
        }
        Console.WriteLine();
        Console.Write($"|  | `WhetReceived` |  |  |  | {whetMax.Average():F1} |");
        foreach (int q in c3Grid) Console.Write($" {100.0 * whetMax.Count(x => x >= q) / n:F1}% |");
        Console.WriteLine();
        Console.Write("|  | 到達T |  |  |  |  |");
        foreach (int q in c3Grid)
        {
            int i = Array.IndexOf(UnitTally.CreakWhetProbes, q);
            Console.Write(i >= 0 && nWhet[i] > 0 ? $" {tWhet[i] / nWhet[i]:F2} |" : " — |");
        }
        Console.WriteLine();
    }

    // =====================================================================================
    // phase0: 紙の計算と分布（**`CreakRule` は無効のまま。盤面は1つも動かない**）
    // =====================================================================================
    if (c3Arg == "phase0")
    {
        Console.WriteLine("# 第77期 Phase 0 —— 自己供給と外部供給（**規則は無効のまま測る**）");
        Console.WriteLine();
        Console.WriteLine("`dotnet run --project BattleSim -c Release 0 creak3 phase0` の出力。**`docs/` には置かない。**");
        Console.WriteLine();

        // ---- 0-1. 選択子の検算 ----
        Console.WriteLine("## 0-1. 選択子の追加が盤面を動かしていないか（**受け入れ基準 1**）");
        Console.WriteLine();
        int c3Diff0 = 0;
        foreach ((string _, Formation f) in c3All)
            for (int w = 0; w < c3W; w++)
                for (int seed = 0; seed < C3Seeds; seed++)
                    if (BattleEngine.Run(f, c3Stages[w].Enemy, seed, verbose: false).PlayerWon
                        != BattleEngine.Run(f, c3Stages[w].Enemy, seed, verbose: false, creak: CreakRule.Default).PlayerWon)
                        c3Diff0++;
        Console.WriteLine($"`creak` を渡さない版 と `CreakRule.Default`（= `(0, Whet)`）を渡した版を、");
        Console.WriteLine($"**{c3All.Length} 行 × {c3W} 波 × {C3Seeds} seed** で1試行ずつ突き合わせた → **ずれ {c3Diff0} 件**。");
        Console.WriteLine();
        Console.WriteLine($"`docs/balance.md` の現在値は **{c3All.Length} 行 × {c3W} 波 = {c3All.Length * c3W} セル**。");
        Console.WriteLine();

        // ---- 0-2. ヨミの在席標本数 ----
        Console.WriteLine("## 0-2. ヨミはドラフト台 Pw に何回入るか（**抽選だけ。戦闘0回**）");
        Console.WriteLine();
        const int C3Sim = 100000;
        int c3LotY = 0, c3LotMove = 0, c3LotFeed = 0, c3LotBoth = 0, c3LotNone = 0;
        var c3LotMoveN = new int[4];
        for (int i = 0; i < C3Sim; i++)
        {
            var ids = C3Team(i).Select(x => x.Id).ToHashSet();
            if (!ids.Contains(c3YomiId)) continue;
            c3LotY++;
            bool mv = c3Movers.Any(ids.Contains);
            bool fd = c3Feeders.Any(ids.Contains);
            if (mv) c3LotMove++;
            if (fd) c3LotFeed++;
            if (mv && fd) c3LotBoth++;
            if (!mv && !fd) c3LotNone++;
            c3LotMoveN[Math.Min(3, c3Movers.Count(ids.Contains))]++;
        }
        Console.WriteLine("| 量 | 抽選 100,000 標本 | 11,000 標本での期待 |");
        Console.WriteLine("|---|--:|--:|");
        Console.WriteLine($"| ヨミ在席 | {100.0 * c3LotY / C3Sim:F2}% | **{C3N * c3LotY / C3Sim:N0}** 件 |");
        Console.WriteLine($"| 一様なら（5 / {c3RN}） | {500.0 / c3RN:F2}% | {C3N * 5 / c3RN:N0} 件 |");
        Console.WriteLine();
        {
            double hyp = 1.0;
            for (int k = 0; k < 5; k++) hyp *= (double)(c3RN - 1 - k) / (c3RN - k);
            Console.WriteLine($"**超幾何との照合**: 無作為5枚ならヨミ在席は **{100.0 * (1 - hyp):F2}%**"
                              + $"（規則 P の実測は {100.0 * c3LotY / C3Sim:F2}%。P は攻撃力／HP で選ぶので一様ではない）。");
        }
        Console.WriteLine();
        Console.WriteLine("**ヨミが在席した標本の中で**（分母 = 在席標本）:");
        Console.WriteLine();
        Console.WriteLine("| 相方 | 割合 |");
        Console.WriteLine("|---|--:|");
        Console.WriteLine($"| 移動の書き手（セロ / カド / バサ のいずれか） | **{100.0 * c3LotMove / Math.Max(1, c3LotY):F1}%** |");
        Console.WriteLine($"| 強化の供給者（カリ / ガン / クグ / シオ / ゴルム / ヒヨ のいずれか） | **{100.0 * c3LotFeed / Math.Max(1, c3LotY):F1}%** |");
        Console.WriteLine($"| 両方 | {100.0 * c3LotBoth / Math.Max(1, c3LotY):F1}% |");
        Console.WriteLine($"| **どちらも無し** | **{100.0 * c3LotNone / Math.Max(1, c3LotY):F1}%** |");
        Console.WriteLine();
        Console.WriteLine("| 移動の書き手の枚数 | 0 | 1 | 2 | 3 |");
        Console.WriteLine("|---|--:|--:|--:|--:|");
        Console.WriteLine("| 割合 | " + string.Join(" | ", c3LotMoveN.Select(x => $"{100.0 * x / Math.Max(1, c3LotY):F1}%")) + " |");
        Console.WriteLine();
        Console.WriteLine("> **理想台の3行はすべて移動の書き手を持つ**（隊列崩し＝バサ＋セロ / 突き出し＝セロ / 移動改＝バサ＋セロ）。");
        Console.WriteLine("> **ドラフト台では相方が保証されない**——これが指示書 §0-2 の「構造的に不利」の分母である。");
        Console.WriteLine("> **ただし第五波の告発人（曝き）は敵側から味方を動かす**ので、移動の供給は 0 にはならない。");
        Console.WriteLine();

        // ---- 0-3. 分布 ----
        Console.WriteLine("## 0-3. ヨミの `AtkBonus` と `WhetReceived` の分布（V0・**規則は無効**）");
        Console.WriteLine();
        Console.WriteLine("格子への到達% は戦闘中の最大値から、到達T は計数の初到達ターンから（格子外は `—`）。");
        Console.WriteLine("**第67期の判定（2値 / 連続 / 不発）をそのまま当てる。**");
        Console.WriteLine();
        Console.Write("| 行 | 量 | 振/戦 | 軋み | 押され | 最大値 |");
        foreach (int q in c3Grid) Console.Write($" {q} |");
        Console.WriteLine();
        Console.Write("|---|---|--:|--:|--:|--:|");
        foreach (int _ in c3Grid) Console.Write("--:|");
        Console.WriteLine();
        foreach ((string rn, Formation f) in c3Rows) C3DistRow(rn, _ => f, 1, ideal: true);

        var c3Samp = new List<int>();
        for (int i = 0; i < C3N && c3Samp.Count < 300; i++)
            if (C3Team(i).Any(x => x.Id == c3YomiId)) c3Samp.Add(i);
        C3DistRow($"**ドラフト台 Pw**（在席 {c3Samp.Count} 標本）",
                  k => { UnitDef[] t = C3Team(c3Samp[k]); return C3Form(t, C3Seats(t)); },
                  c3Samp.Count, ideal: false);
        Console.WriteLine();

        // ---- 0-4. 紙で薙ぎ化率を予測する ----
        Console.WriteLine("## 0-4. 紙の予測 —— 閾値 9 は「1回でも動かされたか」と同値");
        Console.WriteLine();
        Console.WriteLine($"軋みの上昇は **{DisplacedTrait.Gain} / {DisplacedTrait.PushedToFrontGain} の2段**なので、");
        Console.WriteLine("`AtkBonus` の閾値 9 は**1回でも動かされれば必ず越える**。");
        Console.WriteLine("18 は「2回（または突き出し1回）」、30 は「4回（または突き出し＋1回）」に相当する。");
        Console.WriteLine();
        Console.WriteLine("**外部供給の側**は、`Whet` の7経路のうち**開戦時一括の号令の鬨が最大**（第56期 3.36 量/戦）で、");
        Console.WriteLine("第67期はそれが 8.0 を一括で届けたために閾値 1〜8 の到達Tが全部 1.00 に潰れた。");
        Console.WriteLine("**ドラフト台では供給者そのものが同席しない標本が大半**なので、");
        Console.WriteLine("**2値に潰れるのではなく不発になる**——それが P3 の予測。");
        Console.WriteLine();

        // ---- 0-5. 理想台のヨミ3行と歯止めの実効レンジ ----
        Console.WriteLine("## 0-5. 理想台のヨミ3行・主判定19行・歯止めの実効レンジ（自己検査 (c)）");
        Console.WriteLine();
        var c3Prim = new HashSet<string>(Baseline.PrimaryRows);
        var c3In = c3Rows.Where(b => c3Prim.Contains(b.Name)).Select(b => b.Name).ToArray();
        Console.WriteLine($"ヨミを含む行は **{c3Rows.Length} 行**、うち主判定 {Baseline.PrimaryRows.Length} 行に **{c3In.Length} 行**"
                          + $"（{string.Join(" / ", c3In)}）。");
        Console.WriteLine();
        var c3PrimIdx0 = Baseline.PrimaryRows.Select(n => Array.FindIndex(c3All, b => b.Name == n))
                                             .Where(i => i >= 0).ToArray();
        double[] c3Fifth0 = c3PrimIdx0.Select(i => C3Ideal(c3All[i].Item2, 0).Win[4]).ToArray();
        double c3Avg0 = c3Fifth0.Average();
        double c3Range = c3In.Select(n => C3Ideal(c3All[Array.FindIndex(c3All, b => b.Name == n)].Item2, 0).Win[4])
                             .Sum() / c3Fifth0.Length;
        double c3Room = c3Avg0 - Baseline.PrimaryFifthFloor;
        Console.WriteLine($"主判定の第五波平均（V0）= **{c3Avg0:F1}%**、歯止め {Baseline.PrimaryFifthFloor:F1}% との余裕 **{c3Room:F1}pt**。");
        Console.WriteLine($"重なる {c3In.Length} 行が第五波で 0.0% まで落ちても平均の低下は最大 **{c3Range:F2}pt**"
                          + $"——**実効レンジがこの幅**（余裕 {c3Room:F1}pt "
                          + $"{(c3Range > c3Room ? "**より大きい ＝ Q5 は拒否権として実効を持つ**" : "**より小さい ＝ Q5 は構造的に発動しない**")}）。");
        Console.WriteLine();
        Console.WriteLine("## 0-6. 陰性対照の分母（Q7）");
        Console.WriteLine();
        Console.WriteLine($"ヨミを含まない **{c3Other.Length} 行** × {c3W} 波 = **{c3Other.Length * c3W} セル** × 版 {C3V - 1} 本。");
        Console.WriteLine();
        Console.WriteLine($"所要 {c3Sw.Elapsed.TotalSeconds:F1} 秒。");
        return;
    }

    // =====================================================================================
    // ideal66: **第66期 §4-4 の帯（seed 200..599）での再現確認だけ**。
    // 判定基準は1つも変えない——第66期の B 帯は 400 seed で、第73〜76期の器具（200 seed）とは幅が違う。
    // **どちらが正かではなく「Q4 の拒否権がどの帯で発火するか」を並べるための再現**である。
    // =====================================================================================
    if (c3Arg == "ideal66")
    {
        Console.WriteLine("# 第77期 —— 理想台のヨミ3行を**第66期の B 帯**（seed 200..599）で（再現確認）");
        Console.WriteLine();
        Console.WriteLine("**判定基準は変えていない。** 第66期 §4-4 の帯は 400 seed、第73〜76期の器具は 200 seed で幅が違うので、");
        Console.WriteLine("Q4 の拒否権がどの帯で発火するかを並べるためだけに回す。");
        Console.WriteLine();
        (double[] Win, double[] Cnt) C3Ideal66(Formation f, int v)
        {
            var win = new double[c3W];
            var cnt = new double[C3C];
            for (int w = 0; w < c3W; w++)
            {
                int wins = 0;
                for (int seed = 200; seed < 600; seed++)
                {
                    BattleResult r = BattleEngine.Run(f, c3Stages[w].Enemy, seed, verbose: false, creak: c3Rule[v]);
                    if (r.PlayerWon) wins++;
                    C3Acc(r, v, cnt, 0);
                }
                win[w] = wins * 100.0 / 400;
            }
            return (win, cnt);
        }
        Console.WriteLine("| 行 | 版 | 第1波 | 第2波 | 第3波 | 第4波 | 第5波 | 平均 | 帰属 | 薙ぎ化率 | 情報セル |");
        Console.WriteLine("|---|---|--:|--:|--:|--:|--:|--:|--:|--:|--:|");
        foreach ((string rn, Formation f) in c3Rows)
        {
            double b0 = C3Ideal66(f, 0).Win.Average();
            for (int v = 0; v < C3V; v++)
            {
                var g = C3Ideal66(f, v);
                Console.WriteLine($"| {(v == 0 ? rn : "")} | {c3Name[v]} | " + string.Join(" | ", g.Win.Select(x => $"{x:F1}%"))
                                  + $" | {g.Win.Average():F1}% | {(v == 0 ? "—" : C3P1(g.Win.Average() - b0))} "
                                  + $"| {(v == 0 ? "—" : $"{C3Rate(g.Cnt, 0):F1}%")} | {C3Info(g.Win)} |");
            }
        }
        Console.WriteLine();
        Console.WriteLine($"所要 {c3Sw.Elapsed.TotalSeconds:F1} 秒。");
        return;
    }

    // =====================================================================================
    // check: 陰性対照（Q7）
    // =====================================================================================
    if (c3Arg == "check")
    {
        Console.WriteLine("# 第77期 —— 陰性対照（Q7）");
        Console.WriteLine();
        int d1 = 0;
        foreach ((string _, Formation f) in c3All)
            for (int w = 0; w < c3W; w++)
                for (int seed = 0; seed < C3Seeds; seed++)
                    if (BattleEngine.Run(f, c3Stages[w].Enemy, seed, verbose: false).PlayerWon
                        != BattleEngine.Run(f, c3Stages[w].Enemy, seed, verbose: false, creak: CreakRule.Default).PlayerWon)
                        d1++;
        Console.WriteLine($"**(1) 引数なし**: {c3All.Length} 行 × {c3W} 波 × {C3Seeds} seed を"
                          + $" `creak` 無し / `CreakRule.Default` で突き合わせ → **ずれ {d1} 件**"
                          + $"（セル数 {c3All.Length * c3W}）。");
        Console.WriteLine();

        int d2 = 0;
        var d2Rows = new List<string>();
        var c3OtherArr = c3Other.ToArray();
        var d2Each = new int[c3OtherArr.Length];
        Parallel.For(0, c3OtherArr.Length, r0 =>
        {
            Formation f = c3OtherArr[r0].F;
            double[] b0 = C3Ideal(f, 0).Win;
            int bad = 0;
            for (int v = 1; v < C3V; v++)
            {
                double[] bv = C3Ideal(f, v).Win;
                for (int w = 0; w < c3W; w++) if (Math.Abs(b0[w] - bv[w]) > 1e-9) bad++;
            }
            d2Each[r0] = bad;
        });
        for (int r0 = 0; r0 < c3OtherArr.Length; r0++)
        {
            d2 += d2Each[r0];
            if (d2Each[r0] > 0) d2Rows.Add(c3OtherArr[r0].Name);
        }
        Console.WriteLine($"**(2) ヨミを含まない行**: {c3Other.Length} 行 × {c3W} 波 = {c3Other.Length * c3W} セルを"
                          + $"版 {C3V - 1} 本で照合 → **ずれ {d2} 件**"
                          + (d2Rows.Count == 0 ? "。" : $"（{string.Join(" / ", d2Rows)}）。"));
        Console.WriteLine();
        Console.WriteLine($"所要 {c3Sw.Elapsed.TotalSeconds:F1} 秒。");
        return;
    }

    // =====================================================================================
    // 主表: ドラフト台 Pw（主判定）＋ 理想台のヨミ3行（拒否権）
    // =====================================================================================
    string c3BandName = c3Alt ? "B" : "A";
    Console.WriteLine($"# 第77期 —— 自己供給と外部供給（{c3BandName} 帯: ドラフト seed {c3Band}..{c3Band + C3M - 1} / 理想 seed {c3Seed0}..{c3Seed0 + C3Seeds - 1}）");
    Console.WriteLine();
    Console.WriteLine($"`dotnet run --project BattleSim -c Release 0 creak3{(c3Alt ? " alt" : "")}` の出力。**`docs/` には置かない。**");
    Console.WriteLine();
    Console.WriteLine($"版 {C3V} 本（V0 ＋ 自己 9/18/30 ＝第66期の3点 ＋ 外部 2/6/12 ＝第67期の3点 ＋ 合計 9/18/30）。");
    Console.WriteLine("**席は動かさない。行も標本も第69〜76期の写し。**");
    Console.WriteLine();

    // ---- ドラフト台の走査 ----
    var c3DWin = new int[C3N][];
    var c3DHas = new bool[C3N];
    var c3DBox = new int[C3N];
    var c3DMove = new bool[C3N];
    var c3DFeed = new bool[C3N];
    var c3DCnt = new double[C3N][];
    int c3Done = 0;
    Console.Error.Write($"{c3BandName}帯 Pw: ");
    Parallel.For(0, C3N, i =>
    {
        UnitDef[] team = C3Team(i);
        int[] seats = C3Seats(team);
        var ids = team.Select(x => x.Id).ToHashSet();
        bool has = ids.Contains(c3YomiId);
        Formation f = C3Form(team, seats);
        var win = new int[C3V * c3W];
        var cnt = has ? new double[C3V * C3C] : null;
        for (int v = 0; v < C3V; v++)
        {
            if (v > 0 && !has) continue;
            for (int w = 0; w < c3W; w++)
                for (int seed = c3Band; seed < c3Band + C3M; seed++)
                {
                    BattleResult r = BattleEngine.Run(f, c3Weak[w].Enemy, seed, verbose: false, creak: c3Rule[v]);
                    if (r.PlayerWon) win[v * c3W + w]++;
                    if (cnt is not null) C3Acc(r, v, cnt, v * C3C);
                }
        }
        c3DWin[i] = win; c3DHas[i] = has; c3DCnt[i] = cnt!;
        c3DBox[i] = Math.Min(3, C3MoveKeys(team));
        c3DMove[i] = c3Movers.Any(ids.Contains);
        c3DFeed[i] = c3Feeders.Any(ids.Contains);
        int c = Interlocked.Increment(ref c3Done);
        if (c % 1000 == 0) Console.Error.Write(".");
    });
    Console.Error.WriteLine();

    double C3DRate(int i, int v, int w)
        => (v == 0 || c3DHas[i] ? c3DWin[i][v * c3W + w] : c3DWin[i][w]) * 100.0 / C3M;
    double[] C3DRates(int v, int wave)
        => Enumerable.Range(0, C3N).Select(i => wave < 0
            ? Enumerable.Range(1, c3W - 1).Average(w => C3DRate(i, v, w))
            : C3DRate(i, v, wave)).ToArray();
    double C3DMean(IEnumerable<int> idx, int v)
        => idx.Average(i => Enumerable.Range(1, c3W - 1).Average(w => C3DRate(i, v, w)));

    var c3Idx = Enumerable.Range(0, C3N).Where(i => c3DHas[i]).ToArray();
    var c3Agg = new double[C3V * C3C];
    foreach (int i in c3Idx) for (int c = 0; c < C3V * C3C; c++) c3Agg[c] += c3DCnt[i][c];

    Console.WriteLine($"**ヨミの在席標本 = {c3Idx.Length:N0} / {C3N:N0}**"
                      + $"（{100.0 * c3Idx.Length / C3N:F2}%。一様なら 5/{c3RN} = {500.0 / c3RN:F2}%）。");
    Console.WriteLine($"うち移動の相方あり **{c3Idx.Count(i => c3DMove[i]):N0}** / 強化の供給者あり **{c3Idx.Count(i => c3DFeed[i]):N0}** / "
                      + $"どちらも無し **{c3Idx.Count(i => !c3DMove[i] && !c3DFeed[i]):N0}**。");
    Console.WriteLine();

    // ---- 表A ----
    Console.WriteLine("## 表A —— ドラフト台 Pw（**在席標本だけ**・第2〜5波）");
    Console.WriteLine();
    Console.WriteLine("| 版 | 族 | 在席時勝率 | **帰属** | **薙ぎ化率** | 到達% | 初到達T | 振/戦 | 軋み | 押され | 動かされた% | 押された% |");
    Console.WriteLine("|---|---|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|");
    var c3DAttr = new double[C3V];
    double c3D0 = C3DMean(c3Idx, 0);
    for (int v = 0; v < C3V; v++)
    {
        int off = v * C3C;
        double a = C3DMean(c3Idx, v);
        c3DAttr[v] = a - c3D0;
        double n = Math.Max(1, c3Agg[off + 0]);
        Console.WriteLine($"| {c3Name[v]} | {c3FamName[C3Fam(v)]} | {a:F2}% "
                          + $"| {(v == 0 ? "—" : $"**{C3P2(c3DAttr[v])}**")} "
                          + $"| {(v == 0 ? "—" : $"**{C3Rate(c3Agg, off):F1}%**")} "
                          + $"| {(v == 0 ? "—" : $"{100.0 * c3Agg[off + 8] / n:F1}%")} "
                          + $"| {(v == 0 || c3Agg[off + 8] == 0 ? "—" : $"{c3Agg[off + 9] / c3Agg[off + 8]:F2}")} "
                          + $"| {c3Agg[off + 1] / n:F2} | {c3Agg[off + 3] / n:F1} | {c3Agg[off + 4] / n:F1} "
                          + $"| {100.0 * c3Agg[off + 10] / n:F1}% | {100.0 * c3Agg[off + 11] / n:F1}% |");
    }
    Console.WriteLine();

    // ---- 表B ----
    Console.WriteLine("## 表B —— 相方の有無で割る（**この期の主題**）");
    Console.WriteLine();
    var c3Grp = new (string Name, int[] Idx)[]
    {
        ("移動の相方あり", c3Idx.Where(i => c3DMove[i]).ToArray()),
        ("移動の相方なし", c3Idx.Where(i => !c3DMove[i]).ToArray()),
        ("強化の供給者あり", c3Idx.Where(i => c3DFeed[i]).ToArray()),
        ("強化の供給者なし", c3Idx.Where(i => !c3DFeed[i]).ToArray()),
        ("**どちらも無し**", c3Idx.Where(i => !c3DMove[i] && !c3DFeed[i]).ToArray()),
    };
    Console.WriteLine("| 群 | 標本 | V0 | " + string.Join(" | ", Enumerable.Range(1, C3V - 1).Select(v => c3Name[v])) + " |");
    Console.WriteLine("|---|--:|--:|" + string.Concat(Enumerable.Repeat("--:|", C3V - 1)));
    foreach ((string gn, int[] gi) in c3Grp)
    {
        if (gi.Length == 0) { Console.WriteLine($"| {gn} | 0 | — |" + string.Concat(Enumerable.Repeat(" — |", C3V - 1))); continue; }
        double b = C3DMean(gi, 0);
        Console.WriteLine($"| {gn} | {gi.Length:N0} | {b:F2}% | "
                          + string.Join(" | ", Enumerable.Range(1, C3V - 1).Select(v => C3P2(C3DMean(gi, v) - b))) + " |");
    }
    Console.WriteLine();
    Console.WriteLine("**セルは帰属（版 − V0）。** 群の分け方は測る前に固定（移動の書き手3枚 / `Whet` の供給者6枚）。");
    Console.WriteLine();

    // ---- 表B-2（波ごと）----
    Console.WriteLine("## 表B-2 —— 波ごとの帰属（自己 B9 / 外部 W2・群別）");
    Console.WriteLine();
    Console.WriteLine("**味方側でヨミを動かせるのは3枚だけ**（セロ / カド / バサ）。**敵側は第五波の告発人（曝き）1枚**"
                      + $"（`ExposeRule.MaxPerBattle` = {ExposeRule.Default.MaxPerBattle}）——");
    Console.WriteLine("移動の相方がいない標本でヨミが動かされる経路はそこだけである。");
    Console.WriteLine();
    Console.WriteLine("| 群 | 版 | 第2波 | 第3波 | 第4波 | 第5波 |");
    Console.WriteLine("|---|---|--:|--:|--:|--:|");
    foreach ((string gn, int[] gi) in c3Grp)
    {
        if (gi.Length == 0) continue;
        foreach (int v in new[] { 1, 4 })
            Console.WriteLine($"| {(v == 1 ? gn : "")} | {c3Name[v]} | "
                + string.Join(" | ", Enumerable.Range(1, c3W - 1).Select(w =>
                    C3P2(gi.Average(i => C3DRate(i, v, w)) - gi.Average(i => C3DRate(i, 0, w))))) + " |");
    }
    Console.WriteLine();

    // ---- 表C ----
    Console.WriteLine("## 表C —— 傾き（箱 = 移動キーを持つ駒の枚数・全 11,000 標本）");
    Console.WriteLine();
    Console.WriteLine($"箱: **0枚 {c3DBox.Count(x => x == 0):N0} / 1枚 {c3DBox.Count(x => x == 1):N0} / "
                      + $"2枚 {c3DBox.Count(x => x == 2):N0} / 3+ {c3DBox.Count(x => x == 3):N0}**"
                      + "（ヨミ自身も移動キーの持ち手なので、在席標本は必ず1枚以上の箱に入る）。");
    Console.WriteLine();
    Console.WriteLine("| 版 | 0枚 | 1枚 | 2枚 | 3+ | **傾き** | 傾きの改善 |");
    Console.WriteLine("|---|--:|--:|--:|--:|--:|--:|");
    double c3Slope0 = double.NaN;
    var c3SlopeV = new double[C3V];
    for (int v = 0; v < C3V; v++)
    {
        var rate = C3DRates(v, -1);
        double[] bm = C3BoxMeans(rate, c3DBox);
        double sl = C3Slope(rate, c3DBox);
        c3SlopeV[v] = sl;
        if (v == 0) c3Slope0 = sl;
        Console.WriteLine($"| {c3Name[v]} | {bm[0]:F2}% | {bm[1]:F2}% | {bm[2]:F2}% | {(double.IsNaN(bm[3]) ? "—" : $"{bm[3]:F2}%")} "
                          + $"| **{C3P1(sl)}** | {(v == 0 ? "—" : C3P2(sl - c3Slope0))} |");
    }
    Console.WriteLine();

    // ---- 理想台 ----
    Console.WriteLine("## 表D —— 理想台のヨミ3行（**拒否権**・波ごとの勝率）");
    Console.WriteLine();
    var c3IWin = new Dictionary<string, double[][]>();
    var c3ICnt = new Dictionary<string, double[][]>();
    foreach ((string rn, Formation f) in c3Rows)
    {
        var ws = new double[C3V][]; var cs = new double[C3V][];
        for (int v = 0; v < C3V; v++) { var g = C3Ideal(f, v); ws[v] = g.Win; cs[v] = g.Cnt; }
        c3IWin[rn] = ws; c3ICnt[rn] = cs;
    }
    Console.WriteLine("| 行 | 版 | 第1波 | 第2波 | 第3波 | 第4波 | 第5波 | 平均 | **帰属** | **薙ぎ化率** | 到達% | 初到達T | 情報セル |");
    Console.WriteLine("|---|---|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|");
    foreach ((string rn, Formation _) in c3Rows)
    {
        double b0 = c3IWin[rn][0].Average();
        for (int v = 0; v < C3V; v++)
        {
            double[] w = c3IWin[rn][v]; double[] c = c3ICnt[rn][v];
            double n = Math.Max(1, c[0]);
            Console.WriteLine($"| {(v == 0 ? rn : "")} | {c3Name[v]} | " + string.Join(" | ", w.Select(x => $"{x:F1}%"))
                              + $" | {w.Average():F1}% | {(v == 0 ? "—" : C3P1(w.Average() - b0))} "
                              + $"| {(v == 0 ? "—" : $"{C3Rate(c, 0):F1}%")} "
                              + $"| {(v == 0 ? "—" : $"{100.0 * c[8] / n:F1}%")} "
                              + $"| {(v == 0 || c[8] == 0 ? "—" : $"{c[9] / c[8]:F2}")} | {C3Info(w)} |");
        }
    }
    Console.WriteLine();

    // ---- Q1 / Q6 ----
    Console.WriteLine("## Q1（**主判定**: 自己供給 対 外部供給）と Q6（外部供給の上積み）");
    Console.WriteLine();
    int C3Best(int fam)
    {
        int best = -1; double ba = double.NegativeInfinity;
        for (int v = 1; v < C3V; v++)
            if (C3Fam(v) == fam && c3DAttr[v] >= ba) { ba = c3DAttr[v]; best = v; }
        return best;
    }
    int c3BB = C3Best(1), c3BW = C3Best(2), c3BT = C3Best(3);
    Console.WriteLine("**最良 = その族でドラフト台の帰属が最大の版**（同点は高い閾値）。");
    Console.WriteLine();
    Console.WriteLine("| 量 | 版 | 値 |");
    Console.WriteLine("|---|---|--:|");
    Console.WriteLine($"| 自己供給の最良 | {c3Name[c3BB]} | {C3P2(c3DAttr[c3BB])} |");
    Console.WriteLine($"| 外部供給の最良 | {c3Name[c3BW]} | {C3P2(c3DAttr[c3BW])} |");
    Console.WriteLine($"| 合計の最良 | {c3Name[c3BT]} | {C3P2(c3DAttr[c3BT])} |");
    Console.WriteLine($"| **Q1 = 自己 − 外部** | {c3Name[c3BB]} − {c3Name[c3BW]} | **{C3P2(c3DAttr[c3BB] - c3DAttr[c3BW])}** |");
    Console.WriteLine($"| **Q6 = 合計 − 自己** | {c3Name[c3BT]} − {c3Name[c3BB]} | **{C3P2(c3DAttr[c3BT] - c3DAttr[c3BB])}** |");
    Console.WriteLine();
    Console.WriteLine("同じ閾値どうしの対（自己 9/18/30 対 合計 9/18/30）でも見る:");
    Console.WriteLine();
    Console.WriteLine("| 閾値 | 自己 | 合計 | 合計 − 自己 |");
    Console.WriteLine("|--:|--:|--:|--:|");
    for (int k = 0; k < 3; k++)
        Console.WriteLine($"| {UnitTally.CreakProbes[k]} | {C3P2(c3DAttr[1 + k])} | {C3P2(c3DAttr[7 + k])} "
                          + $"| **{C3P2(c3DAttr[7 + k] - c3DAttr[1 + k])}** |");
    Console.WriteLine();

    // ---- Q2 と採る版 ----
    Console.WriteLine("## Q2（条件は条件か）と、採る版");
    Console.WriteLine();
    Console.WriteLine("**Q2 = ドラフト台の薙ぎ化率が 10〜90%、かつ理想台のヨミ3行が3行とも 10〜90%**（測る前に固定）。");
    Console.WriteLine();
    Console.WriteLine("| 版 | ドラフト | 帯内 | 理想台3行 | 3行とも帯内 | **Q2** | ドラフトの帰属 |");
    Console.WriteLine("|---|--:|---|---|---|---|--:|");
    var c3Q2 = new bool[C3V];
    for (int v = 1; v < C3V; v++)
    {
        double dr = C3Rate(c3Agg, v * C3C);
        var ir = c3Rows.Select(b => C3Rate(c3ICnt[b.Name][v], 0)).ToArray();
        bool dok = dr >= 10.0 && dr <= 90.0;
        bool iok = ir.All(x => x >= 10.0 && x <= 90.0);
        c3Q2[v] = dok && iok;
        Console.WriteLine($"| {c3Name[v]} | {dr:F1}% | {(dok ? "○" : "×")} | {string.Join(" / ", ir.Select(x => $"{x:F1}%"))} "
                          + $"| {(iok ? "○" : "×")} | {(c3Q2[v] ? "**○**" : "×")} | {C3P2(c3DAttr[v])} |");
    }
    Console.WriteLine();
    int c3Pick = -1; double c3PickA = double.NegativeInfinity;
    for (int v = 1; v < C3V; v++)
        if (c3Q2[v] && c3DAttr[v] >= c3PickA) { c3PickA = c3DAttr[v]; c3Pick = v; }
    if (c3Pick < 0) Console.WriteLine("**Q2 を満たす版が1つも無い → 採らない。**");
    else Console.WriteLine($"→ 採る版の候補は **{c3Name[c3Pick]}**（帰属 {C3P2(c3DAttr[c3Pick])}）。");
    Console.WriteLine();

    // ---- Q3 / Q4 / Q5 ----
    Console.WriteLine("## Q3（帰属）・Q4（情報セル・**拒否権**）・Q5（歯止め）");
    Console.WriteLine();
    Console.WriteLine("| 版 | ドラフトの帰属 | 傾きの改善 | " + string.Join(" | ", c3Rows.Select(b => $"{b.Name}")) + " |");
    Console.WriteLine("|---|--:|--:|" + string.Concat(Enumerable.Repeat("--:|", c3Rows.Length)));
    for (int v = 1; v < C3V; v++)
        Console.WriteLine($"| {c3Name[v]} | {C3P2(c3DAttr[v])} | {C3P2(c3SlopeV[v] - c3Slope0)} | "
                          + string.Join(" | ", c3Rows.Select(b => C3P1(c3IWin[b.Name][v].Average() - c3IWin[b.Name][0].Average()))) + " |");
    Console.WriteLine();
    Console.WriteLine("（理想台の列は**帰属 = 版 − V0 の5波平均**。）");
    Console.WriteLine();
    Console.WriteLine("| 版 | " + string.Join(" | ", c3Rows.Select(b => b.Name)) + " | 情報セル計 | V0 比 | **Q4** |");
    Console.WriteLine("|---|" + string.Concat(Enumerable.Repeat("--:|", c3Rows.Length)) + "--:|--:|---|");
    int c3Info0 = c3Rows.Sum(b => C3Info(c3IWin[b.Name][0]));
    Console.WriteLine("| V0（無効） | " + string.Join(" | ", c3Rows.Select(b => C3Info(c3IWin[b.Name][0]).ToString()))
                      + $" | {c3Info0} | — | — |");
    var c3Q4 = new bool[C3V];
    for (int v = 1; v < C3V; v++)
    {
        int c3InfoV = c3Rows.Sum(b => C3Info(c3IWin[b.Name][v]));
        c3Q4[v] = c3Rows.All(b => C3Info(c3IWin[b.Name][v]) >= C3Info(c3IWin[b.Name][0]));
        Console.WriteLine($"| {c3Name[v]} | " + string.Join(" | ", c3Rows.Select(b => C3Info(c3IWin[b.Name][v]).ToString()))
                          + $" | {c3InfoV} | {c3InfoV - c3Info0:+0;-0;0} | {(c3Q4[v] ? "○" : "**×**")} |");
    }
    Console.WriteLine();
    Console.WriteLine("**Q4 は行ごとに「情報セルが減っていないこと」**（第66期はここで 96.5〜99.2% を 100.0% に押して落ちた）。");
    Console.WriteLine();

    var c3PrimIdx = Baseline.PrimaryRows.Select(n => Array.FindIndex(c3All, b => b.Name == n))
                                        .Where(i => i >= 0).ToArray();
    Console.WriteLine("| 版 | 主判定19行の第五波平均 | 歯止め 33.2% との余裕 | **Q5** |");
    Console.WriteLine("|---|--:|--:|---|");
    var c3Q5 = new bool[C3V];
    for (int v = 0; v < C3V; v++)
    {
        double avg = c3PrimIdx.Select(i => C3Ideal(c3All[i].Item2, v).Win[4]).Average();
        c3Q5[v] = avg >= Baseline.PrimaryFifthFloor;
        Console.WriteLine($"| {c3Name[v]} | {avg:F1}% | {C3P1(avg - Baseline.PrimaryFifthFloor)} | {(v == 0 ? "—" : c3Q5[v] ? "○" : "**×**")} |");
    }
    Console.WriteLine();

    // ---- 採否 ----
    Console.WriteLine("## 採否（Q2・Q3・Q4・Q5 のすべて）");
    Console.WriteLine();
    Console.WriteLine("| 版 | Q2 | Q3（\\|帰属\\| ≥ 1.5pt） | Q4 | Q5 | **採否** |");
    Console.WriteLine("|---|---|---|---|---|---|");
    for (int v = 1; v < C3V; v++)
    {
        bool q3 = Math.Abs(c3DAttr[v]) >= 1.5;
        bool ok = c3Q2[v] && q3 && c3Q4[v] && c3Q5[v];
        Console.WriteLine($"| {c3Name[v]} | {(c3Q2[v] ? "○" : "×")} | {(q3 ? "○" : "×")}（{C3P2(c3DAttr[v])}） "
                          + $"| {(c3Q4[v] ? "○" : "×")} | {(c3Q5[v] ? "○" : "×")} | {(ok ? "**○**" : "×")} |");
    }
    Console.WriteLine();
    Console.WriteLine("**Q3 の「両 seed 帯で符号一致」は A 帯 / B 帯を別々に回して突き合わせる**（この表は片帯ぶん）。");
    Console.WriteLine();
    Console.WriteLine($"所要 {c3Sw.Elapsed.TotalSeconds:F1} 秒。");
    return;
}

// 強化の使い道の解剖（第65期・調査）。**この期は新しい機構を1つも作らない。駒も作らない。**
// `Traits.cs` の挙動 / `UnitCatalog.All` / `Stages` / `CompareBuilds()` は1行も動かさず、
// 足したのは **(a) 誰も読んで分岐しない計数**（到着ターン・使用・経路別の受け手）と
// **(b) 窓口 `Whet` の加算だけを経路ごとに落とすノブ `WhetMask`**（既定は空＝現行）。
//
// 主題は「**強化の供給の偏りは、編成・配置の判断を減らしているか**」。
// 積み残し1（第56期）は「供給の 47.1% が吐き戻し1本＝編成が選べる供給が無い」として立ち、
// **「要検討」のまま3期（62〜64）を「行き先」の駒に使って3回落ちた。**
// 偏りが問題だと確かめた数字は1つも無い——ここで測る。
//
// 立てた仮説（測って否定してよい。**測る前に指示書 §0-3 で固定**）:
//   H1 偏り説 —— 吐き戻しが半分を占めるので編成が強化について判断する余地が無い
//   H2 無価値説 —— **吐き戻しの帰属は ≈ 0**（第23期の再現）。偏りは価値の無い通貨の帳簿上の偏り
//   H3 遅さ説 —— 律速は偏りではなく**到着の遅さ**。受け手が振る前に戦闘が終わる
//
// **自由度 (e) を構造的に消してある**（第64期の教訓）:
//   行は選ばない（その経路の供給者を含む**全行**）／席は動かさない（`reseat` は帰属の器具ではない）／
//   枠は差し替えない（**落とすのは窓口の加算1行だけ**で、供給者の他の特性は残る）。
//
//     dotnet run --project BattleSim -c Release 0 spend        # 主表（A 帯 seed 0..199）
//     dotnet run --project BattleSim -c Release 0 spend map    # 判断の地図（**戦闘0回**）
//     dotnet run --project BattleSim -c Release 0 spend alt    # 再現帯（seed 200..599）
if (focusId == "spend")
{
    var spBuilds = CompareBuilds().ToArray();
    IReadOnlyList<EnemyCatalog.Stage> spStages = EnemyCatalog.Stages;
    string spArg = args.Length > 2 ? args[2] : "";
    bool spAlt = spArg == "alt";
    int spSeed0 = spAlt ? 200 : 0;
    int spSeedN = spAlt ? 400 : 200;

    // 経路の台帳。**「編成が動かせるか」は測る前にコードを読んで固定した**（指示書 §1-3）。
    // Q3（H1 の判定）はこの分類の上で読むので、**実測を見てから書き換えないこと。**
    var spRoutes = new (WhetRoute Route, TraitId Need, string Supplier, string Dest, string Decided, string Lever)[]
    {
        (WhetRoute.Goad,         TraitId.Goad,     "カリ",   "隣接する `CurrentAttack` 最大の味方1体",
         "カリの隣に誰を置くか", "配置"),
        (WhetRoute.RallyOpening, TraitId.Rally,    "ガン",   "味方全体（自分以外・`SupportTargets`）",
         "—（無条件）", "動かせない"),
        (WhetRoute.RallyTurn,    TraitId.Rally,    "ガン",   "手番を差し出した味方（`SupportTargets`）",
         "`IdleTurn` の供給（痺れ・据え・不動）", "編成"),
        (WhetRoute.Bind,         TraitId.Bind,     "クグ",   "`AcceptsSupport` を通り痺れていない味方から**無作為**",
         "候補集合の枚数だけ（`Roll`）", "編成（弱い）"),
        (WhetRoute.Drifter,      TraitId.Drifter,  "シオ",   "動かされた味方",
         "移動の供給（バサ・ハネ・曝き）", "編成"),
        (WhetRoute.Regurgitate,  TraitId.Colossus, "ゴルム", "ゴルムが庇った相手（`SupportTargets`）",
         "巨躯の被覆（誰がゴルムより後ろにいるか）", "配置"),
        (WhetRoute.Favor,        TraitId.Favor,    "ヒヨ",   "燃えている味方全員（自分を除く・**位置を問わない**）",
         "燃焼の供給（ボルグの隣・破裂）", "配置（間接）"),
    };

    var spName = new Dictionary<string, string>();
    foreach (UnitDef d in UnitCatalog.All) spName[d.Id] = d.Name;
    foreach (EnemyCatalog.Stage st in spStages)
        foreach ((int _, UnitDef d) in st.Enemy.Occupied()) spName[d.Id] = d.Name;
    string SpLabel(string id) => spName.TryGetValue(id, out string? n) ? n : id;

    bool SpHas((string Name, Formation F) row, TraitId t)
        => row.F.Occupied().Any(o => o.Item2.Traits.Contains(t));

    // ---- map: 判断の地図。**戦闘を1回も回さない。** -----------------------------
    if (spArg == "map")
    {
        Console.WriteLine("# 強化の使い道 —— 判断の地図（第65期 Phase 0。**戦闘0回**）");
        Console.WriteLine();
        Console.WriteLine("## 0-2. 出力経路（強化1点が「使われる」ための分母）");
        Console.WriteLine();
        Console.WriteLine("`CurrentAttack` を自分の出力量に変換する箇所は**ロスター全体で4つ**"
                          + "（`BattleContext.NoteAttackRead` の呼び出し元）。");
        Console.WriteLine();
        Console.WriteLine("| # | 場所 | 型 | `CurrentAttack` の読み | 手番 |");
        Console.WriteLine("|--:|---|---|---|---|");
        Console.WriteLine("| 1 | `BattleEngine.cs:1815` `PerformAttack` | 攻撃（単体・薙ぎ・貫き・全体） | "
                          + "1回（`atk` を作る所。倍率＝止めはこの後） | 自分の手番 |");
        Console.WriteLine("| 2 | `Traits.cs:1221` 棘 `ThornsTrait.OnDamaged` | 反撃（範囲） | "
                          + "1回（`CurrentAttack * Multiplier`） | **ターン外**（`CanActOutOfTurn`） |");
        Console.WriteLine("| 3 | `Traits.cs:3453` 仇討ち `AvengeTrait.OnAllyDamaged` | 反撃（単体） | "
                          + "1回（`Max(1, CurrentAttack)`） | **ターン外**（`CanActOutOfTurn`） |");
        Console.WriteLine("| 4 | `Traits.cs:3504` 責め苦の追撃 `TormentTrait.OnAfterAttack` | 追撃（単体） | "
                          + "1回（`Max(1, CurrentAttack)`） | 自分の手番の中 |");
        Console.WriteLine();
        Console.WriteLine("> **乗算はこの4本の外側にある。** `UnitState.CurrentAttack` は "
                          + "`Def.Attack + AtkBonus` を作ってから `Trait.ModifyAttack` を通すので、");
        Console.WriteLine("> **熾火（ホタ・燃焼中は4倍＋貫き）に配った強化1点は 4 点になる**（第58期の乗算監査）。");
        Console.WriteLine("> 逆に `Actions = [Skill]` の3枚（ノノ・ミオ・ヒヨ）は**4本のどれも通らない**"
                          + "＝真の捨て場（第64期）。");
        Console.WriteLine();

        Console.WriteLine("## 0-3. 経路ごとの「行き先の決まり方」");
        Console.WriteLine();
        Console.WriteLine("**Q3（H1 の判定）はこの分類の上で読む。実測を見てから書き換えない。**");
        Console.WriteLine();
        Console.WriteLine("| 経路 | 供給者 | 行き先 | 決めているもの | 編成が動かせるか |");
        Console.WriteLine("|---|:-:|---|---|:-:|");
        foreach ((WhetRoute r, TraitId _, string sup, string dest, string dec, string lev) in spRoutes)
            Console.WriteLine($"| {WhetRoutes.Names[(int)r]} | {sup} | {dest} | {dec} | **{lev}** |");
        Console.WriteLine();
        Console.WriteLine("> **縛めの「?」を埋めた**（指示書 §1-3）——`BindTrait.BindAlly` は");
        Console.WriteLine("> `AcceptsSupport` を通り痺れていない味方から `ctx.Roll` で**無作為に**選ぶ。");
        Console.WriteLine("> 席も攻撃力も隣接も1ビットも読まないので、**配置では動かせない**"
                          + "（動かせるのは候補集合の枚数だけ）。");
        Console.WriteLine();

        Console.WriteLine("## 0-5 / 0-6. 各経路の供給者を含む行（陰性対照の分母）");
        Console.WriteLine();
        var spPrimary = new HashSet<string>(Baseline.PrimaryRows);
        Console.WriteLine("| 経路 | 供給者を含む行 | 含まない行（陰性対照） | 主判定19行のうち |");
        Console.WriteLine("|---|--:|--:|--:|");
        foreach ((WhetRoute r, TraitId need, string _, string __, string ___, string ____) in spRoutes)
        {
            int with = spBuilds.Count(b => SpHas(b, need));
            int prim = spBuilds.Count(b => SpHas(b, need) && spPrimary.Contains(b.Name));
            Console.WriteLine($"| {WhetRoutes.Names[(int)r]} | {with} | {spBuilds.Length - with} | {prim} |");
        }
        Console.WriteLine();
        Console.WriteLine($"全 **{spBuilds.Length} 行**（`docs/balance.md` = {spBuilds.Length} × 5 波 = "
                          + $"**{spBuilds.Length * 5} セル**）。");
        Console.WriteLine();
        return;
    }

    // ---- 測定 -------------------------------------------------------------
    // 1戦ぶんの器。**行 × 波の勝率**と、経路別の量・到着・使用・受け手を同じ走査で取る。
    double[] SpWin(Formation f, WhetMask? mask, double[]? route, double[]? turnSum,
                   double[]? firstSum, double[]? firstCnt, double[]? used,
                   Dictionary<string, double>[]? to, Dictionary<string, double>? got,
                   Dictionary<string, double>? hoardNew, double[]? battleTurns)
    {
        var win = new double[spStages.Count];
        for (int w = 0; w < spStages.Count; w++)
        {
            int wins = 0;
            for (int seed = spSeed0; seed < spSeed0 + spSeedN; seed++)
            {
                BattleResult r = BattleEngine.Run(f, spStages[w].Enemy, seed, verbose: false,
                                                  whetMask: mask);
                if (r.PlayerWon) wins++;
                if (route is null) continue;

                if (battleTurns is not null) battleTurns[0] += r.Turns;
                for (int i = 0; i < WhetRoutes.Count; i++)
                {
                    route[i] += r.WhetByRoute[i];
                    turnSum![i] += r.WhetTurnSumByRoute[i];
                    firstSum![i] += r.WhetFirstTurnSumByRoute[i];
                    firstCnt![i] += r.WhetFirstTurnCountByRoute[i];
                    used![i] += r.WhetUsedByRoute[i];
                    foreach ((string id, int v) in r.WhetToByRoute[i])
                        to![i][id] = to[i].TryGetValue(id, out double had) ? had + v : v;
                }
                foreach ((string id, UnitTally t) in r.TallyByUnit)
                {
                    if (t.Whetted <= 0) continue;
                    got![id] = got.TryGetValue(id, out double g) ? g + t.Whetted : t.Whetted;
                    if (t.AttackReads == 0)
                        hoardNew![id] = hoardNew.TryGetValue(id, out double h) ? h + t.Whetted : t.Whetted;
                }
            }
            win[w] = wins * 100.0 / spSeedN;
        }
        return win;
    }

    var spSw = System.Diagnostics.Stopwatch.StartNew();

    // 現行（`WhetMask` 空）。**ここが 305 セルの `compare` と一致する**（受け入れ基準1）。
    var spBase = new Dictionary<string, double[]>();
    var spRouteAmt = new double[WhetRoutes.Count];
    var spTurnSum = new double[WhetRoutes.Count];
    var spFirstSum = new double[WhetRoutes.Count];
    var spFirstCnt = new double[WhetRoutes.Count];
    var spUsed = new double[WhetRoutes.Count];
    var spTo = Enumerable.Range(0, WhetRoutes.Count).Select(_ => new Dictionary<string, double>()).ToArray();
    var spGot = new Dictionary<string, double>();
    var spHoard = new Dictionary<string, double>();
    var spTurns = new double[1];
    var spRowRoute = new Dictionary<string, double[]>();
    var spRowHoard = new Dictionary<string, double>();

    foreach ((string rn, Formation f) in spBuilds)
    {
        var rr = new double[WhetRoutes.Count];
        var rh = new Dictionary<string, double>();
        var rowTo = Enumerable.Range(0, WhetRoutes.Count).Select(_ => new Dictionary<string, double>()).ToArray();
        spBase[rn] = SpWin(f, null, rr, spTurnSum, spFirstSum, spFirstCnt, spUsed, rowTo, spGot, rh, spTurns);
        for (int i = 0; i < WhetRoutes.Count; i++)
        {
            spRouteAmt[i] += rr[i];
            foreach ((string id, double v) in rowTo[i])
                spTo[i][id] = spTo[i].TryGetValue(id, out double had) ? had + v : v;
        }
        spRowRoute[rn] = rr;
        spRowHoard[rn] = rh.Values.Sum();
        foreach ((string id, double v) in rh)
            spHoard[id] = spHoard.TryGetValue(id, out double h) ? h + v : v;
    }

    // 経路を1本ずつ落とす。**全 61 行**（陰性対照＝供給者を含まない行も同じ表で出す）。
    var spDrop = new Dictionary<(WhetRoute, string), double[]>();
    foreach ((WhetRoute r, TraitId _, string __, string ___, string ____, string _____) in spRoutes)
        foreach ((string rn, Formation f) in spBuilds)
            spDrop[(r, rn)] = SpWin(f, WhetMask.Of(r), null, null, null, null, null, null, null, null, null);

    spSw.Stop();

    int spBattles = spBuilds.Length * spStages.Count * spSeedN * (1 + spRoutes.Length);
    double spN = spBuilds.Length * spStages.Count * (double)spSeedN;
    double Mean(double[] w) => w.Average();

    Console.WriteLine("# 強化は何に使われているのか（第65期・調査）");
    Console.WriteLine();
    Console.WriteLine($"全 **{spBuilds.Length} 行** × {spStages.Count} 波 × seed {spSeed0}..{spSeed0 + spSeedN - 1}"
                      + $"、現行 + 7 経路落とし = **{spBattles} 戦**（{spSw.Elapsed.TotalSeconds:F1} 秒）。");
    Console.WriteLine($"帯は **{(spAlt ? "B（再現・200..599）" : "A（主・0..199）")}**。");
    Console.WriteLine();
    Console.WriteLine("**行を選ばない・席を動かさない・枠を差し替えない**（第64期の自由度 (e) を構造的に消してある）。");
    Console.WriteLine("落とすのは **`BattleContext.Whet` の `AtkBonus +=` の1行だけ**で、");
    Console.WriteLine("縛めの痺れ・移り木の回復・吐き戻しのログ・乱数の消費は1ビットも動かない。");
    Console.WriteLine();

    // ---- 表A -------------------------------------------------------------
    Console.WriteLine("## 表A. 経路の帰属（現行 − その経路を落とした版）");
    Console.WriteLine();
    Console.WriteLine("帰属は**5波平均の勝率(pt)**。**`|帰属| < 1.5pt` は 0 と読む**（第57期の線）。");
    Console.WriteLine();
    Console.WriteLine("| 経路 | 供給量/戦 | 占有率 | 該当行 | 帰属の平均 | 正の行 | \\|帰属\\| ≥ 1.5 の行 | 陰性対照（最大\\|Δ\\|） |");
    Console.WriteLine("|---|--:|--:|--:|--:|--:|--:|--:|");
    double spTotal = spRouteAmt.Sum();
    var spAttr = new Dictionary<WhetRoute, List<(string Row, double D)>>();
    foreach ((WhetRoute r, TraitId need, string _, string __, string ___, string ____) in spRoutes)
    {
        var with = new List<(string, double)>();
        double negMax = 0;
        foreach ((string rn, Formation f) in spBuilds)
        {
            double d = Mean(spBase[rn]) - Mean(spDrop[(r, rn)]);
            if (SpHas((rn, f), need)) with.Add((rn, d));
            else negMax = Math.Max(negMax, Math.Abs(d));
        }
        spAttr[r] = with;
        Console.WriteLine($"| {WhetRoutes.Names[(int)r]} | {spRouteAmt[(int)r] / spN:F2} | "
                          + $"{(spTotal > 0 ? spRouteAmt[(int)r] * 100.0 / spTotal : 0):F1}% | {with.Count} | "
                          + $"**{with.Average(x => x.Item2):+0.0;-0.0;0.0}** | "
                          + $"{with.Count(x => x.Item2 > 0)} | {with.Count(x => Math.Abs(x.Item2) >= 1.5)} | "
                          + $"{negMax:F1} |");
    }
    Console.WriteLine($"| **合計** | **{spTotal / spN:F2}** | 100.0% | — | — | — | — | — |");
    Console.WriteLine();

    Console.WriteLine("### 表A-2. 行ごとの帰属（該当行を全部・選んでいない）");
    Console.WriteLine();
    foreach ((WhetRoute r, TraitId _, string __, string ___, string ____, string _____) in spRoutes)
    {
        Console.WriteLine($"**{WhetRoutes.Names[(int)r]}**（{spAttr[r].Count} 行）: "
                          + string.Join(" / ", spAttr[r].OrderByDescending(x => x.D)
                                .Select(x => $"{x.Row} {x.D:+0.0;-0.0;0.0}")));
        Console.WriteLine();
    }

    // ---- 表B -------------------------------------------------------------
    Console.WriteLine("## 表B. 到着と使用");
    Console.WriteLine();
    Console.WriteLine("**使用率** = 受け取った**後**に受け手が `AttackReads` を1度でも通した量の割合。");
    Console.WriteLine("死蔵（`AttackReads == 0`・第64期）より厳しい——最後の一撃の後に届いた強化は死蔵に数えられない。");
    Console.WriteLine();
    Console.WriteLine("| 経路 | 供給量/戦 | 到着の平均T | 初到着の平均T | 使用率 | 到着T ÷ 決着T |");
    Console.WriteLine("|---|--:|--:|--:|--:|--:|");
    double spAvgTurns = spTurns[0] / spN;
    foreach ((WhetRoute r, TraitId _, string __, string ___, string ____, string _____) in spRoutes)
    {
        int i = (int)r;
        double amt = spRouteAmt[i];
        double arr = amt > 0 ? spTurnSum[i] / amt : 0;
        double first = spFirstCnt[i] > 0 ? spFirstSum[i] / spFirstCnt[i] : 0;
        Console.WriteLine($"| {WhetRoutes.Names[i]} | {amt / spN:F2} | {arr:F2} | {first:F2} | "
                          + $"**{(amt > 0 ? spUsed[i] * 100.0 / amt : 0):F1}%** | "
                          + $"{(spAvgTurns > 0 ? arr / spAvgTurns : 0):F2} |");
    }
    Console.WriteLine();
    Console.WriteLine($"参考: 全 {spBuilds.Length} 行 × 5 波の**決着ターンの平均は {spAvgTurns:F2}T**。");
    Console.WriteLine("開戦時（`OnBattleStart`）の到着はターン **0**。");
    Console.WriteLine();

    // ---- 表C -------------------------------------------------------------
    Console.WriteLine("## 表C. 判断の地図（Phase 0-3 の分類 + 実測）");
    Console.WriteLine();
    Console.WriteLine("**分類は測る前に固定した**（`spend map`）。**実測を見てから書き換えていない。**");
    Console.WriteLine();
    Console.WriteLine("| 経路 | 決めているもの | 編成が動かせるか | 帰属の平均 | 受け手の種類数 | 最大の受け手 |");
    Console.WriteLine("|---|---|:-:|--:|--:|---|");
    foreach ((WhetRoute r, TraitId _, string __, string ___, string dec, string lev) in spRoutes)
    {
        int i = (int)r;
        var top = spTo[i].OrderByDescending(kv => kv.Value).FirstOrDefault();
        double sum = spTo[i].Values.Sum();
        Console.WriteLine($"| {WhetRoutes.Names[i]} | {dec} | **{lev}** | "
                          + $"{spAttr[r].Average(x => x.D):+0.0;-0.0;0.0} | {spTo[i].Count} | "
                          + (top.Key is null ? "—"
                             : $"{SpLabel(top.Key)} {(sum > 0 ? top.Value * 100.0 / sum : 0):F0}%") + " |");
    }
    Console.WriteLine();
    Console.WriteLine("### Q3 の判定（群ごとの帰属の平均）");
    Console.WriteLine();
    Console.WriteLine("| 群 | 経路 | 帰属の平均（経路の単純平均） |");
    Console.WriteLine("|---|---|--:|");
    foreach (string lev in new[] { "配置", "配置（間接）", "編成", "編成（弱い）", "動かせない" })
    {
        var rs = spRoutes.Where(x => x.Lever == lev).ToArray();
        if (rs.Length == 0) continue;
        Console.WriteLine($"| {lev} | {string.Join(" / ", rs.Select(x => WhetRoutes.Names[(int)x.Route]))} | "
                          + $"**{rs.Average(x => spAttr[x.Route].Average(y => y.D)):+0.0;-0.0;0.0}** |");
    }
    Console.WriteLine();

    // ---- 表D -------------------------------------------------------------
    Console.WriteLine("## 表D. 死蔵（新定義・`AttackReads == 0`）の行ごと分布");
    Console.WriteLine();
    double spHoardAll = spHoard.Values.Sum();
    Console.WriteLine($"死蔵総量 **{spHoardAll / spN:F2}** /戦 ＝ 強化総量の "
                      + $"**{(spTotal > 0 ? spHoardAll * 100.0 / spTotal : 0):F1}%**。");
    Console.WriteLine();
    Console.WriteLine("| 駒 | 死蔵(新)/戦 | 受けた総量/戦 | 死蔵率 | 真の捨て場か |");
    Console.WriteLine("|---|--:|--:|--:|:-:|");
    var spDump = new[] { "nono", "mio", "hiyo" };
    foreach ((string id, double v) in spHoard.OrderByDescending(kv => kv.Value).Take(10))
    {
        double g = spGot.TryGetValue(id, out double gv) ? gv : 0;
        Console.WriteLine($"| {SpLabel(id)} | **{v / spN:F2}** | {g / spN:F2} | "
                          + $"{(g > 0 ? v * 100.0 / g : 0):F1}% | {(spDump.Contains(id) ? "○" : "")} |");
    }
    Console.WriteLine();
    Console.WriteLine("捨て場3枚（ノノ・ミオ・ヒヨ）が受けた量: "
                      + string.Join(" / ", spDump.Select(id =>
                          $"{SpLabel(id)} {(spGot.TryGetValue(id, out double g) ? g / spN : 0):F2}"))
                      + " /戦。");
    Console.WriteLine();
    Console.WriteLine("死蔵が多い行（上位8・量/戦）: "
                      + string.Join(" / ", spRowHoard.OrderByDescending(kv => kv.Value).Take(8)
                          .Select(kv => $"{kv.Key} {kv.Value / (spStages.Count * (double)spSeedN):F2}")));
    Console.WriteLine();

    // ---- 表E -------------------------------------------------------------
    Console.WriteLine("## 表E. 乗算・反撃への流入");
    Console.WriteLine();
    Console.WriteLine("| 駒 | 読み方 | 受けた強化/戦 | 実効 | その駒を含む行 |");
    Console.WriteLine("|---|---|--:|---|--:|");
    var spReaders = new (string Id, string How, string Eff)[]
    {
        ("hota", "熾火（燃焼中は攻撃力4倍＋貫き）", "**×4**（第58期の乗算監査。与ダメの実効は 7.4 倍）"),
        ("kado", "棘（`PerformAttack` を通らず反撃量を `CurrentAttack` で決める）", "×1（反撃・範囲）"),
        ("zan",  "仇討ち（ターン外・`CurrentAttack` をそのまま）", "×1（ターン外）"),
        ("shiga", "責め苦の追撃（自分の手番の中）", "×1（追撃）"),
    };
    foreach ((string id, string how, string eff) in spReaders)
    {
        double g = spGot.TryGetValue(id, out double gv) ? gv : 0;
        int rows = spBuilds.Count(b => b.F.Occupied().Any(o => o.Item2.Id == id));
        Console.WriteLine($"| {SpLabel(id)} | {how} | {g / spN:F2} | {eff} | {rows} |");
    }
    Console.WriteLine();
    Console.WriteLine("乗算持ち（ホタ）を含む行と含まない行の帰属:");
    Console.WriteLine();
    Console.WriteLine("| 経路 | ホタを含む行 | 含まない行 |");
    Console.WriteLine("|---|--:|--:|");
    foreach ((WhetRoute r, TraitId _, string __, string ___, string ____, string _____) in spRoutes)
    {
        var withH = spAttr[r].Where(x => spBuilds.First(b => b.Name == x.Row).F.Occupied()
                                          .Any(o => o.Item2.Id == "hota")).ToArray();
        var noH = spAttr[r].Where(x => !spBuilds.First(b => b.Name == x.Row).F.Occupied()
                                        .Any(o => o.Item2.Id == "hota")).ToArray();
        Console.WriteLine($"| {WhetRoutes.Names[(int)r]} | "
                          + (withH.Length > 0 ? $"{withH.Average(x => x.D):+0.0;-0.0;0.0}（{withH.Length} 行）" : "—")
                          + " | "
                          + (noH.Length > 0 ? $"{noH.Average(x => x.D):+0.0;-0.0;0.0}（{noH.Length} 行）" : "—")
                          + " |");
    }
    Console.WriteLine();

    // ---- 陰性対照 ---------------------------------------------------------
    Console.WriteLine("## Q6. 陰性対照（供給者を含まない行が ±0.0 であること）");
    Console.WriteLine();
    Console.WriteLine("| 経路 | 対照の行数 | 最大 \\|Δ\\| | 0 でない行 |");
    Console.WriteLine("|---|--:|--:|--:|");
    foreach ((WhetRoute r, TraitId need, string _, string __, string ___, string ____) in spRoutes)
    {
        var neg = spBuilds.Where(b => !SpHas(b, need))
                          .Select(b => Math.Abs(Mean(spBase[b.Name]) - Mean(spDrop[(r, b.Name)]))).ToArray();
        Console.WriteLine($"| {WhetRoutes.Names[(int)r]} | {neg.Length} | {neg.Max():F1} | "
                          + $"{neg.Count(x => x > 0.0001)} |");
    }
    Console.WriteLine();

    return;
}

// 燃焼の解剖（第57期）。**この期は新しい機構を1つも作らない。**
// `Traits.cs` の挙動 / `UnitCatalog.All` / `Stages` / `CompareBuilds()` は1行も動かさず、
// 足したのは**誰も読んで分岐しない計数フィールド**（`UnitTally` の Burn* 9本）だけ。
//
// 主題は「燃焼は通貨か、それとも遅いダメージか」。書き手は火の粉（ボルグ）1枚、
// 駒の読み手は熾火（ホタ）1枚で、**両者が同席する行は 56 行中1つしかない。**
//
// 立てた仮説（測って否定してよい）:
//   H1 供給不足 —— 足りないのは2枚目の書き手である
//   H2 供給過剰 —— 非スタックなので再着火は残ターンを 3 に戻すだけ。**着火の大半は捨てられている**
//   H3 接続の不在 —— 「燃えている」という事実を読んで分岐するのはホタ1枚だけ
//
// **対照は同数値・特性だけを落とした素体**（`UnitCatalog` には足さない。第49期の `SgPlain` と同型）。
// **`Splash`（巻き込み）は残す**——一緒に落とすと「巻き込みが消えたから勝った」と混ざる
// （第34期の「HP を振ったつもりが波の総HPも振っていた」と同じ穴）。
//
//     dotnet run --project BattleSim -c Release 0 burn [絞り込み]
//     dotnet run --project BattleSim -c Release 0 burn phase0   # 窓口の一覧と接続の地図（戦闘0回）
if (focusId == "burn")
{
    var buBuilds = CompareBuilds();
    IReadOnlyList<EnemyCatalog.Stage> buStages = EnemyCatalog.Stages;
    const int BuSeeds = 200;   // compare / spread / whet と同じ帯
    string buArg = args.Length > 2 ? args[2] : "";

    // ---- phase0: 窓口の一覧と接続の地図。**戦闘を1回も回さない。** -------------------
