    // (G2) 壊れ / 制約 の分解
    foreach (int p in hdFell.Keys.OrderBy(k => k))
    {
        var rows = hdFell[p].Select(x => x.Item1).Distinct().ToArray();
        if (rows.Length == 0) continue;
        Console.WriteLine($"#### {hdVer[p].Tag} の分解（(G2)：駒が使えなくなる＝壊れ／組み合わせ固有＝制約）");
        Console.WriteLine();
        Console.WriteLine("| 落ちた行 | 駒 | その駒を含む**他の**行の全波平均の変化 | 判定 |");
        Console.WriteLine("|---|---|--:|---|");
        foreach (int b in rows)
        {
            bool broke = false;
            foreach (var o in hdBuilds[b].F.Occupied())
            {
                string id = o.Item2.Id;
                var others = Enumerable.Range(0, hdCompare.Length).Where(x => x != b && HdHas(hdBuilds[x], id)).ToArray();
                if (others.Length == 0)
                {
                    Console.WriteLine($"| {hdBuilds[b].Name} | {HdNm(id)} | （他の行が 0 行） | — |");
                    continue;
                }
                double avg = others.Average(x => HdAvg(p, x) - HdAvg(0, x));
                if (avg <= -3.0) broke = true;
                Console.WriteLine($"| {hdBuilds[b].Name} | {HdNm(id)} | {avg:+0.00;-0.00;0.00}pt（{others.Length} 行） | {(avg <= -3.0 ? "**壊れ**" : "制約")} |");
            }
            Console.WriteLine($"| **{hdBuilds[b].Name} の判定** | | | **{(broke ? "壊れ（拒否）" : "組み合わせ固有＝制約（拒否しない）")}** |");
        }
        Console.WriteLine();
    }

    Console.WriteLine("### 拒否権2 —— 主判定19行の第五波平均");
    Console.WriteLine();
    var hdPrim = Baseline.PrimaryRows.Select(n => Array.FindIndex(hdBuilds, b => b.Name == n)).Where(i => i >= 0).ToArray();
    Console.WriteLine($"（`Baseline.PrimaryRows` {Baseline.PrimaryRows.Length} 行のうち {hdPrim.Length} 行が引けた）");
    Console.WriteLine();
    Console.WriteLine("| 版 | 主判定19行の第五波平均 | 歯止め | 判定 |");
    Console.WriteLine("|---|--:|--:|:-:|");
    for (int p = 0; p < hdVer.Length; p++)
    {
        double f5 = hdPrim.Length == 0 ? 0 : hdPrim.Average(i => hdRate[p][hdStages.Count - 1][i]);
        Console.WriteLine($"| {hdVer[p].Tag} | {f5:0.0}% | {Baseline.PrimaryFifthFloor:0.0} | {(f5 >= Baseline.PrimaryFifthFloor ? "○" : "×")} |");
    }
    Console.WriteLine();
    Console.WriteLine("### 注意（規約 (G9)：拒否ではなく記録）—— 第五波が 95% を超えた行");
    Console.WriteLine();
    for (int p = 1; p < hdVer.Length; p++)
    {
        var added = Enumerable.Range(0, hdCompare.Length)
            .Where(b => hdRate[p][hdStages.Count - 1][b] > 95.0 && hdRate[0][hdStages.Count - 1][b] <= 95.0).ToArray();
        Console.WriteLine($"- **{hdVer[p].Tag}**: {added.Length} 行"
            + (added.Length == 0 ? "" : " — " + string.Join(" / ", added.Select(b => hdBuilds[b].Name))));
    }
    Console.WriteLine();
    Console.WriteLine("### 全体の動き（`compare` 61行 × 第2〜5波 = 244 セル）");
    Console.WriteLine();
    Console.WriteLine("| 版 | 動いたセル | 動いた行 | 平均Δ（61行・第2〜5波） |");
    Console.WriteLine("|---|--:|--:|--:|");
    for (int p = 1; p < hdVer.Length; p++)
    {
        int cells = 0; var rows = new HashSet<int>();
        for (int b = 0; b < hdCompare.Length; b++)
            for (int w = 1; w < hdStages.Count; w++)
                if (Math.Abs(hdRate[p][w][b] - hdRate[0][w][b]) > 1e-9) { cells++; rows.Add(b); }
        double avg = Enumerable.Range(0, hdCompare.Length).Average(b => HdAvg(p, b) - HdAvg(0, b));
        Console.WriteLine($"| {hdVer[p].Tag} | {cells} / {hdCompare.Length * (hdStages.Count - 1)} | {rows.Count} | {avg:+0.00;-0.00;0.00} |");
    }
    Console.WriteLine();
    Console.WriteLine($"（自己検査の詳細は `hold check`。弾きが決着ターンを超えた試行 **{hdShoveOverCap}** 件）");
    Console.WriteLine();
    return;
}



//     dotnet run --project BattleSim -c Release 0 spread
// ==================================================================================
// 第107期 —— 保留を閉じる（席・ムド・ハリ）。指示書は design/PHASE107_HOLD2_SPEC.md。
//
// **既存の診断は1文字も書き換えていない。** (S1)(S2)(S3) をモードで分けてある
// （報告書とコミットも別々にする——`docs/balance.md` の差分がどれの帰結か読めなくなるため）。
// ==================================================================================
// 第108期 —— 尾灯（`TaillightTrait`）の受け入れ確認。**測定ではない。**
//
// 指示書 §4 の「必要なら最小の確認用モードを1つ足す」。**第109期の `tomo`（測定）とは別物**で、
// ここがやるのは自己検査 (a)〜(g) だけ——トモは `Presets.Compare` にも `Presets.Cross` にも
// 入っていない（受け入れ 3）ので、**盤面に出す唯一の場所がこの診断のローカル台になる**。
//
// 台は診断のローカルに組む（`gradient` / `aim` / `route` / `sever` と同じ扱い）。
// **`Presets` も `UnitCatalog.All` も1行も読み替えない。**
//
// **ログの文字列を数えている。** UI は `LogKind` を見るという規約に反して見えるが、
// 確かめたいのは「灯がどの駒に何点載っているか」の推移そのもので、
// **消えたことは盤面の値に痕跡を残さない**（`gullet log` / `yoke log` / `sever` と同じ理由）。
//
//     dotnet run --project BattleSim -c Release 0 taillight
// ==================================================================================
if (focusId == "taillight")
{
    const int TlSeeds = 40;
    IReadOnlyList<EnemyCatalog.Stage> tlStages = EnemyCatalog.Stages;

    static Formation TlF(params UnitDef[] m)
    {
        var f = new Formation();
        for (int i = 0; i < m.Length; i++) f[i] = m[i];
        return f;
    }

    // 台。**速さの並びを手で決めてある**——「自分を除いて最も遅い味方」の答えが台ごとに一意に決まる。
    var tlBenches = new (string Name, Formation F, string Expect)[]
    {
        // 速さ: ゴルム3 < ドルガ6 < ノミ7 < キリ12。トモ（3）は自分なので対象外。
        ("(b) 一意", TlF(UnitCatalog.Golm, UnitCatalog.Dolga, UnitCatalog.Tomo, UnitCatalog.Nomi, UnitCatalog.Kiri),
            UnitCatalog.Golm.Name),
        // 速さ: バン2 = セッキ2 < ドルガ6 < ノミ7。**同速は席番号の昇順**なので前1のバン。
        ("(b) 同速→席番号", TlF(UnitCatalog.Ban, UnitCatalog.Sekki, UnitCatalog.Tomo, UnitCatalog.Dolga, UnitCatalog.Nomi),
            UnitCatalog.Ban.Name),
        // 速さ: ガルド4 < ザン5 < ノミ7 < キリ12。**ガルドは支援拒否**なので飛ばしてザンへ。
        ("(b) 支援拒否を飛ばす", TlF(UnitCatalog.Gald, UnitCatalog.Zan, UnitCatalog.Tomo, UnitCatalog.Nomi, UnitCatalog.Kiri),
            UnitCatalog.Zan.Name),
        // トモ2枚。**互いに譲り合っても無限に往復しない**ことの確認（1ホップ）。
        ("(f) トモ2枚", TlF(UnitCatalog.Tomo, UnitCatalog.Tomo, UnitCatalog.Golm, UnitCatalog.Dolga, UnitCatalog.Nomi),
            UnitCatalog.Golm.Name),
    };

    Console.WriteLine("# 第108期 —— 尾灯（`TaillightTrait`）の受け入れ確認");
    Console.WriteLine();
    Console.WriteLine("**測定ではない**（第109期に `tomo` を作る）。トモは `Presets.Compare` にも "
        + "`Presets.Cross` にも入っていないので、盤面に出す唯一の場所がこの診断のローカル台。");
    Console.WriteLine();
    Console.WriteLine("台は 5波 × seed 0.." + (TlSeeds - 1) + "。灯 = " + TaillightTrait.Lumen + "。");
    Console.WriteLine();

    // ------------------------------------------------------------------------------
    // ログを再生して「いま誰に何点の灯が載っているか」を追う。
    // 灯る:  「… が ○○ に灯をともした（攻撃 +5 → n）」
    // 消える:「○○ の灯が消えた（攻撃 -m）」
    // 譲る:  「… は前へ出ず、灯した ○○ に道を譲る」
    // ------------------------------------------------------------------------------
    var tlRows = new List<(string Bench, int Wave, int Seed, int Turns,
                           int Lit, int Doused, int Switches, int Yields, int Hop,
                           int MaxLampsAtOnce, int BadTarget, int BadDouse, int BadYieldPerTurn,
                           int Fires, int Idle, int NoDeath, int NoTarget, int NetLeft)>();

    foreach (var (name, form, expect) in tlBenches)
        for (int w = 0; w < tlStages.Count; w++)
            for (int seed = 0; seed < TlSeeds; seed++)
            {
                BattleResult r = BattleEngine.Run(form, tlStages[w].Enemy, seed, verbose: true);

                // **判定は「トモ1枚あたり1ターン1回」**。トモが2枚の台では 2 回が正しい
                // （それぞれが自分の手番で1回ずつ譲る。1ホップが止めるのは<b>入れ子</b>のほう）。
                int tomoCount = form.Occupied().Count(o => ReferenceEquals(o.Def, UnitCatalog.Tomo));

                var lamp = new Dictionary<string, int>();   // 駒名 → いま載っている灯
                int maxAtOnce = 0, badTarget = 0, badDouse = 0, badYield = 0;
                int lit = 0, doused = 0, turn = 0, yieldsThisTurn = 0, badYieldTurns = 0;

                foreach (LogLine line in r.Log)
                {
                    string t = line.Text;
                    if (line.Kind == LogKind.Turn)
                    {
                        if (yieldsThisTurn > tomoCount) badYieldTurns++;
                        yieldsThisTurn = 0;
                        turn++;
                        continue;
                    }

                    int a = t.IndexOf(" に灯をともした", StringComparison.Ordinal);
                    if (a >= 0)
                    {
                        int b = t.IndexOf(" が ", StringComparison.Ordinal);
                        string who = t.Substring(b + 3, a - b - 3);
                        // (b) 台ごとに答えは一意。**まだ誰も倒れていないあいだだけ**判定する
                        //     （味方が倒れると「最も遅い生存味方」が変わるのは仕様どおりなので）。
                        if (lamp.Count == 0 && lit == 0 && who != expect) badTarget++;
                        lamp[who] = lamp.TryGetValue(who, out int had) ? had + TaillightTrait.Lumen
                                                                      : TaillightTrait.Lumen;
                        lit += TaillightTrait.Lumen;
                        maxAtOnce = Math.Max(maxAtOnce, lamp.Count(kv => kv.Value > 0));
                        continue;
                    }

                    int c = t.IndexOf(" の灯が消えた（攻撃 -", StringComparison.Ordinal);
                    if (c >= 0)
                    {
                        // **`ctx.Log` は先頭の空白を落として `LogLine.Indent` に分けて持つ**
                        // （BattleEngine.Log）ので、駒名は行頭から始まる。
                        string who = t.Substring(0, c);
                        int amt = int.Parse(new string(t.Substring(c).Where(char.IsAsciiDigit).ToArray()));
                        // (c) 消える量は、その駒に載っていた累計とちょうど同じ
                        if (!lamp.TryGetValue(who, out int had2) || had2 != amt) badDouse++;
                        lamp[who] = 0;
                        doused += amt;
                        continue;
                    }

                    if (t.Contains("は前へ出ず、灯した", StringComparison.Ordinal)) yieldsThisTurn++;
                }
                if (yieldsThisTurn > tomoCount) badYieldTurns++;
                badYield = badYieldTurns;

                int sw = 0, yl = 0, hop = 0, fires = 0, idle = 0, nod = 0, not_ = 0;
                foreach (var kv in r.TallyByUnit)
                {
                    sw += kv.Value.TaillightSwitches; yl += kv.Value.TaillightYields;
                    hop += kv.Value.TaillightBlockedHop; fires += kv.Value.TaillightFires;
                    idle += kv.Value.TaillightIdle; nod += kv.Value.TaillightNoDeath;
                    not_ += kv.Value.TaillightNoTarget;
                }

                tlRows.Add((name, w + 1, seed, r.Turns, lit, doused, sw, yl, hop,
                            maxAtOnce, badTarget, badDouse, badYield, fires, idle, nod, not_,
                            lamp.Values.Sum()));
            }

    Console.WriteLine("## 表A —— 台ごとの集計（1戦あたり）");
    Console.WriteLine();
    Console.WriteLine("| 台 | 戦 | 決着T | 灯/戦 | 消/戦 | 替/戦 | 譲/戦 | 空振り/戦 | 敵未撃破の手番/戦 | 同時に灯る最大 | 1ホップ | 消の照合ずれ | 収支ずれ |");
    Console.WriteLine("|---|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|");
    foreach (var g in tlRows.GroupBy(x => x.Bench))
    {
        double n = g.Count();
        Console.WriteLine($"| {g.Key} | {n:F0} | {g.Average(x => x.Turns):F1} | {g.Sum(x => x.Lit) / n:F1} "
            + $"| {g.Sum(x => x.Doused) / n:F1} | {g.Sum(x => x.Switches) / n:F2} | {g.Sum(x => x.Yields) / n:F2} "
            + $"| {g.Sum(x => x.Idle) / n:F2} | {g.Sum(x => x.NoDeath) / n:F2} "
            + $"| **{g.Max(x => x.MaxLampsAtOnce)}** | {g.Sum(x => x.Hop)} "
            + $"| {g.Sum(x => x.BadDouse)} | {g.Count(x => x.Lit - x.Doused != x.NetLeft)} |");
    }
    Console.WriteLine();

    // ------------------------------------------------------------------------------
    // 自己検査
    // ------------------------------------------------------------------------------
    var tlChecks = new List<(string Tag, string What, string Got, bool Ok)>();

    // (a) ハリと縫いの実装が残っている
    bool hariAlive = UnitCatalog.Hari.Id == "hari"
                     && UnitCatalog.Hari.Traits.Contains(TraitId.Suture)
                     && TraitCatalog.Get(TraitId.Suture) is SutureTrait;
    string hariWhere = UnitCatalog.All.Any(u => ReferenceEquals(u, UnitCatalog.Hari)) ? "`All` に居る" : "`All` から外れている";
    tlChecks.Add(("(a)", "`UnitCatalog.Hari` と `SutureTrait` / `SutureRule` / `SutureFireRule` が残置されている",
        $"{UnitCatalog.Hari.Name}（{hariWhere}）・既定 {SutureRule.Default} / {SutureFireRule.Default}", hariAlive));

    // (b) 対象は自分を除く最も遅い味方（同速は席番号昇順・支援拒否は飛ばす）
    foreach (var g in tlRows.GroupBy(x => x.Bench).Where(g => g.Key.StartsWith("(b)", StringComparison.Ordinal)))
        tlChecks.Add(("(b)", g.Key + " の初灯が期待どおり",
            "ずれ " + g.Sum(x => x.BadTarget) + " 件 / 灯 " + g.Sum(x => x.Fires) + " 回",
            g.Sum(x => x.BadTarget) == 0));

    // (c)(c') は**トモ1枚の台でだけ判定する**。
    // この照合は駒名をキーにした帳簿なので、**同名のトモが2枚いると2つの灯を分離できない**
    // ——2枚とも同じ「最も遅い味方」を照らすと lamp[その味方] に両方の灯が混ざり、
    // 片方が消したときの量（自分のぶんだけ）と食い違う。**器具の限界であって盤面の不整合ではない**
    // （下の表A で (f) の台にだけ ずれが出ていることがその証拠）。
    var tlSolo = tlRows.Where(x => !x.Bench.StartsWith("(f)", StringComparison.Ordinal)).ToList();

    // (c) 消える量は、その駒に載っていた累計とちょうど同じ
    tlChecks.Add(("(c)", "対象が変わったとき、前の灯が**ちょうど載っていた量だけ**消える（トモ1枚の台）",
        "ずれ " + tlSolo.Sum(x => x.BadDouse) + " 件 / 消灯 " + tlSolo.Count(x => x.Doused > 0) + " 戦"
        + "（トモ2枚の台は同名で分離できないので除外。ずれ " + tlRows.Sum(x => x.BadDouse) + " 件）",
        tlSolo.Sum(x => x.BadDouse) == 0));

    // (c') 収支: 載った総量 − 消した総量 = 戦闘終了時に残っている灯
    int tlBadNet = tlSolo.Count(x => x.Lit - x.Doused != x.NetLeft);
    tlChecks.Add(("(c')", "灯った総量 − 消した総量 ＝ 終了時に残っている灯（収支が閉じる・トモ1枚の台）",
        "ずれ " + tlBadNet + " 戦 / " + tlSolo.Count + " 戦", tlBadNet == 0));

    // (d) 灯は1体にしか灯らない
    // **トモ1枚につき灯は1つ**。2枚の台で 2 体に灯るのは規則どおり（それぞれが1体を照らす）。
    int tlMax1 = tlRows.Where(x => !x.Bench.StartsWith("(f)", StringComparison.Ordinal))
                       .Max(x => x.MaxLampsAtOnce);
    int tlMax2 = tlRows.Where(x => x.Bench.StartsWith("(f)", StringComparison.Ordinal))
                       .Max(x => x.MaxLampsAtOnce);
    tlChecks.Add(("(d)", "同時に灯が載っている駒が**トモの枚数まで**（1枚の台で 1 体・2枚の台で 2 体）",
        "1枚の台 最大 " + tlMax1 + " 体 / 2枚の台 最大 " + tlMax2 + " 体（全 " + tlRows.Count + " 戦）",
        tlMax1 <= 1 && tlMax2 <= 2));

    // (e) 手番の譲渡は1ターン1回以下
    tlChecks.Add(("(e)", "手番の譲渡が**トモ1枚あたり1ターン1回以下**",
        "違反 " + tlRows.Sum(x => x.BadYieldPerTurn) + " ターン / 譲渡 " + tlRows.Sum(x => x.Yields) + " 回",
        tlRows.Sum(x => x.BadYieldPerTurn) == 0));

    // (f) 1ホップ（トモ2枚でも往復しない）
    var tlTwo = tlRows.Where(x => x.Bench.StartsWith("(f)", StringComparison.Ordinal)).ToList();
    tlChecks.Add(("(f)", "トモ2枚の台が**全戦とも完走する**（無限に譲り合わない）",
        tlTwo.Count + " 戦とも決着（平均 " + (tlTwo.Count > 0 ? tlTwo.Average(x => x.Turns) : 0).ToString("F1")
        + "T）・1ホップで止めた回数 " + tlTwo.Sum(x => x.Hop), tlTwo.Count > 0 && tlTwo.All(x => x.Turns > 0)));

    // (g) ctx.PickOne を新たに使っていない（第89期 (h)。候補2個以上で Roll を消費する）
    static int TlCount(string hay, string needle)
    {
        int n = 0;
        for (int i = hay.IndexOf(needle, StringComparison.Ordinal); i >= 0;
             i = hay.IndexOf(needle, i + 1, StringComparison.Ordinal)) n++;
        return n;
    }
    string? tlRoot = Directory.GetCurrentDirectory();
    while (tlRoot is not null && !File.Exists(Path.Combine(tlRoot, "CLAUDE.md")))
        tlRoot = Directory.GetParent(tlRoot)?.FullName;
    int tlPick = 0, tlPickInTrait = 0;
    if (tlRoot is not null)
    {
        foreach (string f in new[] { Path.Combine(tlRoot, "BattleCore", "Traits.cs"),
                                     Path.Combine(tlRoot, "BattleCore", "BattleEngine.cs") })
            if (File.Exists(f))
                tlPick += TlCount(File.ReadAllText(f), "PickOne(");

        string tf = Path.Combine(tlRoot, "BattleCore", "Traits.cs");
        if (File.Exists(tf))
        {
            string src = File.ReadAllText(tf);
            int i = src.IndexOf("public sealed class TaillightTrait", StringComparison.Ordinal);
            if (i >= 0)
            {
                int j = src.IndexOf("public sealed class", i + 20, StringComparison.Ordinal);
                if (j < 0) j = src.IndexOf("public readonly record struct", i, StringComparison.Ordinal);
                if (j < 0) j = src.Length;
                tlPickInTrait = TlCount(src.Substring(i, j - i), "PickOne(");
            }
        }
    }
    tlChecks.Add(("(g)", "`PickOne(` の素の出現数が **26** のまま（第94期以降不変）で、"
        + "**`TaillightTrait` の中は 0**",
        tlPick + " 箇所（うち `TaillightTrait` の中 " + tlPickInTrait + "）",
        tlPick == 26 && tlPickInTrait == 0));

    Console.WriteLine("## 表B —— 自己検査");
    Console.WriteLine();
    Console.WriteLine("| | 内容 | 実測 | 判定 |");
    Console.WriteLine("|---|---|---|:-:|");
    foreach (var (tag, what, got, ok) in tlChecks)
        Console.WriteLine($"| **{tag}** | {what} | {got} | {(ok ? "○" : "**×**")} |");
    Console.WriteLine();
    Console.WriteLine($"**{tlChecks.Count(x => x.Ok)} / {tlChecks.Count} 件が ○。**");
    Console.WriteLine();

    // ------------------------------------------------------------------------------
    // 1戦の監査（読んで確かめるための生ログ）
    // ------------------------------------------------------------------------------
    // 灯が**移る**戦を選ぶ（対象の死 → 消灯 → 次へ、が1本の中で読める戦）。
    var tlPick2 = tlRows.Where(x => x.Bench == "(b) 一意" && x.Switches > 0 && x.Yields > 0)
                        .OrderBy(x => x.Wave).ThenBy(x => x.Seed).FirstOrDefault();
    Console.WriteLine("## 表C —— 1戦の監査（`(b) 一意`・第" + Math.Max(1, tlPick2.Wave) + "波・seed " + tlPick2.Seed + "）");
    Console.WriteLine();
    Console.WriteLine("**灯が移る戦**（対象が倒れる → 消灯 → 次に遅い味方へ）を選んである。");
    Console.WriteLine();
    Console.WriteLine("```");
    BattleResult tlAudit = BattleEngine.Run(tlBenches[0].F,
        tlStages[Math.Max(0, tlPick2.Wave - 1)].Enemy, tlPick2.Seed, verbose: true);
    foreach (LogLine line in tlAudit.Log)
        if (line.Kind == LogKind.Turn || line.Text.Contains("灯", StringComparison.Ordinal)
            || line.Text.Contains("道を譲る", StringComparison.Ordinal)
            || line.Text.Contains("倒れた", StringComparison.Ordinal))
            Console.WriteLine(line.Text);
    Console.WriteLine("```");
    Console.WriteLine();
    return;
}

if (focusId == "tomo" && args.Length > 2 && args[2] == "yield") { TomoDiag.Yield(args, stageIndex); return; }

if (focusId == "tomo") { TomoDiag.Run(args, stageIndex); return; }

// ==================================================================================
if (focusId == "hold2")
{
    string h2Mode = args.Length > 2 ? args[2] : "tables";
    var h2Compare = CompareBuilds();
    var h2Cross = CrossBuilds();
    var h2All = h2Compare.Concat(h2Cross).ToArray();
    IReadOnlyList<EnemyCatalog.Stage> h2Stages = EnemyCatalog.Stages;

    // `reseat` の狙（ガルドが前列 / セッキが後列）の写し。**判定は1文字も変えていない。**
    static bool H2Intent(Formation f)
    {
        foreach (var (slot, def) in f.Occupied())
        {
            if (ReferenceEquals(def, UnitCatalog.Gald) && FormationRules.RowOf(slot) != Row.Front) return false;
            if (ReferenceEquals(def, UnitCatalog.Sekki) && FormationRules.RowOf(slot) != Row.Back) return false;
        }
        return true;
    }
    static string H2N(UnitDef? d) => d?.Name ?? "−";
    static string H2Seats(Formation f) => H2N(f[0]) + "/" + H2N(f[1]) + " | " + H2N(f[2]) + " | " + H2N(f[3]) + "/" + H2N(f[4]);

    // 情報セル: `0 < x < 100` を**第2〜5波**で数える（第59期 9-1 の定義。規約 (G10)）。
    static int H2Info(double[] cells)
    {
        int n = 0;
        for (int i = 1; i < cells.Length; i++) if (cells[i] > 0.0 && cells[i] < 100.0) n++;
        return n;
    }

    // ------------------------------------------------------------------------------
    // (S1) 席。**`confirm` の候補表は使わない**——あれは焼き付けた台帳で、採用済みの行も
    // 残っている（第89期の訂正）。**生きた判定は `reseat` の器具をその場で回して取る。**
    // ------------------------------------------------------------------------------
    if (h2Mode == "seats")
    {
        const int H2Scan = 50;       // 粗探索。`reseat` / `layout` と揃える
        const int H2Verify = 200;    // 作法1・2 の帯（seed 0..199）。`compare` と揃える
        const int H2CfBase = 200;    // 追試の帯（seed 200..599）。**選定に使っていない seed**
        const int H2CfSeeds = 400;
        const int H2TopOverall = 20, H2TopConstrained = 10;
        const double H2Line = 5.0;   // 第46期の採否閾値

        Console.WriteLine("# 第107期 (S1) —— 席");
        Console.WriteLine();
        Console.WriteLine("作法（第46期）: (1) 現行が `reseat` の上位5通りに入っていれば動かさない ／ "
            + "(2) 入っていない行だけ追試（seed " + H2CfBase + ".." + (H2CfBase + H2CfSeeds - 1) + "）で測り、**"
            + H2Line.ToString("F1") + "pt 以上**のときだけ動かす ／ (3) 採否は1位の配置ではなく**次数**で読む。");
        Console.WriteLine();
        Console.WriteLine("粗探索は seed 0.." + (H2Scan - 1) + "、作法1・2 の帯は seed 0.." + (H2Verify - 1) + "。"
            + "**候補は「平均1位」ではなく、情報セル（`0 < x < 100`・第2〜5波）を 2 以上に保つ最上位を採る**（第59期）。");
        Console.WriteLine();

        var h2Stay1 = new List<string>();
        var h2Stay2 = new List<(string Name, int Rank, double Cur, double Top)>();
        var h2Cand = new List<(string Name, int Rank, double Cur, double Top)>();
        var h2Detail = new List<string>();

        foreach (var build in h2Compare)
        {
            var members = build.F.Occupied().Select(x => x.Def).ToList();
            var perms = new List<Formation>();
            foreach (int[] assign in SlotAssignments(members.Count))
            {
                var f = new Formation();
                for (int m = 0; m < members.Count; m++) f[assign[m]] = members[m];
                perms.Add(f);
            }

            var scan = new int[perms.Count];
            Parallel.For(0, perms.Count, i =>
            {
                int wins = 0;
                foreach (EnemyCatalog.Stage st in h2Stages)
                    for (int seed = 0; seed < H2Scan; seed++)
                        if (BattleEngine.Run(perms[i], st.Enemy, seed, verbose: false).PlayerWon) wins++;
                scan[i] = wins;
            });

            var order = Enumerable.Range(0, perms.Count).OrderByDescending(i => scan[i]).ThenBy(i => i).ToList();
            var pool = order.Take(H2TopOverall)
                .Concat(order.Where(i => H2Intent(perms[i])).Take(H2TopConstrained))
                .Append(order.First(i => SameFormation(perms[i], build.F)))
                .Distinct().ToList();

            var cellsA = new double[pool.Count][];
            Parallel.For(0, pool.Count, k =>
            {
                cellsA[k] = h2Stages.Select(st =>
                {
                    int wins = 0;
                    for (int seed = 0; seed < H2Verify; seed++)
                        if (BattleEngine.Run(perms[pool[k]], st.Enemy, seed, verbose: false).PlayerWon) wins++;
                    return wins * 100.0 / H2Verify;
                }).ToArray();
            });

            var rankedA = Enumerable.Range(0, pool.Count).OrderByDescending(k => cellsA[k].Average()).ToList();
            int curK = pool.FindIndex(i => SameFormation(perms[i], build.F));
            int curRank = rankedA.IndexOf(curK) + 1;
            double curAvg = cellsA[curK].Average(), topAvg = cellsA[rankedA[0]].Average();

            if (curRank <= 5) { h2Stay1.Add(build.Name); continue; }
            if (topAvg - curAvg < H2Line) { h2Stay2.Add((build.Name, curRank, curAvg, topAvg)); continue; }
            h2Cand.Add((build.Name, curRank, curAvg, topAvg));

            // ---- 追試（seed 200..599）。**情報セルの列を出す**（第59期の作法）
            var cellsB = new double[pool.Count][];
            Parallel.For(0, pool.Count, k =>
            {
                cellsB[k] = h2Stages.Select(st =>
                {
                    int wins = 0;
                    for (int seed = H2CfBase; seed < H2CfBase + H2CfSeeds; seed++)
                        if (BattleEngine.Run(perms[pool[k]], st.Enemy, seed, verbose: false).PlayerWon) wins++;
                    return wins * 100.0 / H2CfSeeds;
                }).ToArray();
            });
            var rankedB = Enumerable.Range(0, pool.Count).OrderByDescending(k => cellsB[k].Average()).ToList();
            double curB = cellsB[curK].Average();
            int curInfoB = H2Info(cellsB[curK]);

            var sb = new System.Text.StringBuilder();
            sb.AppendLine();
            sb.AppendLine("### " + build.Name);
            sb.AppendLine();
            sb.AppendLine("作法1 で現行 **" + curRank + " 位**（" + curAvg.ToString("F1") + "% 対 1位 "
                + topAvg.ToString("F1") + "%・差 **" + (topAvg - curAvg).ToString("+0.0;-0.0") + "pt**）なので追試へ。");
            sb.AppendLine();
            sb.AppendLine("| 追順 | 粗順 | 狙 | 前1/前3 | 中央 | 後1/後3 | 平均(400) | 情報セル |"
                + string.Concat(h2Stages.Select((_, i) => " 第" + (i + 1) + "波 |")));
            sb.AppendLine("|--:|--:|:-:|---|---|---|--:|--:|" + string.Concat(h2Stages.Select(_ => "---:|")));
            for (int r = 0; r < Math.Min(10, rankedB.Count); r++)
            {
                int k = rankedB[r];
                Formation f = perms[pool[k]];
                sb.AppendLine("| " + (r + 1) + (k == curK ? "★現行" : "") + " | " + (order.IndexOf(pool[k]) + 1)
                    + " | " + (H2Intent(f) ? "○" : "×") + " | " + H2Seats(f) + " | "
                    + cellsB[k].Average().ToString("F1") + "% | " + H2Info(cellsB[k]) + " |"
                    + string.Concat(cellsB[k].Select(c => " " + c.ToString("F1") + "% |")));
            }
            if (rankedB.IndexOf(curK) >= 10)
                sb.AppendLine("| " + (rankedB.IndexOf(curK) + 1) + "★現行 | " + (order.IndexOf(pool[curK]) + 1)
                    + " | " + (H2Intent(perms[pool[curK]]) ? "○" : "×") + " | " + H2Seats(perms[pool[curK]]) + " | "
                    + curB.ToString("F1") + "% | " + curInfoB + " |"
                    + string.Concat(cellsB[curK].Select(c => " " + c.ToString("F1") + "% |")));

            // 採る席は**3つの条件の積**。無ければ据え置き。
            //   (a) 情報セルを 2 以上に保つ（第59期。席は「勝つ席」ではなく「測れる席」で選ぶ）
            //   (b) **狙（ガルドが前列 / セッキが後列）を満たす**
            //       ——「編成の狙いと探索1位が食い違ったら狙いを優先し、理由をコメントに残す」（CONTRIBUTING.md）。
            //       第107期の初版はこれを器具に入れ忘れていて、`置き去り×分散回復` の1位（ガルドが中央）を
            //       採るところだった。**参考として狙を外した最上位も並べる**（緩めた版ではなく、外した版が
            //       どれだけ上にあるかを読めるようにするため）。
            //   (c) 現行との差が閾値以上（第46期）
            int pick = -1, free = -1;
            foreach (int k in rankedB) { if (free < 0 && H2Info(cellsB[k]) >= 2) free = k; }
            foreach (int k in rankedB) { if (H2Info(cellsB[k]) >= 2 && H2Intent(perms[pool[k]])) { pick = k; break; } }
            sb.AppendLine();
            if (free >= 0 && free != pick)
                sb.AppendLine("（参考）**狙を外した**最上位は 追順 **" + (rankedB.IndexOf(free) + 1) + " 位**（"
                    + cellsB[free].Average().ToString("F1") + "% / 情報セル " + H2Info(cellsB[free]) + "）。**採らない。**");
            if (pick < 0 || pick == curK)
                sb.AppendLine("**判定: 据え置き** —— 狙を満たし情報セルを 2 以上に保つ最上位が現行（または該当なし）。");
            else
            {
                double gain = cellsB[pick].Average() - curB;
                Formation f = perms[pool[pick]];
                sb.AppendLine("狙を満たし情報セルを 2 以上に保つ最上位は 追順 **" + (rankedB.IndexOf(pick) + 1) + " 位**（"
                    + cellsB[pick].Average().ToString("F1") + "% / 情報セル " + H2Info(cellsB[pick])
                    + "）で、現行（" + curB.ToString("F1") + "% / 情報セル " + curInfoB + "）との差は **"
                    + gain.ToString("+0.0;-0.0") + "pt**。");
                sb.AppendLine("次数: 中央（次数4）が **" + H2N(perms[pool[curK]][2]) + " → " + H2N(f[2]) + "**。");
                sb.AppendLine("**判定: " + (gain >= H2Line ? "差し替え" : "据え置き") + "** —— 閾値 "
                    + H2Line.ToString("F1") + "pt に対して " + gain.ToString("+0.0;-0.0") + "pt。");
                if (gain >= H2Line)
                    sb.AppendLine("採る配置: `front1: " + H2N(f[0]) + ", front3: " + H2N(f[1]) + ", center: " + H2N(f[2])
                        + ", back1: " + H2N(f[3]) + ", back3: " + H2N(f[4]) + "`");
            }
            h2Detail.Add(sb.ToString());
            Console.Error.WriteLine("[hold2 seats] " + build.Name + " 追試おわり");
        }

        Console.WriteLine("## 表A-1 —— 61 行の内訳");
        Console.WriteLine();
        Console.WriteLine("| 段 | 行数 |");
        Console.WriteLine("|---|--:|");
        Console.WriteLine("| 作法1（現行が上位5通り）で終わり | " + h2Stay1.Count + " |");
        Console.WriteLine("| 作法2（差が " + H2Line.ToString("F1") + "pt 未満）で終わり | " + h2Stay2.Count + " |");
        Console.WriteLine("| **追試にかかる** | **" + h2Cand.Count + "** |");
        Console.WriteLine();
        Console.WriteLine("### 作法2 で止まった行");
        Console.WriteLine();
        Console.WriteLine("| 行 | 現行の順位 | 現行(200) | 1位(200) | 差 |");
        Console.WriteLine("|---|--:|--:|--:|--:|");
        foreach (var h2s in h2Stay2.OrderByDescending(h2s => h2s.Top - h2s.Cur))
            Console.WriteLine("| " + h2s.Name + " | " + h2s.Rank + " | " + h2s.Cur.ToString("F1") + "% | "
                + h2s.Top.ToString("F1") + "% | " + (h2s.Top - h2s.Cur).ToString("+0.0;-0.0") + "pt |");
        Console.WriteLine();
        Console.WriteLine("## 表A-2 —— 追試（seed 200..599）");
        foreach (string d in h2Detail) Console.Write(d);
        return;
    }
    // ------------------------------------------------------------------------------
    // (S2) ムドの再判定。**seed 帯を第106期（0..199）から変えてある**——
    // 第106期が `Gain = 5` を対照として同じ帯で測っているので、そのまま比べると循環する
    // （第89期 (P1) と同じ作法）。**較正 `+5` は測る前に固定した値**で、
    // 33 ÷ 7.21 = 4.58 → 丸めて 5（指示書 §2-1）。結果を見てから選んだ値ではない。
    // ------------------------------------------------------------------------------
    if (h2Mode == "rage")
    {
        const int R2Base = 200, R2Seeds = 400;
        var r2Ver = new (string Tag, string Desc, RageRule R)[]
        {
            ("R0", "現行（量で育つ・`max(1, dmg / 2)`）", RageRule.Default),
            ("R1", "回数で育つ（`Gain = " + RageRule.MeasuredGain + "`）", new RageRule(RageMode.Count, RageRule.MeasuredGain)),
        };

        // 憤怒の保持者は**2枚**（`TraitId.Rage` の grep 全数）。ムドだけを見ると
        // 後備えの行の変化を取り落とす（第106期の予測1の穴）。
        string[] r2Holders = { "mudo", "sekki" };

        int r2W = h2Stages.Count, r2B = h2All.Length;
        var r2Rate = new double[r2Ver.Length][][];
        var r2Tally = new Dictionary<string, long[]>[r2Ver.Length];
        const int R2N = 12;
        const int R2Battles = 0, R2Fires = 1, R2Gain = 2, R2Peak = 3, R2PeakT = 4,
                  R2Reach = 5, R2ReachT = 6, R2Turns = 7, R2Dmg = 8, R2Live = 9;
        // R2Reach / R2ReachT は `AtkProbes` の最後（+24）だけを見る。

        for (int p = 0; p < r2Ver.Length; p++)
        {
            r2Rate[p] = new double[r2W][];
            for (int w = 0; w < r2W; w++) r2Rate[p][w] = new double[r2B];
            var acc = r2Tally[p] = new Dictionary<string, long[]>();
            foreach (string id in r2Holders) acc[id] = new long[R2N];

            for (int w = 0; w < r2W; w++)
            {
                var enemy = h2Stages[w].Enemy;
                for (int b = 0; b < r2B; b++)
                {
                    var f = h2All[b].F;
                    bool has = f.Occupied().Any(o => r2Holders.Contains(o.Def.Id));
                    int wins = 0;
                    int pp = p, ww = w;
                    var winsArr = new int[R2Seeds];
                    var locArr = new long[R2Seeds][];
                    Parallel.For(0, R2Seeds, s =>
                    {
                        var v = new long[R2N * 2];
                        var r = BattleEngine.Run(f, enemy, R2Base + s, verbose: false, rage: r2Ver[pp].R);
                        if (r.PlayerWon) winsArr[s] = 1;
                        // **駒ごとの帳簿の分母は第2〜5波**（規約 (G10)。第一波は教習波なので参考にしか使わない）。
                        if (has && ww > 0)
                            for (int h = 0; h < r2Holders.Length; h++)
                            {
                                if (!f.Occupied().Any(o => o.Def.Id == r2Holders[h])) continue;
                                int o0 = h * R2N;
                                v[o0 + R2Battles] = 1;
                                v[o0 + R2Turns] = r.Turns;
                                if (r.TallyByUnit.TryGetValue(r2Holders[h], out UnitTally? t))
                                {
                                    v[o0 + R2Fires] = t.RageCountFires;
                                    v[o0 + R2Gain] = t.RageGain;
                                    v[o0 + R2Peak] = t.AtkPeak;
                                    v[o0 + R2PeakT] = t.AtkPeakTurn;
                                    v[o0 + R2Dmg] = t.DamageToEnemy;
                                    int last = UnitTally.AtkProbes.Length - 1;
                                    if (t.AtkProbeTurn is not null && t.AtkProbeTurn[last] > 0)
                                    { v[o0 + R2Reach] = 1; v[o0 + R2ReachT] = t.AtkProbeTurn[last]; }
                                }
                            }
                        locArr[s] = v;
                    });
                    for (int sq = 0; sq < R2Seeds; sq++)
                    {
                        wins += winsArr[sq];
                        if (!has) continue;
                        for (int h = 0; h < r2Holders.Length; h++)
                        {
                            long[] a = acc[r2Holders[h]];
                            for (int k = 0; k < R2N; k++) a[k] += locArr[sq][h * R2N + k];
                        }
                    }
                    r2Rate[p][w][b] = wins * 100.0 / R2Seeds;
                }
                Console.Error.WriteLine("[hold2 rage] " + r2Ver[p].Tag + " 第" + (w + 1) + "波");
            }
        }

        double R2Avg(int p, int b) { double s = 0; for (int w = 1; w < r2W; w++) s += r2Rate[p][w][b]; return s / (r2W - 1); }
        double R2Per(long[] a, int k) => a[R2Battles] == 0 ? 0 : (double)a[k] / a[R2Battles];

        Console.WriteLine("# 第107期 (S2) —— ムドの再判定（憤怒を回数で育てる）");
        Console.WriteLine();
        Console.WriteLine("台: `compare` 61 行 ＋ 交差帯 12 行 × 全 " + r2W + " 波 × seed "
            + R2Base + ".." + (R2Base + R2Seeds - 1) + " ＝ " + ((long)r2B * r2W * R2Seeds).ToString("N0")
            + " 戦/版。**帯は第106期（0..199）と重ならない。**");
        Console.WriteLine();
        Console.WriteLine("| 版 | 中身 |");
        Console.WriteLine("|---|---|");
        foreach (var v in r2Ver) Console.WriteLine("| " + v.Tag + " | " + v.Desc + " |");

        // ---- 表B-1: Phase 0 の較正の確認
        Console.WriteLine();
        Console.WriteLine("## 表B-1 —— 較正の確認（Phase 0 の 1）");
        Console.WriteLine();
        Console.WriteLine("| 版 | 駒 | 在席戦 | 発火/戦 | 1発あたり | `AtkBonus` 到達点 | 到達T | +24 到達% | +24 到達T | 与ダメ/戦 |");
        Console.WriteLine("|---|---|--:|--:|--:|--:|--:|--:|--:|--:|");
        for (int p = 0; p < r2Ver.Length; p++)
            foreach (string id in r2Holders)
            {
                long[] a = r2Tally[p][id];
                Console.WriteLine("| " + r2Ver[p].Tag + " | " + h2All.SelectMany(x => x.F.Occupied())
                        .Where(o => o.Def.Id == id).Select(o => o.Def.Name).First()
                    + " | " + a[R2Battles] + " | " + R2Per(a, R2Fires).ToString("0.00")
                    + " | " + (a[R2Fires] == 0 ? 0 : (double)a[R2Gain] / a[R2Fires]).ToString("0.00")
                    + " | " + R2Per(a, R2Peak).ToString("0.0")
                    + " | " + R2Per(a, R2PeakT).ToString("0.00")
                    + " | " + (a[R2Battles] == 0 ? 0 : a[R2Reach] * 100.0 / a[R2Battles]).ToString("0.0") + "%"
                    + " | " + (a[R2Reach] == 0 ? 0 : (double)a[R2ReachT] / a[R2Reach]).ToString("0.00")
                    + " | " + R2Per(a, R2Dmg).ToString("0.0") + " |");
            }
        Console.WriteLine();
        {
            long[] m0 = r2Tally[0]["mudo"];
            Console.WriteLine("第96期の被弾 **7.21 回/戦** と第106期の到達点 **33** を再現するか: 発火 **"
                + R2Per(m0, R2Fires).ToString("0.00") + " 回/戦**・到達点 **" + R2Per(m0, R2Peak).ToString("0.0")
                + "**（素の攻 " + UnitCatalog.Mudo.Attack + " と合わせて **攻 "
                + (UnitCatalog.Mudo.Attack + R2Per(m0, R2Peak)).ToString("0.0") + "**）。");
        }

        // ---- 表B-2: Q1（ムド／セッキを含む行）
        Console.WriteLine();
        Console.WriteLine("## 表B-2 —— Q1（保持者を含む行の第2〜5波平均）");
        Console.WriteLine();
        Console.WriteLine("| 行 | 保持者 | R0 | R1 | Δ |");
        Console.WriteLine("|---|---|--:|--:|--:|");
        double q1Sum = 0; int q1N = 0, q1Up = 0;
        double q1SumM = 0; int q1NM = 0;
        for (int b = 0; b < r2B; b++)
        {
            var ids = h2All[b].F.Occupied().Select(o => o.Def.Id).Where(i => r2Holders.Contains(i)).ToList();
            if (ids.Count == 0) continue;
            double a0 = R2Avg(0, b), a1 = R2Avg(1, b);
            q1Sum += a1 - a0; q1N++; if (a1 > a0) q1Up++;
            if (ids.Contains("mudo")) { q1SumM += a1 - a0; q1NM++; }
            Console.WriteLine("| " + h2All[b].Name + " | " + string.Join("・", ids) + " | "
                + a0.ToString("F1") + "% | " + a1.ToString("F1") + "% | "
                + (a1 - a0).ToString("+0.0;-0.0") + "pt |");
        }
        Console.WriteLine();
        Console.WriteLine("**保持者を含む " + q1N + " 行の平均 " + (q1Sum / Math.Max(1, q1N)).ToString("+0.00;-0.00")
            + "pt**（上がった行 " + q1Up + " / " + q1N + "）。うち**ムドの " + q1NM + " 行は "
            + (q1SumM / Math.Max(1, q1NM)).ToString("+0.00;-0.00") + "pt**。");
        {
            long[] m0 = r2Tally[0]["mudo"], m1 = r2Tally[1]["mudo"];
            double p0 = R2Per(m0, R2Peak), p1 = R2Per(m1, R2Peak);
            double t0 = m0[R2Reach] == 0 ? 0 : (double)m0[R2ReachT] / m0[R2Reach];
            double t1 = m1[R2Reach] == 0 ? 0 : (double)m1[R2ReachT] / m1[R2Reach];
            Console.WriteLine();
            Console.WriteLine("| 判定 | 量 | 線 | 結果 |");
            Console.WriteLine("|---|---|---|:-:|");
            Console.WriteLine("| **Q1** | ムドを含む行の第2〜5波平均 " + (q1SumM / Math.Max(1, q1NM)).ToString("+0.00;-0.00")
                + "pt | 現行より上 | " + (q1SumM > 0 ? "**○**" : "**×**") + " |");
            Console.WriteLine("| **Q2** | `AtkBonus` の到達点 " + p0.ToString("0.0") + " → " + p1.ToString("0.0")
                + "（差 " + (p1 - p0).ToString("+0.0;-0.0") + "） | ±3 以内 | "
                + (Math.Abs(p1 - p0) <= 3.0 ? "**○**" : "**×**") + " |");
            Console.WriteLine("| **Q3** | +24 への到達T " + t0.ToString("0.00") + " → " + t1.ToString("0.00")
                + "（到達率 " + (m0[R2Battles] == 0 ? 0 : m0[R2Reach] * 100.0 / m0[R2Battles]).ToString("0.0")
                + "% → " + (m1[R2Battles] == 0 ? 0 : m1[R2Reach] * 100.0 / m1[R2Battles]).ToString("0.0")
                + "%） | 現行より早い | " + (t1 < t0 && t1 > 0 ? "**○**" : "**×**") + " |");
        }

        // ---- 表D: 拒否権（分母は compare 61 行全体・第91期 (G1)）
        Console.WriteLine();
        Console.WriteLine("## 表D —— 拒否権（分母は `compare` 61 行全体・第91期 (G1)）");
        Console.WriteLine();
        Console.WriteLine("| 行 | 波 | R0 | R1 | Δ |");
        Console.WriteLine("|---|--:|--:|--:|--:|");
        int veto3 = 0;
        for (int b = 0; b < h2Compare.Length; b++)
            for (int w = 0; w < r2W; w++)
            {
                double d = r2Rate[1][w][b] - r2Rate[0][w][b];
                if (d <= -10.0)
                {
                    veto3++;
                    Console.WriteLine("| " + h2All[b].Name + " | 第" + (w + 1) + "波 | "
                        + r2Rate[0][w][b].ToString("F1") + "% | " + r2Rate[1][w][b].ToString("F1") + "% | "
                        + d.ToString("+0.0;-0.0") + "pt |");
                }
            }
        if (veto3 == 0) Console.WriteLine("| （該当なし） | | | | |");
        Console.WriteLine();
        var primSet = new HashSet<string>(Baseline.PrimaryRows);
        double f0 = 0, f1 = 0; int fn = 0;
        for (int b = 0; b < h2Compare.Length; b++)
            if (primSet.Contains(h2All[b].Name)) { f0 += r2Rate[0][r2W - 1][b]; f1 += r2Rate[1][r2W - 1][b]; fn++; }
        Console.WriteLine("| 拒否権 | 量 | 線 | 結果 |");
        Console.WriteLine("|---|---|---|:-:|");
        Console.WriteLine("| (1) 主判定" + fn + "行の第五波平均 | " + (f0 / Math.Max(1, fn)).ToString("F1")
            + "% → **" + (f1 / Math.Max(1, fn)).ToString("F1") + "%** | ≥ "
            + Baseline.PrimaryFifthFloor.ToString("F1") + "% | "
            + (f1 / Math.Max(1, fn) >= Baseline.PrimaryFifthFloor ? "**○**" : "**×**") + " |");
        Console.WriteLine("| (3) いずれかの波で −10.0pt 以上落ちた行 | **" + veto3 + " 件** | 0 件 | "
            + (veto3 == 0 ? "**○**" : "**×**") + " |");
        Console.WriteLine();
        Console.WriteLine("## 表E —— 自己検査（(b) 1発あたりの比）");
        Console.WriteLine();
        foreach (string id in r2Holders)
        {
            long[] a = r2Tally[1][id];
            double ratio = a[R2Fires] == 0 ? 0 : (double)a[R2Gain] / a[R2Fires];
            Console.WriteLine("- **(b)** " + id + ": `RageGain ÷ RageCountFires` = **" + ratio.ToString("0.00")
                + "**（`Gain = " + RageRule.MeasuredGain + "` と一致すべき） —— "
                + (Math.Abs(ratio - RageRule.MeasuredGain) < 1e-9 ? "**○**" : "**×**"));
        }
        for (int p = 0; p < r2Ver.Length; p++)
        {
            long f = r2Tally[p]["mudo"][R2Fires], b0 = r2Tally[p]["mudo"][R2Battles];
            Console.WriteLine("- **(b')** " + r2Ver[p].Tag + " のムドの発火 **" + (b0 == 0 ? 0 : (double)f / b0).ToString("0.00")
                + " 回/戦** —— **発火する集合は版に依らない**（計数は式の分岐より手前）。");
        }
        return;
    }
    // ------------------------------------------------------------------------------
    // (S3) ハリ。**発火口を手番の外へ移す**（`SutureFireRule`）。
    // 律速は3期にわたって同じで（第83期の「切れる」判定・第85期の振り 2.15 回/戦・
    // 第106期の再行動 0.00 回/戦）、どれも「手番が来ない」に帰着する。
    // 第105期の「回復の 90.3% は手番の外から出る」を、この駒に当てる。
    // ------------------------------------------------------------------------------
    if (h2Mode == "suture")
    {
        const int S3Base = 0, S3Seeds = 200;
        var s3Ver = new (string Tag, string Desc, SutureFireRule R)[]
        {
            ("W0", "現行（`Swing` ＝ 自分の手番で殴った後）", SutureFireRule.Default),
            ("W1", "`OnWound` ＝ 傷が書かれたとき（1ターン1回）", new SutureFireRule(SutureFire.OnWound)),
        };
        // 糸口（`SutureRule`）と発火口（`SutureFireRule`）が**独立**であることの4通り（自己検査 (d)）。
        var s3Side = new[] { SutureSide.Foe, SutureSide.Both };

        int s3W = h2Stages.Count, s3B = h2All.Length;
        var s3Rate = new double[s3Ver.Length][][];
        const int S3N = 10;
        const int S3Battles = 0, S3Calls = 1, S3Fires = 2, S3Ally = 3, S3Capped = 4,
                  S3Healed = 5, S3Dry = 6, S3Turns = 7, S3Attacks = 8, S3Dmg = 9;
        var s3Acc = new long[s3Ver.Length][];
        long s3OverCap = 0;   // 自己検査 (c): 発火が決着ターン数を超えた戦

        for (int p = 0; p < s3Ver.Length; p++)
        {
            s3Rate[p] = new double[s3W][];
            for (int w = 0; w < s3W; w++) s3Rate[p][w] = new double[s3B];
            var a = s3Acc[p] = new long[S3N];
            for (int w = 0; w < s3W; w++)
                for (int b = 0; b < s3B; b++)
                {
                    var f = h2All[b].F;
                    bool has = f.Occupied().Any(o => o.Def.Id == "hari");
                    int pp = p, ww = w;
                    var winsArr = new int[S3Seeds];
                    var locArr = new long[S3Seeds][];
                    var overArr = new int[S3Seeds];
                    Parallel.For(0, S3Seeds, s =>
                    {
                        var v = new long[S3N];
                        var r = BattleEngine.Run(f, h2Stages[ww].Enemy, S3Base + s, verbose: false,
                                                 sutureFire: s3Ver[pp].R);
                        if (r.PlayerWon) winsArr[s] = 1;
                        // **駒ごとの帳簿の分母は第2〜5波**（規約 (G10)）。
                        if (has && ww > 0)
                        {
                            v[S3Battles] = 1; v[S3Turns] = r.Turns;
                            if (r.TallyByUnit.TryGetValue("hari", out UnitTally? t))
                            {
                                long fires = t.SutureFoe + t.SutureAlly;
                                v[S3Calls] = t.SutureCalls; v[S3Fires] = fires; v[S3Ally] = t.SutureAlly;
                                v[S3Capped] = t.SutureCapped; v[S3Healed] = t.SutureHealed;
                                v[S3Dry] = t.SutureDry; v[S3Attacks] = t.Attacks; v[S3Dmg] = t.DamageToEnemy;
                                if (fires > r.Turns) overArr[s] = 1;
                            }
                        }
                        locArr[s] = v;
                    });
                    int wins = 0;
                    for (int sq = 0; sq < S3Seeds; sq++)
                    {
                        wins += winsArr[sq]; s3OverCap += overArr[sq];
                        for (int k = 0; k < S3N; k++) a[k] += locArr[sq][k];
                    }
                    s3Rate[p][w][b] = wins * 100.0 / S3Seeds;
                }
            Console.Error.WriteLine("[hold2 suture] " + s3Ver[p].Tag + " おわり");
        }

        double S3Avg(int p, int b) { double s = 0; for (int w = 1; w < s3W; w++) s += s3Rate[p][w][b]; return s / (s3W - 1); }
        double S3Per(int p, int k) => s3Acc[p][S3Battles] == 0 ? 0 : (double)s3Acc[p][k] / s3Acc[p][S3Battles];

        Console.WriteLine("# 第107期 (S3) —— ハリ（縫いの発火口を手番の外へ移す）");
        Console.WriteLine();
        Console.WriteLine("台: `compare` 61 行 ＋ 交差帯 12 行 × 全 " + s3W + " 波 × seed "
            + S3Base + ".." + (S3Base + S3Seeds - 1) + " ＝ " + ((long)s3B * s3W * S3Seeds).ToString("N0") + " 戦/版。");
        Console.WriteLine();
        Console.WriteLine("| 版 | 中身 |");
        Console.WriteLine("|---|---|");
        foreach (var v in s3Ver) Console.WriteLine("| " + v.Tag + " | " + v.Desc + " |");

        Console.WriteLine();
        Console.WriteLine("## 表C-1 —— Q4（ハリの発火回数。**律速が外れたかの直接の確認**）");
        Console.WriteLine();
        Console.WriteLine("| 版 | 在席戦 | 決着T | フック/戦 | **発火/戦** | 稼働率 | **敵から** | 味方から | 上限で弾かれ | 空振り | 繕い量/戦 | 振/戦 | 与ダメ/戦 |");
        Console.WriteLine("|---|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|");
        for (int p = 0; p < s3Ver.Length; p++)
            Console.WriteLine("| " + s3Ver[p].Tag + " | " + s3Acc[p][S3Battles]
                + " | " + S3Per(p, S3Turns).ToString("0.00")
                + " | " + S3Per(p, S3Calls).ToString("0.00")
                + " | **" + S3Per(p, S3Fires).ToString("0.00") + "**"
                + " | " + (S3Per(p, S3Turns) == 0 ? 0 : S3Per(p, S3Fires) / S3Per(p, S3Turns)).ToString("0.0%")
                + " | **" + (S3Per(p, S3Fires) - S3Per(p, S3Ally)).ToString("0.00") + "**"
                + " | " + S3Per(p, S3Ally).ToString("0.00")
                + " | " + S3Per(p, S3Capped).ToString("0.00")
                + " | " + (S3Per(p, S3Calls) - S3Per(p, S3Fires) - S3Per(p, S3Capped)).ToString("0.00")
                + " | " + S3Per(p, S3Healed).ToString("0.0")
                + " | " + S3Per(p, S3Attacks).ToString("0.00")
                + " | " + S3Per(p, S3Dmg).ToString("0.0") + " |");
        Console.WriteLine();
        Console.WriteLine();
        Console.WriteLine("**`敵から` が塞ぎ（＝ハリの代金）の宛先**——`MinusText`「繕うたび、糸を通した敵の傷がひとつ塞がる」"
            + "が実際に起きる回数。**`味方から` の側では、同じ塞ぎが味方の傷を消すので利得になる。**");
        Console.WriteLine();
        Console.WriteLine("**Q4**: 発火 " + S3Per(0, S3Fires).ToString("0.00") + " → **"
            + S3Per(1, S3Fires).ToString("0.00") + " 回/戦**（第85期の律速 2.15 回/戦）—— "
            + (S3Per(1, S3Fires) > S3Per(0, S3Fires) ? "**○**" : "**×**"));

        Console.WriteLine();
        Console.WriteLine("## 表C-2 —— Q5（ハリを含む行の第2〜5波平均）");
        Console.WriteLine();
        Console.WriteLine("| 行 | W0 | W1 | Δ |");
        Console.WriteLine("|---|--:|--:|--:|");
        double q5 = 0; int q5n = 0, q5up = 0;
        for (int b = 0; b < s3B; b++)
        {
            if (!h2All[b].F.Occupied().Any(o => o.Def.Id == "hari")) continue;
            double a0 = S3Avg(0, b), a1 = S3Avg(1, b);
            q5 += a1 - a0; q5n++; if (a1 > a0) q5up++;
            Console.WriteLine("| " + h2All[b].Name + " | " + a0.ToString("F1") + "% | " + a1.ToString("F1")
                + "% | " + (a1 - a0).ToString("+0.0;-0.0") + "pt |");
        }
        Console.WriteLine();
        Console.WriteLine("**ハリを含む " + q5n + " 行の平均 " + (q5 / Math.Max(1, q5n)).ToString("+0.00;-0.00")
            + "pt**（上がった行 " + q5up + " / " + q5n + "）。**行名は `Presets.Compare` / `Presets.Cross` から引いた。**");

        // ---- 表D: 拒否権
        Console.WriteLine();
        Console.WriteLine("## 表D —— 拒否権（分母は `compare` 61 行全体・第91期 (G1)）");
        Console.WriteLine();
        Console.WriteLine("| 行 | 波 | W0 | W1 | Δ |");
        Console.WriteLine("|---|--:|--:|--:|--:|");
        int veto = 0;
        for (int b = 0; b < h2Compare.Length; b++)
            for (int w = 0; w < s3W; w++)
            {
                double d = s3Rate[1][w][b] - s3Rate[0][w][b];
                if (d <= -10.0)
                {
                    veto++;
                    Console.WriteLine("| " + h2All[b].Name + " | 第" + (w + 1) + "波 | " + s3Rate[0][w][b].ToString("F1")
                        + "% | " + s3Rate[1][w][b].ToString("F1") + "% | " + d.ToString("+0.0;-0.0") + "pt |");
                }
            }
        if (veto == 0) Console.WriteLine("| （該当なし） | | | | |");
        Console.WriteLine();
        var pset = new HashSet<string>(Baseline.PrimaryRows);
        double p50 = 0, p51 = 0; int pn = 0;
        for (int b = 0; b < h2Compare.Length; b++)
            if (pset.Contains(h2All[b].Name)) { p50 += s3Rate[0][s3W - 1][b]; p51 += s3Rate[1][s3W - 1][b]; pn++; }
        // (G9): 第五波 95% 超の行が増えるのは「注意」であって拒否ではない。数だけ出す。
        int hi0 = 0, hi1 = 0;
        for (int b = 0; b < h2Compare.Length; b++)
        {
            if (s3Rate[0][s3W - 1][b] > 95.0) hi0++;
            if (s3Rate[1][s3W - 1][b] > 95.0) hi1++;
        }
        Console.WriteLine("| 拒否権 | 量 | 線 | 結果 |");
        Console.WriteLine("|---|---|---|:-:|");
        Console.WriteLine("| (1) 主判定" + pn + "行の第五波平均 | " + (p50 / Math.Max(1, pn)).ToString("F1")
            + "% → **" + (p51 / Math.Max(1, pn)).ToString("F1") + "%** | ≥ "
            + Baseline.PrimaryFifthFloor.ToString("F1") + "% | "
            + (p51 / Math.Max(1, pn) >= Baseline.PrimaryFifthFloor ? "**○**" : "**×**") + " |");
        Console.WriteLine("| (3) いずれかの波で −10.0pt 以上落ちた行 | **" + veto + " 件** | 0 件 | "
            + (veto == 0 ? "**○**" : "**×**") + " |");
        Console.WriteLine("| （注意・(G9)） 第五波 95% 超の行 | " + hi0 + " → **" + hi1 + " 行** | 記録するだけ | — |");

        // ---- 表E: 自己検査
        Console.WriteLine();
        Console.WriteLine("## 表E —— 自己検査");
        Console.WriteLine();
        Console.WriteLine("- **(c)** 発火が決着ターン数を超えた戦: **" + s3OverCap + " 件** —— "
            + (s3OverCap == 0 ? "**○**" : "**×**") + "（1ターン1回の上限）");
        Console.WriteLine("- **(d)** `SutureRule`（糸口）と `SutureFireRule`（発火口）が独立に働くこと（4通り）:");
        Console.WriteLine();
        Console.WriteLine("| 糸口 | 発火口 | ハリの行の第2〜5波平均 | 発火/戦 | 味方から/戦 |");
        Console.WriteLine("|---|---|--:|--:|--:|");
        foreach (SutureSide side in s3Side)
            foreach (var v in s3Ver)
            {
                double sum = 0; int n = 0; long fires = 0, ally = 0, bt = 0;
                for (int b = 0; b < s3B; b++)
                {
                    if (!h2All[b].F.Occupied().Any(o => o.Def.Id == "hari")) continue;
                    for (int w = 1; w < s3W; w++)
                    {
                        int wins = 0;
                        for (int sd = 0; sd < S3Seeds; sd++)
                        {
                            var r = BattleEngine.Run(h2All[b].F, h2Stages[w].Enemy, S3Base + sd, verbose: false,
                                                     suture: new SutureRule(side), sutureFire: v.R);
                            if (r.PlayerWon) wins++;
                            bt++;
                            if (r.TallyByUnit.TryGetValue("hari", out UnitTally? t))
                            { fires += t.SutureFoe + t.SutureAlly; ally += t.SutureAlly; }
                        }
                        sum += wins * 100.0 / S3Seeds; n++;
                    }
                }
                Console.WriteLine("| " + side + " | " + v.Tag + " | " + (sum / Math.Max(1, n)).ToString("F1")
                    + "% | " + (bt == 0 ? 0 : (double)fires / bt).ToString("0.00")
                    + " | " + (bt == 0 ? 0 : (double)ally / bt).ToString("0.00") + " |");
            }
        Console.WriteLine();
        Console.WriteLine("**`Foe` では味方から引く回数が両版とも 0.00 でなければならない**"
            + "（糸口の規則が発火口に依らないこと）。");

        // ---- (e) 繕いが `ctx.Heal` を通っていること（渇きで封じられる）
        //
        // **「渇きの波で繕い量が 0」では検査にならない**——祭司は倒せるので、倒した後の繕いは通る。
        // 波ごとに「空振り（`SutureDry` ＝ 患者のHPが1点も動かなかった発火）」の割合を出し、
        // **渇きの波だけが突出すること**を見る。
        Console.WriteLine();
        Console.WriteLine("- **(e)** 繕いが `ctx.Heal` を通っていること（渇きで封じられる）:");
        Console.WriteLine();
        Console.WriteLine("| 波 | 渇き | W1 発火/戦 | 空振り/戦 | 空振り率 | 繕い量/発火 |");
        Console.WriteLine("|--:|:-:|--:|--:|--:|--:|");
        for (int w = 1; w < s3W; w++)
        {
            bool dro = h2Stages[w].Enemy.Occupied().Any(o => o.Def.Traits.Contains(TraitId.Drought));
            long fires = 0, dry = 0, healed = 0, bt = 0;
            for (int b = 0; b < s3B; b++)
            {
                if (!h2All[b].F.Occupied().Any(o => o.Def.Id == "hari")) continue;
                for (int sd = 0; sd < S3Seeds; sd++)
                {
                    var r = BattleEngine.Run(h2All[b].F, h2Stages[w].Enemy, S3Base + sd, verbose: false,
                                             sutureFire: new SutureFireRule(SutureFire.OnWound));
                    bt++;
                    if (r.TallyByUnit.TryGetValue("hari", out UnitTally? t))
                    { fires += t.SutureFoe + t.SutureAlly; dry += t.SutureDry; healed += t.SutureHealed; }
                }
            }
            Console.WriteLine("| 第" + (w + 1) + "波 | " + (dro ? "**○**" : "×") + " | "
                + (bt == 0 ? 0 : (double)fires / bt).ToString("0.00") + " | "
                + (bt == 0 ? 0 : (double)dry / bt).ToString("0.00") + " | "
                + (fires == 0 ? 0 : dry * 100.0 / fires).ToString("0.0") + "% | "
                + (fires == 0 ? 0 : (double)healed / fires).ToString("0.0") + " |");
        }

        // ---- Q6: `tempo` の器具（第105期）でハリの分類が動くか
        Console.WriteLine();
        Console.WriteLine("## 表C-3 —— Q6（第105期の器具でハリが手番外型に移るか）");
        Console.WriteLine();
        Console.WriteLine("線は第105期 §1-3 のとおり **手番外の割合 50%**。**通貨ごとに割れる駒は「混合」**。");
        Console.WriteLine();
        Console.WriteLine("| 版 | 与ダメ | 回復 | 状態 | 強化弱体 | 分類 |");
        Console.WriteLine("|---|--:|--:|--:|--:|---|");
        for (int p = 0; p < s3Ver.Length; p++)
        {
            var inn = new long[4]; var off = new long[4];
            for (int b = 0; b < s3B; b++)
            {
                if (!h2All[b].F.Occupied().Any(o => o.Def.Id == "hari")) continue;
                for (int w = 1; w < s3W; w++)
                    for (int sd = 0; sd < S3Seeds; sd++)
                    {
                        var r = BattleEngine.Run(h2All[b].F, h2Stages[w].Enemy, S3Base + sd, verbose: false,
                                                 sutureFire: s3Ver[p].R);
                        if (!r.TallyByUnit.TryGetValue("hari", out UnitTally? t)) continue;
                        inn[0] += t.DmgOutInTurn; off[0] += t.DmgOutOffTurn;
                        inn[1] += t.HealOutInTurn; off[1] += t.HealOutOffTurn;
                        inn[2] += t.StatusOutInTurn; off[2] += t.StatusOutOffTurn;
                        inn[3] += t.BuffOutInTurn; off[3] += t.BuffOutOffTurn;
                    }
            }
            var cells = new string[4];
            bool anyOff = false, anyIn = false;
            for (int i = 0; i < 4; i++)
            {
                long d = inn[i] + off[i];
                if (d == 0) { cells[i] = "—"; continue; }
                double r2 = off[i] * 100.0 / d;
                cells[i] = r2.ToString("0.0") + "%";
                if (r2 > 50.0) anyOff = true; else anyIn = true;
            }
            string kind = !anyOff && !anyIn ? "出力なし" : anyOff && anyIn ? "混合" : anyOff ? "**手番外型**" : "手番型";
            Console.WriteLine("| " + s3Ver[p].Tag + " | " + string.Join(" | ", cells) + " | " + kind + " |");
        }
        Console.WriteLine();
        Console.WriteLine("（列は**手番外の割合**。第105期のロスター全体では 回復 90.3% が手番の外から出ている。）");
        return;
    }
    // ------------------------------------------------------------------------------
    // Phase 0（**戦闘は較正の確認のみ**）と自己検査。
    // ------------------------------------------------------------------------------
    if (h2Mode == "phase0" || h2Mode == "check" || h2Mode == "tables")
    {
        string? h2Root = Directory.GetCurrentDirectory();
        while (h2Root != null && !File.Exists(Path.Combine(h2Root, "docs", "balance.md")))
            h2Root = Path.GetDirectoryName(h2Root);

        if (h2Mode == "phase0")
        {
            Console.WriteLine("# 第107期 Phase 0 —— 地図");
            Console.WriteLine();
            Console.WriteLine("## 0-1. `BattleContext.Wound` の呼び出し口の全数（**指示書の一覧を信用せず数え直した**）");
            Console.WriteLine();
            Console.WriteLine("`WoundRoute` は " + BattleContext.WoundRouteCount + " 本。実測は 73 行 × 全5波 × seed 0..19。");
            Console.WriteLine();
            var wr = new double[BattleContext.WoundRouteCount];
            int wn = 0;
            for (int b = 0; b < h2All.Length; b++)
                for (int w = 0; w < h2Stages.Count; w++)
                    for (int sp = 0; sp < 20; sp++)
                    {
                        var r = BattleEngine.Run(h2All[b].F, h2Stages[w].Enemy, sp, verbose: false);
                        wn++;
                        foreach (var kv in r.TallyByUnit)
                            if (kv.Value.WoundWritesByRoute is not null)
                                for (int k = 0; k < wr.Length; k++) wr[k] += kv.Value.WoundWritesByRoute[k];
                    }
            Console.WriteLine("| 経路 | 書き手 | 回/戦 | 割合 |");
            Console.WriteLine("|---|---|--:|--:|");
            double wtot = wr.Sum();
            for (int k = 0; k < wr.Length; k++)
                Console.WriteLine("| `" + (WoundRoute)k + "` | " + (k switch { 0 => "裂き（キリ）", 1 => "刻み（ノミ）", 2 => "**巻き込み則（engine）**", 3 => "棘の傷（既定 off）", 4 => "棘の巻き込み（既定 off）", _ => "引き取り（ガルド・受け取る側）" }) + " | "
                    + (wr[k] / wn).ToString("0.00") + " | " + (wtot == 0 ? 0 : wr[k] * 100.0 / wtot).ToString("0.0") + "% |");
            Console.WriteLine("| **合計** | | **" + (wtot / wn).ToString("0.00") + "** | 100.0% |");
            Console.WriteLine();
            Console.WriteLine("**発火口を `OnWound` に移すと、この合計の回数だけフックに入る**"
                + "（1ターン1回の上限が無ければ発火も同数になる）。");

            Console.WriteLine();
            Console.WriteLine("## 0-2. 憤怒（`TraitId.Rage`）の保持者 —— **2 枚**");
            Console.WriteLine();
            foreach (UnitDef d in UnitCatalog.All.Where(d => d.Traits.Contains(TraitId.Rage)))
                Console.WriteLine("- " + d.Name + "（攻 " + d.Attack + " / HP " + d.MaxHp + " / 速 " + d.Speed + "）");
            Console.WriteLine();
            Console.WriteLine("**較正はムド1枚でしかできないのに、`RageRule` は両方に効く。**");

            Console.WriteLine();
            Console.WriteLine("## 0-3. ハリを含む行（`Presets.Compare` / `Presets.Cross` から引いた）");
            Console.WriteLine();
            foreach (var b in h2All.Where(b => b.F.Occupied().Any(o => o.Def.Id == "hari")))
                Console.WriteLine("- " + b.Name);
            Console.WriteLine();
            Console.WriteLine("**2 行しかない**（compare 1 ＋ 交差帯 1）。第45期の「新しい機構は最初から2行以上に入れること」の下限。");

            Console.WriteLine();
            Console.WriteLine("## 0-4. `SutureRule`（糸口）と `SutureFireRule`（発火口）は独立");
            Console.WriteLine();
            Console.WriteLine("| 型 | 既定 | 意味 |");
            Console.WriteLine("|---|---|---|");
            Console.WriteLine("| `SutureRule` | `" + SutureRule.Default + "` | 糸を引く**先**（第85期） |");
            Console.WriteLine("| `SutureFireRule` | `" + SutureFireRule.Default + "` | **いつ**引くか（第107期 (S3)） |");
            Console.WriteLine();
            Console.WriteLine("4通りの対照は `hold2 suture` の表E (d)。");
            return;
        }

        if (h2Mode == "check")
        {
            Console.WriteLine("# 第107期 表E —— 自己検査（必須4項目）");
            Console.WriteLine();

            var cells = new List<string>();
            foreach (var b in h2Compare)
            {
                var row = new List<string>();
                foreach (var st in h2Stages)
                {
                    int w = 0;
                    for (int seed = 0; seed < 200; seed++)
                        if (BattleEngine.Run(b.F, st.Enemy, seed, verbose: false).PlayerWon) w++;
                    row.Add((w * 100.0 / 200).ToString("F1") + "%");
                }
                cells.Add("| " + b.Name + " | " + string.Join(" | ", row) + " |");
            }
            int diff = -1;
            if (h2Root is not null)
            {
                var doc = File.ReadAllLines(Path.Combine(h2Root, "docs", "balance.md"))
                              .Where(l => l.StartsWith("| ") && l.Contains('%')).ToArray();
                diff = Math.Abs(doc.Length - cells.Count);
                for (int i = 0; i < Math.Min(doc.Length, cells.Count); i++)
                    if (doc[i].Trim() != cells[i].Trim()) diff++;
            }
            Console.WriteLine("- **必須1** `compare` " + (h2Compare.Length * h2Stages.Count)
                + " セルを `docs/balance.md` と突き合わせ: **ずれ " + diff + " 行**"
                + (diff == 0 ? "（○）" : "（×）")
                + " ——**(S2)(S3) はどちらも既定を1ビットも動かしていない**（動いたのは (S1) の席だけで、そちらは同じコミットで `docs/` を測り直してある）。");

            Console.WriteLine("- **必須2** `docs/` 10ファイルの再生成は (S1) のコミットで済ませてある。"
                + "(S3) で新しく増えるのは `docs/rules.md` の `sutureFire` の 1 行だけ（ノブが増えたので正しい）。");

            Console.WriteLine("- **必須3** 触っていないノブの既定: "
                + "`RageRule.Default` = `" + RageRule.Default + "` ／ "
                + "`SutureRule.Default` = `" + SutureRule.Default + "` ／ "
                + "`SutureFireRule.Default` = `" + SutureFireRule.Default + "` ／ "
                + "`SpillWoundRule.Default` = `" + SpillWoundRule.Default + "` ／ "
                + "`MendRule.Default` = `" + MendRule.Default + "` ／ "
                + "`MenderCostRule.Default` = `" + MenderCostRule.Default + "` ／ "
                + "`LooseRule.Default` = `" + LooseRule.Default + "` ／ "
                + "`EncoreRule.Default` = `" + EncoreRule.Default + "`"
                + "（**`docs/rules.md` の既定値の列で示す**）");

            int pick = 0;
            if (h2Root is not null)
                foreach (string f in Directory.GetFiles(Path.Combine(h2Root, "BattleCore"), "*.cs"))
                    pick += System.Text.RegularExpressions.Regex.Matches(
                        string.Join("\n", File.ReadAllLines(f).Where(l => !l.TrimStart().StartsWith("//"))),
                        @"PickOne\(").Count;
            Console.WriteLine("- **必須4** `BattleCore` の `PickOne(` 呼び出し **" + pick + " 箇所**"
                + "（第94期以降 26 箇所。**第107期は1つも足していない**——縫いを engine から呼ぶ順序は"
                + "スロット昇順で、`ctx.PickOne` を使わない）");
            Console.WriteLine();
            Console.WriteLine("機構固有の (a)〜(e) は `hold2 seats` / `hold2 rage` / `hold2 suture` の表E。");
            return;
        }

        Console.WriteLine("# 第107期 —— 表A〜E");
        Console.WriteLine();
        Console.WriteLine("(S1)(S2)(S3) は**別々のコミット**にしたので、表もモードごとに分けてある。");
        Console.WriteLine();
        Console.WriteLine("| 表 | 内容 | モード |");
        Console.WriteLine("|---|---|---|");
        Console.WriteLine("| A | (S1) 席 | `hold2 seats` |");
        Console.WriteLine("| B | (S2) 較正の確認と Q1〜Q3 | `hold2 rage` |");
        Console.WriteLine("| C | (S3) ハリ（Q4〜Q6） | `hold2 suture` |");
        Console.WriteLine("| D | 拒否権 | `hold2 rage` / `hold2 suture` の表D |");
        Console.WriteLine("| E | 自己検査 | `hold2 check` ＋ 各モードの表E |");
        Console.WriteLine("| — | 地図 | `hold2 phase0` |");
        return;
    }

    Console.WriteLine("モード: seats / rage / suture / phase0 / tables / check");
    return;
}

if (focusId == "spread")
{
    var spreadBuilds = CompareBuilds();
    // 第3引数に除外語（カンマ区切りの部分一致）を渡すと、その行を外して測る。
    // **行を足した期に「同じ行数で前後を測り直す」ためだけの窓口**（CLAUDE.md の
    // 「計測器と測定対象を同時に動かさない」）。省略すれば従来どおり全行。
    string spreadDrop = args.Length > 2 ? args[2] : "";
    if (spreadDrop.Length > 0)
        spreadBuilds = spreadBuilds
            .Where(b => !spreadDrop.Split(',').Any(k => b.Name.Contains(k.Trim()))).ToArray();
    IReadOnlyList<EnemyCatalog.Stage> spreadStages = EnemyCatalog.Stages;
    const int SpreadSeeds = 200;   // compare と同じ。数字を突き合わせるので変えない

    int nb = spreadBuilds.Length, nw = spreadStages.Count;

    // rate[波][編成] = 勝率(%)。compare と同じ計算（同じ seed 帯・同じ Run）なので
    // docs/balance.md の表とセルが一致する。ずれたらどちらかの集計が間違っている。
    var rate = new double[nw][];
    for (int w = 0; w < nw; w++)
    {
        rate[w] = new double[nb];
        for (int b = 0; b < nb; b++)
        {
            int wins = 0;
            for (int seed = 0; seed < SpreadSeeds; seed++)
                if (BattleEngine.Run(spreadBuilds[b].F, spreadStages[w].Enemy, seed, verbose: false).PlayerWon) wins++;
            rate[w][b] = wins * 100.0 / SpreadSeeds;
        }
    }

    Console.WriteLine("# 波の分離度（spread）");
    Console.WriteLine();
    Console.WriteLine($"代表編成 {nb} × 全 {nw} 波、seed 0..{SpreadSeeds - 1} の {SpreadSeeds} 試行。");
    Console.WriteLine("compare と同じ計算なので、セルは docs/balance.md と一致する。");
    Console.WriteLine();

    Console.WriteLine("## 1. 波ごとの飽和");
    Console.WriteLine();
    Console.WriteLine("| 波 | 平均 | 100%の編成 | 0%の編成 | 中間帯(5〜95%) | 標準偏差 |");
    Console.WriteLine("|---|--:|--:|--:|--:|--:|");
    var sd = new double[nw];
    for (int w = 0; w < nw; w++)
    {
        double[] v = rate[w];
        double mean = v.Average();
        sd[w] = Math.Sqrt(v.Select(x => (x - mean) * (x - mean)).Sum() / v.Length);
        int top = v.Count(x => x >= 100.0), bottom = v.Count(x => x <= 0.0);
        int mid = v.Count(x => x > 5.0 && x < 95.0);
        Console.WriteLine($"| 第{w + 1}波 | {mean:F1} | {top} / {nb} | {bottom} | {mid} | {sd[w]:F1} |");
    }
    Console.WriteLine();
    int allTop = Enumerable.Range(0, nb).Count(b => Enumerable.Range(1, Math.Max(0, nw - 2)).All(w => rate[w][b] >= 100.0));
    Console.WriteLine($"第2〜{nw - 1}波すべて 100% の編成: **{allTop} / {nb}**"
                    + "（この編成たちにとって、中間の波は存在しないのと同じ）");
    Console.WriteLine();

    Console.WriteLine("## 2. 波間の相関");
    Console.WriteLine();
    Console.WriteLine("編成ごとの勝率を波の間で相関させる。高いほど「同じ資源に課金している」。");
    Console.WriteLine("分散 0 の波（全編成が同じ勝率）は相関が定義できないので `—`。");
    Console.WriteLine();
    Console.WriteLine("| |" + string.Concat(Enumerable.Range(1, nw - 1).Select(w => $" 第{w + 1}波 |")));
    Console.WriteLine("|---|" + string.Concat(Enumerable.Range(1, nw - 1).Select(_ => "--:|")));
    for (int i = 0; i < nw - 1; i++)
    {
        var cells = new List<string>();
        for (int j = 1; j < nw; j++)
        {
            if (j <= i) { cells.Add(" |"); continue; }   // 下三角は空欄（対称なので上だけ出す）
            double r = Corr(rate[i], rate[j]);
            cells.Add(double.IsNaN(r) ? " — |" : $" {r:+0.00;-0.00} |");
        }
        Console.WriteLine($"| **第{i + 1}波** |" + string.Concat(cells));
    }
    Console.WriteLine();

    Console.WriteLine("## 3. 固有の勝者・敗者");
    Console.WriteLine();
    Console.WriteLine("**固有の勝者** = その波でだけ 100%（他のどの波でも 100% 未満）の編成。");
    Console.WriteLine("**固有の敗者** = その波でだけ 0%（他のどの波でも 0% 超）の編成。");
    Console.WriteLine("両方とも空の波は、独立した波として存在していない。");
    Console.WriteLine();
    Console.WriteLine("**第一波は比較から外してある。** チュートリアル波として全編成 100% を意図的に");
    Console.WriteLine("維持しているので、比較に入れると第2〜5波の固有の勝者が**恒等的に 0** になる");
    Console.WriteLine("——第三波を何に作り替えても動かない指標だった。第一波自身も判定しない。");
    Console.WriteLine();
    for (int w = 0; w < nw; w++)
    {
        Console.WriteLine($"### 第{w + 1}波");
        Console.WriteLine();
        if (w == 0)
        {
            // 第一波は全編成 100%。「他のどの波でも 100% 未満」を要求する判定の比較対象に
            // 入れると、第2〜5波の固有の勝者が恒等的に 0 になる（第20期 逆位の副産物）。
            // ここを直さずに波を作り替えると、主判定が到達不能なまま前後比較をすることになる。
            Console.WriteLine("- （比較対象外。全編成 100% のチュートリアル波）");
            Console.WriteLine();
            continue;
        }

        var winners = new List<string>();
        var losers = new List<string>();
        for (int b = 0; b < nb; b++)
        {
            bool onlyTop = rate[w][b] >= 100.0
                        && Enumerable.Range(1, nw - 1).All(o => o == w || rate[o][b] < 100.0);
            bool onlyBottom = rate[w][b] <= 0.0
                           && Enumerable.Range(1, nw - 1).All(o => o == w || rate[o][b] > 0.0);
            if (onlyTop) winners.Add(spreadBuilds[b].Name);
            if (onlyBottom) losers.Add(spreadBuilds[b].Name);
        }
        Console.WriteLine($"- 固有の勝者 ({winners.Count}): " + (winners.Count == 0 ? "**なし**" : string.Join(" / ", winners)));
        Console.WriteLine($"- 固有の敗者 ({losers.Count}): " + (losers.Count == 0 ? "**なし**" : string.Join(" / ", losers)));
        Console.WriteLine();
    }

    // ---- 4. 主判定の固定行集合（第60期に確定）---------------------------------------
    Console.WriteLine($"## 4. 主判定 {Baseline.PrimaryRows.Length} 行（歯止めはこの集合の上で測る）");
    Console.WriteLine();
    Console.WriteLine("**全行平均は行を足すたびに勝手に動く量である。** 第41〜59期の「歯止めを割った」は");
    Console.WriteLine("すべて分母の話で、波そのものは第40期から1つも動いていない（第59期 9-4 → 第60期に確定）。");
    Console.WriteLine("主判定は**軸の被覆**で選んだ固定集合なので、新機構の行を足しても分母が動かない。");
    Console.WriteLine();
    Console.WriteLine("**情報セルの定義はここだけ第59期 9-1 に揃えてある**——");
    Console.WriteLine("`0 < x < 100` を**第2〜5波**で数える（§1 の中間帯は `5 < x < 95`。別の量なので混ぜない）。");
    Console.WriteLine();
    var primary = Baseline.PrimaryRows
        .Select(n => Array.FindIndex(spreadBuilds, b => b.Name == n))
        .Where(i => i >= 0).ToArray();
    var missing = Baseline.PrimaryRows.Where(n => !spreadBuilds.Any(b => b.Name == n)).ToArray();
    if (missing.Length > 0)
    {
        Console.WriteLine($"**警告: 主判定行のうち {missing.Length} 行が見つからない** —— "
                        + string.Join(" / ", missing));
        Console.WriteLine("（`CompareBuilds()` の行名を変えたら `Baseline.PrimaryRows` も直すこと）");
        Console.WriteLine();
    }
    int Info59(int b) => Enumerable.Range(1, nw - 1).Count(w => rate[w][b] > 0.0 && rate[w][b] < 100.0);
    Console.WriteLine("| # | 行 | 第1波 | 第2波 | 第3波 | 第4波 | 第5波 | 情報セル |");
    Console.WriteLine("|--:|---|--:|--:|--:|--:|--:|--:|");
    for (int k = 0; k < primary.Length; k++)
    {
        int b = primary[k];
        Console.WriteLine($"| {k + 1} | {spreadBuilds[b].Name} "
                        + string.Concat(Enumerable.Range(0, nw).Select(w => $"| {rate[w][b]:0.0}% "))
                        + $"| **{Info59(b)}** |");
    }
    Console.WriteLine();
    string Fold(string tag, IEnumerable<int> idx)
    {
        int[] a = idx.ToArray();
        int info = a.Sum(Info59);
        return $"| {tag} " + string.Concat(Enumerable.Range(0, nw)
                 .Select(w => $"| {a.Average(b => rate[w][b]):0.0}% "))
             + $"| {info} / {info / (double)a.Length:0.00} |";
    }
    Console.WriteLine("| 分母 | 第1波 | 第2波 | 第3波 | 第4波 | 第5波 | 情報セル 合計 / 平均 |");
    Console.WriteLine("|---|--:|--:|--:|--:|--:|--:|");
    Console.WriteLine(Fold($"**主判定 {primary.Length} 行**", primary));
    Console.WriteLine(Fold($"全 {nb} 行", Enumerable.Range(0, nb)));
    Console.WriteLine();
    double fifth = primary.Average(b => rate[nw - 1][b]);
    Console.WriteLine($"**第五波: 主判定 {fifth:0.0}% / 全 {nb} 行 {rate[nw - 1].Average():0.0}%**");
    Console.WriteLine($"**歯止め: 主判定 {Baseline.PrimaryFifthFloor:0.0}%** "
                    + $"——確定時（第60期）の主判定の値 − 5.0pt。現在の余裕は "
                    + $"**{fifth - Baseline.PrimaryFifthFloor:+0.0;-0.0;0.0}pt**。");
    Console.WriteLine();
    Console.WriteLine("**線は「明らかに成立しなくなる線」であって調整目標ではない。**");
    Console.WriteLine("第59期の提案20行がちょうど 40.0 で線上に乗ったのは偶然で、**線上に置くのが一番まずい**");
    Console.WriteLine("——だから確定時の値そのものではなく **−5.0pt** に置いてある。");
    Console.WriteLine();

    return;

    // ピアソン相関。片方の分散が 0 なら定義できないので NaN を返す（呼び出し側で — に置く）。
    static double Corr(double[] a, double[] b)
    {
        double ma = a.Average(), mb = b.Average();
        double num = 0, da = 0, db = 0;
        for (int i = 0; i < a.Length; i++)
        {
            num += (a[i] - ma) * (b[i] - mb);
            da += (a[i] - ma) * (a[i] - ma);
            db += (b[i] - mb) * (b[i] - mb);
        }
        return da <= 0 || db <= 0 ? double.NaN : num / Math.Sqrt(da * db);
    }
}

// 火選り（第58期）の診断。**Phase 0 は実装より先に走らせる**（指示書 §5-4）。
//
// 第57期が出した「燃焼は盤面のどこにも繋がっていない閉じた2枚組」（表E の 18 セルが全部 0）を受けて、
// **盤上に既にある「誰も読んでいない味方側の燃焼」（着火 味 2.40 対 敵 2.21）を
// 強化・弱体へ変換する駒**を作る期。
//
// **Phase 0-1（乗算監査）が最優先。** `UnitState.CurrentAttack` は `Def.Attack + AtkBonus` を
// 作ってから `ModifyAttack` を通すので、**熾火（ホタ）に配った強化1点は燃えている間 4 点になる。**
// ロスター唯一の乗算フラグで、「強化の配布経路を触るときに必ず監査する」が積み残しだった。
//
//     dotnet run --project BattleSim -c Release 0 favor phase0   # 実装前の地図（乗算監査・在庫・試験行）
if (focusId == "favor" && (args.Length > 2 ? args[2] : "") == "phase0")
{
    var kpBuilds = CompareBuilds();
    IReadOnlyList<EnemyCatalog.Stage> kpStages = EnemyCatalog.Stages;
    const int KpSeeds = 200;   // compare / spread / whet / burn と同じ帯

    Console.WriteLine("# 火選りの地図（第58期 Phase 0）");
    Console.WriteLine();

    // ---- 0-1. 乗算監査 ---------------------------------------------------------------
    Console.WriteLine("## 0-1. 熾火の乗算監査（**最優先**・指示書 §1-1）");
    Console.WriteLine();
    Console.WriteLine("`UnitState.CurrentAttack` は `Def.Attack + AtkBonus` を作ってから");
    Console.WriteLine("`Trait.ModifyAttack` を通す。`PyreTrait.ModifyAttack` は燃えている間");
    Console.WriteLine($"`atk * {PyreTrait.Multiplier}` を返すので、**強化は素の攻撃力と一緒に掛けられる**。");
    Console.WriteLine();

    // (a) 盤面を1つも動かさない算術。UnitState を1つ作って CurrentAttack を読むだけ。
    static UnitState KpMake(UnitDef d, int bonus, bool burning)
    {
        var u = new UnitState
        {
            Def = d, Hp = d.MaxHp, MaxHp = d.MaxHp, TeamId = BattleContext.PlayerTeam,
            Traits = TraitCatalog.Resolve(d.Traits), AtkBonus = bonus
        };
        if (burning) u.SetCounter(StatusKeys.Burn, BurnRules.Turns);
        return u;
    }
    Console.WriteLine("### (a) 算術（戦闘0回）");
    Console.WriteLine();
    Console.WriteLine("| 駒 | 素の攻 | AtkBonus | 燃えていない | 燃えている | 1点の実効（冷 / 熱） |");
    Console.WriteLine("|---|--:|--:|--:|--:|---|");
    foreach (UnitDef d in new[] { UnitCatalog.Hota, UnitCatalog.Mudo, UnitCatalog.Dolga })
    {
        int cold0 = KpMake(d, 0, false).CurrentAttack;
        int hot0 = KpMake(d, 0, true).CurrentAttack;
        foreach (int bonus in new[] { 0, 1, 2, 4 })
        {
            int cold = KpMake(d, bonus, false).CurrentAttack;
            int hot = KpMake(d, bonus, true).CurrentAttack;
            string eff = bonus == 0 ? "—"
                : $"{(cold - cold0) / (double)bonus:0.0} / **{(hot - hot0) / (double)bonus:0.0}**";
            Console.WriteLine($"| {d.Name} | {d.Attack} | +{bonus} | {cold} | {hot} | {eff} |");
        }
    }
    Console.WriteLine();
    Console.WriteLine($"**熾火だけが熱 {PyreTrait.Multiplier}.0。** 他の2枚は燃えていても 1.0（`ModifyAttack` を持たない）。");
    Console.WriteLine();

    // (b) 1戦のログ。StatSnapshot はターン頭の CurrentAttack を写す（BattleEngine.cs）。
    //     注入は Materialize → AtkBonus → UnitState 版 Run（第24期 `yield` と同じ経路）。
    //     InstanceId は ctx.Add が味方リストの順（= Materialize のスロット昇順）に 0 から振る。
    var kpRow = kpBuilds.First(b => b.Name.Contains("燃焼 (ボルグ×ホタ)"));
    Console.WriteLine("### (b) 1戦のログ（`燃焼 (ボルグ×ホタ)` × 第4波 × seed 0）");
    Console.WriteLine();
    Console.WriteLine("**ホタの `AtkBonus` に開戦時から +0 / +2 を注入した2版**を並べる。");
    Console.WriteLine("`CurrentAttack` はターン頭のスナップショット、`与ダメ` はそのターンにホタが通した量。");
    Console.WriteLine();
    Console.WriteLine("| 版 | ターン | ホタの `CurrentAttack` | 燃(残) | そのターンのホタの与ダメ |");
    Console.WriteLine("|---|--:|--:|:-:|--:|");
    foreach (int inject in new[] { 0, 2 })
    {
        var pl = BattleEngine.Materialize(kpRow.F, BattleContext.PlayerTeam);
        int hotaIid = pl.FindIndex(u => u.Def.Id == "hota");   // Add が 0 から順に振る
        foreach (UnitState u in pl.Where(u => u.Def.Id == "hota")) u.AtkBonus += inject;
        var fo = BattleEngine.Materialize(kpStages[3].Enemy, BattleContext.EnemyTeam);
        BattleResult rr = BattleEngine.Run(pl, fo, 0, verbose: true);
        for (int t = 1; t <= rr.Turns; t++)
        {
            int atk = -1, burn = 0, dmg = 0;
            foreach (BattleEvent e in rr.Events)
            {
                if (e.Turn != t) continue;
                if (e.Kind == BattleEventKind.StatSnapshot && e.TargetId == hotaIid) atk = e.Amount;
                if (e.Kind == BattleEventKind.StatusSnapshot && e.TargetId == hotaIid && e.Text == "燃") burn = e.Amount;
                if (e.Kind == BattleEventKind.Damage && e.ActorId == hotaIid && !e.FriendlyFire) dmg += e.Amount;
            }
            if (atk < 0) continue;
            Console.WriteLine($"| +{inject} | {t} | **{atk}** | {(burn > 0 ? burn.ToString() : "—")} | {dmg} |");
        }
    }
    Console.WriteLine();

    // (c) 全波の集計。ホタと非乗算の駒に同じ量を注入して、実効倍率を測る。
    Console.WriteLine("### (c) 全波の集計（`燃焼 (ボルグ×ホタ)` × 全5波 × seed 0..199）");
    Console.WriteLine();
    Console.WriteLine("**注入した1点が、その駒の与ダメを何点動かしたか。** 分母は注入量。");
    Console.WriteLine("`振り` は `PerformAttack` を通った回数（**貫きは1体貫くごとに25%減衰する**ので、");
    Console.WriteLine("与ダメの伸びは攻撃力の伸びより緩む）。");
    Console.WriteLine();
    Console.WriteLine("| 注入先 | 注入量 | その駒の与ダメ/戦 | 振り/戦 | 1点あたりの与ダメ増 | 平均勝率 |");
    Console.WriteLine("|---|--:|--:|--:|--:|--:|");
    foreach (string who in new[] { "hota", "mudo" })
    {
        double baseDmg = 0;
        foreach (int inject in new[] { 0, 1, 2, 4 })
        {
            double dmg = 0, atk = 0, win = 0;
            int n = 0;
            for (int w = 0; w < kpStages.Count; w++)
                for (int seed = 0; seed < KpSeeds; seed++)
                {
                    var pl = BattleEngine.Materialize(kpRow.F, BattleContext.PlayerTeam);
                    foreach (UnitState u in pl.Where(u => u.Def.Id == who)) u.AtkBonus += inject;
                    var fo = BattleEngine.Materialize(kpStages[w].Enemy, BattleContext.EnemyTeam);
                    BattleResult r = BattleEngine.Run(pl, fo, seed, verbose: false);
                    if (r.PlayerWon) win++;
                    if (r.TallyByUnit.TryGetValue(who, out UnitTally? t))
                    { dmg += t.DamageToEnemy; atk += t.Attacks; }
                    n++;
                }
            dmg /= n; atk /= n; win = win * 100.0 / n;
            if (inject == 0) baseDmg = dmg;
            string per = inject == 0 ? "—" : $"**{(dmg - baseDmg) / inject:+0.00;-0.00;0.00}**";
            Console.WriteLine($"| {(who == "hota" ? "熾のホタ（乗算あり）" : "泥人形ムド（乗算なし）")} | +{inject} "
                + $"| {dmg:0.0} | {atk:0.00} | {per} | {win:0.0}% |");
            Console.Out.Flush();
        }
    }
    Console.WriteLine();

    // ---- 0-2. 在庫 -------------------------------------------------------------------
    Console.WriteLine("## 0-2. 在庫");
    Console.WriteLine();
    Console.WriteLine($"- `CompareBuilds()` の行数: **{kpBuilds.Length}**（× {kpStages.Count} 波 = **{kpBuilds.Length * kpStages.Count} セル**）");
    Console.WriteLine($"- `UnitCatalog.All`: **{UnitCatalog.All.Count}** 体（上限 52 に対して残り **{52 - UnitCatalog.All.Count}**）");
    Console.WriteLine($"- `WhetRoutes.Count` = **{WhetRoutes.Count}** ／ `DullRoutes.Count` = **{DullRoutes.Count}**（末尾に足す）");
    int kpBorg = kpBuilds.Count(b => b.F.Occupied().Any(o => o.Def.Id == "borg"));
    Console.WriteLine($"- ボルグを含む行: **{kpBorg}**");
    Console.WriteLine();

    // ---- 0-3. 試験行の候補 -----------------------------------------------------------
    Console.WriteLine("## 0-3. 試験行の候補（ボルグを含む行 × 1枠を素体へ差し替え）");
    Console.WriteLine();
    Console.WriteLine("**`ablate` の値ではなく、その行がまだ動くか**を見る（第29期「台が死んでいる」の検査）。");
    Console.WriteLine("`素体5` = 5枠のうち1つを **HP70/攻5/速6・特性なし**（＝火選りの体）へ差し替えた版の平均勝率。");
    Console.WriteLine("**20% 台に潰れる席は、何を入れても測定にならない**（`reseat` の 120 通りが並ぶのと同じ合図）。");
    Console.WriteLine("火種（ボルグ）の枠は差し替えない。");
    Console.WriteLine();
    UnitDef KpBody = new()
    {
        Id = "hiyo_plain", Name = "素体（HP70/攻5/速6）",
        MaxHp = 70, Attack = 5, Speed = 6,
        Traits = Array.Empty<TraitId>(), Pattern = AttackPattern.Single
    };
    double[] KpWins(Formation f)
    {
        var v = new double[kpStages.Count];
        for (int w = 0; w < kpStages.Count; w++)
        {
            int wins = 0;
            for (int seed = 0; seed < KpSeeds; seed++)
                if (BattleEngine.Run(f, kpStages[w].Enemy, seed, false).PlayerWon) wins++;
            v[w] = wins * 100.0 / KpSeeds;
        }
        return v;
    }
    Console.WriteLine("| 行 | 現行 | 差し替えた枠 | 席 | 第1波 | 第2波 | 第3波 | 第4波 | 第5波 | 素体5 | 差 |");
    Console.WriteLine("|---|--:|---|:-:|--:|--:|--:|--:|--:|--:|--:|");
    foreach (var b in kpBuilds.Where(b => b.F.Occupied().Any(o => o.Def.Id == "borg")))
    {
        double cur = KpWins(b.F).Average();
        foreach ((int slot, UnitDef d) in b.F.Occupied().ToList())
        {
            if (d.Id == "borg") continue;   // 火種は残す
            var g = new Formation();
            foreach ((int s2, UnitDef d2) in b.F.Occupied()) g[s2] = s2 == slot ? KpBody : d2;
            double[] v = KpWins(g);
            Console.WriteLine($"| {b.Name} | {cur:0.0}% | {d.Name} | {FormationRules.SeatNames[slot]} "
                + string.Concat(v.Select(x => $"| {x:0.0}% "))
                + $"| **{v.Average():0.0}%** | {v.Average() - cur:+0.0;-0.0;0.0} |");
            Console.Out.Flush();
        }
    }
    Console.WriteLine();
    return;
}

// ---- ここから先は本体（phase0 は上で return 済み）---------------------------------------
if (focusId == "favor")
{
    var kdBuilds = CompareBuilds();
    IReadOnlyList<EnemyCatalog.Stage> kdStages = EnemyCatalog.Stages;
    const int KdSeeds = 200;   // compare / spread / whet / burn / goad と同じ帯
    FavorRule KdMain = FavorRule.Default;
    var kdSweep = new (int G, int L)[] { (0, 0), (2, 2), (4, 2), (2, 4), (4, 4) };

    string kdMode = args.Length > 2 ? args[2] : "";

    static bool KdHasHiyo(Formation f) => f.Occupied().Any(o => ReferenceEquals(o.Def, UnitCatalog.Hiyo));

    var kdTargets = kdBuilds.Where(b => KdHasHiyo(b.F)).ToArray();
    if (kdMode.Length > 0 && kdMode != "sweep" && kdMode != "confirm"
        && kdMode != "alt" && kdMode != "seats")
        kdTargets = kdTargets.Where(b => kdMode.Split(',').Any(k => b.Name.Contains(k.Trim()))).ToArray();

    // **素体の対照。** ヒヨと数値・型・速さが1つも違わず、特性だけを持たない駒。
    // `FavorRule(0, 0)` でも機構は完全に止まる（Whet / Dull が amount <= 0 で即 return し、
    // FavorTrait は乱数を1つも引かない）ので、**この2つは1セルも違わないはず**——§0 で検算する。
    UnitDef KdPlainDef = new()
    {
        Id = "hiyo_plain", Name = "素体のヒヨ", MaxHp = UnitCatalog.Hiyo.MaxHp,
        Attack = UnitCatalog.Hiyo.Attack, Speed = UnitCatalog.Hiyo.Speed,
        Traits = Array.Empty<TraitId>(), Pattern = UnitCatalog.Hiyo.Pattern
    };
    // 火の粉を落としたボルグ（第57期の `BorgNoCinder` の写し）。**`Splash` は残す**
    // ——一緒に落とすと「巻き込みが消えたから勝った」と混ざる。Q2 の帰属はこれで取る。
    UnitDef KdBorgNoCinder = new()
    {
        Id = "borg_nc", Name = "ボルグ（火の粉なし）",
        MaxHp = 60, Attack = 18, Speed = 8,
        Traits = new[] { TraitId.Splash }, Pattern = AttackPattern.Sweep
    };
    Formation KdSwap(Formation f, UnitDef from, UnitDef to)
    {
        var g = new Formation();
        foreach ((int slot, UnitDef d) in f.Occupied())
            g[slot] = ReferenceEquals(d, from) ? to : d;
        return g;
    }
    Formation KdPlain(Formation f) => KdSwap(f, UnitCatalog.Hiyo, KdPlainDef);
    Formation KdNoCinder(Formation f) => KdSwap(f, UnitCatalog.Borg, KdBorgNoCinder);
    // ヒヨを外した4体版。**第21期の飽和検査**も兼ねる。
    static Formation KdWithoutHiyo(Formation f)
    {
        var g = new Formation();
        foreach ((int slot, UnitDef d) in f.Occupied())
            if (!ReferenceEquals(d, UnitCatalog.Hiyo)) g[slot] = d;
        return g;
    }
    // ヒヨの席だけを振った5変種（他の4枚は元の相対順のまま詰める）。
    static Formation KdSeat(Formation f, int seat)
    {
        var others = f.Occupied().Where(o => !ReferenceEquals(o.Def, UnitCatalog.Hiyo))
                      .Select(o => o.Def).ToList();
        var g = new Formation();
        g[seat] = UnitCatalog.Hiyo;
        int k = 0;
        for (int i = 0; i < FormationRules.PlayableSlotCount && k < others.Count; i++)
            if (i != seat) g[i] = others[k++];
        return g;
    }

    KdStat MeasureKd(Formation f, Formation enemy, FavorRule? rule)
    {
        var z = new KdStat();
        for (int seed = 0; seed < KdSeeds; seed++)
        {
            var r = BattleEngine.Run(f, enemy, seed, verbose: false, favor: rule);
            if (r.PlayerWon) z.Win++;
            z.Turns += r.Turns;
            z.Fires += r.FavorFires; z.Idle += r.FavorIdle;
            z.Whetted += r.FavorWhetted; z.Dulled += r.FavorDulled;
            z.Given += r.FavorGiven; z.Taken += r.FavorTaken; z.ToPyre += r.FavorToPyre;
            z.WhetTotal += r.WhetTotal; z.DullTotal += r.DullTotal;
            foreach ((string k, int v) in r.FavorWhetTo)
                z.WhetTo[k] = z.WhetTo.TryGetValue(k, out double a) ? a + v : v;
            foreach ((string k, int v) in r.FavorDullTo)
                z.DullTo[k] = z.DullTo.TryGetValue(k, out double a) ? a + v : v;
            foreach ((string id, UnitTally t) in r.TallyByUnit)
            {
                if (!z.Dmg.ContainsKey(id))
                { z.Dmg[id] = 0; z.Taken2[id] = 0; z.Last[id] = 0; z.Atk[id] = 0; z.Got[id] = 0; }
                z.Dmg[id] += t.DamageToEnemy;
                z.Taken2[id] += t.DamageTaken;
                z.Last[id] += t.LastActiveTurn;
                z.Atk[id] += t.Attacks;
                z.Got[id] += t.Whetted;
            }
            // 死蔵: 強化を受けたのに一度も `PerformAttack` を通らなかった駒への付与量。
            foreach ((string id, UnitTally t) in r.TallyByUnit)
                if (t.Whetted > 0 && t.Attacks == 0) z.Hoard += t.Whetted;
        }
        double n = KdSeeds;
        z.Win = z.Win * 100 / n; z.Turns /= n;
        z.Fires /= n; z.Idle /= n; z.Whetted /= n; z.Dulled /= n;
        z.Given /= n; z.Taken /= n; z.ToPyre /= n; z.Hoard /= n;
        z.WhetTotal /= n; z.DullTotal /= n;
        foreach (string k in z.WhetTo.Keys.ToList()) z.WhetTo[k] /= n;
        foreach (string k in z.DullTo.Keys.ToList()) z.DullTo[k] /= n;
        foreach (string k in z.Dmg.Keys.ToList())
        { z.Dmg[k] /= n; z.Taken2[k] /= n; z.Last[k] /= n; z.Atk[k] /= n; z.Got[k] /= n; }
        return z;
    }

    (double[] Wins, KdStat Z) KdAll(Formation f, FavorRule? rule)
    {
        var wins = new double[kdStages.Count];
        var acc = new KdStat();
        for (int w = 0; w < kdStages.Count; w++)
        {
            var z = MeasureKd(f, kdStages[w].Enemy, rule);
            wins[w] = z.Win;
            acc.Turns += z.Turns; acc.Fires += z.Fires; acc.Idle += z.Idle;
            acc.Whetted += z.Whetted; acc.Dulled += z.Dulled;
            acc.Given += z.Given; acc.Taken += z.Taken; acc.ToPyre += z.ToPyre; acc.Hoard += z.Hoard;
            acc.WhetTotal += z.WhetTotal; acc.DullTotal += z.DullTotal;
            foreach ((string k, double v) in z.WhetTo)
                acc.WhetTo[k] = acc.WhetTo.TryGetValue(k, out double a) ? a + v : v;
            foreach ((string k, double v) in z.DullTo)
                acc.DullTo[k] = acc.DullTo.TryGetValue(k, out double a) ? a + v : v;
            foreach ((string k, double v) in z.Dmg)
            {
                if (!acc.Dmg.ContainsKey(k))
                { acc.Dmg[k] = 0; acc.Taken2[k] = 0; acc.Last[k] = 0; acc.Atk[k] = 0; acc.Got[k] = 0; }
                acc.Dmg[k] += v; acc.Taken2[k] += z.Taken2[k];
                acc.Last[k] += z.Last[k]; acc.Atk[k] += z.Atk[k]; acc.Got[k] += z.Got[k];
            }
        }
        double m = kdStages.Count;
        acc.Win = wins.Average();
        acc.Turns /= m; acc.Fires /= m; acc.Idle /= m; acc.Whetted /= m; acc.Dulled /= m;
        acc.Given /= m; acc.Taken /= m; acc.ToPyre /= m; acc.Hoard /= m;
        acc.WhetTotal /= m; acc.DullTotal /= m;
        foreach (string k in acc.WhetTo.Keys.ToList()) acc.WhetTo[k] /= m;
        foreach (string k in acc.DullTo.Keys.ToList()) acc.DullTo[k] /= m;
        foreach (string k in acc.Dmg.Keys.ToList())
        { acc.Dmg[k] /= m; acc.Taken2[k] /= m; acc.Last[k] /= m; acc.Atk[k] /= m; acc.Got[k] /= m; }
        return (wins, acc);
    }

    double[] KdWins(Formation f, FavorRule? rule = null)
    {
        var v = new double[kdStages.Count];
        for (int w = 0; w < kdStages.Count; w++)
        {
            int wins = 0;
            for (int seed = 0; seed < KdSeeds; seed++)
                if (BattleEngine.Run(f, kdStages[w].Enemy, seed, false, favor: rule).PlayerWon) wins++;
            v[w] = wins * 100.0 / KdSeeds;
        }
        return v;
    }

    static string KdCells(double[] w) => string.Concat(w.Select(x => $" {x:0.0}% |"));
    static string KdTop(Dictionary<string, double> d, int n = 3)
    {
        var parts = d.Where(x => x.Value > 0).OrderByDescending(x => x.Value).Take(n)
            .Select(x => $"{x.Key} {x.Value:0.00}").ToList();
        return parts.Count == 0 ? "—" : string.Join(" / ", parts);
    }
    static double KdGet(Dictionary<string, double> d, string k)
        => k.Length > 0 && d.TryGetValue(k, out double v) ? v : 0;

