    // --- 4. 掃引 ------------------------------------------------------------------------------
    if (kdMode.Length == 0 || kdMode == "sweep")
    {
        Console.WriteLine("## 4. 掃引（V0 `0/0` ／ V1 `2/2` ／ V2 `4/2` ／ V3 `2/4` ／ V4 `4/4`）");
