        int info = v.Count(x => x > 5.0 && x < 95.0);   // 第22期の狭義の中間帯
        Console.WriteLine($"| {b.Name} " + string.Concat(v.Select(x => $"| {x:0.0}% "))
                        + $"| {v.Average():0.0}% | **{info}** |");
