if (focusId == "turn")
{
    var fvBuilds = CompareBuilds();
    IReadOnlyList<EnemyCatalog.Stage> fvStages = EnemyCatalog.Stages;
    string fvMode = args.Length > 2 ? args[2] : "";
    bool fvAlt = fvMode == "alt";
    int fvFrom = fvAlt ? 200 : 0;              // alt は別 seed 帯（200..599）
    int fvSeeds = fvAlt ? 400 : 200;           // それ以外は compare と同じ帯

    var fvRows = fvBuilds.Where(b => b.F.Occupied().Any(o => ReferenceEquals(o.Def, UnitCatalog.Hiyo))).ToArray();

    UnitDef fvTs = FvTurnStartDef(), fvPlainAct = FvPlainActDef(), fvPlain = FvPlainDef();
    Formation FvV0(Formation f) => FvSwap(f, UnitCatalog.Hiyo, fvTs);   // 移設前（ターン頭）
    Formation FvV1(Formation f) => f;                                    // 移設後（＝現行の盤面）
    Formation FvV2(Formation f) => FvSwap(f, UnitCatalog.Hiyo, fvPlainAct);
    Formation FvV3(Formation f) => FvSwap(f, UnitCatalog.Hiyo, fvPlain);

    // 版ごとの計数。ヒヨの id は版で変わるので、駒側の集計は「ヒヨの席にいる駒」で引く。
    var fvIds = new[] { "hiyo", "hiyo_ts", "hiyo_plain_act", "hiyo_plain" };

    FvStat FvMeasure(Formation f, Formation enemy, FavorRule? rule)
    {
        // 味方の総与ダメは**味方の `Def.Id` 集合**で割る（`TallyByUnit` は `Def.Id` で引くので
        // `InstanceId` の範囲では割れない。第59期 `BzStat` と同じ作法）。
        var mine = f.Occupied().Select(o => o.Def.Id).ToHashSet();
        var z = new FvStat();
        for (int seed = fvFrom; seed < fvFrom + fvSeeds; seed++)
        {
            BattleResult r = BattleEngine.Run(f, enemy, seed, verbose: false, favor: rule);
            if (r.PlayerWon) z.Win++;
            z.Turns += r.Turns;
            z.Fires += r.FavorFires; z.Idle += r.FavorIdle;
            z.Whetted += r.FavorWhetted; z.Dulled += r.FavorDulled;
            z.Given += r.FavorGiven; z.Taken += r.FavorTaken; z.ToPyre += r.FavorToPyre;
            foreach ((string k, int v) in r.FavorDullTo)
                z.DullTo[k] = z.DullTo.TryGetValue(k, out double a) ? a + v : v;
            foreach ((string k, int v) in r.FavorWhetTo)
                z.WhetTo[k] = z.WhetTo.TryGetValue(k, out double a) ? a + v : v;
            foreach (string id in fvIds)
                if (r.TallyByUnit.TryGetValue(id, out UnitTally? t))
                { z.Swings += t.Attacks; z.Dmg += t.DamageToEnemy; z.Life += t.LastActiveTurn; }
            z.TeamDmg += r.TallyByUnit.Where(kv => mine.Contains(kv.Key)).Sum(kv => kv.Value.DamageToEnemy);
        }
        double n = fvSeeds;
        z.Win = z.Win * 100 / n; z.Turns /= n; z.Fires /= n; z.Idle /= n;
        z.Whetted /= n; z.Dulled /= n; z.Given /= n; z.Taken /= n; z.ToPyre /= n;
        z.Swings /= n; z.Dmg /= n; z.Life /= n; z.TeamDmg /= n;
        foreach (string k in z.DullTo.Keys.ToList()) z.DullTo[k] /= n;
        foreach (string k in z.WhetTo.Keys.ToList()) z.WhetTo[k] /= n;
        return z;
    }
    double[] FvWins(Formation f, FavorRule? rule)
    {
        var v = new double[fvStages.Count];
        for (int w = 0; w < fvStages.Count; w++)
        {
            int win = 0;
            for (int seed = fvFrom; seed < fvFrom + fvSeeds; seed++)
                if (BattleEngine.Run(f, fvStages[w].Enemy, seed, false, favor: rule).PlayerWon) win++;
            v[w] = win * 100.0 / fvSeeds;
        }
        return v;
    }
    static int FvInfo(double[] v) => v.Count(x => x > 5.0 && x < 95.0);
    static string FvCells(double[] v) => string.Concat(v.Select(x => $"| {x:0.0}% "));

    // ---- 係数の確定（第61期 §4）--------------------------------------------------------
    //
    // **乗算の比**を両 seed 帯で取る。1帯の比で桁の判断をしない（指示書 §4）。
    //
    //     比 = （乗算持ち＝熾のホタがいる行の伸び） ÷ （いない行の伸び）
    //
    // 比が 2.0 以上なら `Gain` は**ホタ専用のノブ**と判定して上げない。
    if (fvMode == "ratio")
    {
        Console.WriteLine("# `FavorRule` の係数の確定（第61期 §4）");
        Console.WriteLine();
        Console.WriteLine("`(4, 2)`（現行）と `(6, 2)` を火選り4行で比べ、**乗算の比**を両 seed 帯で取る。");
        Console.WriteLine("**乗算持ち（熾のホタ・`PyreTrait`）がいるのは `火選り (ヒヨ×ホタ)` の1行だけ。**");
        Console.WriteLine();
        var bands = new (string Tag, int From, int Seeds)[] { ("A 帯 0..199", 0, 200), ("B 帯 200..599", 200, 400) };
        var rows4 = fvBuilds.Where(b => b.F.Occupied().Any(o => ReferenceEquals(o.Def, UnitCatalog.Hiyo))).ToArray();
        foreach ((string tag, int from, int seeds) in bands)
        {
            double[] WinsIn(Formation f, FavorRule? rule)
            {
                var v = new double[fvStages.Count];
                for (int w = 0; w < fvStages.Count; w++)
                {
                    int win = 0;
                    for (int seed = from; seed < from + seeds; seed++)
                        if (BattleEngine.Run(f, fvStages[w].Enemy, seed, false, favor: rule).PlayerWon) win++;
                    v[w] = win * 100.0 / seeds;
                }
                return v;
            }
            Console.WriteLine($"## {tag}");
            Console.WriteLine();
            Console.WriteLine("| 行 | 乗算 | (4,2) | (6,2) | 伸び | 情報セル (4,2) → (6,2) |");
            Console.WriteLine("|---|:-:|--:|--:|--:|--:|");
            double pyre = 0; var plainGains = new List<double>();
            foreach (var b in rows4)
            {
                bool hasPyre = b.F.Occupied().Any(o => o.Def.Traits.Contains(TraitId.Pyre));
                double[] a = WinsIn(b.F, new FavorRule(4, 2));
                double[] c = WinsIn(b.F, new FavorRule(6, 2));
                double gain = c.Average() - a.Average();
                Console.WriteLine($"| {b.Name} | {(hasPyre ? "**あり**" : "—")} | {a.Average():0.0}% | {c.Average():0.0}% "
                                + $"| **{gain:+0.0;-0.0;0.0}** | {FvInfo(a)} → {FvInfo(c)} |");
                if (hasPyre) pyre = gain; else plainGains.Add(gain);
                Console.Out.Flush();
            }
            Console.WriteLine();
            double row2 = plainGains.Count > 0 ? plainGains[0] : 0;
            double mean = plainGains.Count > 0 ? plainGains.Average() : 0;
            Console.WriteLine($"- **行1 ÷ 行2（指示書と同じ形）: {pyre:0.0} ÷ {row2:0.0} = "
                            + $"{(Math.Abs(row2) > 0.05 ? (pyre / row2).ToString("0.00") : "—（分母が 0）")}**");
            Console.WriteLine($"- **行1 ÷ 乗算なし3行の平均: {pyre:0.0} ÷ {mean:0.0} = "
                            + $"{(Math.Abs(mean) > 0.05 ? (pyre / mean).ToString("0.00") : "—（分母が 0）")}**");
            Console.WriteLine();
        }
        Console.WriteLine("**判定**: 比が 2.0 未満なら `(6,2)` を採る。2.0 以上なら `Gain` はホタ専用のノブと判定して上げない。");
        Console.WriteLine();
        return;
    }

    // ---- 掃引だけ --------------------------------------------------------------------
    if (fvMode == "sweep")
    {
        Console.WriteLine("# 移設後の掃引（第60期 §4）");
        Console.WriteLine();
        Console.WriteLine("**4点だけ。** 移設で代金の相手の集合が変わっている可能性があるので、");
        Console.WriteLine("`(4, 4)` が現行値 `(4, 2)` を上回るかどうかが「集合が縮んだ」ことの独立な検算になる。");
        Console.WriteLine("**各点の対照は V2（素体）で足りる**（体の値段はノブで動かない）。");
        Console.WriteLine();
        var pts = new (string Tag, int G, int L)[] { ("現行 (4/2)", 4, 2), ("a (4/4)", 4, 4), ("b (6/2)", 6, 2), ("c (2/2)", 2, 2) };
        Console.WriteLine("| 行 | 版 | 第1波 | 第2波 | 第3波 | 第4波 | 第5波 | 平均 | 素体との差 | 配った | 撒いた | 情報セル |");
        Console.WriteLine("|---|---|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|");
        foreach (var b in fvRows)
        {
            double[] pv = FvWins(FvV2(b.F), null);
            Console.WriteLine($"| {b.Name} | V2 素体（手番） {FvCells(pv)}| **{pv.Average():0.0}%** | — | — | — | {FvInfo(pv)} |");
            foreach (var p in pts)
            {
                var rule = new FavorRule(p.G, p.L);
                double[] v = FvWins(FvV1(b.F), rule);
                double give = 0, take = 0;
                for (int w = 0; w < fvStages.Count; w++)
                {
                    FvStat z = FvMeasure(FvV1(b.F), fvStages[w].Enemy, rule);
                    give += z.Given / fvStages.Count; take += z.Taken / fvStages.Count;
                }
                Console.WriteLine($"| | {p.Tag} {FvCells(v)}| **{v.Average():0.0}%** | {v.Average() - pv.Average():+0.0;-0.0;0.0} "
                                + $"| {give:0.00} | {take:0.00} | {FvInfo(v)} |");
                Console.Out.Flush();
            }
        }
        Console.WriteLine();
        return;
    }

    // ---- 主表 ------------------------------------------------------------------------
    Console.WriteLine(fvAlt ? "# 移設の主表（別 seed 帯 200..599 の追試）" : "# 移設の主表（第60期）");
    Console.WriteLine();
    Console.WriteLine($"seed {fvFrom}..{fvFrom + fvSeeds - 1}。**V1（移設）は第60期に採用したので `UnitCatalog.Hiyo` そのもの**——");
    Console.WriteLine("**V1 の5波が `docs/balance.md` と一致することがこの診断の検算**（第36期 `gullet belly4` と同じ形）。");
    Console.WriteLine("V0 = 移設前（`OnTurnStart`）／V2 = 移設 + 素体（同数値・特性なし。**機構の帰属**）／");
    Console.WriteLine("V3 = 移設前の素体（`V0 − V3` が第58期の機構の帰属）。**V0 / V2 / V3 は診断のローカルの `UnitDef`。**");
    Console.WriteLine();

    Console.WriteLine("## 1. 勝率（4行 × 5波）");
    Console.WriteLine();
    Console.WriteLine("| 行 | 版 | 第1波 | 第2波 | 第3波 | 第4波 | 第5波 | 平均 | 情報セル | V1−V0 | V1−V2 |");
    Console.WriteLine("|---|---|--:|--:|--:|--:|--:|--:|--:|--:|--:|");
    var attr = new List<(string Name, double A, double B, int I0, int I1)>();
    foreach (var b in fvRows)
    {
        double[] v0 = FvWins(FvV0(b.F), null);
        double[] v1 = FvWins(FvV1(b.F), null);
        double[] v2 = FvWins(FvV2(b.F), null);
        double[] v3 = FvWins(FvV3(b.F), null);
        Console.WriteLine($"| {b.Name} | V0 移設前 {FvCells(v0)}| **{v0.Average():0.0}%** | {FvInfo(v0)} | — | — |");
        Console.WriteLine($"| | **V1 移設（現行）** {FvCells(v1)}| **{v1.Average():0.0}%** | **{FvInfo(v1)}** "
                        + $"| **{v1.Average() - v0.Average():+0.0;-0.0;0.0}** | **{v1.Average() - v2.Average():+0.0;-0.0;0.0}** |");
        Console.WriteLine($"| | V2 素体（手番） {FvCells(v2)}| **{v2.Average():0.0}%** | {FvInfo(v2)} | — | — |");
        Console.WriteLine($"| | V3 素体（移設前） {FvCells(v3)}| **{v3.Average():0.0}%** | {FvInfo(v3)} "
                        + $"| （V0−V3 = {v0.Average() - v3.Average():+0.0;-0.0;0.0}） | |");
        attr.Add((b.Name, v1.Average() - v0.Average(), v1.Average() - v2.Average(), FvInfo(v0), FvInfo(v1)));
        Console.Out.Flush();
    }
    Console.WriteLine();
    Console.WriteLine($"**帰属（V1 − V0）の4行平均: {attr.Average(a => a.A):+0.0;-0.0;0.0}pt** "
                    + $"／ **機構の帰属（V1 − V2）の4行平均: {attr.Average(a => a.B):+0.0;-0.0;0.0}pt**");
    Console.WriteLine($"**情報セルの合計: V0 {attr.Sum(a => a.I0)} → V1 {attr.Sum(a => a.I1)}**");
    Console.WriteLine();

    // ---- 計数 ------------------------------------------------------------------------
    Console.WriteLine("## 2. 計数（5波の平均）");
    Console.WriteLine();
    Console.WriteLine("`発火` は強化か弱体を1体でも配った手番、`空振り` は盤上に燃えている味方が1体もいなかった手番。");
    Console.WriteLine("`燃体` / `非燃体` は延べ体数、`配った` / `撒いた` は量。`熾火へ` は乗算持ちへ配った量。");
    Console.WriteLine();
    Console.WriteLine("| 行 | 版 | 発火 | 空振り | 燃体 | 非燃体 | 配った | 撒いた | 熾火へ | ヒヨ振り | ヒヨ与ダメ | 味方総与ダメ | ヒヨ寿命T |");
    Console.WriteLine("|---|---|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|");
    var q2 = new List<(string Name, double T0, double T1, double G0, double G1)>();
    foreach (var b in fvRows)
    {
        var acc = new Dictionary<string, FvStat>();
        foreach ((string tag, Formation f) in new[] { ("V0 移設前", FvV0(b.F)), ("V1 移設", FvV1(b.F)) })
        {
            var agg = new FvStat();
            for (int w = 0; w < fvStages.Count; w++)
            {
                FvStat z = FvMeasure(f, fvStages[w].Enemy, null);
                agg.Fires += z.Fires / 5; agg.Idle += z.Idle / 5; agg.Whetted += z.Whetted / 5;
                agg.Dulled += z.Dulled / 5; agg.Given += z.Given / 5; agg.Taken += z.Taken / 5;
                agg.ToPyre += z.ToPyre / 5; agg.Swings += z.Swings / 5; agg.Dmg += z.Dmg / 5;
                agg.TeamDmg += z.TeamDmg / 5; agg.Life += z.Life / 5;
                foreach ((string k, double v) in z.DullTo)
                    agg.DullTo[k] = agg.DullTo.TryGetValue(k, out double a) ? a + v / 5 : v / 5;
                foreach ((string k, double v) in z.WhetTo)
                    agg.WhetTo[k] = agg.WhetTo.TryGetValue(k, out double a) ? a + v / 5 : v / 5;
            }
            acc[tag] = agg;
            Console.WriteLine($"| {(tag.StartsWith("V0") ? b.Name : "")} | {tag} | {agg.Fires:0.00} | {agg.Idle:0.00} "
                            + $"| {agg.Whetted:0.00} | {agg.Dulled:0.00} | {agg.Given:0.00} | {agg.Taken:0.00} | {agg.ToPyre:0.00} "
                            + $"| {agg.Swings:0.00} | {agg.Dmg:0.0} | {agg.TeamDmg:0.0} | {agg.Life:0.0} |");
            Console.Out.Flush();
        }
        q2.Add((b.Name, acc["V0 移設前"].Taken, acc["V1 移設"].Taken, acc["V0 移設前"].Given, acc["V1 移設"].Given));

        // 受け手の内訳（Q1）
        Console.WriteLine($"| | **弱体の受け手 V0** | " + FvTop(acc["V0 移設前"].DullTo) + " |");
        Console.WriteLine($"| | **弱体の受け手 V1** | " + FvTop(acc["V1 移設"].DullTo) + " |");
        Console.WriteLine($"| | 強化の受け手 V0 | " + FvTop(acc["V0 移設前"].WhetTo) + " |");
        Console.WriteLine($"| | 強化の受け手 V1 | " + FvTop(acc["V1 移設"].WhetTo) + " |");
    }
    Console.WriteLine();
    Console.WriteLine("**Q2（`撒いた` の増減）**");
    Console.WriteLine();
    Console.WriteLine("| 行 | 撒いた V0 | 撒いた V1 | 差 | 配った V0 | 配った V1 | 差 |");
    Console.WriteLine("|---|--:|--:|--:|--:|--:|--:|");
    foreach (var q in q2)
        Console.WriteLine($"| {q.Name} | {q.T0:0.00} | {q.T1:0.00} | **{q.T1 - q.T0:+0.00;-0.00;0.00}** "
                        + $"| {q.G0:0.00} | {q.G1:0.00} | **{q.G1 - q.G0:+0.00;-0.00;0.00}** |");
    Console.WriteLine();

    // ---- Q4: 止まった手番 -------------------------------------------------------------
    Console.WriteLine("## 3. Q4 —— 移設で止まった手番（verbose・seed の先頭 50 本）");
    Console.WriteLine();
    Console.WriteLine("**痺れだけを数える。** 手番が飛ぶ経路は Phase 0-1 の5本で、ヒヨに効きうるのは痺れと死亡だけ。");
    Console.WriteLine("死亡と「決着して行動順ループが `break` した」は移設の前後で同じだけあるので、");
    Console.WriteLine("**新しい交絡になりうるのは痺れ1本**——`StatusSnapshot` の `痺` を数える");
    Console.WriteLine("（痺れは付いた次のターンの頭に立ち、その手番の先頭で消費される）。");
    Console.WriteLine();
    Console.WriteLine("| 行 | 波 | 痺れ V0/戦 | 痺れ V1/戦 | 生存T V1 | 撃った V1 | 差（死亡＋決着） |");
    Console.WriteLine("|---|---|--:|--:|--:|--:|--:|");
    double stun0All = 0, stun1All = 0;
    foreach (var b in fvRows)
    {
        for (int w = 0; w < fvStages.Count; w++)
        {
            double st0 = 0, st1 = 0, alive = 0, cast = 0;
            for (int seed = fvFrom; seed < fvFrom + 50; seed++)
            {
                var p0 = BattleEngine.Materialize(FvV0(b.F), BattleContext.PlayerTeam);
                int i0 = p0.FindIndex(u => u.Def.Id == "hiyo_ts");
                BattleResult r0 = BattleEngine.Run(p0, BattleEngine.Materialize(fvStages[w].Enemy, BattleContext.EnemyTeam), seed, verbose: true);
                st0 += r0.Events.Count(e => e.Kind == BattleEventKind.StatusSnapshot && e.TargetId == i0 && e.Text == "痺");

                var p1 = BattleEngine.Materialize(FvV1(b.F), BattleContext.PlayerTeam);
                int i1 = p1.FindIndex(u => u.Def.Id == "hiyo");
                BattleResult r1 = BattleEngine.Run(p1, BattleEngine.Materialize(fvStages[w].Enemy, BattleContext.EnemyTeam), seed, verbose: true);
                st1 += r1.Events.Count(e => e.Kind == BattleEventKind.StatusSnapshot && e.TargetId == i1 && e.Text == "痺");
                alive += r1.Events.Count(e => e.Kind == BattleEventKind.StatSnapshot && e.TargetId == i1);
                cast += r1.Events.Count(e => e.Kind == BattleEventKind.Skill && e.ActorId == i1);
            }
            Console.WriteLine($"| {(w == 0 ? b.Name : "")} | 第{w + 1}波 | {st0 / 50:0.00} | **{st1 / 50:0.00}** "
                            + $"| {alive / 50:0.00} | {cast / 50:0.00} | {(alive - cast) / 50:0.00} |");
            stun0All += st0 / 50; stun1All += st1 / 50;
            Console.Out.Flush();
        }
    }
    Console.WriteLine();
    Console.WriteLine($"**20 セルの合計で痺れは V0 {stun0All:0.00} 回/戦 → V1 {stun1All:0.00} 回/戦。**");
    Console.WriteLine("`差（死亡＋決着）` は移設に固有ではない——ヒヨが自分の手番の前に落ちたか、");
    Console.WriteLine("その手番が回る前に決着して `order` のループが `break` した回数。");
    Console.WriteLine();
    return;
}

// miasma モード: 瘴気（グザ）を手番へ降ろす（第61期）。
//
// **移設が動かす一番大きい量は「ターン頭の発火順」である。** ターンの順序は
// `TickStatuses` → `OnTurnStart`（**席順の昇順**）→ 行動順ループなので、
// `OnTurnStart` に置いた機構どうしの前後は**席の番号だけ**で決まる。瘴気と澱み喰い
// （ヴィオ）はどちらもターン頭で、グザがヴィオより前の席なら撒いた毒はその場で
// 吸い上げられて**味方は1点も払わない**——「毒の代金を誰が払うか」が席の左右で
// 切り替わる隠れた判断になっていた。手番（速5）へ降ろすと必ずヴィオが先になる。
//
// **版の切り替えは駒の側で行う**（`ActsOnPattern` は `UnitDef.Actions` を読むので
// 規則では切り替わらない）。診断のローカルに `UnitDef` を置き、`UnitCatalog` は触らない
// ——`gradient` / `aim` / `turn` と同じ扱い。
//
//     dotnet run --project BattleSim -c Release 0 miasma phase0  # 実装前の地図（発火順・出力・分母）
//     dotnet run --project BattleSim -c Release 0 miasma         # 主表 V0/V1/V2/V3 × 8行 × 5波 と Q1〜Q7
//     dotnet run --project BattleSim -c Release 0 miasma seat    # 席の入れ替えの追試（Q1 の直接の証拠）
//     dotnet run --project BattleSim -c Release 0 miasma alt     # 帰属の符号を別 seed 帯（200..599）で追試


if (focusId == "miasma" && (args.Length > 2 ? args[2] : "") == "phase0")
{
    var mpBuilds = CompareBuilds();
    IReadOnlyList<EnemyCatalog.Stage> mpStages = EnemyCatalog.Stages;
    const int MpSeeds = 200;   // compare / spread / turn / favor と同じ帯

    var mpRows = mpBuilds.Where(b => MsHas(b.F, UnitCatalog.Guza)).ToArray();

    Console.WriteLine("# 瘴気を手番へ降ろす前の地図（第61期 Phase 0）");
    Console.WriteLine();
    Console.WriteLine($"`dotnet run --project BattleSim -c Release 0 miasma phase0` の出力。seed 0..{MpSeeds - 1}。");
    Console.WriteLine("**盤面は1つも動かしていない**（`UnitCatalog.Guza` は `Actions` を持たないので");
    Console.WriteLine("`ActsOnPattern` が偽 ＝ `MiasmaTrait.OnTurnStart` が従来どおり発火する）。");
    Console.WriteLine();

    // ---- 0-1. 窓口 -------------------------------------------------------------------
    Console.WriteLine("## 0-1. 瘴気の窓口（指示書 §1-1）");
    Console.WriteLine();
    Console.WriteLine($"- `MiasmaTrait.PerTurn` = **{MiasmaTrait.PerTurn}**（敵全体）／ "
                    + $"`MiasmaTrait.AllyLeak` = **{MiasmaTrait.AllyLeak}**（味方全体・**自分を含む**）");
    Console.WriteLine("- 発火口: `OnTurnStart`（現行）／`OnAction`（移設後）。分岐は `Trait.ActsOnPattern`");
    Console.WriteLine("- ターンの順序: `TickStatuses`（**毒 → 燃焼** の2ループ）→ `OnTurnStart` → 行動順ループ");
    Console.WriteLine("- **毒のカウンタは刻んでも減らない**（`TickStatuses` の毒ループは `ApplyDamage` を呼ぶだけ）");
    Console.WriteLine($"- 毒喰らい（ベニ）の倍率 `DevourTrait.AllyPoisonMultiplier` = **{DevourTrait.AllyPoisonMultiplier}**"
                    + "（**味方の毒の刻みにだけ掛かる**。`TickStatuses` の毒ループの中）");
    Console.WriteLine($"- 澱み喰い（ヴィオ）の `BlightfedTrait.GainPerStack` = **{BlightfedTrait.GainPerStack}**"
                    + "（`OnTurnStart`・味方の毒を**全部 0 にして**攻撃力へ。**自分の毒は吸わない**）");
    Console.WriteLine($"- 澱み（ミオ）の `AmplifierTrait.Step` = **{AmplifierTrait.Step}**"
                    + "——**既に第11期に `OnAction` へ降りている**（速8。グザ 速5 より速い）");
    Console.WriteLine();
    Console.WriteLine("`StatusKeys.Poison` を**読んで分岐する**駒側の窓口:");
    Console.WriteLine();
    var mpReaders = new (TraitId Id, string Where, string What)[]
    {
        (TraitId.Blightfed, "OnTurnStart",   "味方の毒を全部吸って攻撃力 +4/層（自分の毒は除く）"),
        (TraitId.Devour,    "OnTurnStart",   "毒に侵された敵の数 × 4 を味方全体に回復"),
        (TraitId.Amplifier, "OnAction",      "毒に侵された敵の毒を +4／傷を持ち毒を持たない敵には毒 1 を置く（第89期）"),
        (TraitId.Contagion, "OnAnyDeath",    "毒に侵された駒が倒れると残りの敵へ毒が飛ぶ"),
        (TraitId.Torment,   "OnAfterAttack", "毒／痺れを負った相手を責める"),
    };
    Console.WriteLine("| 特性 | フック | 何をするか | 8行での枚数 |");
    Console.WriteLine("|---|---|---|--:|");
    foreach (var r in mpReaders)
        Console.WriteLine($"| {r.Id} | `{r.Where}` | {r.What} | {mpRows.Sum(b => FvCountTrait(b.F, r.Id))} |");
    Console.WriteLine();
    Console.WriteLine("engine 側の窓口は `TickStatuses` の毒ループ1本（第50期の一覧のとおり）。");
    Console.WriteLine();

    // ---- 0-2. 発火順の地図 -------------------------------------------------------------
    Console.WriteLine("## 0-2. `OnTurnStart` の発火順（指示書 §1-2）——**これが本題**");
    Console.WriteLine();
    Console.WriteLine("engine は `ctx.AllUnits.Where(IsAlive)` の順に `OnTurnStart` を回す。");
    Console.WriteLine("`_units` は `Run` が `player` → `enemy` の順に `Add` した並びで、");
    Console.WriteLine("`Formation.Occupied()` はスロット昇順に返す ＝ **味方はスロット昇順**。");
    Console.WriteLine();
    Console.WriteLine("`ターン頭で発火する同席者` は 澱み喰い（ヴィオ）と 毒喰らい（ベニ）の2つ。");
    Console.WriteLine("**グザが先なら**その場で吸われる／その場で回復に化ける ＝ **味方は毒を1点も払わない**。");
    Console.WriteLine("**グザが後なら**毒は次の `TickStatuses` まで残って**味方が刻まれる**。");
    Console.WriteLine();
    Console.WriteLine("| 行 | グザの席 | ヴィオ | ベニ | 現行の前後 | 移設後 |");
    Console.WriteLine("|---|:-:|:-:|:-:|---|---|");
    foreach (var b in mpRows)
    {
        int gs = b.F.Occupied().First(o => ReferenceEquals(o.Def, UnitCatalog.Guza)).Slot;
        int vs = MsHas(b.F, UnitCatalog.Vio)
               ? b.F.Occupied().First(o => ReferenceEquals(o.Def, UnitCatalog.Vio)).Slot : -1;
        int bs = MsHas(b.F, UnitCatalog.Beni)
               ? b.F.Occupied().First(o => ReferenceEquals(o.Def, UnitCatalog.Beni)).Slot : -1;
        string Rel(int s, string who) => s < 0 ? "—" : gs < s ? $"**グザ → {who}**" : $"{who} → グザ";
        var parts = new[] { Rel(vs, "ヴィオ"), Rel(bs, "ベニ") }.Where(x => x != "—").ToArray();
        string now = parts.Length == 0 ? "（同席者なし）" : string.Join(" / ", parts);
        Console.WriteLine($"| {b.Name} | {FormationRules.SeatNames[gs]} "
                        + $"| {(vs < 0 ? "—" : FormationRules.SeatNames[vs])} "
                        + $"| {(bs < 0 ? "—" : FormationRules.SeatNames[bs])} "
                        + $"| {now} "
                        + $"| {(parts.Length == 0 ? "（変わらない）" : "**「同席者 → グザ」に潰れる**")} |");
    }
    Console.WriteLine();

    // ---- 0-3. 手番を止めうる経路 --------------------------------------------------------
    Console.WriteLine("## 0-3. 移設後にグザの手番を止めうる経路（指示書 §1-3）");
    Console.WriteLine();
    Console.WriteLine("行動順ループが手番を飛ばす経路は5本——**痺れ／まどろみ／`CanAct` 偽／死亡／決着の `break`**。");
    Console.WriteLine();
    Console.WriteLine($"- **まどろみ**: `ColossusRule.Default.Slumber` = **{ColossusRule.Default.Slumber}**"
                    + "（既定で無効。しかも巨躯の保持者にしか立たない）");
    Console.WriteLine("- **`CanAct` 偽**: グザの特性は `Miasma` 1つで `CanAct` を上書きしない ＝ **原理的に通らない**");
    Console.WriteLine("- **痺れ**: 味方へ痺れを書けるのは 縛め（`Bind`・味方を1体縛る）と、");
    Console.WriteLine("  敵側の 縛め／断罪（`Condemn`・**ターン外に動いた駒**を罰する）。");
    Console.WriteLine("  **グザはターン外に動かない**ので断罪は原理的に当たらない");
    Console.WriteLine("- **死亡 / 決着**: 速5 は遅いので、**自分の手番が回る前に落ちる／決着する**回数を実測する（下表）");
    Console.WriteLine();
    Console.WriteLine("| 行 | 波 | 味方の縛め | 敵の縛め | 敵の断罪 | グザ寿命T | 決着T | 戦死率 |");
    Console.WriteLine("|---|:-:|--:|--:|--:|--:|--:|--:|");
    foreach (var b in mpRows)
    {
        for (int w = 0; w < mpStages.Count; w++)
        {
            double life = 0, turns = 0, dead = 0;
            for (int seed = 0; seed < MpSeeds; seed++)
            {
                BattleResult r = BattleEngine.Run(b.F, mpStages[w].Enemy, seed, verbose: false);
                turns += r.Turns;
                if (r.TallyByUnit.TryGetValue("guza", out UnitTally? t))
                {
                    life += t.LastActiveTurn;
                    if (t.Deaths > 0) dead++;
                }
            }
            Console.WriteLine($"| {(w == 0 ? b.Name : "")} | 第{w + 1}波 "
                            + $"| {FvCountTrait(b.F, TraitId.Bind)} "
                            + $"| {mpStages[w].Enemy.Occupied().Count(o => o.Def.Traits.Contains(TraitId.Bind))} "
                            + $"| {mpStages[w].Enemy.Occupied().Count(o => o.Def.Traits.Contains(TraitId.Condemn))} "
                            + $"| {life / MpSeeds:0.00} | {turns / MpSeeds:0.00} | {dead * 100.0 / MpSeeds:0.0}% |");
            Console.Out.Flush();
        }
    }
    Console.WriteLine();

    // ---- 0-4. グザの現在の出力 ----------------------------------------------------------
    Console.WriteLine("## 0-4. グザの現在の出力（指示書 §1-4）——**素体対照を置くかの判定**");
    Console.WriteLine();
    Console.WriteLine("**攻2。** `与ダメ/戦` が 10 を下回るなら移設で捨てる出力は無視できる（指示書 §1-4）。");
    Console.WriteLine();
    Console.WriteLine("| 行 | 振り/戦 | 与ダメ/戦 | 撒いた(敵) | 漏らした(味) | 味方の刻み額面 | 敵の刻み額面 |");
    Console.WriteLine("|---|--:|--:|--:|--:|--:|--:|");
    double swAll = 0, dmgAll = 0; int cells = 0;
    foreach (var b in mpRows)
    {
        double sw = 0, dmg = 0, tf = 0, ta = 0, bp = 0, be = 0;
        for (int w = 0; w < mpStages.Count; w++)
            for (int seed = 0; seed < MpSeeds; seed++)
            {
                BattleResult r = BattleEngine.Run(b.F, mpStages[w].Enemy, seed, verbose: false);
                if (r.TallyByUnit.TryGetValue("guza", out UnitTally? t)) { sw += t.Attacks; dmg += t.DamageToEnemy; }
                tf += r.MiasmaToFoe; ta += r.MiasmaToAlly;
                bp += r.PoisonBitePlayer; be += r.PoisonBiteEnemy;
            }
        double n = MpSeeds * mpStages.Count;
        Console.WriteLine($"| {b.Name} | {sw / n:0.00} | **{dmg / n:0.0}** | {tf / n:0.0} | {ta / n:0.0} "
                        + $"| {bp / n:0.0} | {be / n:0.0} |");
        swAll += sw / n; dmgAll += dmg / n; cells++;
        Console.Out.Flush();
    }
    Console.WriteLine();
    Console.WriteLine($"**8行平均: 振り {swAll / cells:0.00} 回/戦 ／ 与ダメ {dmgAll / cells:0.0}/戦。**");
    Console.WriteLine(dmgAll / cells < 10
        ? "→ **10/戦 を下回る。** 指示書 §1-4 により素体対照は省略してよいが、**費用が小さいので主表には置く**。"
        : "→ **10/戦 を上回る。** 素体対照（V3）を必ず置く。");
    Console.WriteLine();

    // ---- 0-5. 分母の検算 ----------------------------------------------------------------
    Console.WriteLine("## 0-5. 分母の検算（指示書 §1-5・§1-6・§1-7）");
    Console.WriteLine();
    var mpHiyo = mpBuilds.Where(b => MsHas(b.F, UnitCatalog.Hiyo)).ToArray();
    int overlap = mpBuilds.Count(b => MsHas(b.F, UnitCatalog.Guza) && MsHas(b.F, UnitCatalog.Hiyo));
    Console.WriteLine($"- **グザを含む行: {mpRows.Length}** / ヒヨを含む行: {mpHiyo.Length} / "
                    + $"**両者が同席する行: {overlap}**（指示書の前提の検算）");
    Console.WriteLine($"- `CompareBuilds()` の行数: **{mpBuilds.Length}** × {mpStages.Count} 波 = "
                    + $"**{mpBuilds.Length * mpStages.Count} セル**（うちグザを含まない "
                    + $"{mpBuilds.Length - mpRows.Length} 行 = **{(mpBuilds.Length - mpRows.Length) * mpStages.Count} セル**が受け入れ基準2）");
    var mpPrimary = Baseline.PrimaryRows.Where(n => mpBuilds.Any(b => b.Name == n && MsHas(b.F, UnitCatalog.Guza))).ToArray();
    var mpPrimaryHiyo = Baseline.PrimaryRows.Where(n => mpBuilds.Any(b => b.Name == n && MsHas(b.F, UnitCatalog.Hiyo))).ToArray();
    Console.WriteLine($"- **主判定 {Baseline.PrimaryRows.Length} 行のうちグザを含む行: {mpPrimary.Length}** "
                    + $"—— {(mpPrimary.Length == 0 ? "なし" : string.Join(" / ", mpPrimary))}");
    Console.WriteLine($"- 主判定 {Baseline.PrimaryRows.Length} 行のうちヒヨを含む行: **{mpPrimaryHiyo.Length}**"
                    + $"{(mpPrimaryHiyo.Length == 0 ? "（§4 の係数は歯止めの分母を動かさない）" : "")}");
    Console.WriteLine();

    var mpIdx = Baseline.PrimaryRows.Select(n => Array.FindIndex(mpBuilds, b => b.Name == n)).Where(i => i >= 0).ToArray();
    double mpFifth = 0;
    foreach (int i in mpIdx)
    {
        int win = 0;
        for (int seed = 0; seed < MpSeeds; seed++)
            if (BattleEngine.Run(mpBuilds[i].F, mpStages[^1].Enemy, seed, false).PlayerWon) win++;
        mpFifth += win * 100.0 / MpSeeds;
    }
    mpFifth /= mpIdx.Length;
    Console.WriteLine($"- **主判定 {mpIdx.Length} 行の第五波平均: {mpFifth:0.0}%** ／ "
                    + $"歯止め **{Baseline.PrimaryFifthFloor:0.0}%** ／ "
                    + $"**余裕 {mpFifth - Baseline.PrimaryFifthFloor:+0.0;-0.0;0.0}pt**");
    Console.WriteLine($"- 動きうるのは主判定のうち **{mpPrimary.Length} 行**なので、その行が第五波で 0% まで落ちても");
    Console.WriteLine($"  平均の低下は高々 **{mpPrimary.Length * 100.0 / mpIdx.Length:0.0}pt** —— 実測は §3 Q6 で出す。");
    Console.WriteLine();
    return;
}

if (focusId == "miasma")
{
    var msBuilds = CompareBuilds();
    IReadOnlyList<EnemyCatalog.Stage> msStages = EnemyCatalog.Stages;
    string msMode = args.Length > 2 ? args[2] : "";
    bool msAlt = msMode == "alt";
    int msFrom = msAlt ? 200 : 0;              // alt は別 seed 帯（200..599）
    int msSeeds = msAlt ? 400 : 200;           // それ以外は compare と同じ帯

    var msRows = msBuilds.Where(b => MsHas(b.F, UnitCatalog.Guza)).ToArray();

    UnitDef msAct = MsActDef(), msCyc = MsCycleDef(), msPlain = MsPlainDef();
    Formation MsV0(Formation f) => f;                                  // 現行（ターン頭）＝ 盤面そのもの
    Formation MsV1(Formation f) => FvSwap(f, UnitCatalog.Guza, msAct);  // 移設
    Formation MsV2(Formation f) => FvSwap(f, UnitCatalog.Guza, msCyc);  // 周期
    Formation MsV3(Formation f) => FvSwap(f, UnitCatalog.Guza, msPlain);// 素体（手番）

    // グザの id は版で変わるので、駒側の集計は「グザの席にいる駒」で引く。
    var msIds = new[] { "guza", "guza_act", "guza_cyc", "guza_plain" };

    MsStat MsMeasure(Formation f, Formation enemy)
    {
        var mine = f.Occupied().Select(o => o.Def.Id).ToHashSet();
        var z = new MsStat();
        for (int seed = msFrom; seed < msFrom + msSeeds; seed++)
        {
            BattleResult r = BattleEngine.Run(f, enemy, seed, verbose: false);
            if (r.PlayerWon) z.Win++;
            z.Turns += r.Turns;
            z.Fires += r.MiasmaFires; z.ToFoe += r.MiasmaToFoe; z.ToAlly += r.MiasmaToAlly;
            z.BiteAlly += r.PoisonBitePlayer; z.BiteFoe += r.PoisonBiteEnemy;
            z.TicksAlly += r.PoisonTicksPlayer; z.TicksFoe += r.PoisonTicksEnemy;
            foreach (string id in msIds)
                if (r.TallyByUnit.TryGetValue(id, out UnitTally? t))
                { z.Swings += t.Attacks; z.Dmg += t.DamageToEnemy; z.Life += t.LastActiveTurn; }
            z.TeamDmg += r.TallyByUnit.Where(kv => mine.Contains(kv.Key)).Sum(kv => kv.Value.DamageToEnemy);
            z.TeamTaken += r.TallyByUnit.Where(kv => mine.Contains(kv.Key)).Sum(kv => kv.Value.DamageTaken);
            // ヴィオ／ベニの取り分。ヴィオの攻撃力は tally に無いので**与ダメで代理する**。
            if (r.TallyByUnit.TryGetValue("vio", out UnitTally? tv)) z.VioDmg += tv.DamageToEnemy;
            if (r.TallyByUnit.TryGetValue("beni", out UnitTally? tb)) z.BeniHeal += tb.Healed;
        }
        double n = msSeeds;
        z.Win = z.Win * 100 / n; z.Turns /= n;
        z.Fires /= n; z.ToFoe /= n; z.ToAlly /= n;
        z.BiteAlly /= n; z.BiteFoe /= n; z.TicksAlly /= n; z.TicksFoe /= n;
        z.Swings /= n; z.Dmg /= n; z.Life /= n; z.TeamDmg /= n; z.TeamTaken /= n;
        z.VioDmg /= n; z.BeniHeal /= n;
        return z;
    }
    double[] MsWins(Formation f)
    {
        var v = new double[msStages.Count];
        for (int w = 0; w < msStages.Count; w++)
        {
            int win = 0;
            for (int seed = msFrom; seed < msFrom + msSeeds; seed++)
                if (BattleEngine.Run(f, msStages[w].Enemy, seed, false).PlayerWon) win++;
            v[w] = win * 100.0 / msSeeds;
        }
        return v;
    }
    // 情報セルは**2つの定義を併記する**（CLAUDE.md「情報セルの定義が2つある」）。
    // Info59 = 第59期 9-1（`0 < x < 100` を第2〜5波）。指示書 Q4 の「澱み喰いは現在 1」はこちら。
    static int MsInfo59(double[] v) => v.Skip(1).Count(x => x > 0.0 && x < 100.0);
    static int MsInfoMid(double[] v) => v.Count(x => x > 5.0 && x < 95.0);
    static string MsCells(double[] v) => string.Concat(v.Select(x => $"| {x:0.0}% "));

    // ---- ミオとの順序（第61期の追加測定）------------------------------------------------
    //
    // 主表で V1 の損が大きい上位4行（`追撃×毒` −37.8 / `澱み喰い` −37.1 / `毒+耐久` −18.1 /
    // `毒` −12.5）は、**澱み（ミオ・`Amplifier`）を含む4行とちょうど一致する。**
    // ミオは速8で**既に第11期に `OnAction` へ降りている**ので、グザ（速5）を手番へ降ろすと
    // **必ずミオより後**になる——第1ターンにミオが増幅する毒が盤上に1層も無くなる。
    //
    // **切り分けはミオを同数値・特性なしの素体に差し替えて測る**（`ScaleRule` が作れなかった
    // 「その効果だけを 0 にできるノブ」の代わり。第47期の作法）。`Actions` は残すので、
    // 差は**増幅そのもの**だけに閉じる。
    if (msMode == "mio")
    {
        var msMioPlain = new UnitDef
        {
            Id = "mio_plain", Name = "澱みのミオ（素体）", MaxHp = UnitCatalog.Mio.MaxHp,
            Attack = UnitCatalog.Mio.Attack, Speed = UnitCatalog.Mio.Speed,
            Traits = Array.Empty<TraitId>(), Pattern = UnitCatalog.Mio.Pattern,
            Actions = new UnitAction[] { new(ActionKind.Skill, Label: "水を眺めている") }
        };
        Console.WriteLine("# 追加測定 —— V1 の損はミオとの順序か");
        Console.WriteLine();
        Console.WriteLine($"seed {msFrom}..{msFrom + msSeeds - 1}。**ミオを同数値・特性なしの素体に差し替えて測り直す**");
        Console.WriteLine("（`Actions` は残すので差は増幅そのものだけ）。");
        Console.WriteLine("**ミオを外すと V1−V0 の損が縮む**なら、損の出どころは");
        Console.WriteLine("「グザがミオより後になったこと」であって「手番へ降ろしたこと一般」ではない。");
        Console.WriteLine();
        Console.WriteLine("| 行 | ミオ | V0 | V1 | **V1−V0** | 敵の刻み V0 | V1 |");
        Console.WriteLine("|---|---|--:|--:|--:|--:|--:|");
        foreach (var b in msRows)
        {
            if (!MsHas(b.F, UnitCatalog.Mio)) continue;
            foreach ((string tag, Formation baseF) in new[]
                     { ("そのまま", b.F), ("**素体**", FvSwap(b.F, UnitCatalog.Mio, msMioPlain)) })
            {
                double[] v0 = MsWins(MsV0(baseF));
                double[] v1 = MsWins(MsV1(baseF));
                double be0 = 0, be1 = 0;
                for (int w = 0; w < msStages.Count; w++)
                {
                    be0 += MsMeasure(MsV0(baseF), msStages[w].Enemy).BiteFoe / 5;
                    be1 += MsMeasure(MsV1(baseF), msStages[w].Enemy).BiteFoe / 5;
                }
                Console.WriteLine($"| {(tag == "そのまま" ? b.Name : "")} | {tag} | {v0.Average():0.0}% | {v1.Average():0.0}% "
                                + $"| **{v1.Average() - v0.Average():+0.0;-0.0;0.0}** | {be0:0.0} | {be1:0.0} |");
                Console.Out.Flush();
            }
        }
        Console.WriteLine();
        Console.WriteLine("参考——**ミオを含まない4行**（`毒+ベニ+ラウ` / `毒爆弾` / `毒→被弾強化` / `逸らし`）の");
        Console.WriteLine("V1−V0 は主表のとおり −2.7 / −7.2 / −1.7 / +2.1 で、**桁が違う。**");
        Console.WriteLine();
        return;
    }

    // ---- 席の入れ替え（Q1）------------------------------------------------------------
    if (msMode == "seat")
    {
        Console.WriteLine("# Q1 —— 順序の判断は消えたか（席の入れ替えの追試）");
        Console.WriteLine();
        Console.WriteLine($"seed {msFrom}..{msFrom + msSeeds - 1}。**駒は1枚も差し替えない**——");
        Console.WriteLine("同じ5枚のまま、グザと `OnTurnStart` の同席者の席だけを交換する。");
        Console.WriteLine();
        Console.WriteLine("**V0 では味方の毒の刻みが席で変わり、V1 では変わらない**なら、");
        Console.WriteLine("「席の左右が毒の代金の払い手を決めていた判断」が移設で消えたことの直接の証拠になる。");
        Console.WriteLine();
        var msPairs = new (string Row, UnitDef Other, string OtherName)[]
        {
            ("澱み喰い (グザ×ヴィオ)", UnitCatalog.Vio,  "ヴィオ"),
            ("毒爆弾 (ラウ×ヴィオ)",   UnitCatalog.Vio,  "ヴィオ"),
            ("毒+耐久 (ベニ×トウ)",    UnitCatalog.Beni, "ベニ"),
            ("毒+ベニ+ラウ",           UnitCatalog.Beni, "ベニ"),
        };
        Console.WriteLine("| 行 | 版 | 席 | 第1波 | 第2波 | 第3波 | 第4波 | 第5波 | 平均 | 味方の刻み | 漏らした | 撒いた回 |");
        Console.WriteLine("|---|---|---|--:|--:|--:|--:|--:|--:|--:|--:|--:|");
        foreach (var pr in msPairs)
        {
            var b = msBuilds.First(x => x.Name == pr.Row);
            foreach ((string tag, Func<Formation, Formation> ver) in new (string, Func<Formation, Formation>)[]
                     { ("V0 現行", MsV0), ("**V1 移設**", MsV1) })
            {
                foreach ((string seatTag, Formation baseF) in new[]
                         { ("そのまま", b.F), ($"グザ↔{pr.OtherName}", MsSwapSeats(b.F, UnitCatalog.Guza, pr.Other)) })
                {
                    Formation f = ver(baseF);
                    double[] v = MsWins(f);
                    double bite = 0, leak = 0, fires = 0;
                    for (int w = 0; w < msStages.Count; w++)
                    {
                        MsStat z = MsMeasure(f, msStages[w].Enemy);
                        bite += z.BiteAlly / msStages.Count;
                        leak += z.ToAlly / msStages.Count;
                        fires += z.Fires / msStages.Count;
                    }
                    Console.WriteLine($"| {(seatTag == "そのまま" && tag.StartsWith("V0") ? b.Name : "")} | {tag} | {seatTag} "
                                    + MsCells(v) + $"| **{v.Average():0.0}%** | **{bite:0.0}** | {leak:0.0} | {fires:0.00} |");
                    Console.Out.Flush();
                }
            }
        }
        Console.WriteLine();
        Console.WriteLine("`味方の刻み` は毒の刻みの**額面**（毒喰らいの倍率を掛けた後・肩代わり／破片／軛を通す前）。");
        Console.WriteLine("`漏らした` は瘴気が味方へ撒いた層の総量、`撒いた回` は瘴気の発火回数。");
        Console.WriteLine();
        return;
    }

    // ---- 主表 ---------------------------------------------------------------------------
    Console.WriteLine(msAlt ? "# 瘴気の移設の主表（別 seed 帯 200..599 の追試）" : "# 瘴気の移設の主表（第61期）");
    Console.WriteLine();
    Console.WriteLine($"seed {msFrom}..{msFrom + msSeeds - 1}。**V0（現行・`OnTurnStart`）は `UnitCatalog.Guza` そのもの**——");
    Console.WriteLine("**V0 の5波が `docs/balance.md` と一致することがこの診断の検算**。");
    Console.WriteLine("V1 = 移設（`[Skill]`）／V2 = 周期（`[Skill, Attack]`・供給が半分）／");
    Console.WriteLine("V3 = 移設 + 素体（同数値・特性なし。**V1 − V3 が機構の帰属**）。");
    Console.WriteLine("**V1 / V2 / V3 は診断のローカルの `UnitDef`。`UnitCatalog` は1バイトも触っていない。**");
    Console.WriteLine();

    Console.WriteLine("## 1. 勝率（8行 × 5波）");
    Console.WriteLine();
    Console.WriteLine("`情報セル` は2つの定義を併記する——`59期` は `0 < x < 100` を第2〜5波（指示書 Q4 の定義）、");
    Console.WriteLine("`中間帯` は `5 < x < 95` を全5波（`spread` §1 の定義）。**別の量なので混ぜない。**");
    Console.WriteLine();
    Console.WriteLine("| 行 | 版 | 第1波 | 第2波 | 第3波 | 第4波 | 第5波 | 平均 | 情報 59期 | 中間帯 | 対 V0 |");
    Console.WriteLine("|---|---|--:|--:|--:|--:|--:|--:|--:|--:|--:|");
    var msAttr = new List<(string Name, double A1, double A2, double A3, int I0, int I1, int I2, bool Vio, bool Beni)>();
    foreach (var b in msRows)
    {
        double[] v0 = MsWins(MsV0(b.F));
        double[] v1 = MsWins(MsV1(b.F));
        double[] v2 = MsWins(MsV2(b.F));
        double[] v3 = MsWins(MsV3(b.F));
        Console.WriteLine($"| {b.Name} | V0 現行 {MsCells(v0)}| **{v0.Average():0.0}%** | {MsInfo59(v0)} | {MsInfoMid(v0)} | — |");
        Console.WriteLine($"| | **V1 移設** {MsCells(v1)}| **{v1.Average():0.0}%** | **{MsInfo59(v1)}** | {MsInfoMid(v1)} "
                        + $"| **{v1.Average() - v0.Average():+0.0;-0.0;0.0}** |");
        Console.WriteLine($"| | **V2 周期** {MsCells(v2)}| **{v2.Average():0.0}%** | **{MsInfo59(v2)}** | {MsInfoMid(v2)} "
                        + $"| **{v2.Average() - v0.Average():+0.0;-0.0;0.0}** |");
        Console.WriteLine($"| | V3 素体（手番） {MsCells(v3)}| **{v3.Average():0.0}%** | {MsInfo59(v3)} | {MsInfoMid(v3)} "
                        + $"| （V1−V3 = {v1.Average() - v3.Average():+0.0;-0.0;0.0}） |");
        msAttr.Add((b.Name, v1.Average() - v0.Average(), v2.Average() - v0.Average(), v1.Average() - v3.Average(),
                    MsInfo59(v0), MsInfo59(v1), MsInfo59(v2),
                    MsHas(b.F, UnitCatalog.Vio), MsHas(b.F, UnitCatalog.Beni)));
        Console.Out.Flush();
    }
    Console.WriteLine();
    Console.WriteLine("### Q2 / Q3 —— 帰属と符号");
    Console.WriteLine();
    Console.WriteLine("**閾値 |帰属| ≥ 1.5pt**（第57期。それ未満は 0 と読む）。");
    Console.WriteLine();
    Console.WriteLine("| 行 | 型 | V1−V0 | 判定 | V2−V0 | 判定 | V1−V3（機構） |");
    Console.WriteLine("|---|---|--:|:-:|--:|:-:|--:|");
    static string Sign(double x) => Math.Abs(x) < 1.5 ? "0" : x > 0 ? "**＋**" : "**−**";
    foreach (var a in msAttr)
        Console.WriteLine($"| {a.Name} | {(a.Vio ? "**ヴィオ行**" : a.Beni ? "**ベニ行**" : "—")} "
                        + $"| {a.A1:+0.0;-0.0;0.0} | {Sign(a.A1)} | {a.A2:+0.0;-0.0;0.0} | {Sign(a.A2)} | {a.A3:+0.0;-0.0;0.0} |");
    Console.WriteLine();
    Console.WriteLine($"**8行平均: V1−V0 {msAttr.Average(a => a.A1):+0.0;-0.0;0.0}pt ／ "
                    + $"V2−V0 {msAttr.Average(a => a.A2):+0.0;-0.0;0.0}pt ／ "
                    + $"V1−V3（機構）{msAttr.Average(a => a.A3):+0.0;-0.0;0.0}pt**");
    var vioRows = msAttr.Where(a => a.Vio).ToArray();
    var beniRows = msAttr.Where(a => a.Beni).ToArray();
    Console.WriteLine($"**ヴィオ行 {vioRows.Length} 行の V2−V0 平均: {vioRows.Average(a => a.A2):+0.0;-0.0;0.0}pt ／ "
                    + $"ベニ行 {beniRows.Length} 行: {beniRows.Average(a => a.A2):+0.0;-0.0;0.0}pt**");
    Console.WriteLine($"**Q4（情報セル 59期の合計）: V0 {msAttr.Sum(a => a.I0)} → V1 {msAttr.Sum(a => a.I1)} / V2 {msAttr.Sum(a => a.I2)}**");
    Console.WriteLine();

    // ---- 計数 ---------------------------------------------------------------------------
    Console.WriteLine("## 2. 計数（5波の平均・1戦あたり）");
    Console.WriteLine();
    Console.WriteLine("`撒いた回` は瘴気の発火回数、`敵へ` / `味方へ` は撒いた層の総量（味方側は撒いた本人を含む）。");
    Console.WriteLine("`味方の刻み` / `敵の刻み` は毒の刻みの**額面**（倍率を掛けた後・肩代わり／破片／軛を通す前）。");
    Console.WriteLine("`ヴィオ与ダメ` はヴィオの攻撃力の代理（`AtkBonus` は `UnitTally` に無い）。");
    Console.WriteLine();
    Console.WriteLine("| 行 | 版 | 撒いた回 | 敵へ | 味方へ | 味方の刻み | 敵の刻み | グザ振り | グザ与ダメ | グザ寿命T | 味方総与ダメ | 味方総被ダメ | 決着T | ヴィオ与ダメ |");
    Console.WriteLine("|---|---|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|");
    var msQ5 = new List<(string Name, double F0, double F1, double F2, double B0, double B1, double B2)>();
    foreach (var b in msRows)
    {
        var acc = new Dictionary<string, MsStat>();
        foreach ((string tag, Formation f) in new[] { ("V0 現行", MsV0(b.F)), ("V1 移設", MsV1(b.F)), ("V2 周期", MsV2(b.F)) })
        {
            var agg = new MsStat();
            for (int w = 0; w < msStages.Count; w++)
            {
                MsStat z = MsMeasure(f, msStages[w].Enemy);
                agg.Fires += z.Fires / 5; agg.ToFoe += z.ToFoe / 5; agg.ToAlly += z.ToAlly / 5;
                agg.BiteAlly += z.BiteAlly / 5; agg.BiteFoe += z.BiteFoe / 5;
                agg.Swings += z.Swings / 5; agg.Dmg += z.Dmg / 5; agg.Life += z.Life / 5;
                agg.TeamDmg += z.TeamDmg / 5; agg.TeamTaken += z.TeamTaken / 5;
                agg.Turns += z.Turns / 5; agg.VioDmg += z.VioDmg / 5; agg.BeniHeal += z.BeniHeal / 5;
            }
            acc[tag] = agg;
            Console.WriteLine($"| {(tag.StartsWith("V0") ? b.Name : "")} | {tag} | {agg.Fires:0.00} | {agg.ToFoe:0.0} | {agg.ToAlly:0.0} "
                            + $"| **{agg.BiteAlly:0.0}** | {agg.BiteFoe:0.0} | {agg.Swings:0.00} | {agg.Dmg:0.0} | {agg.Life:0.00} "
                            + $"| {agg.TeamDmg:0.0} | {agg.TeamTaken:0.0} | {agg.Turns:0.00} | {agg.VioDmg:0.0} |");
            Console.Out.Flush();
        }
        msQ5.Add((b.Name, acc["V0 現行"].Fires, acc["V1 移設"].Fires, acc["V2 周期"].Fires,
                          acc["V0 現行"].BiteAlly, acc["V1 移設"].BiteAlly, acc["V2 周期"].BiteAlly));
    }
    Console.WriteLine();

    // ---- Q5: 消えた発火 --------------------------------------------------------------------
    Console.WriteLine("## 3. Q5 —— 新しい交絡（消えた発火と、増えた味方の刻み）");
    Console.WriteLine();
    Console.WriteLine("**痺れは 0 枚（Phase 0-3）**——8行に縛めは1枚も無く、敵側の縛めも 0、");
    Console.WriteLine("断罪はグザがターン外に動かないので原理的に当たらない。");
    Console.WriteLine("したがって移設で消える発火は**「自分の手番が回る前に落ちた／決着した」だけ**である。");
    Console.WriteLine();
    Console.WriteLine("| 行 | 撒いた回 V0 | V1 | 差 | V2 | V2/V1 | 味方の刻み V0 | V1 | 差 | V2 |");
    Console.WriteLine("|---|--:|--:|--:|--:|--:|--:|--:|--:|--:|");
    foreach (var q in msQ5)
        Console.WriteLine($"| {q.Name} | {q.F0:0.00} | {q.F1:0.00} | **{q.F1 - q.F0:+0.00;-0.00;0.00}** | {q.F2:0.00} "
                        + $"| {(q.F1 > 0 ? q.F2 / q.F1 : 0):0.00} | {q.B0:0.0} | {q.B1:0.0} | **{q.B1 - q.B0:+0.0;-0.0;0.0}** | {q.B2:0.0} |");
    Console.WriteLine();
    Console.WriteLine($"**8行平均: 撒いた回 V0 {msQ5.Average(q => q.F0):0.00} → V1 {msQ5.Average(q => q.F1):0.00} "
                    + $"→ V2 {msQ5.Average(q => q.F2):0.00}**（V2/V1 = {(msQ5.Average(q => q.F1) > 0 ? msQ5.Average(q => q.F2) / msQ5.Average(q => q.F1) : 0):0.00}）");
    Console.WriteLine($"**味方の刻み V0 {msQ5.Average(q => q.B0):0.0} → V1 {msQ5.Average(q => q.B1):0.0} → V2 {msQ5.Average(q => q.B2):0.0}**");
    Console.WriteLine();

    // ---- Q6: 歯止め ----------------------------------------------------------------------
    Console.WriteLine("## 4. Q6 —— 歯止め（主判定19行の第五波）");
    Console.WriteLine();
    var msIdx = Baseline.PrimaryRows.Select(n => Array.FindIndex(msBuilds, b => b.Name == n)).Where(i => i >= 0).ToArray();
    Console.WriteLine("| 版 | 主判定19行の第五波平均 | 歯止め | 余裕 | 動いた行 |");
    Console.WriteLine("|---|--:|--:|--:|---|");
    foreach ((string tag, Func<Formation, Formation> ver) in new (string, Func<Formation, Formation>)[]
             { ("V0 現行", MsV0), ("**V1 移設**", MsV1), ("**V2 周期**", MsV2) })
    {
        double sum = 0; var moved = new List<string>();
        foreach (int i in msIdx)
        {
            Formation f = MsHas(msBuilds[i].F, UnitCatalog.Guza) ? ver(msBuilds[i].F) : msBuilds[i].F;
            int win = 0;
            for (int seed = msFrom; seed < msFrom + msSeeds; seed++)
                if (BattleEngine.Run(f, msStages[^1].Enemy, seed, false).PlayerWon) win++;
            double v = win * 100.0 / msSeeds;
            sum += v;
            if (MsHas(msBuilds[i].F, UnitCatalog.Guza)) moved.Add($"{msBuilds[i].Name} {v:0.0}%");
        }
        double avg = sum / msIdx.Length;
        Console.WriteLine($"| {tag} | **{avg:0.0}%** | {Baseline.PrimaryFifthFloor:0.0}% "
                        + $"| **{avg - Baseline.PrimaryFifthFloor:+0.0;-0.0;0.0}pt** | {string.Join(" / ", moved)} |");
        Console.Out.Flush();
    }
    Console.WriteLine();
    return;
}

// blaze モード: 破裂（ゾト）に着火を足す（第59期）。
//
// 燃焼は第57〜58期で「通貨」になったが、**書き手はボルグ1枚しかない**。
// 燃焼を読む駒はすべてボルグとの AND ゲートになり、燃焼が出る行はボルグを含む行に閉じている。
// `BomberTrait` のコメントは既に「味方も巻き込む。**これが他の駒の起点になる**」と書いてある
// ——その起点を実際に使う期。**駒は1枚も作らない**（ロスターの残り枠を消費しない）。
//
// **engine に新しい規則は足さない。** `BomberTrait.OnDeath` の既存のループの中で
// `ctx.Ignite` を呼ぶだけ。`Ignite` は乱数を1つも引かない（`Roll` を呼ばない）ので、
// **着火を足しても乱数列は動かない**——受け入れ基準2（ゾトを含まない行が不変）がこれを検算する。
//
//     dotnet run --project BattleSim -c Release 0 blaze phase0   # 実装前の地図（破裂時点の盤面・層の現況・情報セル）
//     dotnet run --project BattleSim -c Release 0 blaze          # 主表（A / B / V0）・計数・Q2・Q4・Q6
//     dotnet run --project BattleSim -c Release 0 blaze rows     # 試験行（死軸×ホタ / 死軸×ヒヨ）だけ
//     dotnet run --project BattleSim -c Release 0 blaze seats    # 試験行の席（reseat の写し）
//     dotnet run --project BattleSim -c Release 0 blaze confirm  # 配置の追試（seed 200..599）
//     dotnet run --project BattleSim -c Release 0 blaze alt      # 帰属の符号を別 seed 帯で追試
if (focusId == "blaze" && (args.Length > 2 ? args[2] : "") == "phase0")
{
    var bpBuilds = CompareBuilds();
    IReadOnlyList<EnemyCatalog.Stage> bpStages = EnemyCatalog.Stages;
    const int BpSeeds = 200;   // compare / spread / whet / burn / favor と同じ帯

    static bool BpHas(Formation f, UnitDef d) => f.Occupied().Any(o => ReferenceEquals(o.Def, d));

    Console.WriteLine("# 火種の地図（第59期 Phase 0）");
    Console.WriteLine();
    Console.WriteLine($"`dotnet run --project BattleSim -c Release 0 blaze phase0` の出力。seed 0..{BpSeeds - 1}。");
    Console.WriteLine("**盤面は1つも動かしていない**（`BlazeRule` が未実装の時点で測っている）。");
    Console.WriteLine();

    // ---- 0-1. BomberTrait の現況 -------------------------------------------------------
    Console.WriteLine("## 0-1. `BomberTrait` の現況（指示書 §1-1）");
    Console.WriteLine();
    Console.WriteLine($"- `EnemyBlast` = **{BomberTrait.EnemyBlast}** ／ `AllyBlast` = **{BomberTrait.AllyBlast}**");
    Console.WriteLine("- `OnDeath` は `LivingMembersShuffled` を**敵側・味方側の2回**回す（味方側は `ally == self` を飛ばす）");
    Console.WriteLine("- **`Shuffle` は `Roll` を消費する**が、それは今もしている——");
    Console.WriteLine("  **既存のループの中で `ctx.Ignite` を呼べば新しい `Roll` は1つも増えない**");
    Console.WriteLine("  （`BattleContext.Ignite` は `SetCounter` / `Log` / 計数だけで、乱数を引かない）");
    Console.WriteLine($"- `BurnRules.Damage` = **{BurnRules.Damage}** ／ `BurnRules.Turns` = **{BurnRules.Turns}**（触らない）");
    Console.WriteLine();

    // ---- 0-2. ゾトの行とボルグの行 -----------------------------------------------------
    Console.WriteLine("## 0-2. ゾトを含む行 / ボルグを含む行（指示書 §1-2）");
    Console.WriteLine();
    var bpZoto = bpBuilds.Where(b => BpHas(b.F, UnitCatalog.Zoto)).ToArray();
    var bpBorg = bpBuilds.Where(b => BpHas(b.F, UnitCatalog.Borg)).ToArray();
    Console.WriteLine("| 行 | ゾトの席 | 同席する駒 |");
    Console.WriteLine("|---|:-:|---|");
    foreach (var b in bpZoto)
    {
        int seat = b.F.Occupied().First(o => ReferenceEquals(o.Def, UnitCatalog.Zoto)).Slot;
        string mates = string.Join(" / ", b.F.Occupied()
            .Where(o => !ReferenceEquals(o.Def, UnitCatalog.Zoto))
            .Select(o => $"{FormationRules.SeatNames[o.Slot]}:{o.Def.Name}"));
        Console.WriteLine($"| {b.Name} | {FormationRules.SeatNames[seat]} | {mates} |");
    }
    Console.WriteLine();
    Console.WriteLine($"- **ゾトを含む行: {bpZoto.Length}** ／ **ボルグを含む行: {bpBorg.Length}**");
    Console.WriteLine($"- ボルグの行: {string.Join(" / ", bpBorg.Select(b => b.Name))}");
    int bpBoth = bpBuilds.Count(b => BpHas(b.F, UnitCatalog.Zoto) && BpHas(b.F, UnitCatalog.Borg));
    Console.WriteLine($"- **両者が同席する行: {bpBoth}**（指示書の前提の検算）");
    Console.WriteLine($"- `CompareBuilds()` の行数: **{bpBuilds.Length}**（× {bpStages.Count} 波 = **{bpBuilds.Length * bpStages.Count} セル**）");
    Console.WriteLine();

    // ---- 0-3. 破裂の時点の盤面 ---------------------------------------------------------
    //
    // イベント列を頭から舐めて生存集合を保つ。**ゾトの Death イベントは OnDeath（破裂）より
    // 先に Emit される**（`BattleEngine.Kill` の並び）ので、そのイベントを処理し終えた時点の
    // 生存集合が「破裂が当たる相手」そのものになる。
    Console.WriteLine("## 0-3. 破裂の時点の盤面（**着火の上限**・指示書 §1-3）");
    Console.WriteLine();
    Console.WriteLine("**イベント列から実測**（`Death` は `OnDeath` より先に Emit されるので、");
    Console.WriteLine("そのイベントを処理し終えた生存集合が「破裂が当たる相手」そのもの）。");
    Console.WriteLine("`破裂/戦` は1戦あたりの破裂回数——**蘇生（ヴェル）で2回以上になりうる**。");
    Console.WriteLine("`味方` / `敵` は**初回の破裂の瞬間**に生きていた数（ゾト自身を除く）。");
    Console.WriteLine();
    Console.WriteLine("| 行 | 波 | 破裂/戦 | 破裂率 | 初回T | 味方 | 敵 | 決着T |");
    Console.WriteLine("|---|:-:|--:|--:|--:|--:|--:|--:|");
    var bpUp = new List<(string Name, double A, double E)>();
    foreach (var b in bpZoto)
    {
        int zid = BattleEngine.Materialize(b.F, BattleContext.PlayerTeam).FindIndex(u => u.Def.Id == "zoto");
        int pc = b.F.Occupied().Count();
        double sumA = 0, sumE = 0; int cntAll = 0;
        for (int w = 0; w < bpStages.Count; w++)
        {
            int ec = bpStages[w].Enemy.Occupied().Count();
            double bursts = 0, hit = 0, turn = 0, allies = 0, foes = 0, turns = 0;
            for (int seed = 0; seed < BpSeeds; seed++)
            {
                BattleResult r = BattleEngine.Run(b.F, bpStages[w].Enemy, seed, verbose: true);
                turns += r.Turns;
                var alive = new HashSet<int>();
                var team = new Dictionary<int, int>();
                for (int i = 0; i < pc; i++) { alive.Add(i); team[i] = 0; }
                for (int i = pc; i < pc + ec; i++) { alive.Add(i); team[i] = 1; }
                bool first = true;
                foreach (BattleEvent e in r.Events)
                {
                    int id = e.TargetId ?? -1;
                    if (e.Kind == BattleEventKind.Summon) { team[id] = e.Team ?? 0; alive.Add(id); }
                    else if (e.Kind == BattleEventKind.Revive) alive.Add(id);
                    else if (e.Kind == BattleEventKind.Death)
                    {
                        alive.Remove(id);
                        if (id != zid) continue;
                        bursts++;
                        if (!first) continue;
                        first = false; hit++; turn += e.Turn;
                        allies += alive.Count(x => team[x] == 0);
                        foes += alive.Count(x => team[x] == 1);
                    }
                }
            }
            double n = BpSeeds;
            Console.WriteLine($"| {b.Name} | 第{w + 1}波 | {bursts / n:0.00} | {hit * 100 / n:0.0}% "
                + $"| {(hit > 0 ? turn / hit : 0):0.00} | **{(hit > 0 ? allies / hit : 0):0.00}** "
                + $"| **{(hit > 0 ? foes / hit : 0):0.00}** | {turns / n:0.0} |");
            if (hit > 0) { sumA += allies / hit; sumE += foes / hit; cntAll++; }
            Console.Out.Flush();
        }
        bpUp.Add((b.Name, cntAll > 0 ? sumA / cntAll : 0, cntAll > 0 ? sumE / cntAll : 0));
    }
    Console.WriteLine();
    Console.WriteLine("### 供給量の予測（**測る前に書く**）");
    Console.WriteLine();
    Console.WriteLine("A 案（味方だけ）= `味方` の平均、B 案（全員）= `味方 + 敵` の平均。");
    Console.WriteLine("**破裂は一度きり**なので、これが `着火` の期待値の上限になる（増える余地は蘇生の分だけ）。");
    Console.WriteLine();
    Console.WriteLine("| 行 | A 案の予測（着火/戦） | B 案の予測（着火/戦） |");
    Console.WriteLine("|---|--:|--:|");
    foreach ((string nm, double a, double e) in bpUp)
        Console.WriteLine($"| {nm} | {a:0.00} | {a + e:0.00} |");
    Console.WriteLine();

    // ---- 0-4. リィカの層の現況 ---------------------------------------------------------
    Console.WriteLine("## 0-4. リィカの層の現況（**Q2 の分母**・指示書 §1-4）");
    Console.WriteLine();
    Console.WriteLine("`味方の死` は1戦あたりの味方側の `Deaths` の合計（蘇生されて再度倒れると2）。");
    Console.WriteLine("`リィカ攻(終)` は最後に観測した `StatSnapshot`（＝ターン頭の `CurrentAttack`）。");
    Console.WriteLine($"リィカは `ModifyAttack` を持たないので **`AtkBonus` = その値 − {UnitCatalog.Rica.Attack}**。");
    Console.WriteLine($"層は死亡ごとに `NecroTrait.AllyStep` = {NecroTrait.AllyStep} 積み、毎ターン1つ薄れる。");
    Console.WriteLine($"**{NecroTrait.AwakenAt} 層以上で薙ぎに変わる**（覚醒）。");
    Console.WriteLine();
    Console.WriteLine("| 行 | 波 | 味方の死/戦 | リィカ攻(終) | `AtkBonus` | リィカ与ダメ/戦 | 勝率 |");
    Console.WriteLine("|---|:-:|--:|--:|--:|--:|--:|");
    foreach (var b in bpZoto.Where(b => BpHas(b.F, UnitCatalog.Rica)))
    {
        var pl0 = BattleEngine.Materialize(b.F, BattleContext.PlayerTeam);
        int rid = pl0.FindIndex(u => u.Def.Id == "rica");
        var pids = pl0.Select(u => u.Def.Id).ToHashSet();
        for (int w = 0; w < bpStages.Count; w++)
        {
            double deaths = 0, atk = 0, dmg = 0, win = 0;
            for (int seed = 0; seed < BpSeeds; seed++)
            {
                BattleResult r = BattleEngine.Run(b.F, bpStages[w].Enemy, seed, verbose: true);
                if (r.PlayerWon) win++;
                foreach ((string id, UnitTally t) in r.TallyByUnit)
                    if (pids.Contains(id)) deaths += t.Deaths;
                if (r.TallyByUnit.TryGetValue("rica", out UnitTally? rt)) dmg += rt.DamageToEnemy;
                int last = UnitCatalog.Rica.Attack;
                foreach (BattleEvent e in r.Events)
                    if (e.Kind == BattleEventKind.StatSnapshot && e.TargetId == rid) last = e.Amount;
                atk += last;
            }
            double n = BpSeeds;
            Console.WriteLine($"| {b.Name} | 第{w + 1}波 | {deaths / n:0.00} | {atk / n:0.0} "
                + $"| **{atk / n - UnitCatalog.Rica.Attack:+0.0;-0.0;0.0}** | {dmg / n:0.0} | {win * 100 / n:0.0}% |");
            Console.Out.Flush();
        }
    }
    Console.WriteLine();

    // ---- 0-5. 情報セル -----------------------------------------------------------------
    Console.WriteLine("## 0-5. 情報セルの表（棚卸し §4-1 の 1）");
    Console.WriteLine();
    Console.WriteLine("第31期 3-1 の定義: **第2〜5波のうち勝率が開区間 (0, 100) にあるセル**。");
    Console.WriteLine("第1波は全行 100.0% なので分母に入れない。");
    Console.WriteLine();
    Console.WriteLine("| # | 行 | 第1波 | 第2波 | 第3波 | 第4波 | 第5波 | **情報セル** |");
    Console.WriteLine("|--:|---|--:|--:|--:|--:|--:|--:|");
    var bpInfo = new List<(string Name, int N, double[] W)>();
    for (int i = 0; i < bpBuilds.Length; i++)
    {
        var v = new double[bpStages.Count];
        for (int w = 0; w < bpStages.Count; w++)
        {
            int wins = 0;
            for (int seed = 0; seed < BpSeeds; seed++)
                if (BattleEngine.Run(bpBuilds[i].F, bpStages[w].Enemy, seed, false).PlayerWon) wins++;
            v[w] = wins * 100.0 / BpSeeds;
        }
        int info = v.Skip(1).Count(x => x > 0 && x < 100);
        bpInfo.Add((bpBuilds[i].Name, info, v));
        Console.WriteLine($"| {i + 1} | {bpBuilds[i].Name} " + string.Concat(v.Select(x => $"| {x:0.0}% "))
            + $"| **{info}** |");
        Console.Out.Flush();
    }
    Console.WriteLine();
    Console.WriteLine("### 情報セルが 0 または 1 の行（全部名指しする）");
    Console.WriteLine();
    Console.WriteLine("| 行 | 情報セル | 第2波 | 第3波 | 第4波 | 第5波 |");
    Console.WriteLine("|---|--:|--:|--:|--:|--:|");
    foreach ((string nm, int info, double[] v) in bpInfo.Where(x => x.N <= 1))
        Console.WriteLine($"| {nm} | **{info}** " + string.Concat(v.Skip(1).Select(x => $"| {x:0.0}% ")) + "|");
    Console.WriteLine();
    Console.WriteLine($"- 情報セルの合計: **{bpInfo.Sum(x => x.N)}** ／ 平均 **{bpInfo.Average(x => (double)x.N):0.00}**");
    Console.WriteLine($"- 0 の行: **{bpInfo.Count(x => x.N == 0)}** ／ 1 の行: **{bpInfo.Count(x => x.N == 1)}**");
    Console.WriteLine();

    // ---- 0-6. 波ごとの平均（歯止めの現在値）--------------------------------------------
    Console.WriteLine("## 0-6. 波ごとの平均（指示書 §1-6）");
    Console.WriteLine();
    Console.WriteLine("| 分母 | 第1波 | 第2波 | 第3波 | 第4波 | 第5波 |");
    Console.WriteLine("|---|--:|--:|--:|--:|--:|");
    Console.WriteLine($"| **{bpInfo.Count} 行（現行）** "
        + string.Concat(Enumerable.Range(0, bpStages.Count).Select(w => $"| {bpInfo.Average(x => x.W[w]):0.0} ")) + "|");
    var bp56 = bpInfo.Take(56).ToList();
    Console.WriteLine("| 56 行（第53期の分母） "
        + string.Concat(Enumerable.Range(0, bpStages.Count).Select(w => $"| {bp56.Average(x => x.W[w]):0.0} ")) + "|");
    Console.WriteLine();
    return;
}

// ---- ここから先は本体（phase0 は上で return 済み）---------------------------------------
if (focusId == "blaze")
{
    var bzBuilds = CompareBuilds();
    IReadOnlyList<EnemyCatalog.Stage> bzStages = EnemyCatalog.Stages;
    const int BzSeeds = 200;   // compare / spread / whet / burn / favor と同じ帯

    string bzMode = args.Length > 2 ? args[2] : "";
    // 主版の既定は採用版（B）。`a` を渡すと A 案で回る。
    string bzPick = args.Length > 3 ? args[3].ToLowerInvariant() : "b";

    var bzV0 = new BlazeRule(BlazeTargets.None);
    var bzA = new BlazeRule(BlazeTargets.AllyOnly);
    var bzB = new BlazeRule(BlazeTargets.Both);
    // C は**ノブではなく対照**。B の「味方に在庫を作る」と「敵に打点を足す」を割るためだけにある。
    var bzC = new BlazeRule(BlazeTargets.FoeOnly);
    BlazeRule bzMain = bzPick == "a" ? bzA : bzB;
    string bzMainName = bzPick == "a" ? "A（味方だけ）" : "B（全員・採用版）";

    static bool BzHas(Formation f, UnitDef d) => f.Occupied().Any(o => ReferenceEquals(o.Def, d));
    // **既存7行**（第58期までの死軸）と**試験行2本**（第59期に足した）を分けて持つ。
    // どちらもゾトを含むので、名前で割る。
    var bzRowNames = new[] { "死軸×ホタ", "死軸×ヒヨ" };
    var bzTargets = bzBuilds.Where(b => BzHas(b.F, UnitCatalog.Zoto)
                                     && !bzRowNames.Any(n => b.Name.Contains(n))).ToArray();

    // 試験行（指示書 §2-3）。**既存7行は組み替えない。**
    // どちらも `死の連鎖 (リィカ軸)` の**ムグ1枠だけ**を差し替えた形——
    // 1枠差にしておくと compare の既存行がそのまま対照になる。
    // 席は `blaze seats` / `blaze confirm` で決める（ここは探索の出発点）。
    // **採用後は `CompareBuilds()` から引く**（配置は `confirm` で決めた形）。
    // 席の探索そのものは `blaze seats` / `blaze confirm` が 120 通りを回すので、
    // ここが探索の出発点であることに変わりはない。
    var bzRows = bzBuilds.Where(b => bzRowNames.Any(n => b.Name.Contains(n))).ToArray();

    // 敵側の def.Id 集合。**味方 = これに入っていない**（胞子のような戦闘中に湧いた味方も味方に入る）。
    HashSet<string> BzFoeIds(Formation enemy) => enemy.Occupied().Select(o => o.Def.Id).ToHashSet();

    BzStat MeasureBz(Formation f, Formation enemy, BlazeRule rule, int from, int to)
    {
        var z = new BzStat();
        var foeIds = BzFoeIds(enemy);
        var pl0 = BattleEngine.Materialize(f, BattleContext.PlayerTeam);
        int rid = pl0.FindIndex(u => u.Def.Id == "rica");
        for (int seed = from; seed < to; seed++)
        {
            BattleResult r = BattleEngine.Run(f, enemy, seed, verbose: true, blaze: rule);
            if (r.PlayerWon) z.Win++;
            z.Turns += r.Turns;
            foreach ((string id, UnitTally t) in r.TallyByUnit)
            {
                bool ally = !foeIds.Contains(id);
                z.Lit += t.BurnLit; z.Relit += t.BurnRelit; z.LitAlly += t.BurnLitAlly;
                if (ally)
                {
                    z.BurnDmgA += t.BurnTaken; z.BurnDeathA += t.BurnDeaths;
                    z.Deaths += t.Deaths;
                }
                else
                {
                    z.BurnDmgF += t.BurnTaken; z.BurnDeathF += t.BurnDeaths;
                }
                if (!z.Atk.ContainsKey(id)) { z.Atk[id] = 0; z.BurnAtk[id] = 0; z.Dmg[id] = 0; }
                z.Atk[id] += t.Attacks; z.BurnAtk[id] += t.BurnAttacks; z.Dmg[id] += t.DamageToEnemy;
            }
            if (rid >= 0)
            {
                int last = UnitCatalog.Rica.Attack;
                foreach (BattleEvent e in r.Events)
                    if (e.Kind == BattleEventKind.StatSnapshot && e.TargetId == rid) last = e.Amount;
                z.RicaAtk += last;
            }
        }
        double n = to - from;
        z.Win = z.Win * 100 / n; z.Turns /= n;
        z.Lit /= n; z.Relit /= n; z.LitAlly /= n;
        z.BurnDmgA /= n; z.BurnDmgF /= n; z.BurnDeathA /= n; z.BurnDeathF /= n;
        z.Deaths /= n; z.RicaAtk /= n;
        foreach (string k in z.Atk.Keys.ToList())
        { z.Atk[k] /= n; z.BurnAtk[k] /= n; z.Dmg[k] /= n; }
        return z;
    }

    (double[] Wins, BzStat Z) BzAll(Formation f, BlazeRule rule, int from = 0, int to = BzSeeds)
    {
        var wins = new double[bzStages.Count];
        var acc = new BzStat();
        for (int w = 0; w < bzStages.Count; w++)
        {
            BzStat z = MeasureBz(f, bzStages[w].Enemy, rule, from, to);
            wins[w] = z.Win;
            acc.Turns += z.Turns; acc.Lit += z.Lit; acc.Relit += z.Relit; acc.LitAlly += z.LitAlly;
            acc.BurnDmgA += z.BurnDmgA; acc.BurnDmgF += z.BurnDmgF;
            acc.BurnDeathA += z.BurnDeathA; acc.BurnDeathF += z.BurnDeathF;
            acc.Deaths += z.Deaths; acc.RicaAtk += z.RicaAtk;
            foreach ((string k, double v) in z.Atk)
            {
                if (!acc.Atk.ContainsKey(k)) { acc.Atk[k] = 0; acc.BurnAtk[k] = 0; acc.Dmg[k] = 0; }
                acc.Atk[k] += v; acc.BurnAtk[k] += z.BurnAtk[k]; acc.Dmg[k] += z.Dmg[k];
            }
        }
        double m = bzStages.Count;
        acc.Win = wins.Average();
        acc.Turns /= m; acc.Lit /= m; acc.Relit /= m; acc.LitAlly /= m;
        acc.BurnDmgA /= m; acc.BurnDmgF /= m; acc.BurnDeathA /= m; acc.BurnDeathF /= m;
        acc.Deaths /= m; acc.RicaAtk /= m;
        foreach (string k in acc.Atk.Keys.ToList())
        { acc.Atk[k] /= m; acc.BurnAtk[k] /= m; acc.Dmg[k] /= m; }
        return (wins, acc);
    }

    double[] BzWins(Formation f, BlazeRule rule, int from = 0, int to = BzSeeds)
    {
        var v = new double[bzStages.Count];
        for (int w = 0; w < bzStages.Count; w++)
        {
            int wins = 0;
            for (int seed = from; seed < to; seed++)
                if (BattleEngine.Run(f, bzStages[w].Enemy, seed, false, blaze: rule).PlayerWon) wins++;
            v[w] = wins * 100.0 / (to - from);
        }
        return v;
    }

    static string BzCells(double[] w) => string.Concat(w.Select(x => $" {x:0.0}% |"));
    static int BzInfo(double[] w) => w.Skip(1).Count(x => x > 0 && x < 100);
    static double BzGet(Dictionary<string, double> d, string k) => d.TryGetValue(k, out double v) ? v : 0;

    Console.WriteLine("# 火種（blaze）");
    Console.WriteLine();
    Console.WriteLine($"`dotnet run --project BattleSim -c Release 0 blaze [モード] [a|b]` の出力。");
    Console.WriteLine($"**docs/ には置かない**（標準出力で読むだけ）。seed 0..{BzSeeds - 1}。数字は特記なければ**1戦あたりの平均**。");
