                {
                    if (BattleEngine.Run(b.F, gdStages[w].Enemy, seed, false,
                            goad: new GoadRule(0, false)).PlayerWon) a++;
                    if (BattleEngine.Run(b.F, gdStages[w].Enemy, seed, false,
                            goad: new GoadRule(9, true)).PlayerWon) c++;
