        Console.WriteLine("|--:|---|:-:|--:|---|--:|--:|:-:|--:|");

        var ldRed = new List<(string Name, int Info, string Near, double R, double MaxD, bool Prim, double R5)>();
        foreach (var b in ldCompare)
        {
            if (!bal.TryGetValue(b.Name, out double[]? v)) continue;
