    }

    // ==============================================================================
    // unique —— §4-2 の実測版。**規則を1本ずつ切って、動く行を数える。**
    //
    // 特性の数え上げ（表B）は下限でしかない（第109期の `刻み×澱み` は特性では引けない）。
    // **「その規則を切ったときに動く行が 1 行だけ」なら、その行がその規則の唯一の観測点。**
    // ==============================================================================
    if (ldMode == "unique")
    {
        // 切った版。**「何もしない状態」が一意に決まる規則だけを並べる**
        // ——強度のノブ（`ScaleRule` / `ThinBladeRule` / `SeverRule.Wait` など）は
        // 「切る」が定義できないので入れない。off の中身は列に出してあるので後から検算できる。
        var ldKnobs = new (string Name, string Off, Func<Formation, Formation, int, BattleResult> Run)[]
        {
            ("`yoke`",        "Active = False",                    (p, e, s) => BattleEngine.Run(p, e, s, false, yoke: new YokeRule(YokeTrait.Cap, false))),
            ("`hush`",        "Active = False",                    (p, e, s) => BattleEngine.Run(p, e, s, false, hush: new HushRule(false))),
            ("`martyr`",      "RedirectPercent = 0",               (p, e, s) => BattleEngine.Run(p, e, s, false, martyr: new MartyrRule(0))),
            ("`expose`",      "MaxPerBattle = 0",                  (p, e, s) => BattleEngine.Run(p, e, s, false, expose: new ExposeRule(0))),
            ("`shove`",       "Penalty = 0",                       (p, e, s) => BattleEngine.Run(p, e, s, false, shove: new ShoveRule(0))),
            ("`bear`",        "ArmorPerDull = 0",                  (p, e, s) => BattleEngine.Run(p, e, s, false, bear: new BearRule(0))),
            ("`goad`",        "Boost = 0, Mark = False",           (p, e, s) => BattleEngine.Run(p, e, s, false, goad: new GoadRule(0, false))),
            ("`finisher`",    "Multiplier = 1, Consume = False",   (p, e, s) => BattleEngine.Run(p, e, s, false, finisher: new FinisherRule(1, false))),
            ("`favor`",       "Gain = 0, Loss = 0",                (p, e, s) => BattleEngine.Run(p, e, s, false, favor: new FavorRule(0, 0))),
            ("`blaze`",       "Targets = None",                    (p, e, s) => BattleEngine.Run(p, e, s, false, blaze: new BlazeRule(BlazeTargets.None))),
            ("`suture`",      "対照:Side = Foe",                        (p, e, s) => BattleEngine.Run(p, e, s, false, suture: new SutureRule(SutureSide.Foe))),
            ("`spillWound`",  "Enabled = False",                   (p, e, s) => BattleEngine.Run(p, e, s, false, spillWound: new SpillWoundRule(false))),
            ("`mend`",        "対照:Side = Plain",                      (p, e, s) => BattleEngine.Run(p, e, s, false, mend: new MendRule(MendSide.Plain))),
            ("`woundIgnite`", "Enabled = False",                   (p, e, s) => BattleEngine.Run(p, e, s, false, woundIgnite: new IgniteRule(false))),
            ("`gather`",      "Enabled = False",                   (p, e, s) => BattleEngine.Run(p, e, s, false, gather: new GatherRule(false))),
            ("`soak`",        "Poison/Burn = False, DullPerKind = 0", (p, e, s) => BattleEngine.Run(p, e, s, false, soak: new SoakRule(false, false, 0))),
            ("`betray`",      "Enabled = False",                   (p, e, s) => BattleEngine.Run(p, e, s, false, betray: new BetrayRule(false))),
            ("`encore`",      "Enabled = False",                   (p, e, s) => BattleEngine.Run(p, e, s, false, encore: new EncoreRule(false))),
            ("`loose`",       "Shove = False",                     (p, e, s) => BattleEngine.Run(p, e, s, false, loose: new LooseRule(false))),
            ("`menderCost`",  "対照:Percent = 100（第106期より前）",     (p, e, s) => BattleEngine.Run(p, e, s, false, menderCost: new MenderCostRule(100))),
            ("`colossus`",    "Regurgitate/Refund = False",        (p, e, s) => BattleEngine.Run(p, e, s, false, colossus: new ColossusRule(ColossusRule.Default.Percent, ColossusRule.Default.DamagePerGain, false, false, ColossusRule.Default.SlumberThreshold, false, ColossusRule.Default.RefundPercent))),
            ("`taillight`",   "対照:Mode = OwnTurn（V0）",              (p, e, s) => BattleEngine.Run(p, e, s, false, taillight: new TaillightRule(YieldMode.OwnTurn))),
        };

        Console.WriteLine("# 第111期 §4-2（実測）—— 規則を1本ずつ切って、動く行を数える");
        Console.WriteLine();
        Console.WriteLine($"`compare` {ldCompare.Length} 行 × {ldStages.Count} 波 × seed 0..{LdSeeds - 1}。"
            + "**「切った版と既定が1セルでも違う行」を数える。動く行が 1 行だけなら、その行がその規則の唯一の観測点。**");
        Console.WriteLine();
        Console.WriteLine("`種別` の **off** は「その規則が何もしない版」、**対照** は「採用前の版」"
            + "（`mend` / `suture` は側を戻す・`menderCost` は代金を戻す・`taillight` は V0）。**どちらも (b) には同じに効く**"
            + "——問いは「その規則の判断がどの行に届いているか」だから。");
        Console.WriteLine();
        Console.WriteLine("強度のノブ（`scale` / `thinBlade` / `sever` / `divert` / `relay` / `funnel` など）は"
            + "**「切る」が一意に定義できない**ので入れていない。**`rage` も入れていない**"
            + "——`RageMode.Amount` では `Gain` が読まれないので、`Gain = 0` は「切った版」にならない（初版はここを取り違えた）。");
        Console.WriteLine();

        var baseCells = new double[ldCompare.Length][];
        Parallel.For(0, ldCompare.Length, b => baseCells[b] = LdCells(ldCompare[b].F, 0, LdSeeds));

        Console.WriteLine("| 規則 | 種別 | 当てた版 | 動いた行 | 唯一の観測点 | 行名（10 行まで） |");
        Console.WriteLine("|---|:-:|---|--:|:-:|---|");
        var soleBy = new Dictionary<string, List<string>>(StringComparer.Ordinal);
        foreach (var k in ldKnobs)
        {
            var moved = new bool[ldCompare.Length];
            Parallel.For(0, ldCompare.Length, b =>
            {
                for (int w = 0; w < ldStages.Count; w++)
                {
                    int wins = 0;
                    for (int seed = 0; seed < LdSeeds; seed++)
                        if (k.Run(ldCompare[b].F, ldStages[w].Enemy, seed).PlayerWon) wins++;
                    if (Math.Abs(wins * 100.0 / LdSeeds - baseCells[b][w]) > 1e-9) { moved[b] = true; return; }
                }
            });
            var names = Enumerable.Range(0, ldCompare.Length).Where(b => moved[b]).Select(b => ldCompare[b].Name).ToList();
            if (names.Count == 1)
            {
                if (!soleBy.TryGetValue(names[0], out var l)) soleBy[names[0]] = l = new List<string>();
                l.Add(k.Name);
            }
            Console.WriteLine($"| {k.Name} | {(k.Off.StartsWith("対照:") ? "対照" : "off")} "
                + $"| {k.Off.Replace("対照:", "")} | {names.Count} | {(names.Count == 1 ? "**○**" : "")} "
                + $"| {(names.Count == 0 ? "（なし）" : string.Join(" / ", names.Take(10)) + (names.Count > 10 ? " …" : ""))} |");
            Console.Error.WriteLine("[ledger unique] " + k.Name + " done: " + names.Count);
        }

        Console.WriteLine();
        Console.WriteLine("## 唯一の観測点になっている行（(b) で外す行）");
        Console.WriteLine();
        if (soleBy.Count == 0) Console.WriteLine("（該当なし）");
        foreach (var kv in soleBy.OrderBy(kv => kv.Key, StringComparer.Ordinal))
            Console.WriteLine($"- **{kv.Key}** —— {string.Join(" / ", kv.Value)} の唯一の観測点");
        Console.WriteLine();
        Console.WriteLine("> **動いた行が 0 の規則は「既定で何もしない」か「盤面に保持者が居ない」**"
            + "——どちらも (b) には効かない。");
        return;
    }

    // ==============================================================================
    // seat —— §1-3。**「勝つ席」ではなく「測れる席」**（第59期・第89期の作法）。
    // ==============================================================================
    if (ldMode == "seat")
    {
        Console.WriteLine("# 第111期 §1-3 —— トモの行の席");
        Console.WriteLine();
        Console.WriteLine($"5枚組は第110期の台のまま（**§1-1 で固定してある。動かさない**）。"
            + $"120 通りを粗探索 seed 0..{LdScan - 1} → 追試 seed 0..{LdSeeds - 1} で測り、"
            + $"別 seed 帯（{LdCfBase}..{LdCfBase + LdCfSeeds - 1}）を安定の確認に併記する。");
        Console.WriteLine();
        Console.WriteLine("採る席は**3つの条件の積**（第107期 (S1) の器具の写し）: "
            + "(a) 情報セル（`0 < x < 100`・第2〜5波）を **2 以上**に保つ ／ "
            + "(b) **狙**（ガルドが前列） ／ (c) 出発点との差が **" + LdLine.ToString("F1") + "pt 以上**。");
        Console.WriteLine();
        Console.WriteLine("`巻` 列は**ボルグの隣接にドルガかトモが居るか**（第109期の台の作法。"
            + "居ない席を優先する——ただし**判定には使わない。列に出すだけ**）。");

        var perms = new List<Formation>();
        foreach (int[] assign in SlotAssignments(ldTomoMembers.Length))
        {
            var f = new Formation();
            for (int m = 0; m < ldTomoMembers.Length; m++) f[assign[m]] = ldTomoMembers[m];
            perms.Add(f);
        }

        var scan = new int[perms.Count];
        Parallel.For(0, perms.Count, i =>
        {
            int wins = 0;
            foreach (EnemyCatalog.Stage st in ldStages)
                for (int seed = 0; seed < LdScan; seed++)
                    if (BattleEngine.Run(perms[i], st.Enemy, seed, verbose: false).PlayerWon) wins++;
            scan[i] = wins;
        });
        var order = Enumerable.Range(0, perms.Count).OrderByDescending(i => scan[i]).ThenBy(i => i).ToList();
        var pool = order.Take(20)
            .Concat(order.Where(i => LdIntent(perms[i])).Take(10))
            .Append(order.First(i => SameFormation(perms[i], LdTomoBase())))
            .Distinct().ToList();

        var cellsA = new double[pool.Count][];
        var cellsB = new double[pool.Count][];
        Parallel.For(0, pool.Count, k => cellsA[k] = LdCells(perms[pool[k]], 0, LdSeeds));
        Parallel.For(0, pool.Count, k => cellsB[k] = LdCells(perms[pool[k]], LdCfBase, LdCfSeeds));

        // 平均は**第2〜5波**で取る（規約 (G10)。第一波は教習波）。
        static double LdAvg25(double[] c) => c.Skip(1).Average();
        bool Splash(Formation f)
        {
            int borg = -1, dolga = -1, tomo = -1;
            for (int i = 0; i < FormationRules.PlayableSlotCount; i++)
            {
                if (ReferenceEquals(f[i], UnitCatalog.Borg)) borg = i;
                if (ReferenceEquals(f[i], UnitCatalog.Dolga)) dolga = i;
                if (ReferenceEquals(f[i], UnitCatalog.Tomo)) tomo = i;
            }
            return borg >= 0 && ((dolga >= 0 && FormationRules.AreAdjacent(borg, dolga))
                              || (tomo >= 0 && FormationRules.AreAdjacent(borg, tomo)));
        }

        var ranked = Enumerable.Range(0, pool.Count).OrderByDescending(k => LdAvg25(cellsA[k])).ToList();
        int curK = pool.FindIndex(i => SameFormation(perms[i], LdTomoBase()));

        Console.WriteLine();
        Console.WriteLine($"## 追試（seed 0..{LdSeeds - 1}）—— 候補 {pool.Count} 通り");
        Console.WriteLine();
        Console.WriteLine("| 追順 | 粗順 | 狙 | 巻 | 前1/前3 | 中央 | 後1/後3 | 平均(2〜5波) | 情報セル |"
            + string.Concat(ldStages.Select((_, i) => $" 第{i + 1}波 |")) + $" 平均({LdCfBase}..) | 情報セル({LdCfBase}..) |");
        Console.WriteLine("|--:|--:|:-:|:-:|---|---|---|--:|--:|" + string.Concat(ldStages.Select(_ => "---:|")) + "---:|--:|");
        for (int r = 0; r < ranked.Count; r++)
        {
            int k = ranked[r];
            Formation f = perms[pool[k]];
            Console.WriteLine($"| {r + 1}{(k == curK ? "★出発点" : "")} | {order.IndexOf(pool[k]) + 1} "
                + $"| {(LdIntent(f) ? "○" : "×")} | {(Splash(f) ? "当" : "—")} | {LdSeats(f)} "
                + $"| {LdAvg25(cellsA[k]):F1}% | {LdInfo(cellsA[k])} |"
                + string.Concat(cellsA[k].Select(c => $" {c:F1}% |"))
                + $" {LdAvg25(cellsB[k]):F1}% | {LdInfo(cellsB[k])} |");
        }

        int pick = -1, free = -1;
        foreach (int k in ranked) { if (free < 0 && LdInfo(cellsA[k]) >= 2) free = k; }
        foreach (int k in ranked) { if (LdInfo(cellsA[k]) >= 2 && LdIntent(perms[pool[k]])) { pick = k; break; } }

        Console.WriteLine();
        Console.WriteLine($"**出発点（第110期の席）**: 追順 **{ranked.IndexOf(curK) + 1} 位** / 粗順 {order.IndexOf(pool[curK]) + 1}、"
            + $"平均(2〜5波) **{LdAvg25(cellsA[curK]):F1}%**、情報セル **{LdInfo(cellsA[curK])}**"
            + $"（{LdCfBase}.. 帯では {LdAvg25(cellsB[curK]):F1}% / 情報セル {LdInfo(cellsB[curK])}）。");
        Console.WriteLine();
        if (free >= 0 && free != pick)
            Console.WriteLine($"（参考）**狙を外した**最上位は 追順 **{ranked.IndexOf(free) + 1} 位**"
                + $"（{LdAvg25(cellsA[free]):F1}% / 情報セル {LdInfo(cellsA[free])}）。**採らない。**");
        if (pick < 0)
            Console.WriteLine("**判定: 出発点を据え置き** —— 狙を満たし情報セルを 2 以上に保つ席が1つも無い。");
        else if (pick == curK)
            Console.WriteLine("**判定: 出発点を据え置き** —— 狙を満たし情報セルを 2 以上に保つ最上位が出発点そのもの。");
        else
        {
            double gain = LdAvg25(cellsA[pick]) - LdAvg25(cellsA[curK]);
            double gainB = LdAvg25(cellsB[pick]) - LdAvg25(cellsB[curK]);
            Formation f = perms[pool[pick]];
            Console.WriteLine($"狙を満たし情報セルを 2 以上に保つ最上位は 追順 **{ranked.IndexOf(pick) + 1} 位**"
                + $"（{LdAvg25(cellsA[pick]):F1}% / 情報セル {LdInfo(cellsA[pick])}）で、出発点との差は "
                + $"**{gain:+0.0;-0.0}pt**（{LdCfBase}.. 帯では {gainB:+0.0;-0.0}pt）。");
            Console.WriteLine();
            Console.WriteLine($"**判定: {(gain >= LdLine ? "差し替え" : "据え置き")}** —— 閾値 {LdLine:F1}pt に対して {gain:+0.0;-0.0}pt。");
            if (gain >= LdLine)
                Console.WriteLine($"採る配置: `front1: {LdN(f[0])}, front3: {LdN(f[1])}, center: {LdN(f[2])}, "
                    + $"back1: {LdN(f[3])}, back3: {LdN(f[4])}`");
        }
        return;
    }

    // ==============================================================================
    // drop —— 落とす行が「なぜ測らなくなったか」を帯ごとに出す。**指示書には無い。足した理由は §1-2 の
    // 判定の根拠が「情報セル 1」だから**——その 1 がいつ・どの帯で決まったのかを併記しないと、
    // 「たまたま seed の揺れで 1 に見えた」と区別が付かない。
    // ==============================================================================
    if (ldMode == "drop")
    {
        // 第89期 (P2) が動かす**前**の席（`git show aa42e6b^` の `Presets.cs` から引いた）。
        var ldDropVers = new (string Tag, Formation F)[]
        {
            ("第89期より前", Formation.Build(front1: UnitCatalog.Zoto, front3: UnitCatalog.Hota,
                                             center: UnitCatalog.Golm, back1: UnitCatalog.Rica, back3: UnitCatalog.Vel)),
            ("現行（第89期 (P2)）", Formation.Build(front1: UnitCatalog.Zoto, front3: UnitCatalog.Golm,
                                             center: UnitCatalog.Rica, back1: UnitCatalog.Hota, back3: UnitCatalog.Vel)),
        };

        Console.WriteLine("# 第111期 —— 落とす行（`死軸×ホタ (ゾト×熾)`）が測らなくなった経緯");
        Console.WriteLine();
        Console.WriteLine($"帯A = seed 0..{LdSeeds - 1}（**`compare` が測る帯。`docs/balance.md` はこれ**）／"
            + $"帯B = seed {LdCfBase}..{LdCfBase + LdCfSeeds - 1}（**第46期の追試の帯**）。");
        Console.WriteLine();
        Console.WriteLine("| 席 | 帯 | 前1/前3 | 中央 | 後1/後3 | 平均(2〜5波) | **情報セル** |"
            + string.Concat(ldStages.Select((_, i) => $" 第{i + 1}波 |")));
        Console.WriteLine("|---|:-:|---|---|---|--:|--:|" + string.Concat(ldStages.Select(_ => "---:|")));
        foreach (var v in ldDropVers)
            foreach (var (tag, from, n) in new[] { ("A", 0, LdSeeds), ("B", LdCfBase, LdCfSeeds) })
            {
                double[] c = LdCells(v.F, from, n);
                Console.WriteLine($"| {v.Tag} | {tag} | {LdSeats(v.F)} | {c.Skip(1).Average():F1}% "
                    + $"| **{LdInfo(c)}** |" + string.Concat(c.Select(x => $" {x:F1}% |")));
            }
        Console.WriteLine();
        Console.WriteLine("> 第89期 (P2) は**帯B で情報セル 2** を確かめて席を採ったが、"
            + "**`compare` が測る帯A では 1** になる。`docs/balance.md` に載る値は帯A なので、"
            + "**この行はそのとき以来「勝率表の上では 1 セルしか情報を持たない行」だった。**");
        return;
    }

    // ==============================================================================
    // cross —— §2。交差帯 `傷×被弾` のハリの席に入れる駒を測る。**席は現行を据え置く**（後1）。
    // ==============================================================================
    if (ldMode == "cross")
    {
        Console.WriteLine("# 第111期 §2 —— 交差帯 `傷×被弾` のハリの席");
        Console.WriteLine();
        Console.WriteLine("**行が測る交差（傷 × 被弾）は変えない。ハリの席だけを `All` に居る駒に差し替える。**"
            + "他の 11 行は1文字も触らない。**席は現行を据え置く**（後1。交差帯の席の測り直しは第92期 `cross quality` の作法に従い、この期はやらない）。");
        Console.WriteLine();
        Console.WriteLine($"seed 0..{LdSeeds - 1}（`compare` と同じ帯）。");
        Console.WriteLine();
        Console.WriteLine("| 後1 | `All` | 5枚組の一意性 | 平均(2〜5波) | 情報セル |"
            + string.Concat(ldStages.Select((_, i) => $" 第{i + 1}波 |")));
        Console.WriteLine("|---|:-:|---|--:|--:|" + string.Concat(ldStages.Select(_ => "---:|")));

        var known = new Dictionary<string, string>(StringComparer.Ordinal);
        foreach (var b in ldCompare) known[LdKey(b.F)] = "compare: " + b.Name;
        for (int i = 0; i < ldCross.Length; i++) if (i != ldWoundHitIdx) known.TryAdd(LdKey(ldCross[i].F), "交差帯: " + ldCross[i].Name);

        foreach (var d in new[] { UnitCatalog.Hari }.Concat(ldCrossCands))
        {
            Formation f = LdCrossWith(d);
            double[] c = LdCells(f, 0, LdSeeds);
            string k = LdKey(f);
            Console.WriteLine($"| {d.Name}{(ReferenceEquals(d, UnitCatalog.Hari) ? "（現行）" : "")} "
                + $"| {(UnitCatalog.All.Any(u => ReferenceEquals(u, d)) ? "○" : "**×**")} "
                + $"| {(known.TryGetValue(k, out string? h) ? "**× " + h + "**" : "○ 一致なし")} "
                + $"| {c.Skip(1).Average():F1}% | {LdInfo(c)} |" + string.Concat(c.Select(x => $" {x:F1}% |")));
        }
        Console.WriteLine();
        Console.WriteLine("**他の 11 行が ±0.0 であること**（交差帯は行ごとに独立に測るので原理的にそうなる。実測で確かめる）:");
        Console.WriteLine();
        Console.WriteLine("| 行 |" + string.Concat(ldStages.Select((_, i) => $" 第{i + 1}波 |")));
        Console.WriteLine("|---|" + string.Concat(ldStages.Select(_ => "---:|")));
        for (int i = 0; i < ldCross.Length; i++)
        {
            if (i == ldWoundHitIdx) continue;
            double[] c = LdCells(ldCross[i].F, 0, LdSeeds);
            Console.WriteLine($"| {ldCross[i].Name} |" + string.Concat(c.Select(x => $" {x:F1}% |")));
        }
        return;
    }

    // ==============================================================================
    // check —— §5 の判定と自己検査。
    // ==============================================================================
    if (ldMode == "check")
    {
        Console.WriteLine("# 第111期 §5 —— 判定と自己検査");
        Console.WriteLine();

        var bal = LdBalance();
        var now = new double[ldCompare.Length][];
        Parallel.For(0, ldCompare.Length, b => now[b] = LdCells(ldCompare[b].F, 0, LdSeeds));

        // Q3: 残る 60 行が ±0.0（差し替えた1行だけが `docs/balance.md` に無いか値が違う）
        var changed = new List<string>();
        var absent = new List<string>();
        for (int b = 0; b < ldCompare.Length; b++)
        {
            if (!bal.TryGetValue(ldCompare[b].Name, out double[]? v)) { absent.Add(ldCompare[b].Name); continue; }
            for (int w = 0; w < ldStages.Count; w++)
                if (Math.Abs(v[w] - now[b][w]) > 1e-9) { changed.Add(ldCompare[b].Name + " 第" + (w + 1) + "波"); break; }
        }
        var gone = bal.Keys.Where(n => !ldCompare.Any(b => b.Name == n)).ToList();

        var tomoRow = ldCompare.FirstOrDefault(b => b.Name == LdTomoName);
        int tomoIdx = Array.FindIndex(ldCompare, b => b.Name == LdTomoName);
        int tomoInfo = tomoIdx >= 0 ? LdInfo(now[tomoIdx]) : -1;

        double fifthPrim = 0; int nPrim = 0;
        double[] waveAll = new double[ldStages.Count];
        double[] wavePrim = new double[ldStages.Count];
        for (int b = 0; b < ldCompare.Length; b++)
        {
            for (int w = 0; w < ldStages.Count; w++) waveAll[w] += now[b][w];
            if (!ldPrim.Contains(ldCompare[b].Name)) continue;
            nPrim++; fifthPrim += now[b][ldStages.Count - 1];
            for (int w = 0; w < ldStages.Count; w++) wavePrim[w] += now[b][w];
        }
        double fifth = fifthPrim / Math.Max(1, nPrim);

        Console.WriteLine("| | 内容 | 実測 | 線 | 判定 |");
        Console.WriteLine("|---|---|---|---|:-:|");
        Console.WriteLine($"| **Q1** | トモの行の情報セル（第2〜5波） | {(tomoIdx < 0 ? "**行が無い**" : tomoInfo.ToString())} "
            + $"| 2 以上 | {(tomoInfo >= 2 ? "**○**" : "**×**")} |");
        Console.WriteLine($"| **Q3** | `docs/balance.md` と値が違う行 | {changed.Count} 行"
            + $"（新しい行 {absent.Count} / 消えた行 {gone.Count}） | 差し替えた1行だけ "
            + $"| {(changed.Count == 0 && absent.Count <= 1 && gone.Count <= 1 ? "**○**" : "**×**")} |");
        Console.WriteLine($"| **Q4** | 主判定{nPrim}行の第五波平均 | **{fifth:F1}%** "
            + $"| 歯止め {Baseline.PrimaryFifthFloor:F1}% | {(fifth >= Baseline.PrimaryFifthFloor ? "**○**" : "**×**")} |");
        Console.WriteLine();
        Console.WriteLine($"**Q3 の内訳**——値が違う行: {(changed.Count == 0 ? "（なし）" : string.Join(" / ", changed))} ／ "
            + $"`docs/balance.md` に無い行: {(absent.Count == 0 ? "（なし）" : string.Join(" / ", absent))} ／ "
            + $"`docs/balance.md` にしか無い行: {(gone.Count == 0 ? "（なし）" : string.Join(" / ", gone))}");
        Console.WriteLine();
        Console.WriteLine("**`Baseline`（規約：主判定19行／全61行の両方を併記する）**");
        Console.WriteLine();
        Console.WriteLine("| 分母 |" + string.Concat(ldStages.Select((_, i) => $" 第{i + 1}波 |")) + " 歯止めとの余裕 |");
        Console.WriteLine("|---|" + string.Concat(ldStages.Select(_ => "---:|")) + "---:|");
        Console.WriteLine($"| 主判定{nPrim}行 |" + string.Concat(wavePrim.Select(x => $" {x / Math.Max(1, nPrim):F1} |"))
            + $" **{fifth - Baseline.PrimaryFifthFloor:+0.0;-0.0}pt** |");
        Console.WriteLine($"| 全{ldCompare.Length}行 |" + string.Concat(waveAll.Select(x => $" {x / ldCompare.Length:F1} |")) + " — |");

        // 拒否権（規約 (G9)）: 第五波 95% 超の行が新たに出たか
        var ceil = new List<string>();
        for (int b = 0; b < ldCompare.Length; b++)
        {
            double v5 = now[b][ldStages.Count - 1];
            bool wasCeil = bal.TryGetValue(ldCompare[b].Name, out double[]? old) && old[ldStages.Count - 1] > 95.0;
            if (v5 > 95.0 && !wasCeil) ceil.Add($"{ldCompare[b].Name}（{v5:F1}%）");
        }
        Console.WriteLine();
        Console.WriteLine($"**拒否権（規約 (G9)・「注意」）**: 第五波 95% 超が新たに出た行 **{ceil.Count} 行**"
            + $"{(ceil.Count == 0 ? "" : ": " + string.Join(" / ", ceil))}");

        // --- 自己検査
        Console.WriteLine();
        Console.WriteLine("## 自己検査");
        Console.WriteLine();
        Console.WriteLine("| | 項目 | 実測 | 判定 |");
        Console.WriteLine("|---|---|---|:-:|");
        Console.WriteLine($"| (a) | `UnitCatalog.All` の枚数 | {UnitCatalog.All.Count} | {(UnitCatalog.All.Count == 52 ? "○" : "**×**")} |");
        Console.WriteLine($"| (b) | `Presets.Compare` / `Presets.Cross` の行数 | {ldCompare.Length} / {ldCross.Length} "
            + $"| {(ldCompare.Length == 61 && ldCross.Length == 12 ? "○" : "**×**")} |");
        int unres = Baseline.PrimaryRows.Count(n => !ldCompare.Any(b => b.Name == n));
        Console.WriteLine($"| (d) | 主判定19行が `Presets.Compare` に引ける | 引けない {unres} 行 | {(unres == 0 ? "○" : "**×**")} |");
        bool hariGone = !UnitCatalog.All.Any(u => ReferenceEquals(u, UnitCatalog.Hari));
        bool hariInCross = ldCross.Any(b => b.F.Occupied().Any(o => ReferenceEquals(o.Def, UnitCatalog.Hari)));
        bool hariInCompare = ldCompare.Any(b => b.F.Occupied().Any(o => ReferenceEquals(o.Def, UnitCatalog.Hari)));
        Console.WriteLine($"| (e) | ハリが `All` に居ない / `Cross` に居ない / `Compare` に居ない "
            + $"| {(hariGone ? "○" : "×")} / {(hariInCross ? "**×**" : "○")} / {(hariInCompare ? "**×**" : "○")} "
            + $"| {(hariGone && !hariInCross && !hariInCompare ? "○" : "**×**")} |");
        bool tomoInCompare = ldCompare.Any(b => b.F.Occupied().Any(o => ReferenceEquals(o.Def, UnitCatalog.Tomo)));
        Console.WriteLine($"| (Q6) | トモが `Presets.Compare` に居る（`derive scan` の供給が 0 でなくなる） "
            + $"| {(tomoInCompare ? "○" : "**×**")} | {(tomoInCompare ? "○" : "**×**")} |");

        // (c) トモが最遅だった回数・灯の対象
        if (tomoRow.F is not null)
        {
            Console.WriteLine();
            Console.WriteLine("### (c) トモの行——灯の対象");
            Console.WriteLine();
            var cands = tomoRow.F.Occupied().Select(o => o.Def)
                .Where(d => !ReferenceEquals(d, UnitCatalog.Tomo) && !d.Traits.Contains(TraitId.Stoic))
                .OrderBy(d => d.Speed).ThenBy(d => d.Id, StringComparer.Ordinal).ToList();
            var slower = tomoRow.F.Occupied().Select(o => o.Def)
                .Where(d => !ReferenceEquals(d, UnitCatalog.Tomo) && d.Speed <= UnitCatalog.Tomo.Speed).ToList();
            Console.WriteLine($"- トモ（速{UnitCatalog.Tomo.Speed}）より遅いか同速の味方: "
                + $"**{slower.Count} 枚**{(slower.Count == 0 ? "（＝トモが最遅。100%）" : ": " + string.Join(" / ", slower.Select(d => d.Name)))}");
            Console.WriteLine($"- 灯の候補（`Stoic` を除く）のうち最も遅い: **{cands[0].Name}（速{cands[0].Speed}）** "
                + $"——2番目は {cands[1].Name}（速{cands[1].Speed}）で、"
                + $"{(cands[0].Speed < cands[1].Speed ? "**同速が無いので、ドルガ生存中は 100% ドルガ**" : "**同速がある**")}");
        }
        return;
    }

    Console.WriteLine("mode: phase0 / unique / seat / cross / check");
    return;
}

if (focusId == "lit") { LitDiag.Run(args, stageIndex); return; }

if (focusId == "reader") { ReaderDiag.Run(args, stageIndex); return; }

// offturn モード: **手番の外を見せる期**（第125期）。
//
// この期は採否の判定を1つも持たない（第123・124期と同じ性格）。盤面の規則は1本も足しておらず、
// 足したのは表示専用のイベント1種（`BattleEventKind.Intercept`）と、誰も読まない計数2本だけ。
//
// **走査は件数を出し、0件を異常として止める**（第117期「引けなかったときと『該当なし』の区別」）。
//
//     dotnet run --project BattleSim -c Release 0 offturn phase0            # Q0-1〜Q0-9（戦闘0回）
//     dotnet run --project BattleSim -c Release 0 offturn check             # A3 / A4 と実戦の発火
//     dotnet run --project BattleSim -c Release 0 offturn tempo <旧Main.cs>  # A6（再生の総尺の前後）
if (focusId == "offturn")
{
    string ofMode = args.Length > 2 ? args[2] : "phase0";

    // リポジトリの根。`docs/balance.md` を目印にたどる（`watch` と同じ引き方）。
    string? ofRoot = Directory.GetCurrentDirectory();
    while (ofRoot != null && !File.Exists(Path.Combine(ofRoot, "docs", "balance.md")))
        ofRoot = Path.GetDirectoryName(ofRoot);
    if (ofRoot == null)
    {
        Console.WriteLine("**走査が空**: リポジトリの根を引けなかった（`docs/balance.md` が見つからない）。ここで止める。");
        return;
    }
    string ofEnginePath = Path.Combine(ofRoot, "BattleCore", "BattleEngine.cs");
    string ofTraitsPath = Path.Combine(ofRoot, "BattleCore", "Traits.cs");
    string ofModelsPath = Path.Combine(ofRoot, "BattleCore", "Models.cs");
    string ofDemoPath = Path.Combine(ofRoot, "DemoApp", "Main.cs");
    foreach (string p in new[] { ofEnginePath, ofTraitsPath, ofModelsPath, ofDemoPath })
        if (!File.Exists(p))
        {
            Console.WriteLine("**走査が空**: `" + p + "` が無い。ここで止める。");
            return;
        }
    string ofEngine = File.ReadAllText(ofEnginePath);
    string ofTraits = File.ReadAllText(ofTraitsPath);

    var ofFoeDefs = EnemyCatalog.Stages.SelectMany(s => s.Enemy.Occupied().Select(x => x.Def))
        .GroupBy(d => d.Id).Select(g => g.First()).ToList();
    string OfNameOf(string id)
        => UnitCatalog.All.Concat(ofFoeDefs).FirstOrDefault(d => d.Id == id)?.Name ?? id;

    // 特性 → 保持者。
    var ofTraitOwners = new Dictionary<TraitId, List<UnitDef>>();
    foreach (UnitDef d in UnitCatalog.All)
        foreach (TraitId t in d.Traits)
        {
            if (!ofTraitOwners.TryGetValue(t, out var l)) ofTraitOwners[t] = l = new List<UnitDef>();
            l.Add(d);
        }
    string OfOwners(TraitId id)
        => ofTraitOwners.TryGetValue(id, out var l) ? string.Join(" / ", l.Select(d => d.Name)) : "**味方に0体**";

    // 特性クラス名 → TraitId（reflection。手で並べない）。
    var ofClassToId = new Dictionary<string, TraitId>(StringComparer.Ordinal);
    foreach (TraitId id in Enum.GetValues<TraitId>())
    {
        IReadOnlyList<Trait> resolved;
        try { resolved = TraitCatalog.Resolve(new[] { id }); } catch { continue; }
        foreach (Trait t in resolved) ofClassToId[t.GetType().Name] = id;
    }

    // ----------------------------------------------------------------------
    // Q0-1 —— 介入の鎖。`SelectTargetChain` の本文から機械で引く。
    // ----------------------------------------------------------------------
    string ofChain = OffturnScan.Body(ofEngine, "private UnitState? SelectTargetChain(");
    if (ofChain.Length == 0)
    {
        Console.WriteLine("**走査が空**: `SelectTargetChain` の本文を切り出せなかった。ここで止める。");
        return;
    }
    var ofChainSites = System.Text.RegularExpressions.Regex
        .Matches(ofChain, @"EmitIntercept\(\s*(\w+)\s*,\s*(\w+)\s*,\s*InterceptLabels\.(\w+)\s*\)")
        .Select(m => (Guard: m.Groups[1].Value, Target: m.Groups[2].Value, Field: m.Groups[3].Value))
        .ToList();
    var ofGuardPicks = System.Text.RegularExpressions.Regex
        .Matches(ofChain, @"NoteGuardPick\(GuardKind\.(\w+)")
        .Select(m => m.Groups[1].Value).ToList();
    string OfLabelOf(string field)
        => typeof(InterceptLabels).GetField(field)?.GetRawConstantValue() as string ?? field;

    // ----------------------------------------------------------------------
    // Q0-3 —— `ctx.Reaction` / `ctx.Interrupt` に包まれた段。
    // ----------------------------------------------------------------------
    var ofWrapped = new List<(string Wrap, string Class)>();
    foreach (System.Text.RegularExpressions.Match m in
             System.Text.RegularExpressions.Regex.Matches(ofTraits, @"ctx\.(Reaction|Interrupt)\("))
        ofWrapped.Add((m.Groups[1].Value, OffturnScan.EnclosingTrait(ofTraits, m.Index)));

    // ----------------------------------------------------------------------
    // Q0-4 —— `relayed: true` を渡す呼び出し口（肩代わりの中継）。
    // ----------------------------------------------------------------------
    var ofRelaySites = new List<string>();
    foreach (System.Text.RegularExpressions.Match m in
             System.Text.RegularExpressions.Regex.Matches(ofEngine, @"relayed:\s*true"))
    {
        int from = Math.Max(0, m.Index - 1800);
        var near = System.Text.RegularExpressions.Regex.Matches(
            ofEngine.Substring(from, m.Index - from), @"TraitId\.(\w+)").ToList();
        ofRelaySites.Add(near.Count == 0 ? "—" : near[near.Count - 1].Groups[1].Value);
    }

    // ----------------------------------------------------------------------
    // Q0-5 —— `OnTurnStart` を上書きしている特性。
    // ----------------------------------------------------------------------
    var ofTurnStartIds = new List<TraitId>();
    foreach (TraitId id in Enum.GetValues<TraitId>())
    {
        IReadOnlyList<Trait> resolved;
        try { resolved = TraitCatalog.Resolve(new[] { id }); } catch { continue; }
        foreach (Trait t in resolved)
        {
            var mi = t.GetType().GetMethod("OnTurnStart");
            if (mi is not null && mi.DeclaringType != typeof(Trait) && !ofTurnStartIds.Contains(id))
                ofTurnStartIds.Add(id);
        }
    }

    // ----------------------------------------------------------------------
    // 推奨6行（第124期の観察ログと同じ6行・同じ seed）。行名は `Presets` と完全一致で照合する。
    // ----------------------------------------------------------------------
    var ofAll = CompareBuilds().Concat(CrossBuilds()).ToArray();
    var ofByName = new Dictionary<string, Formation>(StringComparer.Ordinal);
    foreach (var (n, f) in ofAll) ofByName[n] = f;
    var ofRows = new List<(string Name, Formation F, int Stage, int Seed)>();
    var ofRowMissing = new List<string>();
    foreach (var (n, st, sd) in OffturnScan.WatchRows)
    {
        if (ofByName.TryGetValue(n, out Formation? f)) ofRows.Add((n, f, st, sd));
        else ofRowMissing.Add(n);
    }

    // ======================================================================
    // phase0 —— Q0-1〜Q0-9。**戦闘0回。**
    // ======================================================================
    if (ofMode == "phase0")
    {
        Console.WriteLine("# 手番の外の地図 —— Phase 0（第125期・`offturn phase0`）");
        Console.WriteLine();
        Console.WriteLine("`dotnet run --project BattleSim -c Release 0 offturn phase0` の出力。**戦闘0回。**");
        Console.WriteLine("すべて実装から引いている（手で並べた表は1つも無い）。走査が空なら止める。");
        Console.WriteLine();

        // ---- Q0-1 ----
        Console.WriteLine("## Q0-1. 介入の鎖の全段");
        Console.WriteLine();
        int ofKinds = ofChainSites.Select(x => OfLabelOf(x.Field)).Distinct(StringComparer.Ordinal).Count();
        Console.WriteLine("`SelectTargetChain` の本文 **" + ofChain.Length + " 字**から引いた。"
            + "差し替えの段 **" + ofChainSites.Count + " 箇所** ／ 段の名前 **" + ofKinds + " 種**"
            + " ／ `InterceptLabels.All` **" + InterceptLabels.All.Length + " 種**。");
        Console.WriteLine();
        Console.WriteLine("| # | 段（鎖の順） | 割り込む駒 | 本来の標的 | `BattleEvent` | 保持者（味方） |");
        Console.WriteLine("|--:|---|---|---|:-:|---|");
        for (int i = 0; i < ofChainSites.Count; i++)
        {
            var ofSite = ofChainSites[i];
            string owners = ofSite.Field switch
            {
                "RearGuard" => OfOwners(TraitId.RearGuard),
                "Guardian" => OfOwners(TraitId.Guardian),
                "Martyr" => OfOwners(TraitId.Martyr),
                "ThornGuard" => OfOwners(TraitId.ThornGuard),
                _ => "—（`StatusKeys.Marked` を engine が読む）",
            };
            Console.WriteLine("| " + (i + 1) + " | " + OfLabelOf(ofSite.Field) + " | `" + ofSite.Guard + "` | `" + ofSite.Target
                + "` | `Intercept` | " + owners + " |");
        }
        Console.WriteLine();
        Console.WriteLine("**`NoteGuardPick` が数える段**（第120期・診断専用）は " + ofGuardPicks.Count + " 箇所"
            + "（" + string.Join(" / ", ofGuardPicks.Distinct().Select(g => "`" + g + "`")) + "）"
            + "——鎖の外の巨躯を含み、**標の段を数えていない。**");
        Console.WriteLine();
        Console.WriteLine("> **第124期まではこの鎖の全段が `Log` の文字列にしか出ていなかった**（第123期 (iii)）。");
        Console.WriteLine("> 駒は1ミリも動かないので、画面では「庇った」ではなく「庇った駒が殴られた」としか見えない。");
        Console.WriteLine();

        // ---- Q0-2 ----
        Console.WriteLine("## Q0-2. 介入の計数");
        Console.WriteLine();
        var ofTallyFields = typeof(UnitTally).GetFields()
            .Where(f => f.FieldType == typeof(int)).Select(f => f.Name).ToArray();
        Console.WriteLine("`UnitTally` の int フィールド **" + ofTallyFields.Length + " 本**。");
        Console.WriteLine();
        Console.WriteLine("| フィールド | 有無 | 意味 |");
        Console.WriteLine("|---|:-:|---|");
        foreach (string w in new[] { "Intercepts", "Shouldered", "Swallowed", "DamageTaken", "TakenFromAlly" })
            Console.WriteLine("| `" + w + "` | " + (ofTallyFields.Contains(w) ? "○" : "**×**") + " | " + (w switch
            {
                "Intercepts" => "**第125期 段1 に足した。** 割り込んで主目標を引き受けた回数（鎖の全段）",
                "Shouldered" => "**第125期 段1 に足した。** 中継の段が実際に削った量（`relayed`）",
                "Swallowed" => "既存（第36期）。巨躯が飲み込んだ**名目量**。分かちは数えない",
                "DamageTaken" => "既存。**庇ったから増えたのか殴られたから増えたのかが分けられない**（第124期 Q0-3）",
                _ => "既存。味方由来のぶん",
            }) + " |");
        Console.WriteLine();
        Console.WriteLine("**既存の計数で代用できるか**: `NoteGuardPick`（第120期）は鎖の4段を数えているが、"
            + "**(a) 傷の在庫の計数（第120期）が生きているときだけ (b) 味方側だけ (c) 駒ごとではなく段ごと**なので、"
            + "戦績パネル（駒ごと・常時）には使えない。**`Swallowed` は巨躯だけ**で分かちを数えない。");
        Console.WriteLine();

        // ---- Q0-3 ----
        Console.WriteLine("## Q0-3. `Reaction` が立つ経路");
        Console.WriteLine();
        if (ofWrapped.Count == 0)
        {
            Console.WriteLine("**走査が空**: `ctx.Reaction` / `ctx.Interrupt` を1件も引けなかった。ここで止める。");
            return;
        }
        Console.WriteLine("`Traits.cs` の呼び出し口 **" + ofWrapped.Count + " 箇所**"
            + "（`Reaction` " + ofWrapped.Count(x => x.Wrap == "Reaction")
            + " ／ `Interrupt` " + ofWrapped.Count(x => x.Wrap == "Interrupt") + "）。");
        Console.WriteLine();
        Console.WriteLine("| 包み | 特性 | 保持者（味方） |");
        Console.WriteLine("|---|---|---|");
        foreach (var (wrap, cls) in ofWrapped)
            Console.WriteLine("| `ctx." + wrap + "` | `" + cls + "` | "
                + (ofClassToId.TryGetValue(cls, out TraitId tid) ? OfOwners(tid) : "—") + " |");
        Console.WriteLine();
        bool ofPursuerWrapped = ofWrapped.Any(x => x.Class == "PursuerTrait");
        string ofPursuerBody = OffturnScan.Body(ofTraits, "public sealed class PursuerTrait");
        bool ofPursuerDirect = ofPursuerBody.Contains("ctx.PerformAttack", StringComparison.Ordinal);
        Console.WriteLine("**追い打ち（`PursuerTrait`・ハギ）**: 包まれているか "
            + (ofPursuerWrapped ? "**包まれている**" : "**包まれていない**")
            + " ／ `ctx.PerformAttack` を直に呼ぶか " + (ofPursuerDirect ? "**呼ぶ**" : "呼ばない")
            + " → `Models.cs` のコメントの主張は"
            + (!ofPursuerWrapped && ofPursuerDirect ? "**今も正しい**" : "**ずれている**") + "。");
        Console.WriteLine();

        // ---- Q0-4 ----
        Console.WriteLine("## Q0-4. `Relayed` が立つ経路");
        Console.WriteLine();
        Console.WriteLine("`relayed: true` の呼び出し口 **" + ofRelaySites.Count + " 箇所**。");
        Console.WriteLine();
        Console.WriteLine("| 経路 | 特性 | 保持者（味方） |");
        Console.WriteLine("|---|---|---|");
        foreach (string tr in ofRelaySites)
            Console.WriteLine("| `ApplyDamage(relayed: true)` | `TraitId." + tr + "` | "
                + (Enum.TryParse(tr, out TraitId rid) ? OfOwners(rid) : "—") + " |");
        Console.WriteLine();
        Console.WriteLine("**庇い（ガルド）は `Relayed` では立たない。** 庇いは `SelectTargetChain` が"
            + "**主目標そのものを差し替える**ので、`ApplyDamage` は最初から庇った駒へ1回だけ入る"
            + "（分割も中継も無い）——だから Q0-1 の側（`Intercept`）でしか出せない。");
        Console.WriteLine();

        // ---- Q0-5 ----
        Console.WriteLine("## Q0-5. ターン頭に発火する味方駒");
        Console.WriteLine();
        if (ofTurnStartIds.Count == 0)
        {
            Console.WriteLine("**走査が空**: `OnTurnStart` を上書きする特性を1件も引けなかった。ここで止める。");
            return;
        }
        var ofTurnStartAllies = UnitCatalog.All.Where(d => d.Traits.Any(ofTurnStartIds.Contains)).ToList();
        Console.WriteLine("`OnTurnStart` を上書きする特性 **" + ofTurnStartIds.Count + " 本** ／ "
            + "それを持つ味方駒 **" + ofTurnStartAllies.Count + " / " + UnitCatalog.All.Count + " 体**。");
        Console.WriteLine();
        Console.WriteLine("| 駒 | ターン頭に走る特性 |");
        Console.WriteLine("|---|---|");
        foreach (UnitDef d in ofTurnStartAllies.OrderBy(x => x.Id, StringComparer.Ordinal))
            Console.WriteLine("| " + d.Name + " | "
                + string.Join(" / ", d.Traits.Where(ofTurnStartIds.Contains).Select(t => "`" + t + "`")) + " |");
        Console.WriteLine();
        Console.WriteLine("> **これは行動順ループの<u>外</u>で全部走り終わる**（`BattleEngine.Run` の順序は");
        Console.WriteLine("> `EmitTurnStart` → `TickStatuses` → `OnTurnStart` の全駒ループ → 行動順ループ）。");
        Console.WriteLine("> **誰の手番でもない時間に起きている**のに、いまの再生は1本の時間軸に並べている。");
        Console.WriteLine();

        // ---- Q0-6 ----
        Console.WriteLine("## Q0-6. ゾトの破裂の攻撃型");
        Console.WriteLine();
        string ofBomber = OffturnScan.Body(ofTraits, "public sealed class BomberTrait");
        if (ofBomber.Length == 0)
        {
            Console.WriteLine("**走査が空**: `BomberTrait` の本文を切り出せなかった。ここで止める。");
            return;
        }
        var ofBomberCalls = System.Text.RegularExpressions.Regex
            .Matches(ofBomber, @"ctx\.ApplyDamage\([^;]*\);").Select(m => m.Value).ToList();
        Console.WriteLine("`BomberTrait` の `ctx.ApplyDamage` **" + ofBomberCalls.Count + " 箇所**"
            + "（うち `pattern:` を渡すもの **"
            + ofBomberCalls.Count(c => c.Contains("pattern:", StringComparison.Ordinal)) + " 箇所**）。");
        Console.WriteLine();
        foreach (string c in ofBomberCalls)
            Console.WriteLine("- `" + c.Replace("\r", "").Replace("\n", " ") + "`");
        Console.WriteLine();
        Console.WriteLine("**`AttackPattern.All` は1度も通らない。** 破裂は敵全員・味方全員へ"
            + "**1体ずつ `ApplyDamage` を呼ぶ**だけで、`Attack` イベントも出さない"
            + "——台本に載るのは `Highlight`（破裂した）と、**`Pattern` が `null` の `Damage` が人数ぶん**。"
            + "**「型なし」として描かれる**のがポンの「爆発している感がない」の実体（P5-a の分母）。");
        Console.WriteLine();

        // ---- Q0-7 ----
        Console.WriteLine("## Q0-7. 味方の常時の攻撃型の分布");
        Console.WriteLine();
        Console.WriteLine("| 型 | 味方（`UnitCatalog.All`） | 敵（`EnemyCatalog` の全波） |");
        Console.WriteLine("|---|--:|--:|");
        foreach (AttackPattern p in Enum.GetValues<AttackPattern>())
            Console.WriteLine("| " + p + " | " + UnitCatalog.All.Count(d => d.Pattern == p)
                + " | " + ofFoeDefs.Count(d => d.Pattern == p) + " |");
        Console.WriteLine();
        Console.WriteLine("味方 **" + UnitCatalog.All.Count + " 体** ／ 敵の実体 **" + ofFoeDefs.Count + " 体**"
            + "（全波の重複を除いた数）。");
        Console.WriteLine();
        Console.WriteLine("**味方に常時の貫き・全体は 0 体**（`Pierce` / `All` は `EnemyCatalog` 側にしかない）。"
            + "戦闘中に型が変わる経路は `Trait.ModifyPattern`（熾火＝貫き・積み過ぎ＝薙ぎ・軋み＝薙ぎ）と"
            + "溜めの `PatternOverride` だけで、**`All` になる味方は1体もいない。**");
        Console.WriteLine();

        // ---- Q0-8 ----
        Console.WriteLine("## Q0-8. `DemoApp` の再生の時間軸");
        Console.WriteLine();
        var ofBeats = OffturnScan.Beats(File.ReadAllText(ofDemoPath));
        if (ofBeats.Sites == 0)
        {
            Console.WriteLine("**走査が空**: `ApplyEvent` の `Delay` を1件も引けなかった。ここで止める。");
            return;
        }
        Console.WriteLine("`DemoApp/Main.cs` の `ApplyEvent` から引いた間 **" + ofBeats.Sites + " 箇所**"
            + "（うち条件付き **" + ofBeats.CondSites + " 箇所**は別に数える）／ "
            + "種類 **" + ofBeats.Map.Count + " 件**（速度 ×1 のときの秒）。");
        Console.WriteLine();
        Console.WriteLine("| 種類 | 1件あたりの間（秒） | 条件付き（上限） |");
        Console.WriteLine("|---|--:|--:|");
        foreach (var kv in ofBeats.Map.OrderByDescending(k => k.Value))
            Console.WriteLine("| `" + kv.Key + "` | " + kv.Value.ToString("0.00")
                + " | " + (ofBeats.Cond.GetValueOrDefault(kv.Key) is var c && c > 0 ? c.ToString("0.00") : "—") + " |");
        Console.WriteLine();
        Console.WriteLine("**構造**: `BeginPlayback` が `_result.Events` を**先頭から1件ずつ**取り出し、"
            + "`ApplyEvent` が種類ごとに絵を出して `Delay` で間を置く。"
            + "**ターンの区切り（`TurnStart`）以外に束ねる単位が無い**ので、"
            + "**割り込み・肩代わり・ターン頭の一括はどれも「そういう順番で起きた1件」として流れる。**");
        Console.WriteLine();
        Console.WriteLine("> **この期に直すのはここである**（§5-1）。情報は既に台本にあるのに読めないのは、"
            + "**いつ起きたかが時間軸から引けない**から。");
        Console.WriteLine();

        // ---- Q0-9 ----
        Console.WriteLine("## Q0-9. 過去に介入の可視化を測っていないか");
        Console.WriteLine();
        string ofDesign = Path.Combine(ofRoot, "design");
        var ofHits = new List<(string File, int Relayed, int Guard, int Intervene)>();
        foreach (string f in Directory.GetFiles(ofDesign, "*.md"))
        {
            string t = File.ReadAllText(f);
            int r = System.Text.RegularExpressions.Regex.Matches(t, "Relayed").Count;
            int g = System.Text.RegularExpressions.Regex.Matches(t, "庇").Count;
            int i = System.Text.RegularExpressions.Regex.Matches(t, "介入").Count;
            if (r + g + i > 0) ofHits.Add((Path.GetFileName(f), r, g, i));
        }
        if (ofHits.Count == 0)
        {
            Console.WriteLine("**走査が空**: `design/` に1件も当たらなかった。ここで止める。");
            return;
        }
        Console.WriteLine("`design/` の Markdown **" + Directory.GetFiles(ofDesign, "*.md").Length + " 件**中、"
            + "`Relayed` / 庇 / 介入 のどれかに当たるのは **" + ofHits.Count + " 件**。上位のみ:");
        Console.WriteLine();
        Console.WriteLine("| ファイル | `Relayed` | 庇 | 介入 |");
        Console.WriteLine("|---|--:|--:|--:|");
        foreach (var h in ofHits.OrderByDescending(x => x.Relayed + x.Guard + x.Intervene).Take(10))
            Console.WriteLine("| `" + h.File + "` | " + h.Relayed + " | " + h.Guard + " | " + h.Intervene + " |");
        Console.WriteLine();
        Console.WriteLine("**「介入を画面に出せるか」を測った期は無い。** 第85期は `Relayed` を"
            + "**計数の札**として足した期（味方の刃を数えるため）で画面の話ではなく、"
            + "第123期 (iii) と第124期 Q0-3 / P5 は**「出せない」と記録しただけ**で手を付けていない。");
        Console.WriteLine();
        Console.WriteLine("**推奨6行の照合**: `Presets` に存在しない行 **" + ofRowMissing.Count + " 件**"
            + (ofRowMissing.Count == 0 ? "。" : ": " + string.Join(" / ", ofRowMissing)));
        return;
    }

    // ======================================================================
    // check —— A3 / A4 と、実戦で介入が出ることの確認。
    // ======================================================================
    if (ofMode == "check")
    {
        Console.WriteLine("# 自己検査（第125期・`offturn check`）");
        Console.WriteLine();

        var ofLabelsUsed = ofChainSites.Select(x => OfLabelOf(x.Field))
            .Distinct(StringComparer.Ordinal).OrderBy(x => x, StringComparer.Ordinal).ToArray();
        var ofLabelsAll = InterceptLabels.All.OrderBy(x => x, StringComparer.Ordinal).ToArray();
        bool a3 = ofLabelsUsed.SequenceEqual(ofLabelsAll, StringComparer.Ordinal);
        Console.WriteLine("- **A3** 介入の段 **" + ofChainSites.Count + " 箇所** → 名前 **" + ofLabelsUsed.Length
            + " 種** ／ `InterceptLabels.All` **" + ofLabelsAll.Length + " 種** → " + (a3 ? "**○**" : "**×**"));
        Console.WriteLine("  - 使われた名前: " + string.Join(" / ", ofLabelsUsed));
        Console.WriteLine("  - **後備えだけ呼び出し口が2つ**（単体の鎖と範囲の鎖）なので、箇所 "
            + ofChainSites.Count + " と種 " + ofLabelsUsed.Length + " がずれるのは正しい。");

        int ofReads = 0, ofWrites = 0;
        foreach (string f in new[] { ofEnginePath, ofTraitsPath, ofModelsPath,
                                     Path.Combine(ofRoot, "BattleCore", "Presets.cs"),
                                     Path.Combine(ofRoot, "BattleCore", "UnitCatalog.cs"),
                                     Path.Combine(ofRoot, "BattleCore", "Engagement.cs") })
        {
            if (!File.Exists(f)) continue;
            string t = File.ReadAllText(f);
            foreach (System.Text.RegularExpressions.Match m in
                     System.Text.RegularExpressions.Regex.Matches(t, @"BattleEventKind\.Intercept"))
            {
                // **コメント（`///` の文書化コメントを含む）は数えない。** 規則が読んでいるかを見たいので、
                // 行頭が `//` の行に出るものは除く（`<see cref=...>` がここに来る）。
                int bol = t.LastIndexOf('\n', m.Index) + 1;
                if (t.Substring(bol, m.Index - bol).TrimStart().StartsWith("//", StringComparison.Ordinal)) continue;
                int from = Math.Max(0, m.Index - 10);
                if (t.Substring(from, m.Index - from).Contains("Kind = ", StringComparison.Ordinal)) ofWrites++;
                else ofReads++;
            }
        }
        Console.WriteLine("- **A4** `BattleCore` が `BattleEventKind.Intercept` に触る箇所（コメントを除く）: 書く **"
            + ofWrites + "** ／ **読む " + ofReads + "** → " + (ofReads == 0 ? "**○**" : "**×**"));
        Console.WriteLine();

        Console.WriteLine("| 行 | 波 | seed | 出来事 | `Intercept` | `Reaction` | `Relayed` | 介入した駒 |");
        Console.WriteLine("|---|--:|--:|--:|--:|--:|--:|---|");
        int ofTotal = 0;
        foreach (var (name, f, ofStage, seed) in ofRows)
        {
            BattleResult r = BattleEngine.Run(f, EnemyCatalog.Stages[ofStage].Enemy, seed, verbose: true);
            int ic = r.Events.Count(e => e.Kind == BattleEventKind.Intercept);
            ofTotal += ic;
            var who = r.TallyByUnit.Where(kv => kv.Value.Intercepts > 0)
                .OrderByDescending(kv => kv.Value.Intercepts)
                .Select(kv => OfNameOf(kv.Key) + "×" + kv.Value.Intercepts).ToArray();
            Console.WriteLine("| " + name + " | 第" + (ofStage + 1) + "波 | " + seed + " | " + r.Events.Count
                + " | " + ic + " | " + r.Events.Count(e => e.Reaction) + " | "
                + r.Events.Count(e => e.Relayed) + " | " + (who.Length == 0 ? "—" : string.Join(" / ", who)) + " |");
        }
        Console.WriteLine();
        Console.WriteLine("**推奨6行の `Intercept` 合計 " + ofTotal + " 件。**"
            + " 0 件なら「載せたが出ていない」なのでここで疑う。");
        Console.WriteLine();

        int nq = 0, nv = 0, sq = 0, sv = 0;
        foreach (var (_, f, ofStage, seed) in ofRows)
        {
            BattleResult q = BattleEngine.Run(f, EnemyCatalog.Stages[ofStage].Enemy, seed, verbose: false);
            BattleResult v = BattleEngine.Run(f, EnemyCatalog.Stages[ofStage].Enemy, seed, verbose: true);
            nq += q.TallyByUnit.Values.Sum(t => t.Intercepts);
            nv += v.TallyByUnit.Values.Sum(t => t.Intercepts);
            sq += q.TallyByUnit.Values.Sum(t => t.Shouldered);
            sv += v.TallyByUnit.Values.Sum(t => t.Shouldered);
        }
        Console.WriteLine("- **計数は `verbose` に依らない**: `Intercepts` 非 verbose **" + nq + "** ／ verbose **"
            + nv + "** → " + (nq == nv ? "**○**" : "**×**"));
        Console.WriteLine("- **同じく `Shouldered`**: 非 verbose **" + sq + "** ／ verbose **" + sv + "** → "
            + (sq == sv ? "**○**" : "**×**"));
        return;
    }

    // ======================================================================
    // tempo —— A6。再生の総尺を、推奨6行の台本 × `ApplyEvent` の間の表で出す。
    // ======================================================================
    if (ofMode == "tempo")
    {
        if (args.Length < 4)
        {
            Console.WriteLine("usage: offturn tempo <比較する旧 Main.cs のパス>");
            return;
        }
        string ofOldPath = args[3];
        if (!File.Exists(ofOldPath))
        {
            Console.WriteLine("**走査が空**: `" + ofOldPath + "` が無い。ここで止める。");
            return;
        }
        var oldB = OffturnScan.Beats(File.ReadAllText(ofOldPath));
        var newB = OffturnScan.Beats(File.ReadAllText(ofDemoPath));
        if (oldB.Sites == 0 || newB.Sites == 0)
        {
            Console.WriteLine("**走査が空**: 間を引けなかった（旧 " + oldB.Sites + " / 新 " + newB.Sites + "）。ここで止める。");
            return;
        }
        Console.WriteLine("# 再生の総尺（第125期・`offturn tempo`）");
        Console.WriteLine();
        Console.WriteLine("無条件の間を旧 **" + oldB.Sites + " 箇所** ／ 新 **" + newB.Sites + " 箇所**、"
            + "条件付きを旧 **" + oldB.CondSites + " 箇所** ／ 新 **" + newB.CondSites + " 箇所**引いた。");
        Console.WriteLine("**総尺は無条件のぶんだけで出す**——条件付きは「1件あたり必ず掛かる時間」ではないので、"
            + "重み付けに使うと上限しか出せない（同じ規則で両方を分けている）。速度 ×1。");
        Console.WriteLine();
        Console.WriteLine("| 種類 | 旧（秒/件） | 新（秒/件） | 旧・条件付き | 新・条件付き |");
        Console.WriteLine("|---|--:|--:|--:|--:|");
        foreach (string k in oldB.Map.Keys.Concat(newB.Map.Keys).Distinct(StringComparer.Ordinal)
                             .OrderBy(x => x, StringComparer.Ordinal))
            Console.WriteLine("| `" + k + "` | " + oldB.Map.GetValueOrDefault(k).ToString("0.00")
                + " | " + newB.Map.GetValueOrDefault(k).ToString("0.00")
                + " | " + (oldB.Cond.GetValueOrDefault(k) > 0 ? oldB.Cond.GetValueOrDefault(k).ToString("0.00") : "—")
                + " | " + (newB.Cond.GetValueOrDefault(k) > 0 ? newB.Cond.GetValueOrDefault(k).ToString("0.00") : "—")
                + " |");
        Console.WriteLine();
        Console.WriteLine("| 行 | 波 | seed | 出来事 | 旧（秒） | 新（秒） | 差 |");
        Console.WriteLine("|---|--:|--:|--:|--:|--:|--:|");
        double to = 0, tn = 0;
        foreach (var (name, f, ofStage, seed) in ofRows)
        {
            BattleResult r = BattleEngine.Run(f, EnemyCatalog.Stages[ofStage].Enemy, seed, verbose: true);
            double o = 0, n = 0;
            foreach (BattleEvent e in r.Events)
            {
                string k = e.Kind.ToString();
                o += oldB.Map.GetValueOrDefault(k);
                n += newB.Map.GetValueOrDefault(k);
            }
            to += o; tn += n;
            Console.WriteLine("| " + name + " | 第" + (ofStage + 1) + "波 | " + seed + " | " + r.Events.Count
                + " | " + o.ToString("0.0") + " | " + n.ToString("0.0") + " | " + (n - o).ToString("+0.0;-0.0;0.0") + " |");
        }
        Console.WriteLine("| **合計** | | | | **" + to.ToString("0.0") + "** | **" + tn.ToString("0.0")
            + "** | **" + (tn - to).ToString("+0.0;-0.0;0.0") + "**（"
            + (to > 0 ? (tn / to - 1) * 100 : 0).ToString("+0.0;-0.0;0.0") + "%） |");
        Console.WriteLine();
        Console.WriteLine("**`Intercept` は旧の表に無い**（第124期には存在しない種類）ので、"
            + "その件数ぶんはまるごと増分として出る。**手番の中を詰めて手番の外に配る**（§5-2）のが要件。");
        Console.WriteLine();
        Console.WriteLine("条件付きの間（新）: "
            + (newB.Cond.Values.Sum() <= 0 ? "—"
               : string.Join(" / ", newB.Cond.Where(x => x.Value > 0)
                   .Select(x => "`" + x.Key + "` " + x.Value.ToString("0.00") + " 秒"))) 
            + "。**発火した回数ぶんだけ乗る**（反撃・同時着弾は毎回は起きない）。");
        return;
    }

    Console.WriteLine("mode: phase0 / check / tempo <旧Main.cs>");
    return;
}

// watch モード: **見る前に「どの行のどの波のどの seed を見るか」を出す地図**（第123期）。
//
// この期は採否の判定を1つも持たない。主判定・拒否権・ノイズ床・2×2 はこのモードに存在しない。
// 出すのは「観察の対象」と「観察しても画面に出得ないもの（盲点表）」の2つだけで、
// 観察そのものはポンが `design/PHASE123_WATCH_LOG.md` に書く。
//
// **戦闘は回すが盤面は1ビットも動かさない**——`compare` と同じ `BattleEngine.Run` を呼ぶだけで、
// 規則も既定も1つも触っていない（受け入れ条件: `docs/balance.md` と 305 セル 0 件）。
//
//     dotnet run --project BattleSim -c Release 0 watch phase0    # 盲点表（戦闘0回）
//     dotnet run --project BattleSim -c Release 0 watch           # 主表（候補行 × 波 × 代表 seed）
//     dotnet run --project BattleSim -c Release 0 watch cast [行名の部分一致]   # 台本の出演内訳
if (focusId == "watch")
{
    string waMode = args.Length > 2 ? args[2] : "";
    const int WatchSeeds = 200;

    // ------------------------------------------------------------------
    // 候補行 —— 手で並べない。`Baseline.PrimaryRows`（19行・コード）と
    // 「第110〜122期に勝率が動いたと記録されている行」（下）の**和集合**。
    // ------------------------------------------------------------------
    //
    // 出どころは `design/PHASE110_*.md` 〜 `PHASE122_*.md` の報告書（Q0-9）。
    // **報告書は手書き文書なので、ここは「引いた結果」を置くしかない**——そのかわり
    // 行名は `Presets` と**完全一致で照合**し、一致しなかったものを件数つきで出す。
    //
    // 採否が盤面を動かした期だけが載る（第112・115・117〜121期は 0 行:
    // 第115期は「盤面を1ビットも動かしていない」・第120/121期は測定だけ・第117〜119期は不採用）。
    // **第111期に落とした `死軸×ホタ (ゾト×熾)` は載せない**——`Presets` から消えた行なので観察できない。
    var waMoved = new (string Name, string Phase)[]
    {
        ("灯×薙ぎ (トモ×ドルガ)",        "第111期に差し替えで新設／第114期に3セル＋席"),
        ("傷×被弾 (カド×ノミ×ノノ)",     "第111期に交差帯の終端を差し替え／第122期 −0.1"),
        ("惨禍×被弾強化",                 "第113期に席／第122期 −0.3"),
        ("澱み喰い (グザ×ヴィオ)",        "第113期に席"),
        ("縛め収入型 (クグ×バン×ガン)",   "第116期 +15.5（第四波 +43.0）"),
        ("溜め改 (クグ×バン×ガン)",       "第116期 第五波 +0.5"),
        ("追撃×毒 (ハギ×グザ)",           "第122期 +20.0（第2波 +58.5）"),
        ("毒→被弾強化 (グザ×ムド)",       "第122期 +1.1"),
        ("反撃改2 (ガン×カド)",           "第122期 +0.3"),
        ("反撃 (ヒサ×カド)",              "第122期 −0.3"),
        ("死軸×ヒヨ (ゾト×火選り)",       "第122期 −0.4"),
        ("耐久 (ガルド×ノノ)",            "第122期 −0.8"),
        ("反撃改 (ドハ×カド)",            "第122期 −1.0"),
    };

    var waAll = CompareBuilds().Concat(CrossBuilds()).ToArray();
    var waByName = new Dictionary<string, Formation>(StringComparer.Ordinal);
    foreach (var (n, f) in waAll) waByName[n] = f;

    var waMissing = new List<string>();
    var waNames = new List<string>();
    foreach (string n in Baseline.PrimaryRows)
    {
        if (!waByName.ContainsKey(n)) { waMissing.Add(n); continue; }
        if (!waNames.Contains(n, StringComparer.Ordinal)) waNames.Add(n);
    }
    int waPrimaryCount = waNames.Count;
    int waExtra = 0;
    foreach (var (n, _) in waMoved)
    {
        if (!waByName.ContainsKey(n)) { waMissing.Add(n); continue; }
        if (waNames.Contains(n, StringComparer.Ordinal)) continue;
        waNames.Add(n); waExtra++;
    }

    // ------------------------------------------------------------------
    // 軸コメント —— `Baseline.PrimaryRows` の行末コメントを**実装（Program.cs）から**引く。
    // 走査が空なら止める（第117期: 引けなかったときと「該当なし」の区別が付かない）。
    // ------------------------------------------------------------------
    string? waRoot = Directory.GetCurrentDirectory();
    while (waRoot != null && !File.Exists(Path.Combine(waRoot, "docs", "balance.md")))
        waRoot = Path.GetDirectoryName(waRoot);
    var waAxis = new Dictionary<string, string>(StringComparer.Ordinal);
    string waAxisSource = "—";
    if (waRoot != null && File.Exists(Path.Combine(waRoot, "BattleSim", "Program.cs")))
    {
        string src = File.ReadAllText(Path.Combine(waRoot, "BattleSim", "Program.cs"));
        // **アンカーは連結で組む。** 走査対象がこのファイル自身なので、検索文字列を
        // そのまま書くと**自分のコードが最初に当たる**（実際に1度踏んだ）。
        // 第117期「実装から引く分類は、引けなかったときに『該当なし』と区別が付かない」の
        // 自己参照の版で、症状は「走査が空」ではなく「別の場所を読む」。
        string waAnchor = "static class " + "Baseline";
        int a0 = src.IndexOf(waAnchor, StringComparison.Ordinal);
        int a = a0 < 0 ? -1 : src.IndexOf("PrimaryRows" + " =", a0, StringComparison.Ordinal);
        int b = a < 0 ? -1 : src.IndexOf("\n    };", a, StringComparison.Ordinal);
        if (a >= 0 && b > a)
        {
            foreach (string line in src.Substring(a, b - a).Split('\n'))
            {
                int q1 = line.IndexOf('"');
                if (q1 < 0) continue;
                int q2 = line.IndexOf('"', q1 + 1);
                int cm = line.IndexOf("//", StringComparison.Ordinal);
                if (q2 < 0 || cm < q2) continue;
                string nm = line.Substring(q1 + 1, q2 - q1 - 1);
                string ax = line.Substring(cm + 2).Trim();
                int par = ax.IndexOf('（');
                if (par > 0) ax = ax.Substring(0, par);
                int star = ax.IndexOf("**", StringComparison.Ordinal);
                if (star > 0) ax = ax.Substring(0, star);
                waAxis[nm] = ax.Trim();
            }
        }
        waAxisSource = $"BattleSim/Program.cs の `PrimaryRows` 行末コメント {waAxis.Count} 件";
    }
    if (waAxis.Count == 0)
    {
        Console.WriteLine("**走査が空**: `Baseline.PrimaryRows` の軸コメントを1件も引けなかった");
        Console.WriteLine("（リポジトリの外から叩いている可能性がある。第117期の形なのでここで止める）。");
        return;
    }

    string WaAxisOf(string name) => waAxis.TryGetValue(name, out string? v) && v.Length > 0 ? v : "追加";

    // ------------------------------------------------------------------
    // 盲点表 —— `watch phase0`。**戦闘0回。**
    // ------------------------------------------------------------------
    if (waMode == "phase0")
    {
        Console.WriteLine("# 盲点表 —— 画面に出得ないもの（第123期・`watch phase0`）");
        Console.WriteLine();
        Console.WriteLine("`dotnet run --project BattleSim -c Release 0 watch phase0` の出力。手で編集しない。**戦闘0回。**");
        Console.WriteLine();
        Console.WriteLine("> **この表に載っているものは、画面で見えなくても駒の設計の問題ではない。**");
        Console.WriteLine("> 窓口が無い通貨は、駒が正しく働いていても出来事として1件も残らない。");
        Console.WriteLine();

        // (1) StatusKeys.All × StatusGain の窓口。呼び出し元を BattleEngine.cs から機械で拾う。
        var waGain = new List<string>();
        string wePath = waRoot == null ? "" : Path.Combine(waRoot, "BattleCore", "BattleEngine.cs");
        if (wePath.Length > 0 && File.Exists(wePath))
        {
            string we = File.ReadAllText(wePath);
            foreach (System.Text.RegularExpressions.Match m in
                     System.Text.RegularExpressions.Regex.Matches(
                         we, "EmitStatusGain\\(\\s*[A-Za-z_]\\w*\\s*,\\s*([A-Za-z_][\\w\\.]*)"))
                waGain.Add(m.Groups[1].Value);
        }
        if (waGain.Count == 0)
        {
            Console.WriteLine("**走査が空**: `EmitStatusGain` の呼び出し元を1件も引けなかった。ここで止める。");
            return;
        }
        var waGainKeys = new HashSet<string>(StringComparer.Ordinal);
        foreach (string g in waGain)
            waGainKeys.Add(g.StartsWith("StatusKeys.", StringComparison.Ordinal) ? g.Substring("StatusKeys.".Length) : g);
        string[] waEventKindNames = Enum.GetNames(typeof(BattleEventKind));
        var waEventKinds = waEventKindNames.ToHashSet(StringComparer.Ordinal);

        Console.WriteLine("## 1. `StatusKeys.All` × 「付いた瞬間」の窓口（`StatusGain`）");
        Console.WriteLine();
        Console.WriteLine($"`StatusKeys.All` {StatusKeys.All.Length} キー ／ `EmitStatusGain` の呼び出し元 {waGain.Count} 箇所"
                          + $"（うち `StatusKeys.*` でないもの {waGain.Count(g => !g.StartsWith("StatusKeys.", StringComparison.Ordinal))} 件）。");
        Console.WriteLine();
        Console.WriteLine("| キー | 表示名 | 付いた瞬間（`StatusGain`） | 残量（`StatusSnapshot`） |");
        Console.WriteLine("|---|---|:-:|:-:|");
        int waNoGate = 0;
        var waKeyHasGate = new Dictionary<string, bool>(StringComparer.Ordinal);
        var waConstName = new Dictionary<string, string>(StringComparer.Ordinal);
        foreach (string key in StatusKeys.All)
        {
            // 定数名を引き当てる（`StatusKeys.Poison` の "Poison"）。値ではなく名前で照合する。
            string cname = typeof(StatusKeys).GetFields()
                .Where(fi => fi.IsLiteral && fi.FieldType == typeof(string) && (string?)fi.GetRawConstantValue() == key)
                .Select(fi => fi.Name).FirstOrDefault() ?? key;
            waConstName[key] = cname;
            bool gate = waGainKeys.Contains(cname);
            waKeyHasGate[key] = gate;
            if (!gate) waNoGate++;
            // 残量は `StatusLabels` が `StatusKeys.All` から作られるので全キー ○。
            Console.WriteLine($"| `{cname}` | {StatusKeys.LabelOf(key)} | {(gate ? "○" : "**×**")} | ○ |");
        }
        Console.WriteLine();
        Console.WriteLine($"**窓口を持たないキー {waNoGate} / {StatusKeys.All.Length}。**"
                          + " 残量はターン頭に全キーぶん写る（`StatusLabels` は `StatusKeys.All` から作られる）ので、"
                          + "**「いま乗っている」は見えるが「いま書かれた」は見えない**。");
        Console.WriteLine();
        var waOrphan = waGainKeys.Where(k => !waConstName.Values.Contains(k, StringComparer.Ordinal)).ToArray();
        Console.WriteLine($"`StatusKeys.All` に無い窓口 {waOrphan.Length} 件: "
                          + (waOrphan.Length == 0 ? "—" : string.Join(" / ", waOrphan.Select(k => $"`{k}`")))
                          + "（なまり＝`BattleContext.DullKey`。`AtkBonus` は状態異常のカウンタではないので `All` に無い）。");
        Console.WriteLine();

        // (1-b) 「誰がやったか」が台本に載る種類・載らない種類。
        //
        // **通貨の窓口とは別の盲点**——回復・蘇生・召喚・移動は出来事としては出るのに
        // `ActorId` を持たないので、**画面では「起きたこと」は見えるが「誰がやったか」は引けない。**
        // 走査は `BattleEngine.cs` の `Emit` の初期化子から機械で引く（0件なら止める）。
        Console.WriteLine("## 1-b. 出来事の種類 × 「誰がやったか」（`ActorId`）");
        Console.WriteLine();
        var waActorOf = new Dictionary<string, bool>(StringComparer.Ordinal);
        int waEmitSites = 0;
        {
            string we = File.ReadAllText(wePath);
            foreach (System.Text.RegularExpressions.Match m in
                     System.Text.RegularExpressions.Regex.Matches(we, "Kind = BattleEventKind\\.(\\w+)"))
            {
                waEmitSites++;
                string kind = m.Groups[1].Value;
                // 初期化子の終わりまで（`});` か、次の `Kind = ` まで）を見る。
                int from = m.Index;
                int end = we.IndexOf("});", from, StringComparison.Ordinal);
                int nxt = we.IndexOf("Kind = BattleEventKind.", from + 1, StringComparison.Ordinal);
                if (end < 0) end = we.Length;
                if (nxt >= 0 && nxt < end) end = nxt;
                bool hasActor = we.IndexOf("ActorId", from, end - from, StringComparison.Ordinal) >= 0;
                waActorOf[kind] = waActorOf.GetValueOrDefault(kind) || hasActor;
            }
        }
        if (waEmitSites == 0)
        {
            Console.WriteLine("**走査が空**: `Kind = BattleEventKind.` の初期化子を1件も引けなかった。ここで止める。");
            return;
        }
        Console.WriteLine($"`BattleEventKind` {waEventKindNames.Length} 種 ／ `BattleEngine.cs` の初期化子 {waEmitSites} 箇所。");
        Console.WriteLine();
        Console.WriteLine("| 種類 | `ActorId` | 意味 |");
        Console.WriteLine("|---|:-:|---|");
        int waNoActor = 0;
        foreach (string k in waEventKindNames)
        {
            bool has = waActorOf.GetValueOrDefault(k);
            // `EmitTurnStart` / `EmitCharge` / `EmitSkill` / `EmitStatusGain` / `EmitStatusSnapshot`
            // は別メソッドなので上の走査に入らない。ここは初期化子に現れる種類だけを見る。
            if (!waActorOf.ContainsKey(k)) { Console.WriteLine($"| `{k}` | — | 初期化子が `Emit*` の中（走査対象外） |"); continue; }
            if (!has) waNoActor++;
            Console.WriteLine($"| `{k}` | {(has ? "○" : "**×**")} | {(has ? "誰がやったかが引ける" : "**起きたことは見えるが、誰がやったかは引けない**")} |");
        }
        Console.WriteLine();
        // **文も走査から組む**（第124期）。第123期は「回復・蘇生・召喚・移動がここに落ちる」と
        // 手で書いていたので、段2 で `ActorId` を足した瞬間に**表は直るが文が嘘になる**
        // ——第122期「規則を降ろすと、その規則を前提に書かれた説明文が静かに嘘になる」の生成物版。
        string[] waNoActorKinds = waEventKindNames
            .Where(k => waActorOf.ContainsKey(k) && !waActorOf[k]).ToArray();
        Console.WriteLine($"**`ActorId` を持たない種類 {waNoActor} 件**"
                          + (waNoActorKinds.Length == 0
                             ? "。**初期化子に現れるすべての種類が書き手を載せている。**"
                             : $": {string.Join(" / ", waNoActorKinds.Select(k => $"`{k}`"))}"
                               + "——**起きたことが画面に出ても「誰の仕業か」の線が引けない。**"));
        Console.WriteLine();
        Console.WriteLine("> **`Death` は `ActorId` を持つが、それは撃破した駒**（＝普通の一振りの結果）で、");
        Console.WriteLine("> 特性の痕跡ではない。`watch cast` の「特性由来」は `Death` を別に数える。");
        Console.WriteLine();

        // (2) 候補行に出る味方駒 × 通貨。
        Console.WriteLine("## 2. 候補行に出る味方駒 × 扱う通貨");
        Console.WriteLine();
        Console.WriteLine($"候補行 {waNames.Count} 行（主判定 {waPrimaryCount} ＋ 追加 {waExtra}）に登場する味方駒。");
        Console.WriteLine("通貨は `TraitKeyMap.KeysOf`（`derive scan` が観測と突き合わせている表）から引く。");
        Console.WriteLine();

        bool waDull = waGainKeys.Contains("DullKey");

        // 第124期 段2: 窓口が**書き手**を受け取るかを reflection で引く。
        // **手で書くと段2 のような変更で表だけ直って文が嘘になる**（第122期の則の生成物版）。
        // 判定は「`by` という名前の引数を持つか」——`UnitState` の数で見ると、
        // 元から2体を受け取る窓口（将来の `Transfer` 等）と区別が付かない。
        static bool WaTakesWriter(string method)
            => typeof(BattleContext).GetMethod(method)?.GetParameters()
                   .Any(x => x.Name == "by") == true;
        string waDullVia = waDull
            ? (WaTakesWriter("Dull")
               ? "`StatusGain`（`DullKey`。**書き手も載る**）"
               : "`StatusGain`（`DullKey`。**writer が null なので札は出るが線は出ない**）")
            : "**×** —";
        (string Key, string Via, bool Seen)[] waCarryGate =
        {
            ("強化", "**×** —（`AtkBonus` の窓口は `Whet` だが `StatusGain` を呼ばない。受け手の `StatSnapshot` に数字として出るだけ）", false),
            ("弱体", waDullVia, waDull),
            ("毒",   waKeyHasGate[StatusKeys.Poison]   ? "`StatusGain`" : "**×** —", waKeyHasGate[StatusKeys.Poison]),
            ("燃",   waKeyHasGate[StatusKeys.Burn]     ? "`StatusGain`" : "**×** —", waKeyHasGate[StatusKeys.Burn]),
            ("痺",   waKeyHasGate[StatusKeys.Stun]     ? "`StatusGain`" : "**×** —", waKeyHasGate[StatusKeys.Stun]),
            ("標",   waKeyHasGate[StatusKeys.Marked]   ? "`StatusGain`" : "**×** —", waKeyHasGate[StatusKeys.Marked]),
            ("破片", waKeyHasGate[StatusKeys.Armor]    ? "`StatusGain`" : "**×** —", waKeyHasGate[StatusKeys.Armor]),
            ("傷",   waKeyHasGate[StatusKeys.Wound]    ? "`StatusGain`" : "**×** —", waKeyHasGate[StatusKeys.Wound]),
            ("手番", waKeyHasGate[StatusKeys.IdleTurn] ? "`StatusGain`" : "**×** —", waKeyHasGate[StatusKeys.IdleTurn]),
            ("被弾", waEventKinds.Contains("Damage") ? "`Damage`" : "**×** —", waEventKinds.Contains("Damage")),
            ("移動", waEventKinds.Contains("Move")
                       ? (WaTakesWriter("SwapSlots") ? "`Move`（**書き手も載る**）" : "`Move`")
                       : "**×** —", waEventKinds.Contains("Move")),
        };
        if (waCarryGate.Length != UnitTally.CarryKeys.Length)
        {
            Console.WriteLine($"**通貨の数が合わない**（表 {waCarryGate.Length} / `UnitTally.CarryKeys` {UnitTally.CarryKeys.Length}）。ここで止める。");
            return;
        }
        for (int i = 0; i < waCarryGate.Length; i++)
            if (!string.Equals(waCarryGate[i].Key, UnitTally.CarryKeys[i], StringComparison.Ordinal))
            {
                Console.WriteLine($"**通貨の並びが `UnitTally.CarryKeys` と違う**（{i}: {waCarryGate[i].Key} / {UnitTally.CarryKeys[i]}）。ここで止める。");
                return;
            }

        Console.WriteLine("| # | 通貨 | 画面に出る窓口 |");
        Console.WriteLine("|--:|---|---|");
        for (int i = 0; i < waCarryGate.Length; i++)
            Console.WriteLine($"| {i} | {waCarryGate[i].Key} | {waCarryGate[i].Via} |");
        Console.WriteLine();
        Console.WriteLine("**`StatusKeys.All` にあって `UnitTally.CarryKeys` に無いキー: "
                          + $"{StatusKeys.LabelOf(StatusKeys.Deep)} / {StatusKeys.LabelOf(StatusKeys.Curse)}**"
                          + "（第68期の11本は当時の7キーから作られていて、以後に増えた2つが入っていない）。");
        Console.WriteLine();

        var waUnits = new List<UnitDef>();
        foreach (string n in waNames)
            foreach (var x in waByName[n].Occupied())
                if (!waUnits.Any(u => u.Id == x.Def.Id)) waUnits.Add(x.Def);
        Console.WriteLine($"候補行に出る味方駒 **{waUnits.Count} 体**（`UnitCatalog` の Id で数えた実体数）。");
        Console.WriteLine();
        Console.WriteLine("| 駒 | 扱う通貨 | 画面に出る通貨 | 判定 |");
        Console.WriteLine("|---|---|---|:-:|");
        var waBlind = new List<UnitDef>();
        foreach (UnitDef d in waUnits.OrderBy(u => u.Id, StringComparer.Ordinal))
        {
            int[] keys = TraitKeyMap.KeysOf(d);
            string mine = keys.Length == 0 ? "**—（キーを1本も持たない）**" : string.Join("/", keys.Select(k => UnitTally.CarryKeys[k]));
            var seen = keys.Where(k => waCarryGate[k].Seen).ToArray();
            string seenS = seen.Length == 0 ? "**なし**" : string.Join("/", seen.Select(k => UnitTally.CarryKeys[k]));
            bool blind = seen.Length == 0;
            if (blind) waBlind.Add(d);
            Console.WriteLine($"| {d.Name} | {mine} | {seenS} | {(blind ? "**盲点**" : "○")} |");
        }
        Console.WriteLine();
        Console.WriteLine($"**窓口の無い通貨しか扱わない駒 {waBlind.Count} / {waUnits.Count} 体**: "
                          + (waBlind.Count == 0 ? "—" : string.Join(" / ", waBlind.Select(d => d.Name))));
        Console.WriteLine();
        Console.WriteLine("> この列は「通貨として画面に出るか」だけを見ている。**通常攻撃・回復・撃破・召喚は別**で、");
        Console.WriteLine("> 振れば `Attack` / `Damage` が出る。**盲点＝「その駒らしさが出ない」であって「映らない」ではない。**");
        Console.WriteLine();

        // (3) 既知の欠落（Q0-8。第97〜99期の報告書から）。
        Console.WriteLine("## 3. 既に判明している欠落（第97〜99期）");
        Console.WriteLine();
        Console.WriteLine("| | 事実 | 印 |");
        Console.WriteLine("|---|---|:-:|");
        Console.WriteLine("| 痺れ・標・破片の `StatusGain` | 窓口が無い。`Traits.cs` の16箇所から直に `SetCounter` される。第90期（毒）・第93期（傷）と同じ形で3本要る | **既知** |");
        Console.WriteLine("| 減算の窓口 | 引き取り・断ち・縫い・塞ぎは「通貨が減った」を1件も残さない。**画面では在庫が黙って消える** | **既知** |");
        // 第124期 段2 でここが埋まった。**印は reflection から引く**（手で書くと直しても文が残る）。
        Console.WriteLine(WaTakesWriter("Dull")
            ? "| `ctx.Dull` の writer | **第124期 段2 に埋めた。**"
              + "窓口が `by` を受け取り、`StatusGain` の `ActorId` に載る（第97期 §4 の (2)） | **解消** |"
            : "| `ctx.Dull` の writer | 窓口が書き手を受け取らないので、**なまりの札は出るが線は出ない**（第97期 §4 の (2)） | **既知** |");
        Console.WriteLine();
        Console.WriteLine("**第123期はこの3本に手を付けなかった**（`StatusKeys` のカウンタはバランスが載っている場所から直に書かれている）。"
                          + "**第124期 段2 は3本目（`ctx.Dull` の writer）だけを埋めた**"
                          + "——上2本は `Traits.cs` の多数箇所から直に `SetCounter` するので、まだ触っていない。");
        Console.WriteLine();

        // (4) デモ側の照合（A7）。
        Console.WriteLine("## 4. デモの編成プリセットと照合する数");
        Console.WriteLine();
        Console.WriteLine($"`Presets.Compare` **{Presets.Compare.Length}** ＋ `Presets.Cross` **{Presets.Cross.Length}** ＝ "
                          + $"**{Presets.Compare.Length + Presets.Cross.Length} 行**（`DemoApp` の「編成プリセット」に出る数）。");
        Console.WriteLine();
        Console.WriteLine($"軸コメントの出どころ: {waAxisSource}。");
        Console.WriteLine();
        Console.WriteLine($"**`Presets` に存在しない候補行 {waMissing.Count} 件**"
                          + (waMissing.Count == 0 ? "。" : ": " + string.Join(" / ", waMissing)));
        return;
    }

    // ------------------------------------------------------------------
    // 1行 × 1波を回す（`compare` と同じ呼び出し）。
    // ------------------------------------------------------------------
    (double Win, double MedTurn, double Surv, int SeedWin, int SeedLose, double Chain)
        WaCell(Formation f, EnemyCatalog.Stage st)
    {
        var turns = new int[WatchSeeds];
        var won = new bool[WatchSeeds];
        double survSum = 0, chainSum = 0;
        int wins = 0;
        for (int seed = 0; seed < WatchSeeds; seed++)
        {
            var r = BattleEngine.Run(f, st.Enemy, seed, verbose: false);
            turns[seed] = r.Turns; won[seed] = r.PlayerWon;
            chainSum += r.MaxEnemyKillsInOneTurn;
            if (r.PlayerWon) { wins++; survSum += r.PlayerSurvivors; }
        }
        var sorted = turns.OrderBy(x => x).ToArray();
        double med = WatchSeeds % 2 == 0
            ? (sorted[WatchSeeds / 2 - 1] + sorted[WatchSeeds / 2]) / 2.0
            : sorted[WatchSeeds / 2];
        // 代表 seed: 決着Tが中央値に最も近いもの。**同値は seed 昇順の最小**（決定的）。
        int Pick(bool wantWin)
        {
            int best = -1; double bestD = double.MaxValue;
            for (int seed = 0; seed < WatchSeeds; seed++)
            {
                if (won[seed] != wantWin) continue;
                double d = Math.Abs(turns[seed] - med);
                if (d < bestD - 1e-9) { bestD = d; best = seed; }
            }
            return best;
        }
        return (wins * 100.0 / WatchSeeds, med, wins > 0 ? survSum / wins : 0,
                Pick(true), Pick(false), chainSum / WatchSeeds);
    }

    // ------------------------------------------------------------------
    // `watch cast` —— 台本の出演内訳。
    // ------------------------------------------------------------------
    if (waMode == "cast")
    {
        string waFilter = args.Length > 3 ? args[3] : "";
        var waTargets = waNames.Where(n => waFilter.Length == 0 || n.Contains(waFilter, StringComparison.Ordinal)).ToArray();
        if (waTargets.Length == 0)
        {
            Console.WriteLine($"**候補行に「{waFilter}」を含む行が無い**（候補 {waNames.Count} 行）。ここで止める。");
            return;
        }

        Console.WriteLine($"# 台本の出演内訳（`watch cast`）— {waTargets.Length} 行");
        Console.WriteLine();
        Console.WriteLine("**1文（`PlusText` / `MinusText`）と、台本に実際に出た件数を横に並べる。**");
        Console.WriteLine("`通常攻撃` は `Attack` の件数と、それに紐づく `Damage` の件数");
        Console.WriteLine("（紐づけの規則は `Pattern` が非 null かつ `Reaction` が偽かつ `Relayed` が偽。Q0-6）。");
        Console.WriteLine("`特性由来` はそれに紐づかない `ActorId` 付きイベント。**0件なら画面に出ない。**");
        Console.WriteLine("**`Death`（撃破）は別列に出して判定から外す**——`ActorId` は持つが、それは");
        Console.WriteLine("普通の一振りの結果であって特性の痕跡ではない（`watch phase0` の 1-b）。");
        Console.WriteLine();

        int waScanned = 0, waAdjAll = 0, waAdjBadAll = 0;

        // 第124期 段2 の判定（P3 / A7）。**書き手が載った件数と、null のまま残った件数**を
        // 種類ごとに数える。**盤面には一切影響しない**——`r.Events` を読むだけ。
        // 「書き手が居ない経路には無理に入れない」（§5-3）ので、**null が残ること自体は正しい**。
        // 数えないと、どこが残ったのかが分からないだけである。
        var waHasActor = new Dictionary<BattleEventKind, int>();
        var waNullActor = new Dictionary<BattleEventKind, int>();

        foreach (string name in waTargets)
        {
            Formation f = waByName[name];
            // 見る波は §5-4 と同じ規則（第2〜5波で 25〜75%、50% に最も近い波）。
            // 線を満たさない行は「第2〜5波で 50% に最も近い波」に落とす（対象を必ず1つ返すため）。
            var cells = new (double Win, double MedTurn, double Surv, int SeedWin, int SeedLose, double Chain)[EnemyCatalog.Stages.Count];
            for (int w = 0; w < EnemyCatalog.Stages.Count; w++) cells[w] = WaCell(f, EnemyCatalog.Stages[w]);
            int bestWave = 1; double bestD = double.MaxValue; bool onLine = false;
            for (int w = 1; w < EnemyCatalog.Stages.Count; w++)
            {
                double d = Math.Abs(cells[w].Win - 50.0);
                bool band = cells[w].Win >= 25.0 && cells[w].Win <= 75.0;
                if (band && !onLine) { onLine = true; bestD = d; bestWave = w; continue; }
                if (band == onLine && d < bestD - 1e-9) { bestD = d; bestWave = w; }
            }
            var cell = cells[bestWave];

            Console.WriteLine($"## {name} ／ 第{bestWave + 1}波{(onLine ? "" : "（線の外。50% に最も近い波）")}");
            Console.WriteLine();
            Console.WriteLine($"勝率 {cell.Win:F1}% ／ 決着T中央値 {cell.MedTurn:F1} ／ 代表 seed（勝） "
                              + $"{(cell.SeedWin < 0 ? "—" : cell.SeedWin.ToString())} ／ 代表 seed（負） "
                              + $"{(cell.SeedLose < 0 ? "—" : cell.SeedLose.ToString())}");
            Console.WriteLine();

            foreach ((string label, int seed) in new[] { ("勝", cell.SeedWin), ("負", cell.SeedLose) })
            {
                if (seed < 0)
                {
                    Console.WriteLine($"### seed —（{label}の試行が 0 件。この波では{label}が存在しない）");
                    Console.WriteLine();
                    continue;
                }
                var players = BattleEngine.Materialize(f, BattleContext.PlayerTeam);
                var foes = BattleEngine.Materialize(EnemyCatalog.Stages[bestWave].Enemy, BattleContext.EnemyTeam);
                var r = BattleEngine.Run(players, foes, seed, verbose: true);
                // **`InstanceId` は `ctx.Add` が振るので、`Run` の<b>後</b>でないと全部 0 になる**
                // （`Materialize` は盤面に載せる前の姿を作るだけ。デモの `StartBattle` も
                // `pending` を作ってから `Run` の後で `InstanceId` を読んでいる）。
                var idOf = players.ToDictionary(u => u.InstanceId, u => u.Def);
                var startId = f.Occupied().ToDictionary(x => x.Def.Id,
                                  x => players.First(u => u.Def.Id == x.Def.Id).InstanceId);
                waScanned += r.Events.Count;

                Console.WriteLine($"### seed {seed}（{label}・{r.Turns}T・イベント {r.Events.Count} 件）");
                Console.WriteLine();
                Console.WriteLine("| 駒 | ＋ | − | 通常攻撃(振/着弾) | 撃破 | 特性由来 | 内訳 | 判定 |");
                Console.WriteLine("|---|---|---|--:|--:|--:|---|:-:|");

                var swings = new Dictionary<int, int>();
                var linked = new Dictionary<int, int>();
                var traitKinds = new Dictionary<int, Dictionary<BattleEventKind, int>>();
                int waAdj = 0, waAdjBad = 0;
                int lastAttacker = -1;
                foreach (BattleEvent e in r.Events)
                {
                    if (e.ActorId is null) waNullActor[e.Kind] = waNullActor.GetValueOrDefault(e.Kind) + 1;
                    else waHasActor[e.Kind] = waHasActor.GetValueOrDefault(e.Kind) + 1;
                    if (e.Kind == BattleEventKind.TurnStart) lastAttacker = -1;
                    if (e.Kind == BattleEventKind.Attack) lastAttacker = e.ActorId ?? -1;
                    if (e.ActorId is not int aid) continue;
                    if (!idOf.ContainsKey(aid)) continue;
                    if (e.Kind == BattleEventKind.Attack) { swings[aid] = swings.GetValueOrDefault(aid) + 1; continue; }
                    bool plain = e.Kind == BattleEventKind.Damage && e.Pattern is not null && !e.Reaction && !e.Relayed;
                    if (plain)
                    {
                        linked[aid] = linked.GetValueOrDefault(aid) + 1;
                        // Q0-6: その `Damage` の直前の `Attack` が同じ駒か（＝台本上で連続しているか）。
                        if (lastAttacker == aid) waAdj++; else waAdjBad++;
                        continue;
                    }
                    if (!traitKinds.TryGetValue(aid, out var kd)) traitKinds[aid] = kd = new Dictionary<BattleEventKind, int>();
                    kd[e.Kind] = kd.GetValueOrDefault(e.Kind) + 1;
                }
                waAdjAll += waAdj; waAdjBadAll += waAdjBad;

                foreach (var x in f.Occupied())
                {
                    int id = startId[x.Def.Id];
                    int sw = swings.GetValueOrDefault(id), lk = linked.GetValueOrDefault(id);
                    var kd = traitKinds.TryGetValue(id, out var k) ? k : new Dictionary<BattleEventKind, int>();
                    // **`Death` は撃破した駒の札**（普通の一振りの結果）で特性の痕跡ではないので、
                    // 別に数えて判定から外す（`watch phase0` の 1-b）。**緩める向きではなく締める向き。**
                    int kills = kd.GetValueOrDefault(BattleEventKind.Death);
                    int tr = kd.Values.Sum() - kills;
                    string br = kd.Count == 0 ? "—" : string.Join(" / ", kd.OrderByDescending(p => p.Value).Select(p => $"{p.Key} {p.Value}"));
                    Console.WriteLine($"| {x.Def.Name} | {x.Def.PlusText} | {x.Def.MinusText} | {sw}/{lk} | {kills} | {tr} | {br} "
                                      + $"| {(tr == 0 ? "**画面に出ない**" : "○")} |");
                }
                Console.WriteLine();
                var byKind = r.Events.GroupBy(e => e.Kind).OrderByDescending(g => g.Count()).ToArray();
                Console.WriteLine($"イベント総数 {r.Events.Count} 件 —— "
                                  + string.Join(" / ", byKind.Select(g => $"{g.Key} {g.Count()}")));
                Console.WriteLine();
                Console.WriteLine($"**Q0-6**: 味方の「型つき・反撃でない・中継でない」`Damage` {waAdj + waAdjBad} 件のうち、"
                                  + $"直前の `Attack` が同じ駒 **{waAdj} 件** / 違う **{waAdjBad} 件**。");
                Console.WriteLine();
            }
        }

        Console.WriteLine("---");
        Console.WriteLine();
        Console.WriteLine($"**走査したイベント {waScanned} 件。**");
        Console.WriteLine();
        Console.WriteLine($"**Q0-6 の通算**: {waAdjAll + waAdjBadAll} 件のうち連続 **{waAdjAll}** / 非連続 **{waAdjBadAll}**"
                          + $"（{(waAdjAll + waAdjBadAll == 0 ? 0.0 : waAdjAll * 100.0 / (waAdjAll + waAdjBadAll)):F1}%）。");
        Console.WriteLine();

        // ------------------------------------------------------------------
        // 第124期 段2 —— 書き手の載り具合（P3 / A7）。
        // ------------------------------------------------------------------
        Console.WriteLine("## 書き手（`ActorId`）が載った件数（第124期 段2）");
        Console.WriteLine();
        Console.WriteLine("**null のまま残るのは、その出来事に「原因になった駒」が居ない経路**"
                          + "（盤面全体の区切り・継続効果の発火・ターン頭の写し）。");
        Console.WriteLine("**無理に「動いた本人」を入れない**——それは書き手ではないので、線を引くと嘘になる（§5-3）。");
        Console.WriteLine();
        Console.WriteLine("| 種類 | 書き手あり | null | null 率 |");
        Console.WriteLine("|---|--:|--:|--:|");
        int waHaveTot = 0, waNullTot = 0;
        foreach (BattleEventKind k in Enum.GetValues<BattleEventKind>())
        {
            int have = waHasActor.GetValueOrDefault(k), none = waNullActor.GetValueOrDefault(k);
            if (have + none == 0) continue;
            waHaveTot += have; waNullTot += none;
            Console.WriteLine($"| `{k}` | {have} | {none} | {none * 100.0 / (have + none):F1}% |");
        }
        Console.WriteLine($"| **計** | **{waHaveTot}** | **{waNullTot}** | "
                          + $"**{(waHaveTot + waNullTot == 0 ? 0.0 : waNullTot * 100.0 / (waHaveTot + waNullTot)):F1}%** |");
        if (waScanned == 0)
        {
            Console.WriteLine();
            Console.WriteLine("**0 件は異常**（台本が空）。ここで止める。");
        }
        return;
    }

    // ------------------------------------------------------------------
    // 主表 —— `watch`。
    // ------------------------------------------------------------------
    Console.WriteLine("# 見る地図 —— 候補行 × 波 × 代表 seed（第123期）");
    Console.WriteLine();
    Console.WriteLine("`dotnet run --project BattleSim -c Release 0 watch > docs/watch.md` に続けて");
    Console.WriteLine("`dotnet run --project BattleSim -c Release 0 watch phase0 >> docs/watch.md` の出力。手で編集しない。");
    Console.WriteLine($"seed 0..{WatchSeeds - 1} の {WatchSeeds} 試行（`compare` と同じ帯）。**盤面は1ビットも動かない。**");
    Console.WriteLine();
    Console.WriteLine("> **盲点表はこの文書の後半（`watch phase0`）。**");
    Console.WriteLine("> **そこに載っているものは、画面で見えなくても駒の設計の問題ではない。**");
    Console.WriteLine();
    Console.WriteLine($"**候補行 {waNames.Count} 行 ＝ 主判定 {waPrimaryCount} ＋ 追加 {waExtra}**"
                      + $"（`Presets` に存在しない名前 **{waMissing.Count} 件**）。");
    foreach (string n in waMissing) Console.WriteLine($"- **見つからない**: {n}");
    Console.WriteLine();
    Console.WriteLine("`決着T` は 200 試行**全部**の中央値（勝敗を分けない）。代表 seed はこの中央値に");
    Console.WriteLine("最も近い試行で、**同値は seed 昇順の最小**（同じ HEAD で何度回しても同じ seed）。");
    Console.WriteLine("`残存` は勝った試行だけの平均生存数。`連鎖` は1ターンの最大同時撃破数の平均。");
    Console.WriteLine("片側が存在しない波は `—`。`情報帯` は勝率が 0.0% でも 100.0% でもない波。");
    Console.WriteLine();

    var waCells = new List<(string Name, int Wave, double Win, double Med, double Surv, int SW, int SL, double Ch)>();
    foreach (string name in waNames)
    {
        Formation f = waByName[name];
        string seats = string.Join(" / ", f.Occupied().Select(x => $"{FormationRules.SeatNames[x.Slot]} {x.Def.Name}"));
        Console.WriteLine($"## {name}");
        Console.WriteLine();
        Console.WriteLine($"軸: **{WaAxisOf(name)}** ／ 席: {seats}");
        Console.WriteLine();
        Console.WriteLine("| 波 | 勝率 | 決着T | 残存 | 連鎖 | 代表 seed（勝） | 代表 seed（負） | 情報帯 |");
        Console.WriteLine("|---|--:|--:|--:|--:|--:|--:|:-:|");
        for (int w = 0; w < EnemyCatalog.Stages.Count; w++)
        {
            var c = WaCell(f, EnemyCatalog.Stages[w]);
            waCells.Add((name, w, c.Win, c.MedTurn, c.Surv, c.SeedWin, c.SeedLose, c.Chain));
            string tag = w == 0 ? "第1波（教習）" : $"第{w + 1}波";
            Console.WriteLine($"| {tag} | {c.Win:F1}% | {c.MedTurn:F1} | {(c.Win > 0 ? c.Surv.ToString("F1") : "—")} "
                              + $"| {c.Chain:F2} | {(c.SeedWin < 0 ? "—" : c.SeedWin.ToString())} "
                              + $"| {(c.SeedLose < 0 ? "—" : c.SeedLose.ToString())} "
                              + $"| {(c.Win > 0.0 && c.Win < 100.0 ? "○" : "")} |");
        }
        Console.WriteLine();
    }

    // ------------------------------------------------------------------
    // 推奨の見る順（§5-4）。**線と採る条件は同じ集合で書く（(G16)）。**
    // ------------------------------------------------------------------
    Console.WriteLine("---");
    Console.WriteLine();
    Console.WriteLine("# 推奨の見る順");
    Console.WriteLine();
    Console.WriteLine("**線**: 候補行のうち、**第2〜5波のいずれかで勝率が 25.0%〜75.0% にある行**。");
    Console.WriteLine("その行の中で **50% に最も近い波**を1つ選ぶ（同距離なら波番号の小さい方）。");
    Console.WriteLine();
    Console.WriteLine("**採る条件**: 線を満たした行を `Baseline.PrimaryRows` の軸コメントで **1軸につき1行**に絞り、");
    Console.WriteLine("50% に近い順に**上位6行**。軸コメントの無い追加行は「追加」という1つの軸として扱う。");
    Console.WriteLine();

    var waLine = new List<(string Name, int Wave, double Win, int SW, int SL, string Axis)>();
    foreach (string name in waNames)
    {
        int best = -1; double bestD = double.MaxValue;
        foreach (var c in waCells.Where(x => x.Name == name && x.Wave >= 1))
        {
            if (c.Win < 25.0 || c.Win > 75.0) continue;
            double d = Math.Abs(c.Win - 50.0);
            if (d < bestD - 1e-9) { bestD = d; best = c.Wave; }
        }
        if (best < 0) continue;
        var cell = waCells.First(x => x.Name == name && x.Wave == best);
        waLine.Add((name, best, cell.Win, cell.SW, cell.SL, WaAxisOf(name)));
    }

    var waTaken = new List<(string Name, int Wave, double Win, int SW, int SL, string Axis)>();
    var waUsedAxis = new HashSet<string>(StringComparer.Ordinal);
    int waDroppedByAxis = 0;
    foreach (var c in waLine.OrderBy(x => Math.Abs(x.Win - 50.0)).ThenBy(x => x.Name, StringComparer.Ordinal))
    {
        if (!waUsedAxis.Add(c.Axis)) { waDroppedByAxis++; continue; }
        if (waTaken.Count < 6) waTaken.Add(c);
    }

    Console.WriteLine($"**線を満たした行 {waLine.Count} / {waNames.Count}。"
                      + $"軸の重複で落ちた行 {waDroppedByAxis}。軸の数 {waUsedAxis.Count}。採った行 {waTaken.Count}。**");
    if (waTaken.Count < 6)
        Console.WriteLine($"**6 行に満たない（{waTaken.Count} 行）。線は緩めない**（(G16)・(G11)）。");
    Console.WriteLine();
    Console.WriteLine("| # | 行名 | 軸 | 波 | 勝率 | 代表 seed（勝） | 代表 seed（負） |");
    Console.WriteLine("|--:|---|---|---|--:|--:|--:|");
    for (int i = 0; i < waTaken.Count; i++)
    {
        var c = waTaken[i];
        Console.WriteLine($"| {i + 1} | {c.Name} | {c.Axis} | 第{c.Wave + 1}波 | {c.Win:F1}% "
                          + $"| {(c.SW < 0 ? "—" : c.SW.ToString())} | {(c.SL < 0 ? "—" : c.SL.ToString())} |");
    }
    Console.WriteLine();
    Console.WriteLine($"**{waTaken.Count} 行 × 勝敗2本 ＝ "
                      + $"{waTaken.Count(x => x.SW >= 0) + waTaken.Count(x => x.SL >= 0)} 戦。**");
    Console.WriteLine();
    Console.WriteLine("線は満たしたが採らなかった行（**掛かっているが効かなかったことも記録する**・第114期）:");
    Console.WriteLine();
    // 落ちた理由を分ける。**「軸が重なった」と「6行の枠が埋まった」は別の落ち方**で、
    // (G16) が数えろと言っているのは前者だけ。
    var waSeenAxis = new HashSet<string>(StringComparer.Ordinal);
    bool waAnyDropped = false;
    foreach (var c in waLine.OrderBy(x => Math.Abs(x.Win - 50.0)).ThenBy(x => x.Name, StringComparer.Ordinal))
    {
        bool firstOfAxis = waSeenAxis.Add(c.Axis);
        if (waTaken.Any(t => string.Equals(t.Name, c.Name, StringComparison.Ordinal))) continue;
        waAnyDropped = true;
        Console.WriteLine($"- {c.Name}（軸 {c.Axis} ／ 第{c.Wave + 1}波 {c.Win:F1}%）"
                          + $" —— {(firstOfAxis ? "**上位6行の枠**" : "**軸の重複**")}");
    }
    if (!waAnyDropped) Console.WriteLine("- （なし）");
    Console.WriteLine();
    Console.WriteLine("**手順**: `DemoApp` を起動し、ヘッダの「編成プリセット」で行名を選び、"
                      + "「敵ウェーブ」で波を、「戦闘 seed」で代表 seed を入れて「この配置で出撃」。");
    Console.WriteLine("気づいたことは `design/PHASE123_WATCH_LOG.md` に書く。");
    Console.WriteLine();
    Console.WriteLine("**連鎖深度の内訳は `docs/chain.md` を横に置いて読むこと**"
                      + "（この表の `連鎖` は行 × 波の全試行平均で、`chain.md` は全ステージ通算なので分母が違う）。");
    return;
}

// compare モード: 代表的な編成を全ステージで比較する。
// 総当たりは駒が増えるほど爆発するので、系統ごとの当たり外れはこちらで見る。
if (focusId == "compare")
{
    var builds = CompareBuilds();

    const int CompareSeeds = 200;

    // 第126期 段1 —— 勝ち方の質（残存・圧勝率・完全勝利・全滅勝ち）。
    //
    // **`docs/balance.md` には1文字も足さない。別の生成物（`docs/quality.md`）にする。**
    // 指示書 §4-1 は「`compare` の出力に足す」と書いているが、**同じ節が挙げている理由
    // （(G8) の検算が使えなくなる）が、足した瞬間に現実になる**——`docs/balance.md` を読む
    // 自己検査は「`| ` で始まり `%` を含む行」を**位置で**突き合わせる版（`curse check`）と、
    // **行名をキーに 2..6 列目を数値として読む**版（`encore check`）の2種類があり、
    // 勝ち方の質の表は**どちらにも引っかかる**（実測で 61 行 / 293 件のずれが出た）。
    // **指示書の字と、指示書が挙げた理由が食い違っている場所なので、理由のほうを採る。**
    //
    // **戦闘は1回も増えない**——勝率表と同じ `BattleResult` から読むだけ。
    //
    //     dotnet run --project BattleSim -c Release 0 compare > docs/balance.md          # 勝率表（不変）
    //     dotnet run --project BattleSim -c Release 0 compare quality > docs/quality.md  # 勝ち方の質
    bool cqQuality = args.Length > 2 && args[2] == "quality";

    // そのまま docs/balance.md になるので、見出しと注意書きもここで吐く。
    // 手で足した文章はリダイレクトのたびに消えるため、文書の体裁ごと生成物にする。
    if (!cqQuality)
    {
        Console.WriteLine("# 勝率表");
        Console.WriteLine();
        Console.WriteLine("`dotnet run --project BattleSim -c Release 0 compare > docs/balance.md` の出力。手で編集しない。");
        Console.WriteLine($"代表編成 × 全ステージ、seed 0..{CompareSeeds - 1} の {CompareSeeds} 試行。");
        Console.WriteLine();

        // 列はステージ数から作るので、ステージを足しても勝手に増える。
        // 固定幅で揃えるのはやめた。全角の編成名では桁が合わない（`,-24` は表示幅ではなく文字数を数える）。
        Console.WriteLine("| 編成 |" + string.Concat(EnemyCatalog.Stages.Select((st, i) => $" 第{i + 1}波 |")));
        Console.WriteLine("|---|" + string.Concat(EnemyCatalog.Stages.Select(_ => "---:|")));
    }

    var qWins = new int[builds.Length];
    var qSurv = new double[builds.Length];
    var qBlow = new int[builds.Length];      // 生存 >= 4（`run` の `圧勝率` と同じ定義）
    var qPerf = new int[builds.Length];      // 生存 >= 出撃数（**この期の新しい列**）
    var qNarrow = new int[builds.Length];    // 生存 <= 1
    var qParty = new int[builds.Length];

    // 第127期 段0-2 —— **波別の完全勝利率**。
    // 通算だけだと「第三波だけを見た人には 76.1% がその戦の確率に読める」（指示書 §3-1）。
    // **戦闘は1回も増えない**（同じ `BattleResult` から波ごとに落とすだけ）。
    var qWinsW = new int[builds.Length, EnemyCatalog.Stages.Count];
    var qPerfW = new int[builds.Length, EnemyCatalog.Stages.Count];

    // 第129期 段1 —— **無傷勝利 / 実質無傷勝利 / 決着ターンの分布**。
    //
    // **現行の `完全勝利` は緩い。** 判定式は `PlayerSurvivors >= 出撃数` だが、
    // `PlayerSurvivors` は `ctx.LivingMembers(PlayerTeam).Count()` なので**戦闘中に湧いた駒
    // （胞子・餌）も数える**——出撃5枚のうち3枚が落ちて胞子が3体湧いた戦も通る。
    // 分母も「勝った試行」だけなので、負けた試行が1つも効かない。
    //
    // **ここは `BattleResult.PlayerStarterFallen`（出撃した駒だけを個体の同一性で見る）を読む。**
    // **戦闘は1回も増えていない**——上の表とまったく同じ `BattleResult` から落とすだけ。
    var qTrials = new int[builds.Length];                          // 分母（第2〜5波の**全試行**）
    var qClean = new int[builds.Length];                           // 無傷勝利
    var qClean2 = new int[builds.Length];                          // 実質無傷勝利
    var qTrialsW = new int[builds.Length, EnemyCatalog.Stages.Count];
    var qCleanW = new int[builds.Length, EnemyCatalog.Stages.Count];
    var qClean2W = new int[builds.Length, EnemyCatalog.Stages.Count];
    var qPerfDirty = new int[builds.Length];   // 現行の「完全勝利」のうち**出撃駒が欠けている**試行
    var qOver = new int[builds.Length];        // `PlayerSurvivors` > 出撃数（現行の判定式を通せる形）
    var qSummonAlive = new int[builds.Length]; // `PlayerSurvivors` ≠ 出撃数 − 欠けた数（湧いた駒が残った戦）
    var qExcused = new HashSet<string>[builds.Length];             // 免除する駒（`OnDeath` の保持者）
    var qTurnAll = new List<int>[builds.Length];                   // 決着T（第2〜5波・全試行）
    var qTurnW = new List<int>[builds.Length][];

    // === 第140期 —— 行（編成）ごとに並列化した（器具の期・値は1ビットも変えない） ===
    //
    // **この表の集計は、どの行も自分の `[bi]` の枠にしか書かない**——`qWins[bi]` も
    // `qTurnAll[bi]` も行の私物なので、行をまたいだ競合が原理的に起きない。
    // **波（`w`）では割らない**——`qWins[bi] += ...` のように波をまたいで足す量があるので、
    // 同じ行の2つの波を別スレッドに置くと壊れる。**割ってよい軸は行だけ。**
    //
    // 印字は従来どおり直列に `builds` の順で行う（行の文字列を控えて後でまとめて出す）。
    var cqRow = new string[builds.Length];
    Parallel.For(0, builds.Length, bi =>
    {
        (string name, Formation f) = builds[bi];
        qParty[bi] = f.Occupied().Count();
        qExcused[bi] = SurviveScan.ExcusedIds(f);
        qTurnAll[bi] = new List<int>();
        qTurnW[bi] = new List<int>[EnemyCatalog.Stages.Count];
        for (int w = 0; w < EnemyCatalog.Stages.Count; w++) qTurnW[bi][w] = new List<int>();
        var cells = new List<string>();
        for (int w = 0; w < EnemyCatalog.Stages.Count; w++)
        {
            EnemyCatalog.Stage st = EnemyCatalog.Stages[w];
            int wins = 0;
            for (int seed = 0; seed < CompareSeeds; seed++)
            {
                BattleResult r = BattleEngine.Run(f, st.Enemy, seed, verbose: false);

                // --- 第129期 段1 ——「勝ったか」より前に**全試行**を分母に取る ---------------
                // **第一波は実行して除外**（規約 (G10)。ここも同じ分母の切り方にそろえる）。
                if (w > 0)
                {
                    qTrials[bi]++; qTrialsW[bi, w]++;
                    qTurnAll[bi].Add(r.Turns); qTurnW[bi][w].Add(r.Turns);
                    if (r.PlayerSurvivors > qParty[bi]) qOver[bi]++;
                    // **湧いた駒が数えられている証拠は「> 出撃数」ではなく「≠ 出撃数 − 欠けた数」**
                    // ——前者は「欠けた数 ≦ 湧いた数」まで要求するので、1枚欠けて1体湧いた戦を数え落とす。
                    if (r.PlayerSurvivors != qParty[bi] - r.PlayerStarterFallen.Count) qSummonAlive[bi]++;
                    if (r.PlayerWon)
                    {
                        bool clean = r.PlayerStarterFallen.Count == 0;
                        if (clean) { qClean[bi]++; qCleanW[bi, w]++; }
                        // **免除するのは `OnDeath` を上書きする札の保持者だけ**
                        // （`OnAnyDeath` / `OnAllyDeath` は「他人の死を読む側」なので混ぜない
                        //   ——混ぜるとリィカ・ラウ・ハギの死軸が丸ごと免除される）。
                        if (r.PlayerStarterFallen.All(id => qExcused[bi].Contains(id)))
                        { qClean2[bi]++; qClean2W[bi, w]++; }
                        if (r.PlayerSurvivors >= qParty[bi] && !clean) qPerfDirty[bi]++;
                    }
                }

                if (!r.PlayerWon) continue;
                wins++;
                if (w == 0) continue;
                qWins[bi]++;
                qSurv[bi] += r.PlayerSurvivors;
                if (r.PlayerSurvivors >= 4) qBlow[bi]++;
                if (r.PlayerSurvivors >= qParty[bi]) qPerf[bi]++;
                if (r.PlayerSurvivors <= 1) qNarrow[bi]++;
                qWinsW[bi, w]++;
                if (r.PlayerSurvivors >= qParty[bi]) qPerfW[bi, w]++;
            }
            cells.Add($" {wins * 100.0 / CompareSeeds:F1}% |");
        }
        cqRow[bi] = $"| {name} |" + string.Concat(cells);
    });

    if (!cqQuality)
    {
        foreach (string row in cqRow) Console.WriteLine(row);
        return;
    }

    Console.WriteLine("# 勝ち方の質");
    Console.WriteLine();
    Console.WriteLine("`dotnet run --project BattleSim -c Release 0 compare quality > docs/quality.md` の出力。手で編集しない。");
    Console.WriteLine($"代表編成 × 全ステージ、seed 0..{CompareSeeds - 1} の {CompareSeeds} 試行"
        + "（**勝率表と同じ戦・同じ帯**。戦闘は1回も増えていない）。");
    Console.WriteLine();
    Console.WriteLine("**`docs/balance.md` とは別のファイルにしてある。** 勝率表に節を足すと、"
        + "`docs/balance.md` を読む自己検査（`curse check` は `| ` で始まり `%` を含む行を位置で、"
        + "`encore check` は行名をキーに 2..6 列目を数値として読む）が両方とも壊れる"
        + "——実測で 61 行 / 293 件のずれが出た。規約 (G8) の必須1 を守るほうを採った。");
    Console.WriteLine();
    Console.WriteLine("## 勝ち方の質（第2〜5波）");
    Console.WriteLine();
    Console.WriteLine("**分母は「第2〜5波で勝った試行」**（規約 (G10)。第一波は全行必勝の教習波なので入れない）。");
    Console.WriteLine("定義は `run` の `RunSolo` から写した——`残存` は勝った試行の平均生存数、");
    Console.WriteLine("`圧勝率` は生存4体以上、`全滅勝ち` は生存1体以下の割合。");
    Console.WriteLine();
    Console.WriteLine("`完全勝利` は**この期に足した列**で、**生存数 ≧ 出撃数**（＝1体も失わずに勝った割合）。");
    Console.WriteLine("`圧勝率`（4体以上）とは別の量である——`PlayerSurvivors` は戦闘中に湧いた駒");
    Console.WriteLine("（胞子・餌）も数えるので、`==` ではなく `>=` で書いてある。");
    Console.WriteLine();
    Console.WriteLine("| 編成 | 出撃 | 勝った試行 | 残存 | 圧勝率 | **完全勝利** | 全滅勝ち |");
    Console.WriteLine("|---|--:|--:|--:|--:|--:|--:|");
    for (int bi = 0; bi < builds.Length; bi++)
    {
        int n = qWins[bi];
        Console.WriteLine($"| {builds[bi].Name} | {qParty[bi]} | {n} "
            + (n == 0
                ? "| — | — | — | — |"
                : $"| {qSurv[bi] / n:F2} | {qBlow[bi] * 100.0 / n:F1}% "
                  + $"| **{qPerf[bi] * 100.0 / n:F1}%** | {qNarrow[bi] * 100.0 / n:F1}% |"));
    }

    int tw = qWins.Sum();
    if (tw > 0)
    {
        Console.WriteLine();
        Console.WriteLine($"**全 {builds.Length} 行の通算**（勝った試行 {tw}）: "
            + $"残存 **{qSurv.Sum() / tw:F2}** ／ 圧勝率 **{qBlow.Sum() * 100.0 / tw:F1}%** ／ "
            + $"**完全勝利 {qPerf.Sum() * 100.0 / tw:F1}%** ／ 全滅勝ち **{qNarrow.Sum() * 100.0 / tw:F1}%**。");
    }

    // --- 第127期 段0-2 —— 波別の完全勝利率 -------------------------------------------
    Console.WriteLine();
    Console.WriteLine("## 波別の完全勝利率（第127期 段0-2）");
    Console.WriteLine();
    Console.WriteLine("上の表の `完全勝利` は**第2〜5波の通算**なので、**1つの波だけを見たときの確率ではない**。");
    Console.WriteLine("分母は**その波で勝った試行**（波ごとに違う）。`—` はその波で1度も勝っていない行。");
    Console.WriteLine("**戦闘は1回も増えていない**——上の表とまったく同じ `BattleResult` から波ごとに落としただけ。");
    Console.WriteLine("**第一波は判定に使わない**（規約 (G10)。全行必勝の教習波）ので列にも出さない。");
    Console.WriteLine();
    Console.WriteLine("| 編成 |" + string.Concat(Enumerable.Range(1, EnemyCatalog.Stages.Count - 1)
        .Select(i => $" 第{i + 1}波 |")));
    Console.WriteLine("|---|" + string.Concat(Enumerable.Range(1, EnemyCatalog.Stages.Count - 1)
        .Select(_ => "---:|")));
    for (int bi = 0; bi < builds.Length; bi++)
    {
        var cells = new List<string>();
        for (int w = 1; w < EnemyCatalog.Stages.Count; w++)
            cells.Add(qWinsW[bi, w] == 0
                ? " — |"
                : $" {qPerfW[bi, w] * 100.0 / qWinsW[bi, w]:F1}% |");
        Console.WriteLine($"| {builds[bi].Name} |" + string.Concat(cells));
    }
    Console.WriteLine();
    for (int w = 1; w < EnemyCatalog.Stages.Count; w++)
    {
        int ww = 0, pp = 0;
        for (int bi = 0; bi < builds.Length; bi++) { ww += qWinsW[bi, w]; pp += qPerfW[bi, w]; }
        Console.WriteLine($"- **第{w + 1}波の通算**: 勝った試行 {ww} ／ 完全勝利 "
            + (ww == 0 ? "—" : $"**{pp * 100.0 / ww:F1}%**"));
    }

    // --- 第129期 段1 —— 無傷勝利 / 実質無傷勝利 --------------------------------------
    Console.WriteLine();
    Console.WriteLine("## 無傷勝利と実質無傷勝利（第129期 段1）");
    Console.WriteLine();
    Console.WriteLine("**上の `完全勝利` は緩い。** 判定式は `PlayerSurvivors >= 出撃数` だが、");
    Console.WriteLine("`PlayerSurvivors` は `ctx.LivingMembers(PlayerTeam).Count()` なので"
        + "**戦闘中に湧いた駒（胞子・餌）も数える**。");
    Console.WriteLine("分母も「勝った試行」だけなので、負けた試行が1つも効かない。");
    Console.WriteLine();
    Console.WriteLine("**ここは `BattleResult.PlayerStarterFallen` を読む**"
        + "——出撃した駒だけを、**個体（`UnitState`）の同一性で**見る。");
    Console.WriteLine("**戦闘は1回も増えていない**（上の表とまったく同じ `BattleResult` から落としただけ）。");
    Console.WriteLine();
    Console.WriteLine("| 列 | 定義 | 分母 |");
    Console.WriteLine("|---|---|---|");
    Console.WriteLine("| `完全勝利(参考)` | 上の表と同じ値（`PlayerSurvivors >= 出撃数`） | 勝った試行 |");
    Console.WriteLine("| `無傷勝利` | **出撃した駒が1枚も欠けずに勝った**（`PlayerStarterFallen` が空） | **全試行** |");
    Console.WriteLine("| `実質無傷勝利` | 上から**自分の死が起動条件の駒**を免除したもの"
        + "（欠けたのが免除対象だけなら成功とみなす） | **全試行** |");
    Console.WriteLine("| `免除` | その行で免除した駒。`—` は免除対象が1枚もいない行 | — |");
    Console.WriteLine();
    Console.WriteLine($"**免除の判定は実装から引く**——`OnDeath` を上書きする札 "
        + $"**{SurviveScan.DeathTraits.Count} 本**"
        + $"（{SurviveScan.NameList(SurviveScan.DeathTraits)}）の保持者。");
    Console.WriteLine($"**`OnAnyDeath` / `OnAllyDeath`（他人の死を読む側）は混ぜない**"
        + $"——{SurviveScan.OtherDeathTraits.Count} 本"
        + $"（{SurviveScan.NameList(SurviveScan.OtherDeathTraits)}）は**1つも免除に使っていない**。");
    Console.WriteLine("混ぜると墓守リィカ・疫みのラウ・追い打ちのハギを含む死軸が丸ごと免除される。");
    Console.WriteLine();
    Console.WriteLine("| 編成 | 出撃 | 全試行 | 完全勝利(参考) | **無傷勝利** | **実質無傷勝利** | 免除 |");
    Console.WriteLine("|---|--:|--:|--:|--:|--:|---|");
    for (int bi = 0; bi < builds.Length; bi++)
    {
        int n = qTrials[bi], nw = qWins[bi];
        string ex = qExcused[bi].Count == 0
            ? "—"
            : string.Join("・", builds[bi].F.Occupied()
                .Where(o => qExcused[bi].Contains(o.Def.Id)).Select(o => o.Def.Name));
        Console.WriteLine($"| {builds[bi].Name} | {qParty[bi]} | {n} "
            + (nw == 0 ? "| — " : $"| {qPerf[bi] * 100.0 / nw:F1}% ")
            + (n == 0
                ? "| — | — "
                : $"| **{qClean[bi] * 100.0 / n:F1}%** | **{qClean2[bi] * 100.0 / n:F1}%** ")
            + $"| {ex} |");
    }

    int tt = qTrials.Sum();
    if (tt > 0)
    {
        Console.WriteLine();
        Console.WriteLine($"**全 {builds.Length} 行の通算**（全試行 {tt} ／ 勝った試行 {tw}）: "
            + $"完全勝利(参考) **{qPerf.Sum() * 100.0 / Math.Max(1, tw):F1}%** ／ "
            + $"無傷勝利 **{qClean.Sum() * 100.0 / tt:F1}%** ／ "
            + $"実質無傷勝利 **{qClean2.Sum() * 100.0 / tt:F1}%**。");
        Console.WriteLine();
        Console.WriteLine($"- 現行の「完全勝利」に数えられた {qPerf.Sum()} 試行のうち、"
            + $"**出撃した駒が1枚以上欠けているもの {qPerfDirty.Sum()} 件**"
            + $"（{qPerfDirty.Sum() * 100.0 / Math.Max(1, qPerf.Sum()):F1}%）"
            + "——**召喚体が欠けを埋めた戦**。");
        Console.WriteLine($"- 決着時に**湧いた駒が盤上に残っていた**試行 **{qSummonAlive.Sum()} 件**"
            + $"（全試行の {qSummonAlive.Sum() * 100.0 / tt:F1}%。"
            + "`PlayerSurvivors` ≠ 出撃数 − 欠けた数）——**湧いた駒が数えられていることの直接の証拠**。"
            + $"うち `PlayerSurvivors` が出撃数を上回った試行は **{qOver.Sum()} 件**"
            + "（＝現行の判定式を実際に通せる形）。");
        Console.WriteLine($"- 免除対象を1枚以上含む行 **{qExcused.Count(h => h.Count > 0)} / {builds.Length}**。");
    }

    // --- 第129期 段1 —— 波別の無傷勝利率 ---------------------------------------------
    Console.WriteLine();
    Console.WriteLine("### 波別の無傷勝利率（分母はその波の全試行）");
    Console.WriteLine();
    Console.WriteLine("`—` は分母 0 の波。**第一波は判定に使わない**（規約 (G10)）ので列にも出さない。");
    Console.WriteLine();
    Console.WriteLine("| 編成 |" + string.Concat(Enumerable.Range(1, EnemyCatalog.Stages.Count - 1)
        .Select(i => $" 第{i + 1}波 |")));
    Console.WriteLine("|---|" + string.Concat(Enumerable.Range(1, EnemyCatalog.Stages.Count - 1)
        .Select(_ => "---:|")));
    for (int bi = 0; bi < builds.Length; bi++)
    {
        var cells = new List<string>();
        for (int w = 1; w < EnemyCatalog.Stages.Count; w++)
            cells.Add(qTrialsW[bi, w] == 0
                ? " — |"
                : $" {qCleanW[bi, w] * 100.0 / qTrialsW[bi, w]:F1}% |");
        Console.WriteLine($"| {builds[bi].Name} |" + string.Concat(cells));
    }

    // --- 第129期 段1 —— 決着ターンの分布 ---------------------------------------------
    Console.WriteLine();
    Console.WriteLine("## 決着ターンの分布（第129期 段1）");
    Console.WriteLine();
    Console.WriteLine("**勝率からは「安定した」と「運の幅が広がった」が区別できない**"
        + "（第128期の宿題。8ターン決着と9ターン全滅が同居しうる）。");
    Console.WriteLine("**分母は全試行**（勝ち負けを問わない）。`σ` は標本標準偏差、"
        + "`Q1`/`中`/`Q3` は四分位（線形補間なしの順位法）。");
    Console.WriteLine("**戦闘は1回も増えていない**（`BattleResult.Turns` を読んだだけ）。");
    Console.WriteLine();
    Console.WriteLine("| 編成 | 第2〜5波 平均 | σ | Q1 | 中 | Q3 |"
        + string.Concat(Enumerable.Range(1, EnemyCatalog.Stages.Count - 1)
            .Select(i => $" 第{i + 1}波 |")));
    Console.WriteLine("|---|--:|--:|--:|--:|--:|"
        + string.Concat(Enumerable.Range(1, EnemyCatalog.Stages.Count - 1).Select(_ => "---:|")));
    for (int bi = 0; bi < builds.Length; bi++)
    {
        List<int> all = qTurnAll[bi];
        var cells = new List<string>();
        for (int w = 1; w < EnemyCatalog.Stages.Count; w++)
        {
            List<int> v = qTurnW[bi][w];
            cells.Add(v.Count == 0 ? " — |" : $" {SurviveScan.Mean(v):F2}±{SurviveScan.Sd(v):F2} |");
        }
        Console.WriteLine($"| {builds[bi].Name} "
            + (all.Count == 0
                ? "| — | — | — | — | — "
                : $"| {SurviveScan.Mean(all):F2} | {SurviveScan.Sd(all):F2} "
                  + $"| {SurviveScan.Quantile(all, 0.25)} | {SurviveScan.Quantile(all, 0.50)} "
                  + $"| {SurviveScan.Quantile(all, 0.75)} ")
            + "|" + string.Concat(cells));
    }
    return;
}

// engage モード: 会戦（部隊連戦・持ち越しあり）を「列 × 投入部隊数」で測る。
//
// compare は各波を独立した1戦として測るが、会戦は勝った部隊が生存駒の状態
// （HP・最大HPの損耗・蘇生回数・墓守の層-1）を持ち越して次の波と戦う。
// 主表は地点（3波）× 投入部隊数 1〜3。5波1本の順路では全編成が突破 0% に潰れて序列に
// ならず、部隊数を積んだ地点だけが 0〜100% に散る（第3期で切り替え。順路は参考、
// 逆順は第1削り専用へ格下げ）。投入部隊数は同一編成の複製。組み合わせ（別編成×別編成）は
// 多すぎるので測らない。
//
// 却下した案: 独立積（各波の独立勝率の積）・突破分布（0..N 抜きの試行数）・引分の列を残す——
// 会戦の効き目（独立積との差）は第2期で確認済みで役目を終えた。独立勝率そのものは
// docs/balance.md が持ち続けるので、ここに残すと waveCache と順路↔逆順一致検算の維持費だけが残る。
//
//     dotnet run --project BattleSim -c Release 0 engage [絞り込み] > docs/engage.md
if (focusId == "engage")
{
    var all = CompareBuilds();
    const int EngageSeeds = 200;

    string filter = args.Length > 2 ? args[2] : "";
    var targets = all
        .Where(b => filter.Length == 0 || filter.Split(',').Any(k => b.Name.Contains(k.Trim())))
        .ToArray();

    // 列は Name で引く（Columns の並び順は GodotApp の EngagementColumn が使うので当てにしない）
    EnemyCatalog.Column spot = EnemyCatalog.Columns.First(c => c.Name == "地点");
    EnemyCatalog.Column route = EnemyCatalog.Columns.First(c => c.Name == "順路");
    EnemyCatalog.Column rev = EnemyCatalog.Columns.First(c => c.Name == "逆順");

    // 1編成 × 1列 × 投入 nSquads 部隊（同一編成の複製）の一括計測。
    // 突破率は PlayerWon で数える（EnemySquadsCleared == N は相打ち全滅を突破に数えてしまう）。
    // 入場戦力・敵側検算は1部隊のときだけ集計する。「第 i 戦の入場 = PlayerEntries[i]、
    // 敵は毎回新規投入」という 1:1 の前提（負けた時点で会戦が終わる）が2部隊以上では崩れるため。
    (int Full, double Cleared, double Attr, int Draws, int[] Dist,
     double[] AliveSum, double[] HpRatioSum, int[] Reached,
     double[] EnemyEroded, int[] EnemyReached)
        Sweep(Formation f, IReadOnlyList<Formation> column, int nSquads)
    {
        int squads = column.Count;
        Formation[] playerColumn = Enumerable.Repeat(f, nSquads).ToArray();

        // HP割合の分母は**編成全体**の定義上総最大HP（不変値）。SquadEntry.DefMaxHpSum を
        // そのまま分母にする案は却下した——あれは「その戦闘に入った駒」だけの合計なので、
        // 死んだ駒が分子と分母から一緒に抜け、% が「部隊の残存戦力」ではなく「生き残りの
        // 健康度」に化ける（1体だけ全快で残った部隊が 100% に見える）。
        int playerDefTotal = f.Occupied().Sum(x => x.Def.MaxHp);
        int[] enemyDefTotal = column.Select(e => e.Occupied().Sum(x => x.Def.MaxHp)).ToArray();

        var dist = new int[squads + 1];
        int full = 0, draws = 0;
        double clearedSum = 0, attrSum = 0;
        var aliveSum = new double[squads];
        var hpRatioSum = new double[squads];
        var reached = new int[squads];
        var enemyEroded = new double[squads];
        var enemyReached = new int[squads];

        for (int seed = 0; seed < EngageSeeds; seed++)
        {
            EngagementResult r = EngagementEngine.Run(playerColumn, column, seed, verbose: false);
            dist[r.EnemySquadsCleared]++;
            if (r.PlayerWon) full++;
            clearedSum += r.EnemySquadsCleared;
            attrSum += r.FirstBattleAttrition;
            draws += r.Draws;

            if (nSquads != 1) continue;
            for (int b = 0; b < r.PlayerEntries.Count && b < squads; b++)
            {
                aliveSum[b] += r.PlayerEntries[b].Alive;
                hpRatioSum[b] += (double)r.PlayerEntries[b].HpSum / playerDefTotal;
                reached[b]++;

                // 敵側の分母はその戦闘の敵部隊の定義上総最大HP（味方1部隊では ei = b）
                enemyEroded[b] += 1.0 - (double)r.EnemyEntries[b].HpSum
                    / enemyDefTotal[r.Pairings[b].EnemySquad];
                enemyReached[b]++;
            }
        }
        return (full, clearedSum, attrSum, draws, dist,
                aliveSum, hpRatioSum, reached, enemyEroded, enemyReached);
    }

    // 主表1節ぶん: 突破率(1/2/3)・期待突破数(1/2/3)・非線形 → 入場戦力（1部隊）→ 敵側検算行。
    void EmitSection(EnemyCatalog.Column col)
    {
        int squads = col.Squads.Count;
        Console.WriteLine("### 突破率と期待突破数（1部隊 / 2部隊 / 3部隊）");
        Console.WriteLine();
        Console.WriteLine("| 編成 | 突破率(1) | 突破率(2) | 突破率(3) | 期待突破数(1) | 期待突破数(2) | 期待突破数(3) | 非線形(2部隊/1部隊×2) |");
        Console.WriteLine("|---|--:|--:|--:|--:|--:|--:|--:|");

        var entryRows = new List<string>();
        var enemyErodedAll = new double[squads];
        var enemyReachedAll = new int[squads];

        // === 第140期 —— 3つの `Sweep` を編成をまたいで1つの平坦な並列パスに前出しした ===
        //
        // `Sweep` は (編成, 部隊列, 投入部隊数) の純関数で、内側で作る配列も呼び出しごとに新しい。
        // `EngagementEngine.Run` は `BattleEngine.Run` を繋ぐだけなので同じく seed 決定的。
        // **各ジョブは自分の添字にしか書かず、印字は従来どおり直列に `targets` の順で行う。**
        var egS = new (int Full, double Cleared, double Attr, int Draws, int[] Dist,
                       double[] AliveSum, double[] HpRatioSum, int[] Reached,
                       double[] EnemyEroded, int[] EnemyReached)[targets.Length, 3];
        Parallel.For(0, targets.Length * 3, k =>
        {
            int t = k / 3, n = k % 3;
            egS[t, n] = Sweep(targets[t].F, col.Squads, n + 1);
        });

        for (int t = 0; t < targets.Length; t++)
        {
            string name = targets[t].Name;
            var s1 = egS[t, 0];
            var s2 = egS[t, 1];
            var s3 = egS[t, 2];

            // 非線形 = 期待突破数(2部隊) ÷ (期待突破数(1部隊)×2)。1.00 超なら第1部隊の削りを
            // 第2部隊が拾えている。期待(1) が 0 の編成は分母が立たないので —（現状は出ない）。
            string nonlinear = s1.Cleared == 0 ? "—" : $"{s2.Cleared / (2 * s1.Cleared):F2}";

            Console.WriteLine($"| {name} | {s1.Full * 100.0 / EngageSeeds:F1}% | {s2.Full * 100.0 / EngageSeeds:F1}% "
                + $"| {s3.Full * 100.0 / EngageSeeds:F1}% | {s1.Cleared / EngageSeeds:F2} | {s2.Cleared / EngageSeeds:F2} "
                + $"| {s3.Cleared / EngageSeeds:F2} | {nonlinear} |");
            Console.Out.Flush();

            entryRows.Add($"| {name} |" + string.Concat(Enumerable.Range(0, squads).Select(b =>
                s1.Reached[b] == 0
                    ? $" — (0/{EngageSeeds}) |"
                    : $" {s1.AliveSum[b] / s1.Reached[b]:F1}体 {s1.HpRatioSum[b] * 100 / s1.Reached[b]:F0}%"
                      + $" ({s1.Reached[b]}/{EngageSeeds}) |")));
            for (int b = 0; b < squads; b++)
            {
                enemyErodedAll[b] += s1.EnemyEroded[b];
                enemyReachedAll[b] += s1.EnemyReached[b];
            }
        }

        Console.WriteLine();
        Console.WriteLine("### 入場戦力（味方・1部隊）");
        Console.WriteLine();
        Console.WriteLine("| 編成 |" + string.Concat(Enumerable.Range(0, squads).Select(b => $" 第{b + 1}戦 |")));
        Console.WriteLine("|---|" + string.Concat(Enumerable.Range(0, squads).Select(_ => "---|")));
        foreach (string row in entryRows) Console.WriteLine(row);
        Console.WriteLine();
        Console.WriteLine("持ち越された敵部隊が削れていた割合の平均（全編成・全試行）: "
            + string.Join(" / ", Enumerable.Range(0, squads).Select(b => enemyReachedAll[b] == 0
                ? $"第{b + 1}戦 —"
                : $"第{b + 1}戦 {enemyErodedAll[b] * 100 / enemyReachedAll[b]:F0}%"))
            + "（味方1部隊では敵は毎回新規投入なので全戦 0%＝入場HP 100% のはず。ずれていたら実装がおかしい）");
    }

    Console.WriteLine("# 会戦");
    Console.WriteLine();
    Console.WriteLine("`dotnet run --project BattleSim -c Release 0 engage > docs/engage.md` の出力。手で編集しない。");
    Console.WriteLine($"各編成を3本の部隊列にぶつけ、それぞれ seed 0..{EngageSeeds - 1} の {EngageSeeds} 試行。");
    Console.WriteLine("投入部隊数 1〜3 は同一編成の複製（組み合わせは測らない）。");
    Console.WriteLine();
    Console.WriteLine("勝った部隊は生存駒の HP・最大HPの損耗・蘇生回数・墓守の層(-1) を持ち越して次の波と戦う。");
    Console.WriteLine("状態異常（毒・燃焼・痺れ・標的・破片）と攻撃力の一時変動は波の境界で消える。");
    Console.WriteLine();
    Console.WriteLine("部隊列は3本。敵の中身はどれも既存5波のままで、並びと長さだけが違う。");
    Console.WriteLine();
    foreach (EnemyCatalog.Column c in EnemyCatalog.Columns)
        Console.WriteLine($"- **{c.Name}**（{c.Squads.Count}部隊） — {c.Note}");
    Console.WriteLine();
    Console.WriteLine("### 表の読み方");
    Console.WriteLine();
    Console.WriteLine("- `突破率(n)` は n 部隊投入で列の全部隊を抜いた試行の割合。`期待突破数(n)` は抜いた部隊数の平均。");
    Console.WriteLine("- `非線形` は 期待突破数(2部隊) ÷ (期待突破数(1部隊)×2)。**1.00 を超えるなら第1部隊の削りを");
    Console.WriteLine("  第2部隊が拾えている**＝複数部隊制が噛み合っている証拠。期待突破数(1部隊) が列の長さに");
    Console.WriteLine("  近い編成は ×2 が列の長さを超えるので、頭打ちで 1.00 を下回る（弱いのではなく測り切れないだけ）。");
    Console.WriteLine("- `入場戦力` は各部隊戦に入る時点の味方の生存数と HP（**編成全体の定義上の**総最大HPに");
    Console.WriteLine("  対する割合。死んだ駒の枠も分母に残るので、% は部隊の残存戦力を表す。生き残りの健康度");
    Console.WriteLine("  ではない）。到達しなかった試行は分母から外し、到達率を併記する。1部隊投入の走行から集計する。");
    Console.WriteLine("- `第1削り` は最初の Battle で敵の先頭部隊の総 MaxHp を削った割合。**勝てなくても削れる編成**");
    Console.WriteLine("  （特攻隊）はここに出る。逆順の節にだけ載せる（順路・地点では第一波が全編成必勝で");
    Console.WriteLine("  一律 100% になり無情報）。");

    Console.WriteLine();
    Console.WriteLine($"## 地点（{spot.Squads.Count}部隊） — 標準の測定系");
    Console.WriteLine();
    Console.WriteLine("マップ上の1地点は敵1〜3部隊（design/concept_wave_engagement.md §7）。5波1本の順路では");
    Console.WriteLine("全編成が突破 0% に潰れるのに対し、この列は部隊数を積むと突破率が 0〜100% に散る——");
    Console.WriteLine("現時点で唯一、編成の序列として機能する分布なので主表とする。");
    Console.WriteLine();
    EmitSection(spot);

    Console.WriteLine();
    Console.WriteLine($"## 順路（{route.Squads.Count}部隊） — 参考。1地点としては長すぎる");
    Console.WriteLine();
    Console.WriteLine("第2期まで主表だった5波1本の列。全編成が突破 0%・期待突破数 1.00〜2.00 に潰れて序列として");
    Console.WriteLine("機能せず、コンセプト上も1地点は敵1〜3部隊なので参考へ降格した。第2戦→第3戦で駒も HP も");
    Console.WriteLine("一気に落ちる消耗（第二波が代金）の位置は、この列の入場戦力で読む。");
    Console.WriteLine();
    EmitSection(route);

    Console.WriteLine();
    Console.WriteLine("## 逆順 — 第1削り専用");
    Console.WriteLine();
    Console.WriteLine("強い波が先頭の列。**突破数の列は載せない**——逆順は全編成が 0 か 1 抜きで初戦＝第五波の");
    Console.WriteLine("勝敗しか測らず、突破数は docs/balance.md の第5波（独立勝率）の測り直しにしかならない。");
    Console.WriteLine("勝てない編成が先頭の強敵をどれだけ削るか（特攻隊の価値）だけをこの列で読む。");
    Console.WriteLine();
    Console.WriteLine("### 第1削り");
    Console.WriteLine();
    Console.WriteLine("| 編成 | 第1削り |");
    Console.WriteLine("|---|--:|");
    foreach (var (name, f) in targets)
    {
        var m1 = Sweep(f, rev.Squads, 1);
        Console.WriteLine($"| {name} | {m1.Attr * 100 / EngageSeeds:F0}% |");
        Console.Out.Flush();
    }
    return;
}

// seats モード: 会戦の隊列持ち越し診断。第2戦・第3戦の入場スロットが初期配置から
// どれだけずれているかを測る（第3期 Phase H。仮説 (i)「D5 の Slot 持ち越しが移動系の
// 隊列を壊している」の切り分け）。診断用で docs/ には置かない（標準出力で読むだけ）。
//
// 会戦を跨いだ駒の同定は UnitId で行う。Slot はまさに今動いている量なので同定キーに使えない
// （BattleOpening の (TeamId, Slot) 同定は再生側の話。ここは味方限定＋重複ガード付き）。
//
//     dotnet run --project BattleSim -c Release 0 seats [絞り込み]
if (focusId == "seats")
{
    var all = CompareBuilds();
    const int SeatSeeds = 200;

    string filter = args.Length > 2 ? args[2] : "";
    var targets = all
        .Where(b => filter.Length == 0 || filter.Split(',').Any(k => b.Name.Contains(k.Trim())))
        .ToArray();

    // 列は Name で引く（Columns の並び順に依存しない）。診断は順路のみ——知りたいのは
    // 「第2戦の開始時点でどこに居るか」で、どの列に当てても D5 の挙動は同じ。
    IReadOnlyList<Formation> route = EnemyCatalog.Columns.First(c => c.Name == "順路").Squads;
    string[] seatName = FormationRules.SeatNames;

    Console.WriteLine($"# 会戦の隊列持ち越し診断（順路・seed 0..{SeatSeeds - 1} の {SeatSeeds} 試行）");
    Console.WriteLine();
    Console.WriteLine("一致 = 生存駒がすべて自分の初期スロットに居る試行（死んだ駒の枠が空くことはずれに数えない）。");
    Console.WriteLine("後退済み = 第2戦の入場時点で HasFallenBack が立っている駒の平均数（判断 D6 で会戦を跨いで維持される）。");

    foreach (var (name, f) in targets)
    {
        // 同定不能ガード: 味方編成内に同じ UnitId の駒が複数あると UnitId で駒を同定できない。
        // 現在の31編成に重複は無いが、増えたときに黙って嘘の集計を出さないための番犬（作業ルール7）。
        var seats0 = f.Occupied().ToList();
        if (seats0.GroupBy(x => x.Def.Id).Any(g => g.Count() > 1))
        {
            Console.WriteLine();
            Console.WriteLine(name);
            Console.WriteLine("  同定不能（UnitId 重複）: 集計から除外");
            continue;
        }
        var home = seats0.ToDictionary(x => x.Def.Id, x => x.Slot);

        // 添字はそのまま Battle 番号（1=第2戦, 2=第3戦）。第1戦は初期配置そのものなので測らない。
        var reached = new int[3];
        var match = new int[3];
        var patterns = new Dictionary<string, int>[] { new(), new(), new() };
        double fbSum = 0, aliveSum = 0; // 第2戦の入場時のみ（§2.4）

        for (int seed = 0; seed < SeatSeeds; seed++)
        {
            // Openings は verbose:true のときだけ入る（このモードが engage より遅い理由）
            EngagementResult r = EngagementEngine.Run(new[] { f }, route, seed, verbose: true);
            for (int b = 1; b <= 2 && b < r.Openings.Count; b++)
            {
                // 味方1部隊なので Openings[b] の存在＝第 b+1 戦に到達（負けた時点で会戦が終わる）。
                // 持ち越されるのは生存駒だけなので、死んだ駒はここに現れない。
                var mine = r.Openings[b]
                    .Where(o => o.TeamId == BattleContext.PlayerTeam)
                    .OrderBy(o => o.Slot).ToList();
                reached[b]++;
                if (mine.All(o => home[o.UnitId] == o.Slot)) match[b]++;
                // 最頻パターン: スロット昇順の表示文字列をそのままキーにする
                // （味方は UnitId・Slot とも一意なので昇順整列が正準形になる）
                string pat = string.Join(" ", mine.Select(o => $"{seatName[o.Slot]}={o.Name}"));
                patterns[b][pat] = patterns[b].GetValueOrDefault(pat) + 1;
                if (b == 1)
                {
                    fbSum += mine.Count(o => o.HasFallenBack);
                    aliveSum += mine.Count;
                }
            }
        }

        Console.WriteLine();
        Console.WriteLine(name);
        Console.WriteLine("  初期配置    : "
            + string.Join(" ", seats0.Select(x => $"{seatName[x.Slot]}={x.Def.Name}")));
        for (int b = 1; b <= 2; b++)
        {
            string label = b == 1 ? "第2戦の入場" : "第3戦の入場";
            if (reached[b] == 0)
            {
                Console.WriteLine($"  {label} : 到達 0/{SeatSeeds}");
                continue;
            }
            // 同数タイは Ordinal 順で先頭を取る（実行のたびに最頻が入れ替わらないように）
            var top = patterns[b].OrderByDescending(kv => kv.Value)
                                 .ThenBy(kv => kv.Key, StringComparer.Ordinal).First();
            // 一致/ずれの分母は到達試行数。200 未満なら到達数を前置する
            // （一致・ずれ・未到達の3値を同じ /200 に混ぜると読めない）
            string reach = reached[b] < SeatSeeds ? $"到達 {reached[b]}/{SeatSeeds}  " : "";
            Console.WriteLine($"  {label} : {reach}一致 {match[b]}/{reached[b]}  ずれ {reached[b] - match[b]}/{reached[b]}"
                + $"   最頻: {top.Key} （{top.Value}/{reached[b]}）");
        }
        if (reached[1] > 0)
            Console.WriteLine($"  第2戦の入場で後退済み: {fbSum / reached[1]:F1}体/{aliveSum / reached[1]:F1}体");
        Console.Out.Flush();
    }
    return;
}


// =====================================================================================
// boss モード: 「被害で育つ駒」×「死なない駒」の 4×4 を測る（第117期・ボスの土台）。
//
// **新しい機構を1つも作らない。** `BattleCore` に足したのは計数（`BossRule`）だけで、
// **`Presets` は1行も触らない**（台は診断のローカル）。
//
// 測るのは勝率ではなく**傾き**（指示書 §0-2）——勝率は「決着が早いほど高い」ので、
// 時間に比例する項を探す期には向かない。
//
//     dotnet run --project BattleSim -c Release 0 boss phase0   # §3（戦闘は決着Tの分布のみ）
//     dotnet run --project BattleSim -c Release 0 boss run      # 16組 × 対照 × 波
//     dotnet run --project BattleSim -c Release 0 boss check    # 自己検査
if (focusId == "boss")
{
    string bsMode = args.Length > 2 ? args[2] : "phase0";
    IReadOnlyList<EnemyCatalog.Stage> bsStages = EnemyCatalog.Stages;
    const int BsSeeds = 200;      // 帯A。`compare` と揃える（規約 (G14)）
    const int BsHalf = 3;         // 前半3T / 後半3T（指示書 §0-2）
    const int BsMinTurns = 2 * BsHalf;   // 前半と後半が重ならない最短の戦闘
    // **傾きが「測れている」ための線**（規約 (G12)。**Phase 0 の分布を見た後、`run` を回す前に固定した**）。
    // L ≥ 6 の戦がこの割合を下回る組は、傾きの分母が組ごとに桁で違う——
    // 「後半が強い」と「後半まで残った戦だけを見ている」を区別できない。
    const double BsOkFloor = 20.0;

    // --- 被害で育つ 4 枚 × 死なない 4 枚（指示書 §0-1）。**指示書の分類は表P-1 で検算する。**
    var bsGrow = new[] { UnitCatalog.Mudo, UnitCatalog.Kado, UnitCatalog.Yomi, UnitCatalog.Utsu };
    var bsHold = new[] { UnitCatalog.Gald, UnitCatalog.Vel, UnitCatalog.Mug, UnitCatalog.Golm };

    // 素体（同じ数値・特性なし）。`Actions` も落とす（カドの構えが残ると差分が1つに閉じない）。
    static UnitDef BsPlain(UnitDef d) => new()
    {
        Id = d.Id + "_plain", Name = "素体の" + d.Name,
        MaxHp = d.MaxHp, Attack = d.Attack, Speed = d.Speed, Pattern = d.Pattern,
        Traits = Array.Empty<TraitId>()
    };

    // ------------------------------------------------------------------------------
    // Traits.cs をクラス単位に切って索く（第94期の「手で写した表を機械が照合する」の作法）。
    // **戦闘を1回も回さない。** 手で書いた分類は1件も無い。
    // ------------------------------------------------------------------------------
    static string? BsRoot()
    {
        string? root = Directory.GetCurrentDirectory();
        while (root != null && !File.Exists(Path.Combine(root, "docs", "balance.md")))
            root = Path.GetDirectoryName(root);
        return root;
    }

    var bsBody = new Dictionary<TraitId, string>();
    {
        string? root = BsRoot();
        string path = root is null ? "" : Path.Combine(root, "BattleCore", "Traits.cs");
        if (File.Exists(path))
        {
            string src = File.ReadAllText(path);
            // クラス宣言で切る。基底（`: XxxTrait`）の本体は後段で連結する。
            var decl = System.Text.RegularExpressions.Regex.Matches(
                src, @"public (?:sealed |abstract )?class (\w+Trait)(?:\s*:\s*(\w+))?");
            var byName = new Dictionary<string, (string Body, string? Base)>(StringComparer.Ordinal);
            for (int i = 0; i < decl.Count; i++)
            {
                int st = decl[i].Index;
                int en = i + 1 < decl.Count ? decl[i + 1].Index : src.Length;
                string bse = decl[i].Groups[2].Success ? decl[i].Groups[2].Value : null!;
                byName[decl[i].Groups[1].Value] = (src.Substring(st, en - st), bse);
            }
            foreach (var kv in byName)
            {
                string body = kv.Value.Body;
                // 基底の本体を連結する（庇う＝`GuardianTrait : RedirectGainTrait` がこれ）。
                if (kv.Value.Base is { } b && byName.TryGetValue(b, out var bb)) body += bb.Body;
                var m = System.Text.RegularExpressions.Regex.Match(body, @"TraitId Id => TraitId\.(\w+)");
                if (m.Success && Enum.TryParse(m.Groups[1].Value, out TraitId tid))
                    bsBody[tid] = body;
            }
        }
    }
    // **索けなかったら止める。** `bsBody` が空でも分類はすべて偽を返すので、
    // 黙って「規則 (a)〜(c) に1枚も引っかからない」＝**土台の顔ぶれが静かに変わる**
    // （実際に踏んだ: リポジトリの外から叩くと `Traits.cs` が見つからず、
    //  土台が ドルガ・ナタ・エグ から ドルガ・ボルグ・ハギ に化けた）。
    if (bsBody.Count == 0)
    {
        Console.WriteLine("boss: `BattleCore/Traits.cs` が見つからない（リポジトリ直下から実行すること）。");
        return;
    }

    bool BsHas(UnitDef d, params string[] needles)
        => d.Traits.Any(t => bsBody.TryGetValue(t, out string? b) && needles.Any(n => b.Contains(n, StringComparison.Ordinal)));

    // 規則 (a)〜(d)（指示書 §1-1）。**すべて実装から引く。**
    bool BsWritesAtk(UnitDef d) => BsHas(d, "ctx.Whet(", "ctx.Dull(");                    // (a)
    bool BsReadsAtk(UnitDef d) => d.Traits.Any(t => t is TraitId.Overload or TraitId.Perverse); // (b)
    bool BsSuppliesHit(UnitDef d) => BsHas(d, "isFriendlyFire: true");                    // (c) 被弾
    bool BsSuppliesMove(UnitDef d) => BsHas(d, "SwapSlots", "HaulOutPair", "FallBack", "ctx.Summon"); // (c) 移動
    bool BsFragile(UnitDef d) => d.MaxHp < 50;                                            // (d)
    // (c') 追加で見る2つ。**規則ではなく判断**なので、表に列として出したうえで報告書に書く。
    bool BsHeals(UnitDef d) => BsHas(d, "ctx.Heal(", "ctx.Revive(");
    bool BsSelfGrows(UnitDef d) => BsHas(d, "self.AtkBonus +=");

    // 8 枚と、埋め草の候補（`UnitCatalog.All` から）。
    var bsRoster = UnitCatalog.All.ToArray();
    var bsEight = bsGrow.Concat(bsHold).ToArray();

    bool BsFillerOk(UnitDef d) => !bsEight.Contains(d)
        && !BsWritesAtk(d) && !BsReadsAtk(d) && !BsSuppliesHit(d) && !BsSuppliesMove(d) && !BsFragile(d);

    // ------------------------------------------------------------------------------
    // 台（§1-1）。**16 組すべてで土台3枚・席は同一。**
    //   前1 = 死なない（庇う・巨躯・後備えはどれも「前にいること」が条件）
    //   中央 = 育つ（隣接次数4 ＝ 棘の巻き込みが最大／両レーンに属して被弾も最大／
    //          前1 の巨躯の被覆に入る）
    //   前3・後1・後3 = 土台3枚（16 組で不変）
    // 席は測る前に固定する（結果を見てから動かさない）。
    // ------------------------------------------------------------------------------
    UnitDef[] bsFill = Array.Empty<UnitDef>();
    Formation BsBench(UnitDef? grow, UnitDef? hold) => Formation.Build(
        front1: hold, front3: bsFill.Length > 0 ? bsFill[0] : null, center: grow,
        back1: bsFill.Length > 1 ? bsFill[1] : null, back3: bsFill.Length > 2 ? bsFill[2] : null);

    // 埋め草は「規則を満たす候補のうち、回復も自己強化も持たず、総攻がいちばん大きい3枚」。
    // **選び方を測る前に固定する**（第64期）。総攻で選ぶのは台を床にしないため（第109期）。
    // 4枚目は**置換用**（§1-2 の単騎／死なない側だけ の対照で、抜けた枠に入る駒）。
    var bsPool = bsRoster.Where(BsFillerOk).Where(d => !BsHeals(d) && !BsSelfGrows(d))
                     .OrderByDescending(d => d.Attack).ThenBy(d => d.Id, StringComparer.Ordinal)
                     .ToArray();
    bsFill = bsPool.Take(3).ToArray();
    UnitDef? bsSub = bsPool.Length > 3 ? bsPool[3] : null;   // 置換用（4枚目）

    // ------------------------------------------------------------------------------
    // 1戦を回して時系列を切り出す。**`BossRule(true)` は計数だけを起こす**（盤面は動かない）。
    // 前半 = ターン 1..3、後半 = ターン L-2..L（L = 決着ターン）。
    // **L < 6 の戦は前半と後半が重なる**ので、傾きの分母から外す（`Ok` の列）。
    // ------------------------------------------------------------------------------
    BsRow BsOne(Formation f, Formation enemy, int seed, string growId)
    {
        BattleResult r = BattleEngine.Run(f, enemy, seed, verbose: false, boss: new BossRule(true));
        int L = Math.Max(1, r.Turns);
        var row = new BsRow { Turns = L, Won = r.PlayerWon };

        int[] team = new int[BattleEngine.MaxTurns + 2];
        foreach ((int _, UnitDef d) in f.Occupied())
        {
            if (!r.TallyByUnit.TryGetValue(d.Id, out UnitTally? t)) continue;
            if (t.BossLastAliveTurn > row.PartyAlive) row.PartyAlive = t.BossLastAliveTurn;
            if (t.BossDmgByTurn is { } by)
                for (int i = 0; i < team.Length && i < by.Length; i++) team[i] += by[i];
            row.DmgTotal += t.DamageToEnemy;
        }

        if (r.TallyByUnit.TryGetValue(growId, out UnitTally? g))
        {
            row.GrowAlive = g.BossAliveTurns;
            row.GrowSwing = g.BossSwingTurns;
            row.GrowLastAlive = g.BossLastAliveTurn;
            row.GrowDmg = g.DamageToEnemy;
            int[] a = g.BossAtkByTurn ?? Array.Empty<int>();
            int At(int t) => t >= 0 && t < a.Length ? a[t] : 0;
            row.Atk1 = At(1);
            row.Atk3 = At(Math.Min(BsHalf, L));
            row.AtkEnd = At(g.BossLastAliveTurn);
            for (int t = 1; t <= L && t < a.Length; t++) if (a[t] > row.AtkMax) row.AtkMax = a[t];
        }

        if (r.TallyByUnit.TryGetValue(growId, out UnitTally? g2) && g2.BossDmgByTurn is { } gby)
        {
            for (int t = 1; t <= Math.Min(BsHalf, L) && t < gby.Length; t++) row.GrowEarly += gby[t];
            for (int t = Math.Max(1, L - BsHalf + 1); t <= L && t < gby.Length; t++) row.GrowLate += gby[t];
        }
        for (int t = 1; t <= Math.Min(BsHalf, L); t++) row.DmgEarly += team[t];
        for (int t = Math.Max(1, L - BsHalf + 1); t <= L && t < team.Length; t++) row.DmgLate += team[t];
        row.Ok = L >= BsMinTurns;
        return row;
    }

    // 波は第2〜5波（規約 (G10)。第一波は全行が単発で 100% 勝つ教習波）。
    int[] bsWaves = { 1, 2, 3, 4 };   // 添字（0 = 第一波）

    // ------------------------------------------------------------------------------
    // 長期戦の台（§1-3）。**敵の HP だけを倍にする。特性・攻撃力・速さ・攻撃型・体数は1つも触らない。**
    //
    // Phase 0 の結論は「ターン数の観点では長期戦の台は要らない」（L ≥ 6 が 67.3%）だったが、
    // `run` の実測で**別の理由**が出た——既存5波は敵が 3〜5 体で、後半には**標的が尽きる**。
    // 与ダメ/T が落ちたのが「味方が倒れたから」なのか「殴る相手がいないから」なのかを、
    // 5波の台では原理的に切り分けられない（規約 (G7) の3つ目「分母を削るか」）。
    // **ボスは1体で HP が大きい**ので、この台のほうが主題に近い。
    // ------------------------------------------------------------------------------
    const int BsLongMul = 4;
    static Formation BsLongOf(Formation e, int mul)
    {
        var f = new Formation();
        foreach ((int sl, UnitDef d) in e.Occupied())
            f[sl] = new UnitDef
            {
                Id = d.Id, Name = d.Name, MaxHp = d.MaxHp * mul,
                Attack = d.Attack, Speed = d.Speed, Pattern = d.Pattern,
                Traits = d.Traits, Actions = d.Actions,
                PlusText = d.PlusText, MinusText = d.MinusText, Flavor = d.Flavor
            };
        return f;
    }
    bool bsLong = false;
    Formation BsEnemy(int w) => bsLong ? BsLongOf(bsStages[w].Enemy, BsLongMul) : bsStages[w].Enemy;

    // 傾き = 後半の与ダメ/T ÷ 前半の与ダメ/T。**戦ごとの比を平均しない**
    // （前半 0 の戦で発散する）——**合計どうしを割る**。分母は `Ok` の戦だけ。
    static double BsRate(List<BsRow> xs, Func<BsRow, int> f)
    {
        var ok = xs.Where(x => x.Ok).ToList();
        return ok.Count == 0 ? 0 : ok.Sum(x => (double)f(x)) / (ok.Count * 3.0);
    }
    static double BsSlope(List<BsRow> xs)
    {
        double e = BsRate(xs, x => x.DmgEarly), l = BsRate(xs, x => x.DmgLate);
        return e <= 0 ? 0 : l / e;
    }
    /// <summary>育つ側だけの傾き（味方全体の傾きから「他の駒が倒れた」を抜いたもの）。</summary>
    static double BsSlopeGrow(List<BsRow> xs)
    {
        double e = BsRate(xs, x => x.GrowEarly), l = BsRate(xs, x => x.GrowLate);
        return e <= 0 ? 0 : l / e;
    }
    static double BsAvg(List<BsRow> xs, Func<BsRow, double> f) => xs.Count == 0 ? 0 : xs.Average(f);
    static double BsWin(List<BsRow> xs) => xs.Count == 0 ? 0 : xs.Count(x => x.Won) * 100.0 / xs.Count;

    List<BsRow> BsRunAll(Formation f, string growId)
    {
        var rows = new List<BsRow>();
        foreach (int w in bsWaves)
            for (int seed = 0; seed < BsSeeds; seed++)
                rows.Add(BsOne(f, BsEnemy(w), seed, growId));
        return rows;
    }

    // 16 組（4 × 4 の総当たり）。並びは表の行順で固定する。
    var bsPairs = new List<(UnitDef G, UnitDef H)>();
    foreach (UnitDef g0 in bsGrow) foreach (UnitDef h0 in bsHold) bsPairs.Add((g0, h0));

    // ==============================================================================
    // phase0（§3）。**戦闘は決着Tの分布だけ。**
    // ==============================================================================
    if (bsMode == "phase0")
    {
        Console.WriteLine("# 第117期 Phase 0 —— ボスの土台（`boss phase0`）");
        Console.WriteLine();
        Console.WriteLine($"`Traits.cs` から索けた特性: **{bsBody.Count} 件**（手で書いた分類は 0 件）。");

        // --- 表P-1: 8枚の入力
        Console.WriteLine();
        Console.WriteLine("## 表P-1. 8 枚の機構を実装から引く（§3-1）");
        Console.WriteLine();
        Console.WriteLine("**指示書 §0-1 の分類は信用しない**（第116期に §0-2 が実配置と合わなかった）。");
        Console.WriteLine();
        Console.WriteLine("| 枠 | 駒 | HP | 攻 | 速 | 特性 | フック | 自己強化 | 回復/蘇生 | 味方に被弾 | 移動 | 他人の攻を書く |");
        Console.WriteLine("|---|---|--:|--:|--:|---|---|:-:|:-:|:-:|:-:|:-:|");
        foreach (UnitDef d in bsEight)
        {
            bool grow = bsGrow.Contains(d);
            string traits = string.Join("・", d.Traits.Select(t => t.ToString()));
            var hooks = new List<string>();
            foreach (TraitId t in d.Traits)
            {
                if (!bsBody.TryGetValue(t, out string? b)) continue;
                if (b.Contains("void OnDamaged", StringComparison.Ordinal)) hooks.Add($"{t}:被弾");
                if (b.Contains("void OnMoved", StringComparison.Ordinal)) hooks.Add($"{t}:移動");
                if (b.Contains("void OnDeath", StringComparison.Ordinal)) hooks.Add($"{t}:死");
                if (b.Contains("void OnAllyDeath", StringComparison.Ordinal)) hooks.Add($"{t}:味方の死");
                if (b.Contains("int ModifyAttack", StringComparison.Ordinal)) hooks.Add($"{t}:攻の書換");
                if (b.Contains("bool BlocksSupport", StringComparison.Ordinal)) hooks.Add($"{t}:支援拒否");
            }
            Console.WriteLine($"| {(grow ? "**育つ**" : "死なない")} | {d.Name} | {d.MaxHp} | {d.Attack} | {d.Speed} | {traits} | "
                + $"{(hooks.Count == 0 ? "—" : string.Join(" / ", hooks))} | "
                + $"{(BsSelfGrows(d) ? "○" : "×")} | {(BsHeals(d) ? "○" : "×")} | {(BsSuppliesHit(d) ? "○" : "×")} | "
                + $"{(BsSuppliesMove(d) ? "○" : "×")} | {(BsWritesAtk(d) ? "○" : "×")} |");
        }
        Console.WriteLine();
        Console.WriteLine("> **惨禍（`Havoc`）は育ちの機構ではない**——`OnBattleStart` でログを出すだけで、");
        Console.WriteLine("> 判定は engine（`ApplyDamage` の味方全体 被ダメージ +50%）にある。");
        Console.WriteLine("> **カドが育つのは棘（`Thorns`）の味方巻き込み**で、代金は隣接味方のHP。");

        // --- 表P-2: 土台候補の全数列挙
        Console.WriteLine();
        Console.WriteLine("## 表P-2. 土台3枚の候補を規則 (a)〜(d) で全数列挙（§1-1）");
        Console.WriteLine();
        Console.WriteLine($"分母は `UnitCatalog.All` の **{bsRoster.Length} 枚**から 8 枚を除いた **{bsRoster.Length - bsEight.Length} 枚**（規約 (G4)）。");
        Console.WriteLine();
        Console.WriteLine("| 判定 | 駒 | HP | 攻 | 速 | (a) 他人の攻を書かない | (b) 読み手でない | (c) 被弾を撒かない | (c) 移動を撒かない | (d) HP≥50 | 回復 | 自己強化 |");
        Console.WriteLine("|:-:|---|--:|--:|--:|:-:|:-:|:-:|:-:|:-:|:-:|:-:|");
        foreach (UnitDef d in bsRoster.Where(d => !bsEight.Contains(d))
                                      .OrderByDescending(d => bsFill.Contains(d) || bsSub == d)
                                      .ThenByDescending(d => d.Attack))
        {
            bool ok = BsFillerOk(d);
            bool pick = bsFill.Contains(d);
            bool sub = bsSub == d;
            if (!ok && !pick && !sub) continue;
            string mark = pick ? "**採**" : sub ? "**置**" : "候";
            Console.WriteLine($"| {mark} | {d.Name} | {d.MaxHp} | {d.Attack} | {d.Speed} | "
                + $"{(!BsWritesAtk(d) ? "○" : "×")} | {(!BsReadsAtk(d) ? "○" : "×")} | {(!BsSuppliesHit(d) ? "○" : "×")} | "
                + $"{(!BsSuppliesMove(d) ? "○" : "×")} | {(!BsFragile(d) ? "○" : "×")} | "
                + $"{(BsHeals(d) ? "○" : "×")} | {(BsSelfGrows(d) ? "○" : "×")} |");
        }
        Console.WriteLine();
        var bsRej = bsRoster.Where(d => !bsEight.Contains(d) && !BsFillerOk(d)).ToArray();
        Console.WriteLine($"規則 (a)〜(d) で落ちた候補は **{bsRej.Length} 枚**（内訳: "
            + $"(a) {bsRej.Count(BsWritesAtk)} / (b) {bsRej.Count(BsReadsAtk)} / "
            + $"(c)被弾 {bsRej.Count(BsSuppliesHit)} / (c)移動 {bsRej.Count(BsSuppliesMove)} / (d) {bsRej.Count(BsFragile)}"
            + "。**重複して落ちる駒があるので合計は一致しない**）。");
        Console.WriteLine();
        Console.WriteLine("**規則 (a)〜(d) に加えて、回復と自己強化の2つを判断で落とした**（指示書には無い）:");
        Console.WriteLine("回復は Q3（死なない側が生存Tを買っているか）と交絡し、");
        Console.WriteLine("自己強化は Q4（育ちが出力になっているか）の分子に土台のぶんが混ざる。");
        Console.WriteLine($"採ったのは **{string.Join("・", bsFill.Select(d => d.Name))}**"
            + $"（総攻 {bsFill.Sum(d => d.Attack)}）、置換用の4枚目は **{bsSub?.Name ?? "—"}**。");

        // --- 表P-3: 決着ターンの分布
        Console.WriteLine();
        Console.WriteLine("## 表P-3. 16 組の決着ターンの分布（§1-3・**ここだけ戦闘を回す**）");
        Console.WriteLine();
        Console.WriteLine($"seed 0..{BsSeeds - 1} × 第2〜5波。**前半3T と後半3T が重ならない条件は L ≥ {BsMinTurns}**。");
        Console.WriteLine();
        Console.WriteLine("| 組 | 第2波 | 第3波 | 第4波 | 第5波 | 平均 | L≥6 の割合 | 勝率 |");
        Console.WriteLine("|---|--:|--:|--:|--:|--:|--:|--:|");
        var bsP3 = new List<(string Name, List<BsRow> Rows)>();
        foreach ((UnitDef g, UnitDef h) in bsPairs)
        {
            Formation f = BsBench(g, h);
            var all = new List<BsRow>();
            var cells = new List<string>();
            foreach (int w in bsWaves)
            {
                var rows = new List<BsRow>();
                for (int seed = 0; seed < BsSeeds; seed++) rows.Add(BsOne(f, bsStages[w].Enemy, seed, g.Id));
                all.AddRange(rows);
                cells.Add($"{BsAvg(rows, x => x.Turns):F1}");
            }
            bsP3.Add(($"{g.Name} × {h.Name}", all));
            Console.WriteLine($"| {g.Name} × {h.Name} | {string.Join(" | ", cells)} | "
                + $"{BsAvg(all, x => x.Turns):F1} | {all.Count(x => x.Ok) * 100.0 / all.Count:F1}% | {BsWin(all):F1}% |");
        }
        double bsOkAll = bsP3.SelectMany(v => v.Rows).Count(x => x.Ok) * 100.0
                       / Math.Max(1, bsP3.Sum(v => v.Rows.Count));
        Console.WriteLine();
        Console.WriteLine($"**16 組 × 4 波 × {BsSeeds} seed の全体で L ≥ {BsMinTurns} は {bsOkAll:F1}%。**");
        Console.WriteLine(bsOkAll >= 50.0
            ? "→ **長期戦の台は足さない**（後半3T が過半の戦で取れる）。§1-3 の分岐は既存5波のまま。"
            : "→ **後半3T が取れる戦が過半に届かない。** §1-3 の分岐に従い、長期戦の台を検討する。");

        // --- 表P-4: 読み手の混入
        Console.WriteLine();
        Console.WriteLine("## 表P-4. `AtkBonus` の読み手が土台に混ざっていないこと（§3-4）");
        Console.WriteLine();
        Console.WriteLine("| 読み手の特性 | 駒 | 土台に入るか |");
        Console.WriteLine("|---|---|:-:|");
        foreach (UnitDef d in bsRoster.Where(BsReadsAtk))
            Console.WriteLine($"| {string.Join("・", d.Traits.Where(t => t is TraitId.Overload or TraitId.Perverse))} | "
                + $"{d.Name} | {(bsFill.Contains(d) || bsSub == d ? "**×（混入）**" : "○（入らない）")} |");
        Console.WriteLine();
        Console.WriteLine("**ウツは 16 組の「育つ」側なので、土台には入らない。**"
            + " `ReaderRule` の既定は第116期に 5 なので、バンが台に入ると薙ぎ化が混ざる。");

        // --- 表P-5: 過去に同種を測っていないか
        Console.WriteLine();
        Console.WriteLine("## 表P-5. 過去に同種を測っていないか（§3-5・`design/` の grep）");
        Console.WriteLine();
        {
            string? root5 = BsRoot();
            string dir5 = root5 is null ? "" : Path.Combine(root5, "design");
            var needles = new[] { "被弾強化", "巨躯", "死なない", "傾き", "ボス", "時間に比例" };
            Console.WriteLine("| 語 | 当たった文書 |");
            Console.WriteLine("|---|---|");
            foreach (string n in needles)
            {
                var hits = Directory.Exists(dir5)
                    ? Directory.GetFiles(dir5, "*.md").Where(p => File.ReadAllText(p).Contains(n, StringComparison.Ordinal))
                        .Select(Path.GetFileName).OrderBy(x => x, StringComparer.Ordinal).ToArray()
                    : Array.Empty<string?>();
                Console.WriteLine($"| `{n}` | {(hits.Length == 0 ? "—" : string.Join(" / ", hits.Take(6)) + (hits.Length > 6 ? $" ほか {hits.Length - 6} 件" : ""))} |");
            }
        }

        // --- 表P-6: Presets に既にある組
        Console.WriteLine();
        Console.WriteLine("## 表P-6. `Presets` に既にある「育つ × 死なない」の組（§3-6）");
        Console.WriteLine();
        Console.WriteLine("| 行 | 育つ | 死なない |");
        Console.WriteLine("|---|---|---|");
        var bsBuilds = CompareBuilds();
        int bsHave = 0;
        foreach (var (name, f) in bsBuilds)
        {
            var gs = f.Occupied().Select(o => o.Def).Where(d => bsGrow.Contains(d)).ToArray();
            var hs = f.Occupied().Select(o => o.Def).Where(d => bsHold.Contains(d)).ToArray();
            if (gs.Length == 0 || hs.Length == 0) continue;
            bsHave++;
            Console.WriteLine($"| {name} | {string.Join("・", gs.Select(d => d.Name))} | {string.Join("・", hs.Select(d => d.Name))} |");
        }
        Console.WriteLine();
        Console.WriteLine($"**{bsHave} 行 / {bsBuilds.Length} 行**が既に「育つ × 死なない」を含む。"
            + "ただし**土台が行ごとに違う**ので、16 組の総当たりの代わりにはならない（§1-1 の比較の成立条件）。");

        // --- 予測
        Console.WriteLine();
        Console.WriteLine("## 予測（§2-3・**測る前に書いてある**）");
        Console.WriteLine();
        Console.WriteLine("1. **ゴルム × ムド が傾き最上位**（ただし巨躯は被弾を肩代わりして `Rage` の入力を**奪う**ので、");
        Console.WriteLine("   実際に効くのは吐き戻し＝`Whet` の側。指示書の理由付けは実装と合っていない）");
        Console.WriteLine("2. **ウツはどの組でも傾きが低い**——弱体の供給が土台に無い（規則 (c)）ので入力が敵依存");
        Console.WriteLine("3. **ヨミは死なない側と噛まない**——`Displaced` の入力は移動で、死なない駒は移動の供給者ではない");
        Console.WriteLine("4. **Q3 はガルドとゴルムが通り、ムグとヴェルは通らない**");
        Console.WriteLine("5. **Q5 は届かない**——15T でも 1,400 の半分程度");
        return;
    }

    // ==============================================================================
    // run（§4）。16 組 × 対照 × 波。**測るのは勝率ではなく傾き**（§0-2）。
    // ==============================================================================
    if (bsMode == "run" || bsMode == "long")
    {
        bsLong = bsMode == "long";
        Console.WriteLine($"# 第117期 —— ボスの土台（`boss {bsMode}`）");
        Console.WriteLine();
        Console.WriteLine($"台 = 前1 死なない / 中央 育つ / 前3・後1・後3 **{string.Join("・", bsFill.Select(d => d.Name))}**"
            + $"（16 組で同一）。第2〜5波 × seed 0..{BsSeeds - 1}。");
        if (bsLong)
        {
            Console.WriteLine();
            Console.WriteLine($"**長期戦の台（§1-3）: 敵の最大HPを一律 ×{BsLongMul}。特性・攻撃力・速さ・攻撃型・体数は1つも触っていない。**");
            Console.WriteLine("狙いは**標的が尽きることと味方が倒れることの切り分け**（規約 (G7) の3つ目）。");
        }
        Console.WriteLine();
        Console.WriteLine($"**傾き = 後半{BsHalf}T の与ダメ/T ÷ 前半{BsHalf}T の与ダメ/T。**"
            + $" 分母は **L ≥ {BsMinTurns} の戦だけ**（前半と後半が重ならない条件）。");

        // --- 本体を回す
        var bsMain = new List<(UnitDef G, UnitDef H, List<BsRow> Cur, List<BsRow> Pla)>();
        foreach ((UnitDef g, UnitDef h) in bsPairs)
        {
            bsMain.Add((g, h, BsRunAll(BsBench(g, h), g.Id),
                              BsRunAll(BsBench(BsPlain(g), h), BsPlain(g).Id)));
        }
        // 単騎（死なない側を置換駒に）と、死なない側だけ（育つ側を置換駒に）
        var bsSolo = bsGrow.ToDictionary(g => g.Id, g => BsRunAll(BsBench(g, bsSub), g.Id));
        var bsHoldOnly = bsHold.ToDictionary(h => h.Id, h => BsRunAll(BsBench(bsSub, h), bsSub!.Id));

        // --- 表A: 16 組 × 門1〜3 ＋ 傾き（全波まとめ）
        Console.WriteLine();
        Console.WriteLine("## 表A. 16 組 —— 門1〜3 と傾き（第2〜5波まとめ）");
        Console.WriteLine();
        Console.WriteLine($"**※ = L ≥ {BsMinTurns} の戦が {BsOkFloor:F0}% 未満 ＝ 傾きが測れていない**（規約 (G12)。"
            + "分母が組ごとに桁で違うので、判定 Q1・Q2・Q4 からは外す）。");
        Console.WriteLine();
        Console.WriteLine("| 組 | 決着T | 生存T | 育ち 開戦 | 前半末 | 終端 | **到達点** | 前半 ダメ/T | 後半 ダメ/T | **傾き** | 育つ側の与ダメ | 育つ側だけの傾き | 空振り | 勝率 | L≥6 |");
        Console.WriteLine("|---|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|");
        var bsSlopes = new List<(string Name, double Slope, double Peak, double Late, UnitDef G, UnitDef H)>();
        foreach (var (g, h, cur, _) in bsMain)
        {
            double sl = BsSlope(cur), peak = BsAvg(cur, x => x.AtkMax), late = BsRate(cur, x => x.DmgLate);
            if (cur.Count(x => x.Ok) * 100.0 / cur.Count >= BsOkFloor)
                bsSlopes.Add(($"{g.Name} × {h.Name}", sl, peak, late, g, h));
            double idle = BsAvg(cur, x => x.GrowAlive - x.GrowSwing);
            double okPct = cur.Count(x => x.Ok) * 100.0 / cur.Count;
            Console.WriteLine($"| {g.Name} × {h.Name}{(okPct < BsOkFloor ? " ※" : "")} | {BsAvg(cur, x => x.Turns):F2} | {BsAvg(cur, x => x.PartyAlive):F2} | "
                + $"{BsAvg(cur, x => x.Atk1):F1} | {BsAvg(cur, x => x.Atk3):F1} | {BsAvg(cur, x => x.AtkEnd):F1} | "
                + $"**{peak:F1}** | {BsRate(cur, x => x.DmgEarly):F1} | {late:F1} | **{sl:F2}** | "
                + $"{BsAvg(cur, x => x.GrowDmg):F1} | {BsSlopeGrow(cur):F2} | {idle:F2} | {BsWin(cur):F1}% | {okPct:F1}% |");
        }

        // --- 表A': 波別の傾き
        Console.WriteLine();
        Console.WriteLine("## 表A'. 波別の傾き（**L ≥ 6 の戦の割合を併記**。規約 (G6)）");
        Console.WriteLine();
        Console.WriteLine("| 組 | 第2波 | 第3波 | 第4波 | 第5波 |");
        Console.WriteLine("|---|--:|--:|--:|--:|");
        foreach (var (g, h, cur, _) in bsMain)
        {
            var cells = new List<string>();
            for (int i = 0; i < bsWaves.Length; i++)
            {
                var seg = cur.Skip(i * BsSeeds).Take(BsSeeds).ToList();
                int ok = seg.Count(x => x.Ok);
                cells.Add(ok == 0 ? "—" : $"{BsSlope(seg):F2} ({ok * 100.0 / seg.Count:F0}%)");
            }
            Console.WriteLine($"| {g.Name} × {h.Name} | {string.Join(" | ", cells)} |");
        }

        // --- 表B: 対照
        Console.WriteLine();
        Console.WriteLine("## 表B. 対照（§1-2）");
        Console.WriteLine();
        Console.WriteLine("### B-1. 素体差し替え（育つ側を同じ数値・特性なしに）");
        Console.WriteLine();
        Console.WriteLine("| 組 | 傾き 現行 | 傾き 素体 | 差 | 到達点 現行 | 到達点 素体 | 勝率 現行 | 勝率 素体 | 帰属 |");
        Console.WriteLine("|---|--:|--:|--:|--:|--:|--:|--:|--:|");
        foreach (var (g, h, cur, pla) in bsMain)
            Console.WriteLine($"| {g.Name} × {h.Name} | {BsSlope(cur):F2} | {BsSlope(pla):F2} | "
                + $"{BsSlope(cur) - BsSlope(pla):+0.00;-0.00;0.00} | {BsAvg(cur, x => x.AtkMax):F1} | {BsAvg(pla, x => x.AtkMax):F1} | "
                + $"{BsWin(cur):F1}% | {BsWin(pla):F1}% | {BsWin(cur) - BsWin(pla):+0.0;-0.0;0.0}pt |");

        Console.WriteLine();
        Console.WriteLine($"### B-2. 単騎（死なない側を置換駒 **{bsSub?.Name ?? "—"}** に）");
        Console.WriteLine();
        Console.WriteLine("| 育つ | 生存T | 傾き | 到達点 | 勝率 |");
        Console.WriteLine("|---|--:|--:|--:|--:|");
        foreach (UnitDef g in bsGrow)
        {
            var so = bsSolo[g.Id];
            Console.WriteLine($"| {g.Name} | {BsAvg(so, x => x.PartyAlive):F2} | {BsSlope(so):F2} | "
                + $"{BsAvg(so, x => x.AtkMax):F1} | {BsWin(so):F1}% |");
        }

        Console.WriteLine();
        Console.WriteLine($"### B-3. 死なない側だけ（育つ側を置換駒 **{bsSub?.Name ?? "—"}** に）");
        Console.WriteLine();
        Console.WriteLine("| 死なない | 生存T | 傾き | 勝率 |");
        Console.WriteLine("|---|--:|--:|--:|");
        foreach (UnitDef h in bsHold)
        {
            var so = bsHoldOnly[h.Id];
            Console.WriteLine($"| {h.Name} | {BsAvg(so, x => x.PartyAlive):F2} | {BsSlope(so):F2} | {BsWin(so):F1}% |");
        }

        // --- 表C: Q4 の順位相関
        Console.WriteLine();
        Console.WriteLine("## 表C. Q4 —— 到達点 × 出力（順位相関）");
        Console.WriteLine();
        double[] bsX = bsSlopes.Select(x => x.Peak).ToArray();
        double[] bsY = bsSlopes.Select(x => x.Late).ToArray();
        static double[] BsRank(double[] v)
        {
            var idx = Enumerable.Range(0, v.Length).OrderBy(i => v[i]).ToArray();
            var r = new double[v.Length];
            for (int i = 0; i < idx.Length;)
            {
                int j = i;
                while (j + 1 < idx.Length && Math.Abs(v[idx[j + 1]] - v[idx[i]]) < 1e-9) j++;
                double avg = (i + j) / 2.0 + 1;
                for (int k = i; k <= j; k++) r[idx[k]] = avg;
                i = j + 1;
            }
            return r;
        }
        static double BsPearson(double[] a, double[] b)
        {
            double ma = a.Average(), mb = b.Average();
            double sa = Math.Sqrt(a.Sum(x => (x - ma) * (x - ma))), sb = Math.Sqrt(b.Sum(x => (x - mb) * (x - mb)));
            if (sa <= 0 || sb <= 0) return 0;
            return a.Zip(b, (x, y) => (x - ma) * (y - mb)).Sum() / (sa * sb);
        }
        double bsSp = BsPearson(BsRank(bsX), BsRank(bsY));
        double bsPe = BsPearson(bsX, bsY);
        int bsTieX = bsX.Length - bsX.Distinct().Count(), bsTieY = bsY.Length - bsY.Distinct().Count();
        Console.WriteLine("| 量 | スピアマン | ピアソン | 同値塊 |");
        Console.WriteLine("|---|--:|--:|--:|");
        Console.WriteLine($"| 到達点 × 後半ダメ/T | {bsSp:F3} | {bsPe:F3} | X {bsTieX} / Y {bsTieY} |");
        Console.WriteLine();
        Console.WriteLine("**(G13)**: 同値塊が分母の 2 割を超えたら順位相関を判定に使わない。"
            + $" いまの同値塊は X {bsTieX * 100.0 / bsX.Length:F0}% / Y {bsTieY * 100.0 / bsY.Length:F0}%。");

        // --- 表D: Q5 の外挿
        Console.WriteLine();
        Console.WriteLine("## 表D. Q5 —— 15T の外挿（**紙**。門ではなく出力・規約 (G7)）");
        Console.WriteLine();
        var bsTop = bsSlopes.OrderByDescending(x => x.Slope).Take(3).ToList();
        Console.WriteLine("| 組 | 傾き | 前半 ダメ/T | 後半 ダメ/T | 平均 L | 1T あたりの伸び | 15T の累積 | 1,400 に届くか |");
        Console.WriteLine("|---|--:|--:|--:|--:|--:|--:|:-:|");
        foreach (var t in bsTop)
        {
            var cur = bsMain.First(m => m.G == t.G && m.H == t.H).Cur;
            double e = BsRate(cur, x => x.DmgEarly), l = BsRate(cur, x => x.DmgLate);
            double L = BsAvg(cur.Where(x => x.Ok).ToList(), x => x.Turns);
            double te = (1 + BsHalf) / 2.0, tl = L - (BsHalf - 1) / 2.0;
            double m2 = tl > te ? (l - e) / (tl - te) : 0;
            double cum = 0;
            for (int t2 = 1; t2 <= 15; t2++) cum += Math.Max(0, e + m2 * (t2 - te));
            Console.WriteLine($"| {t.Name} | {t.Slope:F2} | {e:F1} | {l:F1} | {L:F2} | {m2:F2} | **{cum:F0}** | "
                + $"{(cum >= 1400 ? "**○**" : "×")} |");
        }
        Console.WriteLine();
        Console.WriteLine("**外挿の前提（全部書く。規約 (G7)）**:");
        Console.WriteLine("1. 味方が 15T 生き残る（実測の平均 L はこれより**短い**。生存の外挿がいちばん甘い前提）");
        Console.WriteLine("2. 育ちが線形に続き、飽和しない（実測は前半末→終端の2点しか見ていない）");
        Console.WriteLine("3. 敵が既存5波と同じ密度で立っている（ボスは**1体**なので薙ぎ・全体の副次目標が消え、");
        Console.WriteLine("   **範囲の駒はここで大きく目減りする**——この外挿はその目減りを織り込んでいない）");
        Console.WriteLine("4. 分母を削らない（規約 (G7) の3つ目。撃破で相手が減ると払い出しの機会も消える）");

        // --- 判定
        Console.WriteLine();
        Console.WriteLine("## 判定（§2-2）");
        Console.WriteLine();
        int bsQ1 = bsSlopes.Count(x => x.Slope >= 1.2);
        double bsQ2 = bsSlopes.Count == 0 ? 0 : bsSlopes.Max(x => x.Slope) - bsSlopes.Min(x => x.Slope);
        var bsQ3 = new List<(string H, double D)>();
        foreach (UnitDef h in bsHold)
        {
            double with = bsMain.Where(m => m.H == h).Average(m => BsAvg(m.Cur, x => x.PartyAlive));
            double solo = bsGrow.Average(g => BsAvg(bsSolo[g.Id], x => x.PartyAlive));
            bsQ3.Add((h.Name, with - solo));
        }
        double bsQ5 = 0;
        {
            var t = bsTop[0];
            var cur = bsMain.First(m => m.G == t.G && m.H == t.H).Cur;
            double e = BsRate(cur, x => x.DmgEarly), l = BsRate(cur, x => x.DmgLate);
            double L = BsAvg(cur.Where(x => x.Ok).ToList(), x => x.Turns);
            double te = (1 + BsHalf) / 2.0, tl = L - (BsHalf - 1) / 2.0;
            double m2 = tl > te ? (l - e) / (tl - te) : 0;
            for (int t2 = 1; t2 <= 15; t2++) bsQ5 += Math.Max(0, e + m2 * (t2 - te));
        }
        Console.WriteLine($"判定の分母は **傾きが測れている {bsSlopes.Count} 組 / 16 組**"
            + $"（L ≥ {BsMinTurns} の戦が {BsOkFloor:F0}% 以上。規約 (G4)）。");
        Console.WriteLine();
        Console.WriteLine("| | 内容 | 線 | 実測 | 判定 |");
        Console.WriteLine("|---|---|---|--:|:-:|");
        Console.WriteLine($"| **Q1** | 傾きが 1.2 以上の組 | 3 組以上 | {bsQ1} 組 | {(bsQ1 >= 3 ? "○" : "**×**")} |");
        Console.WriteLine($"| **Q2** | 16 組の傾きの最大 − 最小 | 0.5 以上 | {bsQ2:F2} | {(bsQ2 >= 0.5 ? "○" : "**×**")} |");
        Console.WriteLine($"| **Q3** | 単騎対照との生存Tの差が +1.0T 以上 | 4 枚中 2 枚以上 | "
            + $"{bsQ3.Count(x => x.D >= 1.0)} 枚 | {(bsQ3.Count(x => x.D >= 1.0) >= 2 ? "○" : "**×**")} |");
        Console.WriteLine($"| **Q4** | 到達点 × 後半ダメ/T の順位相関 | r ≥ 0.5 | {bsSp:F3} | {(bsSp >= 0.5 ? "○" : "**×**")} |");
        Console.WriteLine($"| **Q5** | 15T の累積与ダメ | 1,400 | {bsQ5:F0} | {(bsQ5 >= 1400 ? "○" : "**×**")} |");
        Console.WriteLine();
        Console.WriteLine("**Q3 の内訳**: " + string.Join(" / ", bsQ3.Select(x => $"{x.H} {x.D:+0.00;-0.00;0.00}T")));
        Console.WriteLine();
        Console.WriteLine("**傾き上位3組**: " + string.Join(" / ", bsTop.Select(x => $"{x.Name} {x.Slope:F2}")));
        return;
    }

    // ==============================================================================
    // check（§4 の自己検査）。
    // ==============================================================================
    if (bsMode == "check")
    {
        Console.WriteLine("# 第117期 —— 自己検査（`boss check`）");
        Console.WriteLine();
        var bsBuilds2 = CompareBuilds();
        string? bsRoot2 = BsRoot();

        // (必須1) compare 305 セルが docs/balance.md と 0 件
        var cells = new List<string>();
        foreach (var b in bsBuilds2)
        {
            var row = new List<string>();
            foreach (var st in bsStages)
            {
                int w = 0;
                for (int seed = 0; seed < 200; seed++)
                    if (BattleEngine.Run(b.F, st.Enemy, seed, verbose: false).PlayerWon) w++;
                row.Add($"{w * 100.0 / 200:F1}%");
            }
            cells.Add($"| {b.Name} | {string.Join(" | ", row)} |");
        }
        int bsDiff = -1;
        if (bsRoot2 is not null)
        {
            var doc = File.ReadAllLines(Path.Combine(bsRoot2, "docs", "balance.md"))
                          .Where(l => l.StartsWith("| ") && l.Contains('%')).ToArray();
            bsDiff = Math.Abs(doc.Length - cells.Count);
            for (int i = 0; i < Math.Min(doc.Length, cells.Count); i++)
                if (doc[i].Trim() != cells[i].Trim()) bsDiff++;
        }
        Console.WriteLine($"- **必須1** `compare` {bsBuilds2.Length} 行 × {bsStages.Count} 波 ＝ "
            + $"{bsBuilds2.Length * bsStages.Count} セルを `docs/balance.md` と突き合わせ: "
            + $"**ずれ {bsDiff} 行**{(bsDiff == 0 ? "（○）" : "（×）")}");

        // (必須3) 触っていないノブの既定
        Console.WriteLine($"- **必須3** `BossRule.Default` = `{BossRule.Default}`"
            + $"（`Census` が偽 ＝ 配列を1本も確保しない）{(BossRule.Default.Census ? "（**×**）" : "（○）")}"
            + " ／ `ReaderRule.Default` = `" + ReaderRule.Default + "`（第116期の 5 のまま）");

        // (必須4) ctx.PickOne の箇所数
        int bsPick = 0;
        if (bsRoot2 is not null)
            foreach (string f in Directory.GetFiles(Path.Combine(bsRoot2, "BattleCore"), "*.cs"))
                bsPick += System.Text.RegularExpressions.Regex.Matches(File.ReadAllText(f), @"PickOne\(").Count;
        Console.WriteLine($"- **必須4** `BattleCore` の `PickOne(` の出現: **{bsPick} 箇所**"
            + "（宣言 1 ＋ 呼び出し。**この期は1つも足していない**）");

        // (a) 16 組で土台3枚が完全に同一
        bool bsSameFill = bsPairs.All(p =>
        {
            var f = BsBench(p.G, p.H);
            return f[1] == bsFill[0] && f[3] == bsFill[1] && f[4] == bsFill[2];
        });
        Console.WriteLine($"- **(a)** 16 組で土台3枚（前3・後1・後3）が完全に同一: "
            + $"{(bsSameFill ? "○" : "**×**")}（{string.Join("・", bsFill.Select(d => d.Name))}）");

        // (b) 傾きの分子と分母が同じ計数から
        int bsB1 = 0, bsB2 = 0;
        foreach ((UnitDef g, UnitDef h) in bsPairs)
        {
            Formation f = BsBench(g, h);
            BattleResult r = BattleEngine.Run(f, bsStages[4].Enemy, 0, verbose: false, boss: new BossRule(true));
            foreach ((int _, UnitDef d) in f.Occupied())
            {
                if (!r.TallyByUnit.TryGetValue(d.Id, out UnitTally? t)) continue;
                bsB1 += t.DamageToEnemy;
                bsB2 += t.BossDmgByTurn?.Sum() ?? 0;
            }
        }
        Console.WriteLine($"- **(b)** 傾きの分子・分母が同じ計数から: `DamageToEnemy` の総和 {bsB1} 対 "
            + $"`BossDmgByTurn` の総和 {bsB2} → {(bsB1 == bsB2 ? "**一致（○）**" : "**ずれ（×）**")}");

        // (c) 長期戦の台
        // (c) 長期戦の台は敵の HP 以外が1ビットも違わないこと
        int bsC = 0, bsCn = 0;
        foreach (var st in bsStages)
        {
            Formation lo = BsLongOf(st.Enemy, BsLongMul);
            foreach ((int sl, UnitDef d) in st.Enemy.Occupied())
            {
                UnitDef? m = lo[sl];
                bsCn++;
                if (m is null || m.Id != d.Id || m.Name != d.Name || m.Attack != d.Attack
                    || m.Speed != d.Speed || m.Pattern != d.Pattern
                    || !m.Traits.SequenceEqual(d.Traits)
                    || (m.Actions?.Count ?? 0) != (d.Actions?.Count ?? 0)
                    || m.MaxHp != d.MaxHp * BsLongMul) bsC++;
            }
            if (lo.Count != st.Enemy.Count) bsC++;
        }
        Console.WriteLine($"- **(c)** 長期戦の台（`boss long`）が敵の HP 以外を1ビットも変えていない: "
            + $"**ずれ {bsC} / {bsCn} 体**{(bsC == 0 ? "（○）" : "（×）")}"
            + $"（HP は一律 ×{BsLongMul}。`EnemyCatalog.Stages` そのものは1文字も触っていない）");

        // (d) 到達点が CurrentAttack で取られていること
        bool bsD = false;
        if (bsRoot2 is not null)
        {
            string eng = File.ReadAllText(Path.Combine(bsRoot2, "BattleCore", "BattleEngine.cs"));
            int i = eng.IndexOf("public void NoteBossCensus", StringComparison.Ordinal);
            int j = i >= 0 ? eng.IndexOf("\n    }", i, StringComparison.Ordinal) : -1;
            string body = i >= 0 && j > i ? eng.Substring(i, j - i) : "";
            bsD = body.Contains("u.CurrentAttack", StringComparison.Ordinal)
                  && !body.Contains("u.AtkBonus", StringComparison.Ordinal);
        }
        Console.WriteLine($"- **(d)** `NoteBossCensus` が写すのは `CurrentAttack` で、`AtkBonus` の生値ではない: "
            + $"{(bsD ? "○" : "**×**")}");

        // (e) 計数が盤面を1ビットも動かさないこと（BossRule の有無で 61 行が一致）
        int bsE = 0, bsEn = 0;
        foreach (var b in bsBuilds2)
            foreach (var st in bsStages)
                for (int seed = 0; seed < 20; seed++)
                {
                    BattleResult a = BattleEngine.Run(b.F, st.Enemy, seed, verbose: false);
                    BattleResult c = BattleEngine.Run(b.F, st.Enemy, seed, verbose: false, boss: new BossRule(true));
                    bsEn++;
                    if (a.PlayerWon != c.PlayerWon || a.Turns != c.Turns
                        || a.PlayerSurvivors != c.PlayerSurvivors
                        || a.MaxEnemyKillsInOneTurn != c.MaxEnemyKillsInOneTurn) bsE++;
                }
        Console.WriteLine($"- **(e)** `BossRule(true)` と既定で勝敗・ターン・生存数・連鎖が一致: "
            + $"**ずれ {bsE} / {bsEn} 戦**{(bsE == 0 ? "（○）" : "（×）")}");
        return;
    }

    Console.WriteLine("boss: モードは phase0 / run / check のいずれか。");
    return;
}

